window.MAO_METHODS={"1":[{"t":"按客观形势状态确定相应策略","d":"面对行动策略的选择，不固守一套做法，而先辨识客观形势处于何种状态；不同状态对应不同策略，形势转换则策略随之切换，错配形势与策略必致失败。","sub":[{"t":"依统治阶级形势确定割据战略与推进方式","d":"面对割据在不同形势下的战略选择，先判定统治阶级是暂时稳定还是政治破裂；稳定时敌联合\"进剿\"，须集中红军、相机应敌、波浪式推进、反对分兵冒进；破裂时乘机发展，但仍须建立中心区域的坚实基础。八月失败证明形势误判致战略错用必败，战略边界由客观形势而非抽象常理决定。","p":["中国的红色政权为什么能够存在？","井冈山的斗争"]},{"t":"按环境与领导条件在集中与分兵之间切换","d":"不把集中或分散当作固定原则，先说明各自目的：集中为消灭大一点的敌人、占领城镇，从而发动大范围群众、建立数县联片政权；分兵为更能争取群众、深入土地革命、扩大武装。再定条件：环境恶劣、领导不健全时须集中，只有较好环境与比较健全的领导机关两个条件下才可远距离分兵；达不到目的则不如不分。","p":["星星之火，可以燎原"]}]},{"t":"按内部差别分解整体","d":"面对成分复杂的整体，不能用一个总名称代替内部差别。应先找出决定内部差异的关键条件，把整体分解为可区分的部分，比较各部分的处境，得出有差别的结论与有差别的对待，而不是对整体给出单一评价。","sub":[{"t":"在同一群体内部按境况细分并排出可依靠次序","d":"当总名称掩盖内部差别时不停留在大类结论上：找出区分内部差别的关键指标（是否有余剩、是否自给、生活升降，是否占有土地、农具与资金），据此把整体分成若干可辨认的部分；比较各部分处境的艰难程度，排出可依靠程度次序，标出左翼、中间与右翼；再确定重点争取对象。","p":["中国社会各阶级的分析"]},{"t":"区分农民阶层以识别革命主力","d":"面对笼统的\"农民\"概念，按经济地位把农民分为富农、中农、贫农，分别考察其对革命的态度与行动：富农始终消极、中农游移后加入、贫农最革命并掌握领导权；再以调查数据（贫农占人口百分之七十）确定谁是运动的先锋与中坚，据以决定依靠谁、团结谁、警惕谁。","p":["湖南农民运动考察报告"]}]},{"t":"调查先于结论的问题解决","d":"面对众说纷纭、责难四起的群众运动，先放下二手成见与阶层立场带来的道理，亲自到现场取得第一手材料再作判断；用实地事实核对各类议论，使结论建立在可核验的经验之上，而非预设立场。","sub":[{"t":"实地调查以掌握运动真实状况","d":"面对对一场群众运动众说纷纭、责难四起的局面，先放下在城里绅士阶级那里听得的道理，亲自到运动发生地召集有经验的农民和农运同志开调查会，仔细听报告、看实况，用第一手材料核对各种议论。只有跑到乡村里去看过一遍，才能对运动性质作出可靠判断，不被\"糟得很\"的满城风雨议论裹挟。","p":["湖南农民运动考察报告"]},{"t":"以社会经济调查替代主观主义的分析与指导","d":"针对主观主义的分析与指导，改用马列方法作政治形势分析与阶级估量，注重社会经济调查和研究以决定斗争策略与工作方法；强调离开实际调查会堕入空想盲动，党内批评须有、注意政治。","p":["关于纠正党内的错误思想"]}]},{"t":"在同一组条件下比较备选以择优","d":"面对\"应在何处立足\"的选择，不凭单一优点或就近取便，而先确定这类立足点所依赖的同一组条件，用它对全部备选逐项比较，取综合条件最好者；同时明说所选者的短处，使选择不被优点掩盖。","sub":[{"t":"在同一组条件下比较备选区域以确定割据中心","d":"面对在何处立足的选择，先走遍整个可选区域，再用同一组条件逐项比较各段：地势可否进守、与大政治都会的距离、群众基础、党的组织基础、地方武装经验、有无军事根据地、对邻省下游的政治影响；据此判定中段优于南北两段，并同时明说所选之处割据已久、\"围剿\"军多、现金困难等缺点。","p":["井冈山的斗争","星星之火，可以燎原"]}]},{"t":"从客观地位推断立场","d":"面对\"谁可依靠、谁会反对\"这类判断问题，不以对象的自我宣称、口号或身份名义为准，而以其在现实结构中的客观处境为依据，由处境推出其可能的态度，再据此确定对待方式。宣称只被当作处境的表现，而不是独立。","sub":[{"t":"依据客观经济地位判定敌友与依靠对象","d":"先把敌友判断确定为行动前必须解决的首要问题，再逐类列出全部相关群体；对每一类先考察其客观经济地位——是否占有生产资料、收入来源、受压迫程度——再由地位推断其对变革的态度；最后归入敌人、领导力量、最接近的朋友与动摇者，并对动摇者附加提防边界。态度自述只作为地位的表现。","p":["中国社会各阶级的分析"]}]},{"t":"在条件变化中判断可变态度","d":"对象的态度往往不是固定属性，而随外部形势的变化而变化。认识时须说明结论在何种条件下成立，分别给出不同条件下的判断，并用已经发生的事实检验这些判断，而不是把某一时点的表现当作对象的恒定性质。","sub":[{"t":"区分常态与高潮期判断中间力量的可变态度","d":"对态度不确定的中间群体不给固定标签，而分别设定两种条件下的判断：平时各部分态度各不相同；斗争潮流高涨时左派参加、中派亦可参加、右派受裹挟也只得附和。同时判断对立局面加剧时中间群体必然分化，没有保持\"独立\"的余地。判断作出后用已发生的运动经验检验，再决定争取还是提防。","p":["中国社会各阶级的分析"]}]},{"t":"以斗争阶段判定行动边界","d":"面对被指责\"过火\"\"过分\"的行动，不孤立评判单个举动，而把它放回运动所处阶段考察；在旧秩序须被彻底推翻的阶段，非常手段具有正当性，行动边界由当前斗争任务而非抽象常理决定。","sub":[{"t":"以革命阶段判定过火行动的正当性","d":"面对\"农会举动太过分\"\"矫枉过正\"的责难，不孤立评判单个举动，而把它放回运动所处阶段（第二时期即革命时期）考察：此时期必须建立农民绝对权力、镇压反革命派，短时期\"恐怖现象\"非如此不能造成。所谓过分本是土豪劣绅自己逼出来的，农民惩罚轻重极有分寸。结论：矫枉必须过正，不过正不能矫枉。","p":["湖南农民运动考察报告"]}]},{"t":"用系统事实枚举回应定性指责","d":"面对笼统的定性指责，不陷入抽象辩驳，而把对象行动系统分类、逐条枚举为可核验的事实清单，以具体内容证明其性质，使指责在事实面前失去依据。","sub":[{"t":"系统枚举事实清单回应定性指责","d":"面对\"农会做了许多坏事\"的笼统指责，不陷入抽象辩驳，而把农民数月行动分类总计为十四件大事，逐一检视其内容与意义，用可查证的清单证明件件具有革命意义，把难以正面说清的争议转化为对具体事实的核对，使指责者在事实面前失去立足点。","p":["湖南农民运动考察报告"]}]},{"t":"按斗争主次确定先后次序","d":"面对多重任务同时展开，不平均用力，先解决决定全局的基干矛盾，其余在其胜利后自然推进；对次要或条件未熟者不强求、不硬推，避免给对立面以可乘口实。","sub":[{"t":"区分斗争主次与先后次序","d":"面对政治、经济、文化（族权神权夫权）多重斗争同时展开的局面，不平均用力：先集中破坏地主政治权力这一基干，经济斗争随之，家族神道男女关系的破坏须待政治经济利益胜利后自然发生。对迷信旧俗不施过早过大的生硬破坏，对群众用\"引而不发\"启发自觉而非包办。","p":["湖南农民运动考察报告"]}]},{"t":"以群众可接受的形式启发自觉","d":"面对教育与启蒙困难，用对象熟悉、易接受的极简形式传递核心主张，并以启发代替包办，让对象在自身经验中形成自觉，而非由外部强迫替代其行动。","sub":[{"t":"用极简形式实现群众政治自觉","d":"面对乡村文盲普及、政治教育极难的困难，不依赖正规法政学校，而用简单标语、图画、讲演把\"打倒帝国主义\"等口号不翼而飞地送入男女老少头脑；再对迷信以启发代替包办——向农民讲清帝君大士打不倒土豪，让农民自己笑起来、自己丢菩萨，以群众可接受的形式促成其自觉。","p":["湖南农民运动考察报告"]}]},{"t":"以必要条件集合判断事物能否存在发展","d":"面对\"某事物能否在不利环境中长期存在\"类判断，不靠情绪，而把能否成立化为若干必要条件：先识别独特前提，再列出存在发展所依赖的各项条件并逐项说明，以条件是否具备作判断；亦可反向用于识别并落实存续所需的关键条件。","sub":[{"t":"红色政权存在的必要条件结构分析","d":"面对\"一小块红色政权能否在白色包围中长期存在发展\"的判断，先区分其发生前提（白色政权间长期分裂战争，源于半殖民地、地方农业经济与帝国主义分裂政策）与存在发展条件，再逐项列出五条必要条件（分裂战争、民主革命影响地区、全国革命形势向前、相当力量正式红军、党组织有力政策不误），以\"条件具备则存在无疑\"作判断。","p":["中国的红色政权为什么能够存在？"]},{"t":"巩固军事根据地的三项物质准备","d":"面对长期立足的根据地如何巩固，先识别其存续依赖的关键物质条件（防御工事、粮食储备、医疗保障），再逐项落实（修工事、储粮食、建医院），使根据地能在敌封锁与进攻中坚持；物质保障缺一则难坚持。","p":["中国的红色政权为什么能够存在？"]}]},{"t":"以现实关系的改变而非说服改变态度","d":"人的态度与主动性主要由其在现实关系中的地位和利害决定，单纯说理作用有限。要改变态度，应改变其在组织中的地位与权利，或使各方处于共同的处境与利害之中，并以具体处置消除现实损害；说服与教育在此基础上才真正起效。","sub":[{"t":"以军队内部关系的改造取代雇佣关系","d":"面对物质极端菲薄、成分复杂的队伍如何维持战斗力，不靠增加供给而改造内部关系：废除雇佣制，使士兵为自己而非为他人打仗；官长不打士兵、官兵待遇平等、经济公开、士兵有开会说话自由并自管伙食；从军长到伙夫一律同等待遇。俘虏兵过来即被熔化，同一个兵在敌军不勇敢、在红军很勇敢。","p":["井冈山的斗争"]},{"t":"借共同处境与具体利害化解队伍内历史积怨","d":"面对由历史社会关系造成的内部分裂——家族式支部、县区乡地方主义、土客籍数百年仇怨——先承认单靠讲道理至多发生几分效力；主要靠外部共同压迫使各方在斗争中有了共同利害；同时以具体处置消除现实损害：宣传不杀反水农民、责令退还没收财物、出布告保护；在此基础上党内加紧教育。","p":["井冈山的斗争"]}]},{"t":"在总体劣势下集中力量求局部优势","d":"面对整体力量不如对方的局面，不谋求各处同时取胜，而把力量集中到能造成有利对比的局部；性质不同的力量按其适用方式分别配置；活动范围以自身实有力量为限，不因外部估计过大而铺得过广。","sub":[{"t":"按敌我力量对比集中主力、分散地方武装","d":"面对总体上敌众我寡的作战问题，先看清对方在稳定时期能集中大量军力、分兵必被各个击破；据此定红军以集中为原则，只在能造成有利对比时出战——击小于我、等于我或稍大于我之敌；同时按武装性质分别配置，赤卫队以分散为原则；并据实有力量拒绝纵横数千里的过广游击区域。","p":["井冈山的斗争"]}]},{"t":"以最小单元的组织质量决定整体稳固","d":"一个处在高压环境中的组织，其不溃散的程度不取决于总体规模，而取决于领导力量是否深入到最小单元、单元内成员是否可靠。应把组织建到最小单元并配以专责人员；当规模掩盖质量时，宁可缩减数量以换取可靠性。","sub":[{"t":"把党组织建到最基层单位并以质量标准整顿成分","d":"面对成分复杂、伤亡大、易被投机分子渗透的组织，一面把组织建到最小单元：连有支部、班有小组，连一级设党代表兼支部书记，督促政治训练与民运；一面在挫折暴露渗透后厉行洗党，严格限制成分，问题最重的县党组织全部解散重新登记，并由公开转为秘密。党员数量大减而战斗力反而增加。","p":["井冈山的斗争"]}]},{"t":"按后果调整打击范围以扩大可团结面","d":"确定打击对象时不只依原则划线，还要看打击造成的实际后果：打击面过宽会把本可中立或争取的部分推到对立面，使自己陷于孤立；因此应据实际后果收缩打击边界，并以对象的现实反应检查这一收缩是否恰当。","sub":[{"t":"按打击后果收缩打击面以争取中间阶级","d":"面对打击面过宽的问题，先把农村分为大中地主、小地主富农的中间阶级、中农贫农三层，看清全部没收使中间阶级与豪绅同被打击；再考察后果——延宕分田、隐瞒土地，白色恐怖一到即反水带路，贫农成了孤军；据此改变过左政策，停止对中等商人的没收滥派，并以商人不再畏避、圩场恢复为凭据。","p":["井冈山的斗争"]}]},{"t":"形式建立不等于制度生效","d":"一个新制度即使在形式上普遍建立，也可能因旧习惯和图省便而空转。判断它是否成立要看实际权力关系是否按制度运行；使其真正生效，须查明习惯性阻力、补足对新制度的说明，并让它在实际事务中显出效力。","sub":[{"t":"使新政治制度名实相符","d":"面对政权已普遍组织而名不副实的局面，先查明实际运行：许多地方无代表会，有者仅作临时选举机关，大权揽于委员会乃至几名驻会人员；再查明原因——缺乏对新制度的宣传教育、独裁恶习深中头脑、遇事贪图便利；据此制订各级代表会组织法、经常建立士兵代表会，并规定党的主张须通过政府组织执行。","p":["井冈山的斗争"]}]},{"t":"在分类与根源追溯中识别和纠正偏差","d":"面对一类复杂的偏差或错误，先按性质分门别类，对每类追索其产生来源，再据来源定纠正办法，使判断与处置建立在\"现象—根源\"对应之上，而非仅凭总体印象。","sub":[{"t":"以“表现—来源—纠正”逐类诊断错误思想","d":"面对混杂的党内错误思想，不笼统批评，而逐类处理：先具体列出表现，再追溯社会阶级或认识来源，最后针对来源给出纠正方法，使纠正有的放矢而非泛泛而谈。","p":["关于纠正党内的错误思想"]}]},{"t":"通过思想教育改造认识与立场","d":"对源于认识偏差与错误立场的问题，首要以思想教育与提高认识水平着手，从观念根子上促其转变，而非仅以外在约束应付表象。","sub":[{"t":"以政治教育和思想改造从根源上纠正错误观念","d":"对根子在认识水平与立场的错误观念，以教育为主：提高党内政治水平、肃清理论根源、加紧政治训练、从思想上纠正倾向，并在教育中说清其社会阶级来源，使党员自觉转变立场而非仅受纪律约束。","p":["关于纠正党内的错误思想"]}]},{"t":"通过组织纪律与集中指导规范行为","d":"对破坏组织秩序的行为，以明确的组织原则与纪律（集中指导下的民主、少数服从多数、按程序批评）来规范，使集体行动有统一方向与约束。","sub":[{"t":"以集中指导下的民主生活和纪律规范组织行为","d":"针对极端民主化与非组织观点，实行集中指导下的民主生活：领导机关拿出正确路线与办法、明了下情、决议坚决执行、迅速传达、下级充分讨论以求理解；同时以少数服从多数、开会尽量发表意见、批评须有且针对政治组织错误等纪律规范组织行为。","p":["关于纠正党内的错误思想"]}]},{"t":"通过制度与成分改造将原则固化为结构与基础","d":"将正确原则以法规制度与组织成分改造加以固化，使关系与行为由结构和基础保障，而非仅靠一时教育或口头要求。","sub":[{"t":"以制度法规建设固化正确关系并约束行为","d":"对易反复的正确关系（军政、军民、官兵、士兵会与机关），编制红军法规明文规定各自任务与关系；对盲动主义残余，从制度上和政策上纠正盲动行为，把原则以法规形式固定，减少因人而异的随意性。","p":["关于纠正党内的错误思想"]},{"t":"从组织成分上削弱错误思想的下层基础","d":"针对错误思想的社会成分基础（俘虏兵带来的雇佣思想、游民成分带来的流寇思想），从组织上削弱其根源：由地方政权选派有斗争经验的工农分子加入红军，争取工农积极分子改变队伍成分，从下层基础削弱错误思想滋生土壤。","p":["关于纠正党内的错误思想"]}]},{"t":"以相对关系与内在实质作估量","d":"判断某一方力量或形势的强弱，不用绝对标准，也不凭表面印象：一面把它与对立方放在同一关系中相对比较，并参照可比情境；一面把现象只当作入门的向导，进一步把握其内在实质，据此得出既不夸大也不缩小的估量。","sub":[{"t":"在敌我相对对比与实质分析中估量形势","d":"估量形势先防两种相反偏差：看大己方、看小对方走向盲动，反之走向悲观。不用绝对标准判断强弱，而把双方力量放在同一关系中相对比较，并参照可比情境；对己方与对方都不停留在表面现象，把现象只当作入门的向导，进门后抓住实质；再用已发生的事实检验估量，避免被一时的表面情况迷惑。","p":["星星之火，可以燎原"]}]},{"t":"依据内在矛盾的实际发展判断趋势","d":"判断一种趋势是否正在临近，先找出引起这一趋势的各种矛盾，逐项察看它们是否真正在向前发展并相互推动；矛盾普遍发展则趋势不可避免，其临近程度亦可由已发生的实际变动加以估计，而非凭表象或愿望推断。","sub":[{"t":"以引起趋势的各种矛盾是否发展判断其临近","d":"判断某一趋势是否快要到来，不凭一时的、特殊的、小的环境，也不凭愿望，而详细察看引起它的各种矛盾是否真正向前发展：逐项列出各对矛盾，说明它们如何相互推动、逐层扩大；矛盾普遍发展则趋势不可避免，再以实际已经出现的活动量估计其距离到来还有多远。","p":["星星之火，可以燎原"]}]},{"t":"由对象的根本性质解释特殊现象并推定做法","d":"一种主张若与实情不合，根源常在于误认了对象的根本性质。应先确认这一性质，用它统一解释那些看似反常的特殊现象，再据此否定与性质不适应的做法，确定与之相适应的路线，使做法由对象性质而非一般常理决定。","sub":[{"t":"从对象的根本性质推定适合的路线","d":"面对一种流行却与实情不合的理论，先追问其根源是否在于误认了对象的根本性质；确认根本性质后，用它逐项解释在此性质下才会出现的特殊现象；再据这些现象否定与性质不适应的做法，确定与之相适应的路线，并把路线落实为可执行的发展次序与推进方式。","p":["星星之火，可以燎原"]}]},{"t":"对未来只判定方向与趋近程度，不机械规定时日","d":"对尚未发生的发展变化，只能指出大的方向和它已经临近到什么程度，不应机械规定实现的时日；同时方向判断必须保有行动意义，而不是可望不可即的空的可能性。","sub":[{"t":"以大方向和临近征象代替对时点的规定","d":"对尚未发生的发展变化只说出大的方向，不机械规定实现的时日；回头检查已作的预计，指出定期这类规定是错误的，并说明它会给方向判断带上急躁性。同时不把方向判断降为\"有到来之可能\"这种没有行动意义的空话，而以可观察的临近征象说明其确定性与远近。 # Method Dedup Index 本文件是 Theory Layer 的候选导航索引，按 `Primary L2 → L1 → Evidence 出处 + 可选 Related L2` 组织，不代表正式理论结论。 **批次：** 01…","p":["星星之火，可以燎原"]}]},{"t":"按客观形势状态确定相应策略","d":"面对行动策略的选择，不固守一套做法，而先辨识客观形势处于何种状态；不同状态对应不同策略，形势转换则策略随之切换，错配形势与策略必致失败。","sub":[{"t":"依统治阶级形势确定割据战略与推进方式","d":"面对割据在不同形势下的战略选择，先判定统治阶级是暂时稳定还是政治破裂；稳定时敌联合\"进剿\"，须集中红军、相机应敌、波浪式推进、反对分兵冒进；破裂时乘机发展，但仍须建立中心区域的坚实基础。八月失败证明形势误判致战略错用必败，战略边界由客观形势而非抽象常理决定。","p":["中国的红色政权为什么能够存在？","井冈山的斗争"]},{"t":"按环境与领导条件在集中与分兵之间切换","d":"不把集中或分散当作固定原则，先说明各自目的：集中为消灭大一点的敌人、占领城镇，从而发动大范围群众、建立数县联片政权；分兵为更能争取群众、深入土地革命、扩大武装。再定条件：环境恶劣、领导不健全时须集中，只有较好环境与比较健全的领导机关两个条件下才可远距离分兵；达不到目的则不如不分。","p":["星星之火，可以燎原"]}]},{"t":"按内部差别分解整体","d":"面对成分复杂的整体，不能用一个总名称代替内部差别。应先找出决定内部差异的关键条件，把整体分解为可区分的部分，比较各部分的处境，得出有差别的结论与有差别的对待，而不是对整体给出单一评价。","sub":[{"t":"在同一群体内部按境况细分并排出可依靠次序","d":"当总名称掩盖内部差别时不停留在大类结论上：找出区分内部差别的关键指标（是否有余剩、是否自给、生活升降，是否占有土地、农具与资金），据此把整体分成若干可辨认的部分；比较各部分处境的艰难程度，排出可依靠程度次序，标出左翼、中间与右翼；再确定重点争取对象。","p":["中国社会各阶级的分析"]},{"t":"区分农民阶层以识别革命主力","d":"面对笼统的\"农民\"概念，按经济地位把农民分为富农、中农、贫农，分别考察其对革命的态度与行动：富农始终消极、中农游移后加入、贫农最革命并掌握领导权；再以调查数据（贫农占人口百分之七十）确定谁是运动的先锋与中坚，据以决定依靠谁、团结谁、警惕谁。","p":["湖南农民运动考察报告"]}]},{"t":"调查先于结论的问题解决","d":"面对众说纷纭、责难四起的群众运动，先放下二手成见与阶层立场带来的道理，亲自到现场取得第一手材料再作判断；用实地事实核对各类议论，使结论建立在可核验的经验之上，而非预设立场。","sub":[{"t":"实地调查以掌握运动真实状况","d":"面对对一场群众运动众说纷纭、责难四起的局面，先放下在城里绅士阶级那里听得的道理，亲自到运动发生地召集有经验的农民和农运同志开调查会，仔细听报告、看实况，用第一手材料核对各种议论。只有跑到乡村里去看过一遍，才能对运动性质作出可靠判断，不被\"糟得很\"的满城风雨议论裹挟。","p":["湖南农民运动考察报告"]},{"t":"以社会经济调查替代主观主义的分析与指导","d":"针对主观主义的分析与指导，改用马列方法作政治形势分析与阶级估量，注重社会经济调查和研究以决定斗争策略与工作方法；强调离开实际调查会堕入空想盲动，党内批评须有、注意政治。","p":["关于纠正党内的错误思想"]}]},{"t":"在同一组条件下比较备选以择优","d":"面对\"应在何处立足\"的选择，不凭单一优点或就近取便，而先确定这类立足点所依赖的同一组条件，用它对全部备选逐项比较，取综合条件最好者；同时明说所选者的短处，使选择不被优点掩盖。","sub":[{"t":"在同一组条件下比较备选区域以确定割据中心","d":"面对在何处立足的选择，先走遍整个可选区域，再用同一组条件逐项比较各段：地势可否进守、与大政治都会的距离、群众基础、党的组织基础、地方武装经验、有无军事根据地、对邻省下游的政治影响；据此判定中段优于南北两段，并同时明说所选之处割据已久、\"围剿\"军多、现金困难等缺点。","p":["井冈山的斗争","星星之火，可以燎原"]}]},{"t":"从客观地位推断立场","d":"面对\"谁可依靠、谁会反对\"这类判断问题，不以对象的自我宣称、口号或身份名义为准，而以其在现实结构中的客观处境为依据，由处境推出其可能的态度，再据此确定对待方式。宣称只被当作处境的表现，而不是独立。","sub":[{"t":"依据客观经济地位判定敌友与依靠对象","d":"先把敌友判断确定为行动前必须解决的首要问题，再逐类列出全部相关群体；对每一类先考察其客观经济地位——是否占有生产资料、收入来源、受压迫程度——再由地位推断其对变革的态度；最后归入敌人、领导力量、最接近的朋友与动摇者，并对动摇者附加提防边界。态度自述只作为地位的表现。","p":["中国社会各阶级的分析"]}]},{"t":"在条件变化中判断可变态度","d":"对象的态度往往不是固定属性，而随外部形势的变化而变化。认识时须说明结论在何种条件下成立，分别给出不同条件下的判断，并用已经发生的事实检验这些判断，而不是把某一时点的表现当作对象的恒定性质。","sub":[{"t":"区分常态与高潮期判断中间力量的可变态度","d":"对态度不确定的中间群体不给固定标签，而分别设定两种条件下的判断：平时各部分态度各不相同；斗争潮流高涨时左派参加、中派亦可参加、右派受裹挟也只得附和。同时判断对立局面加剧时中间群体必然分化，没有保持\"独立\"的余地。判断作出后用已发生的运动经验检验，再决定争取还是提防。","p":["中国社会各阶级的分析"]}]},{"t":"以斗争阶段判定行动边界","d":"面对被指责\"过火\"\"过分\"的行动，不孤立评判单个举动，而把它放回运动所处阶段考察；在旧秩序须被彻底推翻的阶段，非常手段具有正当性，行动边界由当前斗争任务而非抽象常理决定。","sub":[{"t":"以革命阶段判定过火行动的正当性","d":"面对\"农会举动太过分\"\"矫枉过正\"的责难，不孤立评判单个举动，而把它放回运动所处阶段（第二时期即革命时期）考察：此时期必须建立农民绝对权力、镇压反革命派，短时期\"恐怖现象\"非如此不能造成。所谓过分本是土豪劣绅自己逼出来的，农民惩罚轻重极有分寸。结论：矫枉必须过正，不过正不能矫枉。","p":["湖南农民运动考察报告"]}]},{"t":"用系统事实枚举回应定性指责","d":"面对笼统的定性指责，不陷入抽象辩驳，而把对象行动系统分类、逐条枚举为可核验的事实清单，以具体内容证明其性质，使指责在事实面前失去依据。","sub":[{"t":"系统枚举事实清单回应定性指责","d":"面对\"农会做了许多坏事\"的笼统指责，不陷入抽象辩驳，而把农民数月行动分类总计为十四件大事，逐一检视其内容与意义，用可查证的清单证明件件具有革命意义，把难以正面说清的争议转化为对具体事实的核对，使指责者在事实面前失去立足点。","p":["湖南农民运动考察报告"]}]},{"t":"按斗争主次确定先后次序","d":"面对多重任务同时展开，不平均用力，先解决决定全局的基干矛盾，其余在其胜利后自然推进；对次要或条件未熟者不强求、不硬推，避免给对立面以可乘口实。","sub":[{"t":"区分斗争主次与先后次序","d":"面对政治、经济、文化（族权神权夫权）多重斗争同时展开的局面，不平均用力：先集中破坏地主政治权力这一基干，经济斗争随之，家族神道男女关系的破坏须待政治经济利益胜利后自然发生。对迷信旧俗不施过早过大的生硬破坏，对群众用\"引而不发\"启发自觉而非包办。","p":["湖南农民运动考察报告"]}]},{"t":"以群众可接受的形式启发自觉","d":"面对教育与启蒙困难，用对象熟悉、易接受的极简形式传递核心主张，并以启发代替包办，让对象在自身经验中形成自觉，而非由外部强迫替代其行动。","sub":[{"t":"用极简形式实现群众政治自觉","d":"面对乡村文盲普及、政治教育极难的困难，不依赖正规法政学校，而用简单标语、图画、讲演把\"打倒帝国主义\"等口号不翼而飞地送入男女老少头脑；再对迷信以启发代替包办——向农民讲清帝君大士打不倒土豪，让农民自己笑起来、自己丢菩萨，以群众可接受的形式促成其自觉。","p":["湖南农民运动考察报告"]}]},{"t":"以必要条件集合判断事物能否存在发展","d":"面对\"某事物能否在不利环境中长期存在\"类判断，不靠情绪，而把能否成立化为若干必要条件：先识别独特前提，再列出存在发展所依赖的各项条件并逐项说明，以条件是否具备作判断；亦可反向用于识别并落实存续所需的关键条件。","sub":[{"t":"红色政权存在的必要条件结构分析","d":"面对\"一小块红色政权能否在白色包围中长期存在发展\"的判断，先区分其发生前提（白色政权间长期分裂战争，源于半殖民地、地方农业经济与帝国主义分裂政策）与存在发展条件，再逐项列出五条必要条件（分裂战争、民主革命影响地区、全国革命形势向前、相当力量正式红军、党组织有力政策不误），以\"条件具备则存在无疑\"作判断。","p":["中国的红色政权为什么能够存在？"]},{"t":"巩固军事根据地的三项物质准备","d":"面对长期立足的根据地如何巩固，先识别其存续依赖的关键物质条件（防御工事、粮食储备、医疗保障），再逐项落实（修工事、储粮食、建医院），使根据地能在敌封锁与进攻中坚持；物质保障缺一则难坚持。","p":["中国的红色政权为什么能够存在？"]}]},{"t":"以现实关系的改变而非说服改变态度","d":"人的态度与主动性主要由其在现实关系中的地位和利害决定，单纯说理作用有限。要改变态度，应改变其在组织中的地位与权利，或使各方处于共同的处境与利害之中，并以具体处置消除现实损害；说服与教育在此基础上才真正起效。","sub":[{"t":"以军队内部关系的改造取代雇佣关系","d":"面对物质极端菲薄、成分复杂的队伍如何维持战斗力，不靠增加供给而改造内部关系：废除雇佣制，使士兵为自己而非为他人打仗；官长不打士兵、官兵待遇平等、经济公开、士兵有开会说话自由并自管伙食；从军长到伙夫一律同等待遇。俘虏兵过来即被熔化，同一个兵在敌军不勇敢、在红军很勇敢。","p":["井冈山的斗争"]},{"t":"借共同处境与具体利害化解队伍内历史积怨","d":"面对由历史社会关系造成的内部分裂——家族式支部、县区乡地方主义、土客籍数百年仇怨——先承认单靠讲道理至多发生几分效力；主要靠外部共同压迫使各方在斗争中有了共同利害；同时以具体处置消除现实损害：宣传不杀反水农民、责令退还没收财物、出布告保护；在此基础上党内加紧教育。","p":["井冈山的斗争"]}]},{"t":"在总体劣势下集中力量求局部优势","d":"面对整体力量不如对方的局面，不谋求各处同时取胜，而把力量集中到能造成有利对比的局部；性质不同的力量按其适用方式分别配置；活动范围以自身实有力量为限，不因外部估计过大而铺得过广。","sub":[{"t":"按敌我力量对比集中主力、分散地方武装","d":"面对总体上敌众我寡的作战问题，先看清对方在稳定时期能集中大量军力、分兵必被各个击破；据此定红军以集中为原则，只在能造成有利对比时出战——击小于我、等于我或稍大于我之敌；同时按武装性质分别配置，赤卫队以分散为原则；并据实有力量拒绝纵横数千里的过广游击区域。","p":["井冈山的斗争"]}]},{"t":"以最小单元的组织质量决定整体稳固","d":"一个处在高压环境中的组织，其不溃散的程度不取决于总体规模，而取决于领导力量是否深入到最小单元、单元内成员是否可靠。应把组织建到最小单元并配以专责人员；当规模掩盖质量时，宁可缩减数量以换取可靠性。","sub":[{"t":"把党组织建到最基层单位并以质量标准整顿成分","d":"面对成分复杂、伤亡大、易被投机分子渗透的组织，一面把组织建到最小单元：连有支部、班有小组，连一级设党代表兼支部书记，督促政治训练与民运；一面在挫折暴露渗透后厉行洗党，严格限制成分，问题最重的县党组织全部解散重新登记，并由公开转为秘密。党员数量大减而战斗力反而增加。","p":["井冈山的斗争"]}]},{"t":"按后果调整打击范围以扩大可团结面","d":"确定打击对象时不只依原则划线，还要看打击造成的实际后果：打击面过宽会把本可中立或争取的部分推到对立面，使自己陷于孤立；因此应据实际后果收缩打击边界，并以对象的现实反应检查这一收缩是否恰当。","sub":[{"t":"按打击后果收缩打击面以争取中间阶级","d":"面对打击面过宽的问题，先把农村分为大中地主、小地主富农的中间阶级、中农贫农三层，看清全部没收使中间阶级与豪绅同被打击；再考察后果——延宕分田、隐瞒土地，白色恐怖一到即反水带路，贫农成了孤军；据此改变过左政策，停止对中等商人的没收滥派，并以商人不再畏避、圩场恢复为凭据。","p":["井冈山的斗争"]}]},{"t":"形式建立不等于制度生效","d":"一个新制度即使在形式上普遍建立，也可能因旧习惯和图省便而空转。判断它是否成立要看实际权力关系是否按制度运行；使其真正生效，须查明习惯性阻力、补足对新制度的说明，并让它在实际事务中显出效力。","sub":[{"t":"使新政治制度名实相符","d":"面对政权已普遍组织而名不副实的局面，先查明实际运行：许多地方无代表会，有者仅作临时选举机关，大权揽于委员会乃至几名驻会人员；再查明原因——缺乏对新制度的宣传教育、独裁恶习深中头脑、遇事贪图便利；据此制订各级代表会组织法、经常建立士兵代表会，并规定党的主张须通过政府组织执行。","p":["井冈山的斗争"]}]},{"t":"在分类与根源追溯中识别和纠正偏差","d":"面对一类复杂的偏差或错误，先按性质分门别类，对每类追索其产生来源，再据来源定纠正办法，使判断与处置建立在\"现象—根源\"对应之上，而非仅凭总体印象。","sub":[{"t":"以“表现—来源—纠正”逐类诊断错误思想","d":"面对混杂的党内错误思想，不笼统批评，而逐类处理：先具体列出表现，再追溯社会阶级或认识来源，最后针对来源给出纠正方法，使纠正有的放矢而非泛泛而谈。","p":["关于纠正党内的错误思想"]}]},{"t":"通过思想教育改造认识与立场","d":"对源于认识偏差与错误立场的问题，首要以思想教育与提高认识水平着手，从观念根子上促其转变，而非仅以外在约束应付表象。","sub":[{"t":"以政治教育和思想改造从根源上纠正错误观念","d":"对根子在认识水平与立场的错误观念，以教育为主：提高党内政治水平、肃清理论根源、加紧政治训练、从思想上纠正倾向，并在教育中说清其社会阶级来源，使党员自觉转变立场而非仅受纪律约束。","p":["关于纠正党内的错误思想"]}]},{"t":"通过组织纪律与集中指导规范行为","d":"对破坏组织秩序的行为，以明确的组织原则与纪律（集中指导下的民主、少数服从多数、按程序批评）来规范，使集体行动有统一方向与约束。","sub":[{"t":"以集中指导下的民主生活和纪律规范组织行为","d":"针对极端民主化与非组织观点，实行集中指导下的民主生活：领导机关拿出正确路线与办法、明了下情、决议坚决执行、迅速传达、下级充分讨论以求理解；同时以少数服从多数、开会尽量发表意见、批评须有且针对政治组织错误等纪律规范组织行为。","p":["关于纠正党内的错误思想"]}]},{"t":"通过制度与成分改造将原则固化为结构与基础","d":"将正确原则以法规制度与组织成分改造加以固化，使关系与行为由结构和基础保障，而非仅靠一时教育或口头要求。","sub":[{"t":"以制度法规建设固化正确关系并约束行为","d":"对易反复的正确关系（军政、军民、官兵、士兵会与机关），编制红军法规明文规定各自任务与关系；对盲动主义残余，从制度上和政策上纠正盲动行为，把原则以法规形式固定，减少因人而异的随意性。","p":["关于纠正党内的错误思想"]},{"t":"从组织成分上削弱错误思想的下层基础","d":"针对错误思想的社会成分基础（俘虏兵带来的雇佣思想、游民成分带来的流寇思想），从组织上削弱其根源：由地方政权选派有斗争经验的工农分子加入红军，争取工农积极分子改变队伍成分，从下层基础削弱错误思想滋生土壤。","p":["关于纠正党内的错误思想"]}]},{"t":"以相对关系与内在实质作估量","d":"判断某一方力量或形势的强弱，不用绝对标准，也不凭表面印象：一面把它与对立方放在同一关系中相对比较，并参照可比情境；一面把现象只当作入门的向导，进一步把握其内在实质，据此得出既不夸大也不缩小的估量。","sub":[{"t":"在敌我相对对比与实质分析中估量形势","d":"估量形势先防两种相反偏差：看大己方、看小对方走向盲动，反之走向悲观。不用绝对标准判断强弱，而把双方力量放在同一关系中相对比较，并参照可比情境；对己方与对方都不停留在表面现象，把现象只当作入门的向导，进门后抓住实质；再用已发生的事实检验估量，避免被一时的表面情况迷惑。","p":["星星之火，可以燎原"]}]},{"t":"依据内在矛盾的实际发展判断趋势","d":"判断一种趋势是否正在临近，先找出引起这一趋势的各种矛盾，逐项察看它们是否真正在向前发展并相互推动；矛盾普遍发展则趋势不可避免，其临近程度亦可由已发生的实际变动加以估计，而非凭表象或愿望推断。","sub":[{"t":"以引起趋势的各种矛盾是否发展判断其临近","d":"判断某一趋势是否快要到来，不凭一时的、特殊的、小的环境，也不凭愿望，而详细察看引起它的各种矛盾是否真正向前发展：逐项列出各对矛盾，说明它们如何相互推动、逐层扩大；矛盾普遍发展则趋势不可避免，再以实际已经出现的活动量估计其距离到来还有多远。","p":["星星之火，可以燎原"]}]},{"t":"由对象的根本性质解释特殊现象并推定做法","d":"一种主张若与实情不合，根源常在于误认了对象的根本性质。应先确认这一性质，用它统一解释那些看似反常的特殊现象，再据此否定与性质不适应的做法，确定与之相适应的路线，使做法由对象性质而非一般常理决定。","sub":[{"t":"从对象的根本性质推定适合的路线","d":"面对一种流行却与实情不合的理论，先追问其根源是否在于误认了对象的根本性质；确认根本性质后，用它逐项解释在此性质下才会出现的特殊现象；再据这些现象否定与性质不适应的做法，确定与之相适应的路线，并把路线落实为可执行的发展次序与推进方式。","p":["星星之火，可以燎原"]}]},{"t":"对未来只判定方向与趋近程度，不机械规定时日","d":"对尚未发生的发展变化，只能指出大的方向和它已经临近到什么程度，不应机械规定实现的时日；同时方向判断必须保有行动意义，而不是可望不可即的空的可能性。","sub":[{"t":"以大方向和临近征象代替对时点的规定","d":"对尚未发生的发展变化只说出大的方向，不机械规定实现的时日；回头检查已作的预计，指出定期这类规定是错误的，并说明它会给方向判断带上急躁性。同时不把方向判断降为\"有到来之可能\"这种没有行动意义的空话，而以可观察的临近征象说明其确定性与远近。 --- # Method Dedup Index（07–12 批次） **批次：** 07–12（每 6 篇一个独立 method index 文件） **当前覆盖：** 第 07–12 篇 · 6 篇 Evidence · 《反对本本主义》…","p":["星星之火，可以燎原"]}]},{"t":"以可控的经济组织与杠杆动员群众经济力量","d":"面对外部约束（封锁、中间剥削）或内部力量分散，不能听任自发市场，而应以可控的组织化手段（贸易管理、公共金融、合作社、可控经济成分）把分散的经济力量纳入目标；计划性与适度边界（非专卖、非全管）是关键。","sub":[{"t":"以计划贸易统制打破封锁抵制剥削","d":"面对白区封锁与商人在出入口中的高额剥削（如谷价七倍、盐价悬殊），不能放任不管。须设对外贸易局、粮食调剂局，一方面在红色区域内把有余地的粮食调到不足地、平抑地区差价，另一方面有计划（非无限制）地把多余粮食运出出口、从白区低价购入盐布必需品，打破封锁、抵制剥削、改善群众生活。","p":["必须注意经济工作","我们的经济政策"]},{"t":"以公债与合作社杠杆动员群众经济力量","d":"以三百万元经济建设公债为杠杆：一百万供红军作战费，两百万借合作社、粮食调剂局、对外贸易局做本钱，其中小部分发展生产、大部分发展出入口贸易；普遍建设谷仓、备荒仓，每县设粮食调剂分局、重要区圩场设支局。把群众经济力量组织起来，发展生产贸易、改良生活、增加财政收入，确切建立战争物质基础。","p":["必须注意经济工作","我们的经济政策"]},{"t":"在国营、合作社、私人并存中发展前两者以取得领导","d":"国民经济由国营、合作社、私人三成分组成，私人现时占绝对优势且将长期如此；政策在不违法范围内鼓励私人，同时尽量发展国营经济、大规模发展合作社经济，使两者配合经长期发展对私人逐渐占优势并取得领导地位。判断标准是可控组织成分能否持续壮大并导向主导，而非否定私人经济的现实作用。","p":["我们的经济政策"]}]},{"t":"以组织化协作统筹关键生产要素","d":"在关键部门面临分散的资源约束时，以自愿互利的合作组织形式（互助、合股、动员）把零散要素集中调度，比单纯号召更能突破瓶颈；组织化是弥补个体经济短板的可控手段，且不改变基本所有制。","sub":[{"t":"以农业为第一位并组织生产要素保障生产","d":"在苏区条件下农业为经济建设第一位，须同时解决粮食与棉麻蔗竹等原料。面对劳动力、耕牛、肥料、种子、水利等困难，组织劳动互助社与耕田队调剂劳动力、推动妇女参加生产，组织犁牛合作社合股买牛共用，视水利为农业命脉；并在小农基础上对重要农产作适当生产计划、动员农民努力。","p":["我们的经济政策"]}]},{"t":"以发展生产本身作为增收的根本来源","d":"把财政收入建立在被课税对象（经济本身）发展的基础上，而非竭泽而渔；收入增长与经济发展互相促进，财政需要服从于经济需要，二者形成正向循环而非对立。","sub":[{"t":"以发展国民经济为财政收入基本方针","d":"财政政策的基本方针是从发展国民经济来增加财政收入，而非单纯征集；国家银行发行纸币基本上应根据国民经济发展的需要，单纯财政需要只居次要地位。增收与经济发展互为促进，财政须服务于经济需要。","p":["我们的经济政策"]}]},{"t":"以节约与禁绝浪费约束公共支出","d":"公共资源的支出须以节约为绝对原则，把贪污浪费提升至“犯罪”高度以确立刚性约束；节约不是消极克扣，而是把有限资源集中投向主导任务，体现公共资源使用的方向纪律。","sub":[{"t":"以节省与反浪费为财政支出铁律","d":"财政支出根据节省方针，使政府人员明白贪污和浪费是极大的犯罪；节省每一个铜板为着战争与经济建设是会计制度原则；国家收入的使用方法应与国民党方法严格区别。","p":["我们的经济政策"]}]},{"t":"以实际调查作为认识的出发点","d":"认识的起点应是客观实际情况与历史材料，而非脱离材料的纯主观推想；判断与结论的正确依赖于对实际材料的占有，调查是消除唯心指导的根本手段。","sub":[{"t":"调查先于结论的问题解决","d":"面对不能解决的问题，先调查其现状与历史，完全调查明白后办法自然产生；一切结论产生于调查末尾，而非先于调查冥思苦索“想办法”。可实地走访学“每事问”，或召集明了情况者开调查会弄清来源与现状。","p":["反对本本主义"]},{"t":"以实际调查洗刷唯心工作指导","d":"估量政治形势、指导斗争前必须作实际调查；离开实际调查去估量形势、指导工作，必是空洞唯心的，导致机会主义或盲动主义错误。须努力作实际调查洗刷唯心精神，防止错误，才能完成争取群众、战胜敌人的任务。","p":["反对本本主义"]}]},{"t":"以明确对象与目的组织调查","d":"组织调查时先确定清晰的研究对象与最终目的，通过结构化解剖取得可用估计再据以决定行动；目的不清则调查流于表面，无助于核心决策。","sub":[{"t":"以社会各阶级为对象的阶级估量调查","d":"社会经济调查以社会各阶级（而非片断现象）为对象，既调查农村也调查城市；通过解剖各阶级及其相互关系，得正确阶级估量，据以定出斗争策略，分清革命主力、同盟者与要打倒的对象。","p":["反对本本主义"]}]},{"t":"把理论与权威置于实际检验之下","d":"真理或正确指示的根据不在其来源（书本、上级、权威），而在是否适合具体客观情势并为实践所证明；既有理论须与具体情况结合，反对脱离实际的教条式沿用。","sub":[{"t":"把本本与上级指示置于实际检验之下","d":"判断上级指示或理论“本本”是否正确，不看其来源（上级机关、马克思“先哲”之名），而看内容是否适合斗争客观主观情势、是否为实践所证明。学习马克思主义但须同本国实际结合；盲目执行上级、一味拿本本是形式主义，须纠正为本本与实际结合。","p":["反对本本主义"]}]},{"t":"以规范操作保证调查可靠","d":"为使调查所得近于正确，须以规范化的操作程序约束过程，降低个人见闻局限与主观偏差带来的误差。","sub":[{"t":"按七项技术开展实际调查","d":"开展实际调查须遵循七项技术：开调查会作讨论式调查；到会人须深切明了社会经济情况；人数依指挥能力定、至少三人；事先定调查纲目（大纲含细目）；指导者亲身出马不单靠书面报告；初次深入一处或一题；调查人自己做记录不假手于人。","p":["反对本本主义"]}]},{"t":"在总任务下确定具体工作的从属与服务定位","d":"面对多任务情境，须识别主导任务并据以确定各具体工作的从属地位与服务方向；既不可因次要而弃之，亦不可本末倒置。判断标准始终是“是否服务于主导任务”，而非任务本身的重要性宣称。","sub":[{"t":"围绕中心任务统筹次级任务的定位","d":"当多项任务并存时，先确认当前中心任务，将具体工作（如经济建设）定位为环绕并服务于它的次级任务；同时反对两种偏差——以“忙不过来”取消次级任务（实为削弱中心），以及把次级任务倒置为当前中心而离开中心去推进。每一件具体工作都须检验其是否服务于中心任务。","p":["必须注意经济工作"]}]},{"t":"通过组织与说服把群众动员到中心任务","d":"要完成须群众参与的中心任务，须以组织体系（议程、督促检查、群众团体）把任务落到基层，并以面向群众的宣传把任务与群众切身利益相关连形成参与热情；动员方式须为群众可接受，按具体环境与真实群众情绪说服而非强制，才能保证工作巩固、得群众拥护。","sub":[{"t":"从组织上常议常查地动员群众","d":"把经济任务（发公债、合作社、调剂粮食、发展生产贸易）常列政府主席团、国民经济部、财政部议程，定期讨论、督促、检查；推动工会、贫农团等群众团体；以村屋群众大会宣传，讲明革命战争与经济建设的真实关系与改良生活的实际利益，把群众热情提起来。不如此组织动员则不能达到目的。","p":["必须注意经济工作"]},{"t":"以说服适应群众情绪替代命令主义动员","d":"动员群众不可用官僚主义方式。须识别两类官僚表现——不理不睬的怠工与表面努力实则蛮横派任务的命令主义；命令主义发展合作社、推销公债虽形式暂成却不能巩固、失信用。正确做法是努力宣传、说服群众，按具体环境与具体表现出来的群众情绪去发展合作社、推销公债、做一切经济动员。","p":["必须注意经济工作"]}]},{"t":"从实践斗争中识别与培养骨干","d":"完成艰巨任务所需的骨干并非外求或先天稀缺，而蕴含于经历实际斗争锻炼的群众之中；破除“无干部”的主观预设，在实践斗争中识别、组织并训练骨干。","sub":[{"t":"从群众斗争中识别与起用干部","d":"开展大规模经济运动需要几千几万干部。面对“没有干部”的叹气，须丢掉这一错误观点：干部并非稀缺，而是从土地斗争、经济斗争、革命战争中锻炼出来的群众里涌出。识别与起用干部的标准是实际斗争的锻炼，而非先设“无人”的前提。","p":["必须注意经济工作"]}]},{"t":"将关联任务协同纳入中心任务服务链","d":"完成中心任务须把若干相互关联的具体任务协同组织起来，使每项任务既独立成立又共同汇入对中心的服务；条件之间互相促进，整体指向主导任务。","sub":[{"t":"以任务联动协同服务于中心","d":"经济建设不能孤立推进，须与其他革命任务相互结合、共同服务于战争：深入查田运动消灭封建土地制以发展农业生产；坚决实行劳动法改善工人生活以加强其领导；正确领导选举与检举以健全政府；以文化教育提高群众政治文化水平；不忽略扩大红军。争取上述一切条件并都服务于革命战争，则胜利属我。","p":["必须注意经济工作"]}]},{"t":"以结构性多维要素的综合判定认识对象类别","d":"对复杂对象作类别判断时，不依赖单一可见属性，而同时考察其资源占有、从事活动与获益来源等多维结构性要素，并据核心区分维度解决模糊边界；分类的根据在于要素的组合而非名目。","sub":[{"t":"以占有、劳动与生活来源三维综合判定阶级成分","d":"面对农村阶级划分，不以名目或单一表象判定，而同时考察三维结构性要素：占有何种生产资料、本人是否参加劳动、生活来源主要靠自身劳动还是剥削他人（及剥削是否经常且为主要收入）。三者组合决定类别，对模糊情形以\"主要生活来源靠剥削、生活超过普通中农\"为决定判据归入地主，相邻边界以核心维度（是否出卖劳动力）区分。","p":["怎样分析农村阶级"]}]},{"t":"以实际满足切身需要换取对更高目标的支持","d":"要使对象接受并投入超出其直接利益的更高目标，反复号召与单纯宣传并不足够。须先把对象自身的实际困难当作自己应处理的事项逐项解决，形成真实的利益关联与信任；更高目标由这些切身事情引出，才可能被自愿接受和全力支持。","sub":[{"t":"以解决群众切身生活问题取得中心任务的动员力","d":"面对中心任务需要广泛动员却动员不起来的局面，不能只布置任务而不管群众生活。须查明群众最迫切的实际困难（缺柴、无盐、无房、缺米、疾病、失学、桥梁失修），把从土地劳动到柴米油盐的一切生活问题提到议事日程，逐项讨论、决定、实行、检查，并组织可用力量当场解决；使群众认识领导者与其呼吸相通，再由这些切身事情出发引出更高的中心任务。","p":["关心群众生活，注意工作方法"]}]},{"t":"以实际成效对照判定做法优劣并推广范例","d":"在同类条件下比较不同执行单位的实际结果，把结果差别归因于做法差别，据此判定做法优劣，而不以主张、名义或形式为准。经此判定的较优做法应确立为可学习的范例并推广，由已见成效者带动未见成效者。","sub":[{"t":"从正反实例的成绩差别中判定并推广领导方法","d":"判断领导方法是否可取，不看主张与形式，而取同一任务下不同执行单位作实际对照：一面是只布置任务、不理生活因而会开不成、成绩极少的地方，一面是解决群众具体困难因而扩红与公债成绩突出的地方。把成绩差别归因于方法差别，把成效最好的做法确认为模范并公开树立，反对与之相反的官僚主义方法；再以先进帮助薄弱，使模范由个别扩展为普遍。","p":["关心群众生活，注意工作方法"]}]},{"t":"把目标与实现手段作为同一问题解决","d":"确定目标之后，认识不能停留在目标本身；没有可行手段的目标等于空话，重复申明目标不产生结果。须把\"做什么\"与\"用什么办法做\"当作同一个问题同时解决，并以是否存在具体可行、且为执行对象所能接受的办法，作为目标能否成立的判据。","sub":[{"t":"提出任务的同时解决完成任务的方法","d":"提出任务后不得停留在重复号召——把任务念一千遍也不能成功。须在提出任务的同时把\"用什么办法完成\"作为并列问题处理：确认没有渡河手段则过河只是空话，据此为每项工作（扩红、查田、经济建设、文化教育、新区边区工作）找出实行时的具体办法；并以实际的具体的方法替代官僚主义方法，以耐心说服的方法替代命令主义方法。","p":["关心群众生活，注意工作方法"]}]},{"t":"以主要矛盾的变动重新划分对立面与可联合面","d":"当出现一个压倒性的主要对立力量时，各方之间的关系不再由既有属性和历史立场固定，而应按其与该主要对立面的现实利害重新排列；判定根据是当下的利害结构而非名目与成分。力量应集中于这一唯一目标，其余分歧转为可利用条件，判据是打击面最小、可联合面最大。","sub":[{"t":"依形势根本变动重估各阶级态度以确定策略任务","d":"面对形势的根本变动，先确定其基本特点（主要敌人及其目标的改变），再逐一考察各阶级与政治派别在新环境下的利害得失；对中间对象不按历史成分或固有弱点作固定判定，而检验该弱点在过去时期是否同样存在而当时结果相反、同类分裂在过去是否已实际发生；据此区分对象内部的不同部分，以动摇、中立、可能参加等分层结论代替一次性归类，最后汇总为营垒势力的消长并据以规定策略任务。","p":["论反对日本帝国主义的策略"]},{"t":"以主要敌人为准择敌并汇集一切可争取力量","d":"自身力量不足以单独取胜时，先确定当前唯一的最中心目标，集中射击而不分散目标，避免主要敌人没有打中而次要敌人甚至同盟军身上吃了子弹；再按与该目标的关系重划阵线：把过去是敌人而今日可能做友军的人拉过来，把对方营垒中的一切争斗、缺口、矛盾收集起来作为反对主要敌人之用，以是否有利于打击主要敌人判定他方行为的性质，由此把敌人驱逐到狭小孤立的阵地。","p":["论反对日本帝国主义的策略"]}]},{"t":"由相反两方面的分别估计综合出整体判断","d":"任何整体判断都须由分方面的分别判定综合得出，任一单方面的事实都不足以支持全局结论；对同一对象应同时给出相反两方面的估计并承认两者同为事实，行动方案须同时满足这两方面共同提出的要求，因而既不由有利面推出冒进，也不由不利面推出退缩。","sub":[{"t":"分方面判定成败并以两面估计确定策略","d":"面对对同一事实的对立评价，不接受笼统的整体断语，而把它分解到各具体方面上分别判定得失，再由全体作出结论；对同一形势同时给出相反两方面的估计并承认两者都是事实；策略须同时满足两方面提出的要求——据有利一面抛弃关门主义采取广泛联合，据不利一面防止冒险主义、不到决战时机不进行决战，阶段性转变亦以条件是否具备为标准而非以主观愿望提前。","p":["论反对日本帝国主义的策略"]}]},{"t":"以自身独立力量保证联合关系的可靠","d":"在与不稳定对象结成的联合中，联合能否维持不取决于对方的意愿或承诺，而取决于己方是否拥有不依赖对方的独立力量与在联合中的主导地位；应把扩充自身力量与保持批评权、主导权当作维持联合的条件，而不是把联合本身当作力量的替代。","sub":[{"t":"在联合中保持独立力量与领导权","d":"建立广泛联合时不把联合的可靠性寄托于同盟者的承诺。须同时：努力扩大自己的队伍并使之在政治上坚强，作为联合的中心支柱而不依仗暂时的同盟者；批评同盟者、揭破以革命或半革命面目出现的假革命，承担争取领导权的责任；对挑拨离间、威迫利诱、各个击破以同样的争取手段反制，容许受影响的坏分子退出而吸收对方队伍中可争取的人进来。判据是自身力量是否存在并发展。","p":["论反对日本帝国主义的策略"]}]},{"t":"以主导任务为准调整自身规则与容纳边界","d":"主导任务改变时，组织自身的成员范围与既有规则同样是待调整的对象，而不只是外部对象需要重新判断；调整的唯一判据是是否适合新的主导任务。但扩大容纳不等于改变性质，须同时确定不可让渡的底线与主体地位，使范围的扩大不消解自身成立的根据。","sub":[{"t":"依基本任务调整政权成分与政策边界","d":"基本任务改变时，组织的成员范围与既有政策不应固定不变。以\"是否适合于新的基本任务\"为唯一原则，把容纳范围扩大到一切愿意参加该任务的成分（包括只认同部分目标者），据此对过去的政策作适当修改并限定内部斗争的限度。同时划出不可让渡的边界：与主要敌人利益不可分离的成分不列入容纳范围；基本群众须占主体并保持领导；扩大范围不改变自身的性质。 --- # Method Dedup Index（13–18 批次） **批次：** 13–18（每 6 篇一个独立 method index 文件…","p":["论反对日本帝国主义的策略"]}]},{"t":"使主观指导符合客观实况的两段认识过程","d":"判断的可靠来自对对象材料的占有与加工：先取得材料，经去伪存真、由表及里的加工形成判断，并把双方条件的相互关系计入。这一过程不止于方案成立之时，方案执行本身构成第二次认识，须以新出现的实况检验原判断并据以改变原方案；符合的标准是在有决定意义的部分上符合。","sub":[{"t":"由必要侦察构成判断并在执行中重新认识情况","d":"承认错误的根源是主观指导与客观实在情况不相符合，据此把决策展开为一条来源链：使用一切可能的和必要的侦察手段取得对方材料，作去粗取精、去伪存真、由此及彼、由表及里的思索，再加上自己方面的情况，研究双方的对比和相互关系，构成判断、定下决心、作出计划。计划成立后须在执行中重新检查是否符合实况，不符合就依新的认识构成新判断、改变已定计划。","p":["中国革命战争的战略问题"]},{"t":"以感性材料的丰富合实际为前提经加工上升到理性认识","d":"面对\"如何从实践中形成正确理论认识\"的问题，先通过亲身实践取得十分丰富（非零碎不全）、合于实际（非错觉）的感觉材料；再将材料加以去粗取精、去伪存真、由此及彼、由表及里的改造制作，造成概念、判断、推理的系统，从感性认识跃进到理性认识；并在实践基础上把两阶段统一起来，反对割裂二者的唯理论与经验论。","p":["实践论"]}]},{"t":"按主要矛盾与次要矛盾地位的变化调整当前工作的中心","d":"当所处对象中的若干矛盾（问题）在整体里的主次地位随条件改变时，先确认当下哪一个是主要的、哪一些降为次要，再把当前工作的中心放到解决主要矛盾上；原主要者降次后转为服从地位并作相应调整。判断依据是其相对地位的变化，而非主观愿望或阶段未变时的随意转移。","sub":[{"t":"按主要矛盾地位的变化重新确定阶段中心任务","d":"面对长过程中任务重心的选择，先判定当前各种矛盾在其整体中的主次地位发生了什么变化：哪一对上升为主要矛盾、哪一对降为次要和服从。依据这一变化把当前阶段的中心任务转到解决主要矛盾上来，已降为次要的矛盾转为服从并作适当调整。不在阶段未变时随意转移重心，也不在矛盾比重已变时仍固守旧重心。","p":["中国共产党在抗日时期的任务"]},{"t":"在多个矛盾中找出起领导作用的主要矛盾","d":"研究存在两个以上矛盾的复杂过程时，不把诸矛盾平均看待，而用全力找出其中规定或影响其他矛盾存在和发展的那一个主要矛盾，其余置于次要和服从的地位，捉住它则一切问题迎刃而解。主次不是固定的：外部压迫采取战争形式时对外矛盾成为主要矛盾，内部矛盾暂降为次要；压迫改取较温和形式时内部矛盾又转为主要。每一阶段都须重新判定。","p":["矛盾论"]}]},{"t":"按对象的层级与阶段差别确定规律的适用范围","d":"任何规律都在一定的层级和一定的发展阶段上成立；上位层次的规律不能直接充当下位对象的行动依据，下位对象在共性之外另有自己的情形、性质与关联。接受一项现成结论前须先确定它是在哪一层次、哪一条件下得出的，再判断本对象是否落在其适用范围之内。","sub":[{"t":"按一般与特殊的层级分别研究战争指导规律","d":"面对既有成规与他处经验，先按包含关系建立层级：一般类别的规律、其中某一特殊类别的规律、更特殊的具体对象的规律，逐层追问该层次在情形、性质及其与外部事情的关联上有何不同；再按时间、性质、地域三个条件核对差别，判定哪些成规只是上位层次的规律因而不能呆板移用。对既有经验采取三步处理：着重学习其总结，用自己的经验考证结论，吸收用得着的、拒绝用不着的、增加自己特有的。","p":["中国革命战争的战略问题"]},{"t":"依现阶段条件承认自身形态并以条件变化为改变依据","d":"对自身被视为不体面的特征，不按理想形态否定，也不按现状固守。先确认它由什么条件产生，再判断这些条件在现阶段是否仍存在；仍存在就承认它是现阶段的长处并据此规定日程，不作长时期的具体计划。同时把该特征拆成两面：属于低级阶段遗留而在更高阶段有害的部分逐渐去掉，由现阶段条件决定而当前仍需要的部分必须坚持。改变的依据是条件本身的改变，而非主观上想要进入新阶段。","p":["中国革命战争的战略问题"]}]},{"t":"在总体劣势下按层级分置相反取值以造成可胜的局部","d":"总体力量对比不利，并不等于每一次具体较量都不利。应把总体与具体分为不同层级，允许同一对范畴在两个层级上取相反的值；据此使对方在总体上的优势在具体接触点上转为劣势，其余方向以最小配置维持，损失由主要方向的结果偿还。","sub":[{"t":"以兵力集中把战略上的劣势改变为战役上的优势","d":"承认总体对比上处于劣势和被包围的内线地位，但不把这一地位当作每次具体行动的既定条件。在同一时间内只确定一个主要使用方向，除地方部队和钳制兵力外把突击力量全部集中，对强敌用绝对优势、对弱敌用相对优势，从而把对方的一个大包围改为自己对其一部的许多小包围。相应反对力量平均分配的各种形式；同时保留边界：次要方向仍需钳制力量，配合性的分散力量不予取消。","p":["中国革命战争的战略问题"]},{"t":"按战略与战役两级分置持久与速决","d":"面对快与慢的争论，不在同一层级上取折中，而先判定两个层级各自的决定条件：总体过程的时间长度由双方力量消长规律决定，对方雄厚而己方逐渐生长就必须承认长期性；单次行动的时间长度由自身补给、对方数量与配置决定，补给无来源且对方部队密接就必须迅速解决。据此总体取持久、单次取速决，并为速决准备具体条件；同时各设一条限制：持久不许可无谓拖延，速决之下仍须反对不正当的急躁性。","p":["中国革命战争的战略问题"]}]},{"t":"由部分对整体的决定作用区分轻重","d":"整体不能脱离部分而独立，但各部分对整体的作用并不相等；有些部分的失败不改变整体，有些立即改变整体。轻重不能按事物的一般属性或表面规模判定，只能按当下具体条件确定哪些部分具有决定作用，并据此配置注意力与力量。整体性的关系不能被直接观察，只能由局部经验经思索而把握。","sub":[{"t":"以对全局有决定意义的关节确定指挥重心","d":"面对头绪繁多而精力有限的指导任务，先确认自己所负责的那个整体的边界，即哪些方面和哪些阶段必须由自己照顾；再区分各部分对整体的作用是否具有决定意义，其判定不按一般的或抽象的情况，而按当前具体情况逐一确定；然后把注意力的重心放在这些关节上，而不去忙次要问题。整体性的关系眼睛看不见，须以已有的局部经验为基础用心思索，最终把一切重要问题提到较高的原则性上去解决。","p":["中国革命战争的战略问题"]}]},{"t":"由两端偏差的共同根源确定正确做法的位置","d":"当同一问题上出现两种方向相反的错误时，正确做法不能由否定其中一端得出，也不是两端之间的折中。应先辨明两种偏差共同的发生机制，再把有关判断拆为成对的范畴，分别指明在哪一层次上肯定、在哪一层次上否定，从而得到带有适用层次与限度的方针。","sub":[{"t":"以成对的正反限定确立作战方针","d":"先找出实践中出现过的两种相反错误并指出其同源——轻视敌人与被敌人吓倒，一个只讲进攻不讲防御退却，一个采取非必要的退却，二者都在精神上解除了防御的武装，都由不按敌我实际对比作判断而来。再把方针拆成若干对范畴，逐对指明在哪一面上反对、在哪一面上承认，并注明层次。方针由此不落在任一极端，也不是两端的折中，而带有明确的层次与限度。","p":["中国革命战争的战略问题"]}]},{"t":"以暂时的局部让出换取力量对比的改变","d":"在总体上处于劣势时，力量对比不是固定的前提而是可以改变的结果。让出局部与一时的东西不是失败，而是取得改变对比所需条件的手段；判断得失不按单次、局部的增减，而按它是否使整体的、后续的对比向有利方向变化。因此让步须是有计划、有终点、有条件清单的，而不是被动的溃退。","sub":[{"t":"以有计划的退却创造转入反攻的条件","d":"在劣势而不能迅速击破对方进攻时，把退让当作有计划的步骤，目的是保存力量并造成对比关系的改变。先列出转入反攻所需的若干具体条件并规定至少取得二种以上，再在退让中逐项争取：依靠最有利的支持力量、选择利于己方的位置、使力量完全集中、发现对方最弱部分、使对方在深入中消耗疲劳、必要时人为造成对方过失。终点不预先固定，以整个形势为出发点确定；得失以局部暂时的丧失换全局长期的取得来换算。","p":["中国革命战争的战略问题"]}]},{"t":"由整个过程的预先推演确定起手的一步","d":"在由多个阶段衔接而成的过程中，起手一步的价值不由它自身的成败决定，而由它在整个过程中引起的变化决定。决定之前须对后续各步在成功与失败两种结果下的走向作大体推演，并把本过程之后的下一阶段一并计入；条件不足以支持这一推演时，宁可推迟起手也不冒然投入。","sub":[{"t":"以全战役和下一阶段的通盘计算决定初战","d":"对由若干相互衔接的行动构成的过程，先把同类过程的历次实例逐一列出，把每次的具体条件与最终结果对照，指出胜负所系的条件差别；据此确立三项要求：第一步必须有把握，条件不具备宁可退让、持重待机；第一步的方案必须是整个过程方案的有机序幕，动手前须设想此后各步及胜败两种结果引起的变化，凡不利于整个过程的胜利仍算失败；还须把下一阶段计入，反对走一步看一步。","p":["中国革命战争的战略问题"]}]},{"t":"以事实与后续行动检验言辞而非表面表述","d":"面对一方对自身或事件的言辞表述，不依其表面字句直接接受，而以其实际所指的具体事实与后续客观行动为判定依据；言辞是否可信，由事实与行动检验，不由表述者的自我定性或措辞决定。","sub":[{"t":"以对方自述承诺为标尺考察其后续行动","d":"面对对手公开的表态，先不依其措辞轻信，而将其自述中可取的具体承诺与条件列为待考察项；随后把判定标准交还给对方自己的诺言，以其撤兵后及今后实际行动是否不打折扣地兑现为准，而非以声明文字本身为准。作用：既避免空文搪塞，又给对手以可观察的诚信账本。边界：考察以对方自身承诺为尺，不另设无法验证的他求。","p":["关于蒋介石声明的声明"]},{"t":"按发言的虚实区分可取处与须揭批处","d":"评估一篇含混的政治文献，不整体褒贬，而先逐段判其虚实：对确有可取的具体表态（如\"言必信行必果\"一段）明确肯定；对含含糊糊、曲曲折折、不能满足人民要求的总体表述，指出其未能痛悔已往、开辟将来，不能满足要求。由此把\"值得赞扬\"与\"不能满需\"分别落位，避免以全概偏或以偏概全。","p":["关于蒋介石声明的声明"]},{"t":"以事实力量还原被对手歪曲的命名","d":"当对手用歪曲性名词（如\"反动派\"）指称某类势力却不说明所指，不以名词本身争辩，而列举该命名实际所指的具体事实力量（六类抗日与革命势力），据以揭示其真实性质恰与命名相反，并正告对方改正命名使其名副其实。作用：以事实拆穿命名颠倒，而不陷入语义空战。","p":["关于蒋介石声明的声明"]}]},{"t":"以有原则有限度的让步换取建立统一战线的必要前提","d":"为取得合作联盟所需的共同前提，可以作出让步，但让步须是原则性与有限度的：明确列出让出的具体内容，并规定不可让出的底线（核心领导与独立性）。得失不按单次局部增减计，而按是否换得更大的共同目标。超过底线的让步不被允许。","sub":[{"t":"以有原则有限度的让步换取统一战线的共同前提","d":"为建立全民族所需的共同前提（和平、民主、抗战），可向同盟者作出让步，但让步必须是有原则、有限度的：先列出愿意作出的具体保证（如改变政权军队名称、停止某些方针），同时明确规定不让步的底线——保持自身在特区与军队中的领导权和独立性、批评自由。超过限度的让步不许可。让步是两党的，对方也须抛弃内战独裁不抵抗政策。不把这种让步误认为投降，也不因怕被骂而拒绝必要让步。","p":["中国共产党在抗日时期的任务"]}]},{"t":"在联盟内部按共同总任务区分应停止与应保留的矛盾斗争","d":"在合作联盟内部，局部矛盾与斗争难以完全消除，但应依据联盟的共同总任务设一道标准：凡削弱该总任务的矛盾斗争予以停止，凡增强该总任务的予以保留。判断不属于各矛盾自身的一般性质，而只看它与总任务的关系。","sub":[{"t":"按是否有利于团结抗日区分应停与应存的矛盾斗争","d":"在统一战线（合作联盟）内部，阶级间、党派间、集团间的矛盾和斗争无法避免，但应按一条总原则区分处理：凡是削弱团结抗日的斗争（国内战争、党派敌对、地方割据、过火经济要求等）应当停止；凡是有利于团结抗日的斗争（批评自由、党派独立性、人民政治经济条件改善等）应当保存。区分标准只有一个——是否有助于抗日民族统一战线的增强和扩大。","p":["中国共产党在抗日时期的任务"]}]},{"t":"通过提出共同目标、以身作则、巩固同盟与严格自律实现政治领导","d":"要使自身成为联合力量的政治领导，须：提出可被共同行动的具体目标与动员口号；以模范行动带动；在不失总目标下建立并巩固同盟；同时保持自身队伍的思想统一与纪律。领导权不是自封的，而由执行这些条件去实现，并使联合不被同盟者的动摇所破坏。","sub":[{"t":"通过提口号当模范建同盟强队伍实现政治领导","d":"无产阶级（先锋队）要实现对各革命阶级的政治领导，须同时做到四条：第一，根据历史发展行程提出基本的政治口号，并在每一发展阶段和重大事变中提出动员口号，使全国有具体一致行动目标；第二，以无限的积极性与忠诚成为实现这些目标的模范；第三，在不失既定政治目标前提下，与同盟者建立并巩固适当关系；第四，发展党的队伍、统一思想、严格纪律。这四条是保证领导权不被同盟者动摇性破坏的基础。","p":["中国共产党在抗日时期的任务"]}]},{"t":"在路线问题上同时防范左右两种偏差并以多数和全局为准","d":"当推进一项路线或策略时，须同时防范两种相反偏差：过\"左\"的狭隘排他或冒险，与过\"右\"的妥协退让、迎合对方。正确立场既不取其一端，也不是简单折中，而是依靠多数、照顾全局，并坚持该路线的彻底性。两端偏差都源自脱离实际与多数。","sub":[{"t":"同时防范左右两种偏差并以多数和全局为准","d":"在群众运动与路线问题上，须同时向两种相反的错误倾向作斗争：一端是关门主义、宗派主义、冒险主义（过于狭隘排他、蛮干），另一端是尾巴主义（陈独秀式，降低党的立场、牺牲工农利益去迎合资产阶级改良主义）。正确立场不是两端折中，而是依靠多数、照顾全局，实行坚决的革命政策。同时须在全党提高理论水平，以理论为指南克服上述倾向。","p":["中国共产党在抗日时期的任务"]}]},{"t":"从根本矛盾与总规律出发判定历史阶段","d":"判断历史阶段或形势时，不从一时、局部的现象出发，而先抓住决定事物性质的根本矛盾与各方根本性质，并依据总的历史发展规律；个别的、暂时的后退现象不能代替总规律，据此判定新阶段与新任务是否成立。","sub":[{"t":"以根本矛盾与总规律判定阶段而不为局部一时现象所惑","d":"面对对新阶段与新任务的否认，先确定决定时局的根本之点——日本帝国主义与亲日派的存在使和平不巩固、国民党已开始转变但未彻底转变、资产阶级不得不向无产阶级找同盟军；再把佐藤外交、苏州审判等局部一时现象与总的历史规律区分开，不以后者代替前者，从而判定新阶段与新任务确实到来，并提出\"巩固和平、争取民主、实现抗战\"三位一体口号。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以事物间的互为条件关系安排任务的相互位置","d":"处理多项任务的关系时，先识别它们之间\"互为条件\"的相互依存：一项是另一项的前提与保证，另一项又给该项发展以有利条件；再在条件网络中确定当前阶段的中心任务，以中心带动其余，而非孤立地强调或贬低某一任务。","sub":[{"t":"以任务间的互为条件关系确定中心任务的位置","d":"面对\"只应强调抗日、强调民主错误\"的偏差，先指明民主与抗日互为条件——民主是抗日的保证，抗日给民主运动以有利条件，正如和平是抗日的条件；再把\"争取民主\"确定为新阶段的中心与本质任务，置于与和平、抗战互为条件的网络中，以国民大会与人民自由为中心环节，日常反日斗争与之相配合而不喧宾夺主。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以必经阶段承接当前努力与长远目标","d":"处理当前努力与长远目标的关系时，把当前阶段视为长远目标所必须经过的\"上篇\"，确认二者先后与条件关系；既不放弃长远大目标，也不放松当前阶段的努力，经过一切必要阶段到达，而不跳跃、不拖延、也不因曲折偏离方向。","sub":[{"t":"以必经阶段连接当前努力与长远目标","d":"面对革命前途的模糊与同\"不断革命\"论的混淆，先区分\"两篇文章\"——上篇民主革命做好，下篇社会主义才能做好；再确认当前民主革命是走向社会主义的必经阶段，在民主共和国口号下经过若干发展阶段、争取领导权；据此既以社会主义为大目标，又全力做好今日努力，反对跳过必要阶段的\"不断革命\"论与尾巴主义、冒险主义。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"通过长期艰苦的群众工作使先进方针成为群众的方针","d":"要使先进政党的方针真正发挥作用，不能停留在党内决定，而须经过长期、百折不挠、耐心而不怕麻烦的宣传、鼓动与组织工作，把党的方针变为千百万群众的方针，使群众在自觉基础上接受领导；没有这种努力，一切都不成功。","sub":[{"t":"以长期艰苦的群众工作把党的方针变为群众的方针","d":"面对\"把党的方针变为群众的方针\"这一目的，先明确有待争取的对象——无产阶级、农民、城市小资产阶级的广大群众，以及尚需进一步工作的资产阶级抗日派；再通过长期坚持、百折不挠、艰苦卓绝且耐心不怕麻烦的努力去宣传、鼓动和组织；确认统一战线的组成巩固与民主共和国实现丝毫离不开这一争取群众的努力，争取千百万群众在领导之下则革命任务能迅速完成。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以民主集中制发动全党积极性来锻炼干部、巩固团结","d":"要使政党有力量，不是仅靠集中或仅靠民主，而是实行民主集中制，使集中制密切联系于民主制；以民主制的实行发挥全党积极性，再用积极性锻炼大批干部、肃清宗派残余、把全党团结得像钢铁一样。制度设计以\"积极性\"为中介连接民主与力量。","sub":[{"t":"以民主集中制发动全党积极性来锻炼干部巩固团结","d":"为达\"伟大的革命要有伟大的党与许多最好的干部\"之目的，实行党的民主集中制：在反动内战时期集中制较多，新时期则使集中密切联系于民主；用民主制的实行发动全党积极性，再用积极性去锻炼大批干部、肃清宗派观念残余，把全党团结得像钢铁一样，从而在干部与组织上支撑革命。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以层级递进的团结作为战胜敌人的基础","d":"团结不是一次性、平面地达成，而是按层级递进：先实现先锋队内部的团结，再经过它达到全阶级、全民族的团结，最后凭这种广泛团结战胜敌人、完成任务。每一层级的团结是下一层级的前提，基础的团结决定最终胜利的可能。","sub":[{"t":"以层级递进的团结作为战胜敌人的基础","d":"面对民族与民主革命的任务，先确认党的团结是\"当前民族和民主革命最重要的基础\"；再据\"只有经过共产党的团结，才能达到全阶级和全民族的团结，只有经过全阶级全民族的团结，才能战胜敌人\"的层级递进，把全党在政治上的一致转化为阶级与民族的团结，作为完成革命任务的前提。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以实践作为检验与发展认识的根本标准","d":"认识是否正确、是否需要发展，不依主观认定或理论自身，而由它回到实践后是否达到预想结果来判定。实践因而是检验真理的根本标准，也是理论继续深化与发展的动力；理论若束之高阁不实行，便无从证实也失去意义。","sub":[{"t":"以理性认识回到实践检验并发展理论","d":"面对\"已取得理性认识后如何使其不沦为空谈并继续深化\"的问题，先把理性的认识再回到改造世界的实践中去应用；再看它是否达到预想目的，据此证实或纠正理论。检验和发展理论不是认识终点之后的附加，而是整个认识过程的继续，使理论在尔后实践中被证实或纠正其不完全与错误。","p":["实践论"]},{"t":"以实践结果作为判定认识真理性的标准","d":"面对\"如何判定一个认识或理论是否为真理\"的问题，不以主观上觉得如何、理论上是否自洽而定；而以客观上社会实践的结果如何而定——只有在社会实践过程中，人们达到了思想中所预想的结果时，认识才被证实。据此排斥一切否认实践重要性、使认识离开实践的错误理论。","p":["实践论"]}]},{"t":"以亲身实践为认识之源并据客观性质判定间接知识","d":"对未经亲身经历的事物，要取得直接真知必须亲身参加变革该事物现实的实践，才能触其现象、暴露其本质；对他人的间接知识，不能仅以来源取信或轻视，而须以其是否真实反映客观（科学的抽象）判定可靠与否。","sub":[{"t":"以亲身变革现实的实践取得直接真知并据客观为准对待间接经验","d":"面对\"知识从何而来、如何对待未亲身经历的知识\"的问题，要直接认识某事物，须亲身参加变革该事物的实践，才能触到其现象并暴露其本质；同时承认一切真知源于直接经验，但多数知识为间接经验，对古人与外人的间接知识，须以其是否\"科学的抽象\"（即是否科学反映客观事物）判定可靠与否，不凭来源轻信或轻视。","p":["实践论"]}]},{"t":"使认识随客观过程的推移发展并以具体的历史的统一为准则","d":"认识不是一次完成，须随客观过程由一阶段向另一阶段的推移而发展，及时改正错误方案、提出适合新情况的任务。正确与否的界限是主观与客观、理论与实践、知与行具体的历史的统一，据此反对思想落后于实际与超过阶段的两种偏差。","sub":[{"t":"使认识随客观过程的推移发展并以具体的历史的统一反对左右偏差","d":"面对\"认识如何在变化发展的过程中保持正确\"的问题，从事变革现实者须随客观过程由一阶段向另一阶段的推移而转变主观认识，善于改正错误方案、提出适合新情况的任务；并以\"主观和客观、理论和实践、知和行的具体的历史的统一\"为准绳，反对思想落后于实际（右倾）与思想超过阶段、\"左\"翼空谈（冒险主义）两种偏差。","p":["实践论"]}]},{"t":"由对象内部的对立关系解释其变化，外部影响只作条件","d":"对象为什么变化，首先由它自身内部互相对立的方面决定；外部影响是变化的条件，须通过内部的根据才发生作用。据此解释差异与转化时应先追问对象内部的对立关系，而不把原因外推；外部条件相近而结果不同的事实，正是这一定位的检验。","sub":[{"t":"从事物内部的矛盾寻找变化的根据并把外因定位为条件","d":"面对\"这一事物为什么发生变化\"的解释问题，先拒绝把原因单纯归于外部推动；转而在事物内部找出互相矛盾的方面，把发展看作内部矛盾引起的自己的运动，把与他事物的联系影响列为第二位原因。再把外部影响定位为条件，承认它只有通过内部的根据才起作用；并用外部条件相近而结果不同的对照检验这一定位，从而解释质的差别与互相变化，而不只解释数量增减。","p":["矛盾论"]}]},{"t":"由对象特有的对立关系逐层展开其本质与差别","d":"一类对象区别于他物的本质，由它自身特有的对立关系规定；要把握这种特殊性，须由总体到各个方面、由全过程到各个阶段逐层展开差别，而不能停留在表面或只看一方。层次展开得越完全，对象的本质与它同他物的边界才越清楚。","sub":[{"t":"逐层分析矛盾的特殊性以确定对象的本质与研究范围","d":"认识一类对象时，先注意它与其他运动形式的质的区别，找出其本身特殊的矛盾——这一特殊矛盾构成它区别于他物的特殊本质，研究领域的划分亦据此。再研究其发展长途中每一过程的特殊矛盾；进而从矛盾各个方面着手，了解各方各占何等地位、以何种具体形式互相依存又互相斗争；还要注意各发展阶段的特点及阶段上各方的特点。全过程反对主观性、片面性和表面性。","p":["矛盾论"]}]},{"t":"在个别与一般之间往返以形成并修正共同认识","d":"一般性的认识只能由许多个别对象的特殊性概括而来，形成之后又必须回到新的个别对象中去检查和补充。缺少前一方向，一般就成为凭空的公式；缺少后一方向，一般就会枯槁僵死。认识的深化依赖这两个方向反复联结。","sub":[{"t":"在个别与一般之间双向往返形成并修正共同认识","d":"面对\"一般结论从哪里来、又怎样不至于僵死\"的问题，先由认识许多个别的、特殊的事物的特殊本质入手，逐步概括出诸种事物共同的本质；再以这种共同认识为指导，继续研究尚未研究过或新冒出来的具体事物，找出其特殊本质，用以补充、丰富和发展原有的共同认识。两个过程互相联结、循环往复，每次循环都可能使认识提高一步；据此反对把一般真理看成凭空出现的抽象公式。","p":["矛盾论"]}]},{"t":"解决办法的性质须与问题的性质相应","d":"解决办法不能由一个通用公式给出，只能由问题自身的性质决定；问题的性质变了，办法也应随之更换。冲突是否已取激烈的外部形式同样是一种性质差别，并可依条件互相转化，因而处理方式与限度须按当前性质确定，而不是一律采取最激烈或最和缓的形式。","sub":[{"t":"按矛盾性质的不同选择解决方法与斗争形式","d":"面对\"用什么方法解决这个矛盾\"的问题，先判定该矛盾的质——不同质的矛盾只有用不同质的方法才能解决；过程变化、旧矛盾消灭而新矛盾发生时，方法也随之改变。进一步区分斗争形式：对抗只是矛盾斗争的一种形式而非一切形式，有些矛盾具有公开对抗性，有些则不是，二者依发展可以互相转化。据此对尚未取对抗形式的矛盾既严肃斗争又留出改正机会而反对过火，并反对把任一公式到处硬套。","p":["矛盾论"]}]},{"t":"由取得支配地位的一方判定对象的性质","d":"对象的性质不由并存的各方平均决定，而由当下取得支配地位的一方规定；双方地位随力量消长而互易，性质也随之改变。因此判定性质要先找出当前的主导方面，预判变化要观察力量对比的方向，而不能把任何一方的地位当作永久固定。","sub":[{"t":"由取得支配地位的矛盾方面判定事物的性质及其变化","d":"判定一个事物\"现在是什么\"时，先承认矛盾双方发展是不平衡的：必有一方处于支配地位、起主导作用，事物的性质主要由这一方面规定。再观察双方斗争中力量的增减：新的方面由小变大上升为支配的东西，旧的方面由大变小趋于消亡；一当支配地位易手，事物性质随之变化。据此既承认生产力、实践、经济基础一般起决定作用，也承认生产关系、理论、上层建筑在一定条件下转过来起主要的决定的作用。","p":["矛盾论"]}]},{"t":"对立面的转化以具体条件为限","d":"相反的两方并非彼此隔绝，在一定条件下可以向对方所处的地位转化；但转化不是任意的，能否发生取决于必要条件是否具备。因此判断变化的可能，应把注意力从愿望转向条件的考察；共处的统一是有条件而相对的，双方的相互排斥则是无条件而绝对的。","sub":[{"t":"依一定的必要条件判断对立面的相互转化","d":"判断\"这一事物能否变为它的反面\"时，先确认矛盾双方互为存在的条件、共处于一个统一体中；再找出使转化得以发生的具体的、必要的条件——缺乏这些条件就没有同一性，转化也不可能。据此把现实的、具体的转化同幻想的变化区别开来。进而承认这种统一是有条件的、暂时的、相对的，而斗争贯串始终、是无条件的绝对的，因而应把对立看作可变动、可转化的东西，并通过具备条件促成转化。 # Method Dedup Index（07–12 批次） **批次：** 07–12（每 6 篇一个独立 method…","p":["矛盾论"]}]},{"t":"以可控的经济组织与杠杆动员群众经济力量","d":"面对外部约束（封锁、中间剥削）或内部力量分散，不能听任自发市场，而应以可控的组织化手段（贸易管理、公共金融、合作社、可控经济成分）把分散的经济力量纳入目标；计划性与适度边界（非专卖、非全管）是关键。","sub":[{"t":"以计划贸易统制打破封锁抵制剥削","d":"面对白区封锁与商人在出入口中的高额剥削（如谷价七倍、盐价悬殊），不能放任不管。须设对外贸易局、粮食调剂局，一方面在红色区域内把有余地的粮食调到不足地、平抑地区差价，另一方面有计划（非无限制）地把多余粮食运出出口、从白区低价购入盐布必需品，打破封锁、抵制剥削、改善群众生活。","p":["必须注意经济工作","我们的经济政策"]},{"t":"以公债与合作社杠杆动员群众经济力量","d":"以三百万元经济建设公债为杠杆：一百万供红军作战费，两百万借合作社、粮食调剂局、对外贸易局做本钱，其中小部分发展生产、大部分发展出入口贸易；普遍建设谷仓、备荒仓，每县设粮食调剂分局、重要区圩场设支局。把群众经济力量组织起来，发展生产贸易、改良生活、增加财政收入，确切建立战争物质基础。","p":["必须注意经济工作","我们的经济政策"]},{"t":"在国营、合作社、私人并存中发展前两者以取得领导","d":"国民经济由国营、合作社、私人三成分组成，私人现时占绝对优势且将长期如此；政策在不违法范围内鼓励私人，同时尽量发展国营经济、大规模发展合作社经济，使两者配合经长期发展对私人逐渐占优势并取得领导地位。判断标准是可控组织成分能否持续壮大并导向主导，而非否定私人经济的现实作用。","p":["我们的经济政策"]}]},{"t":"以组织化协作统筹关键生产要素","d":"在关键部门面临分散的资源约束时，以自愿互利的合作组织形式（互助、合股、动员）把零散要素集中调度，比单纯号召更能突破瓶颈；组织化是弥补个体经济短板的可控手段，且不改变基本所有制。","sub":[{"t":"以农业为第一位并组织生产要素保障生产","d":"在苏区条件下农业为经济建设第一位，须同时解决粮食与棉麻蔗竹等原料。面对劳动力、耕牛、肥料、种子、水利等困难，组织劳动互助社与耕田队调剂劳动力、推动妇女参加生产，组织犁牛合作社合股买牛共用，视水利为农业命脉；并在小农基础上对重要农产作适当生产计划、动员农民努力。","p":["我们的经济政策"]}]},{"t":"以发展生产本身作为增收的根本来源","d":"把财政收入建立在被课税对象（经济本身）发展的基础上，而非竭泽而渔；收入增长与经济发展互相促进，财政需要服从于经济需要，二者形成正向循环而非对立。","sub":[{"t":"以发展国民经济为财政收入基本方针","d":"财政政策的基本方针是从发展国民经济来增加财政收入，而非单纯征集；国家银行发行纸币基本上应根据国民经济发展的需要，单纯财政需要只居次要地位。增收与经济发展互为促进，财政须服务于经济需要。","p":["我们的经济政策"]}]},{"t":"以节约与禁绝浪费约束公共支出","d":"公共资源的支出须以节约为绝对原则，把贪污浪费提升至“犯罪”高度以确立刚性约束；节约不是消极克扣，而是把有限资源集中投向主导任务，体现公共资源使用的方向纪律。","sub":[{"t":"以节省与反浪费为财政支出铁律","d":"财政支出根据节省方针，使政府人员明白贪污和浪费是极大的犯罪；节省每一个铜板为着战争与经济建设是会计制度原则；国家收入的使用方法应与国民党方法严格区别。","p":["我们的经济政策"]}]},{"t":"以实际调查作为认识的出发点","d":"认识的起点应是客观实际情况与历史材料，而非脱离材料的纯主观推想；判断与结论的正确依赖于对实际材料的占有，调查是消除唯心指导的根本手段。","sub":[{"t":"调查先于结论的问题解决","d":"面对不能解决的问题，先调查其现状与历史，完全调查明白后办法自然产生；一切结论产生于调查末尾，而非先于调查冥思苦索“想办法”。可实地走访学“每事问”，或召集明了情况者开调查会弄清来源与现状。","p":["反对本本主义"]},{"t":"以实际调查洗刷唯心工作指导","d":"估量政治形势、指导斗争前必须作实际调查；离开实际调查去估量形势、指导工作，必是空洞唯心的，导致机会主义或盲动主义错误。须努力作实际调查洗刷唯心精神，防止错误，才能完成争取群众、战胜敌人的任务。","p":["反对本本主义"]}]},{"t":"以明确对象与目的组织调查","d":"组织调查时先确定清晰的研究对象与最终目的，通过结构化解剖取得可用估计再据以决定行动；目的不清则调查流于表面，无助于核心决策。","sub":[{"t":"以社会各阶级为对象的阶级估量调查","d":"社会经济调查以社会各阶级（而非片断现象）为对象，既调查农村也调查城市；通过解剖各阶级及其相互关系，得正确阶级估量，据以定出斗争策略，分清革命主力、同盟者与要打倒的对象。","p":["反对本本主义"]}]},{"t":"把理论与权威置于实际检验之下","d":"真理或正确指示的根据不在其来源（书本、上级、权威），而在是否适合具体客观情势并为实践所证明；既有理论须与具体情况结合，反对脱离实际的教条式沿用。","sub":[{"t":"把本本与上级指示置于实际检验之下","d":"判断上级指示或理论“本本”是否正确，不看其来源（上级机关、马克思“先哲”之名），而看内容是否适合斗争客观主观情势、是否为实践所证明。学习马克思主义但须同本国实际结合；盲目执行上级、一味拿本本是形式主义，须纠正为本本与实际结合。","p":["反对本本主义"]}]},{"t":"以规范操作保证调查可靠","d":"为使调查所得近于正确，须以规范化的操作程序约束过程，降低个人见闻局限与主观偏差带来的误差。","sub":[{"t":"按七项技术开展实际调查","d":"开展实际调查须遵循七项技术：开调查会作讨论式调查；到会人须深切明了社会经济情况；人数依指挥能力定、至少三人；事先定调查纲目（大纲含细目）；指导者亲身出马不单靠书面报告；初次深入一处或一题；调查人自己做记录不假手于人。","p":["反对本本主义"]}]},{"t":"在总任务下确定具体工作的从属与服务定位","d":"面对多任务情境，须识别主导任务并据以确定各具体工作的从属地位与服务方向；既不可因次要而弃之，亦不可本末倒置。判断标准始终是“是否服务于主导任务”，而非任务本身的重要性宣称。","sub":[{"t":"围绕中心任务统筹次级任务的定位","d":"当多项任务并存时，先确认当前中心任务，将具体工作（如经济建设）定位为环绕并服务于它的次级任务；同时反对两种偏差——以“忙不过来”取消次级任务（实为削弱中心），以及把次级任务倒置为当前中心而离开中心去推进。每一件具体工作都须检验其是否服务于中心任务。","p":["必须注意经济工作"]}]},{"t":"通过组织与说服把群众动员到中心任务","d":"要完成须群众参与的中心任务，须以组织体系（议程、督促检查、群众团体）把任务落到基层，并以面向群众的宣传把任务与群众切身利益相关连形成参与热情；动员方式须为群众可接受，按具体环境与真实群众情绪说服而非强制，才能保证工作巩固、得群众拥护。","sub":[{"t":"从组织上常议常查地动员群众","d":"把经济任务（发公债、合作社、调剂粮食、发展生产贸易）常列政府主席团、国民经济部、财政部议程，定期讨论、督促、检查；推动工会、贫农团等群众团体；以村屋群众大会宣传，讲明革命战争与经济建设的真实关系与改良生活的实际利益，把群众热情提起来。不如此组织动员则不能达到目的。","p":["必须注意经济工作"]},{"t":"以说服适应群众情绪替代命令主义动员","d":"动员群众不可用官僚主义方式。须识别两类官僚表现——不理不睬的怠工与表面努力实则蛮横派任务的命令主义；命令主义发展合作社、推销公债虽形式暂成却不能巩固、失信用。正确做法是努力宣传、说服群众，按具体环境与具体表现出来的群众情绪去发展合作社、推销公债、做一切经济动员。","p":["必须注意经济工作"]}]},{"t":"从实践斗争中识别与培养骨干","d":"完成艰巨任务所需的骨干并非外求或先天稀缺，而蕴含于经历实际斗争锻炼的群众之中；破除“无干部”的主观预设，在实践斗争中识别、组织并训练骨干。","sub":[{"t":"从群众斗争中识别与起用干部","d":"开展大规模经济运动需要几千几万干部。面对“没有干部”的叹气，须丢掉这一错误观点：干部并非稀缺，而是从土地斗争、经济斗争、革命战争中锻炼出来的群众里涌出。识别与起用干部的标准是实际斗争的锻炼，而非先设“无人”的前提。","p":["必须注意经济工作"]}]},{"t":"将关联任务协同纳入中心任务服务链","d":"完成中心任务须把若干相互关联的具体任务协同组织起来，使每项任务既独立成立又共同汇入对中心的服务；条件之间互相促进，整体指向主导任务。","sub":[{"t":"以任务联动协同服务于中心","d":"经济建设不能孤立推进，须与其他革命任务相互结合、共同服务于战争：深入查田运动消灭封建土地制以发展农业生产；坚决实行劳动法改善工人生活以加强其领导；正确领导选举与检举以健全政府；以文化教育提高群众政治文化水平；不忽略扩大红军。争取上述一切条件并都服务于革命战争，则胜利属我。","p":["必须注意经济工作"]}]},{"t":"以结构性多维要素的综合判定认识对象类别","d":"对复杂对象作类别判断时，不依赖单一可见属性，而同时考察其资源占有、从事活动与获益来源等多维结构性要素，并据核心区分维度解决模糊边界；分类的根据在于要素的组合而非名目。","sub":[{"t":"以占有、劳动与生活来源三维综合判定阶级成分","d":"面对农村阶级划分，不以名目或单一表象判定，而同时考察三维结构性要素：占有何种生产资料、本人是否参加劳动、生活来源主要靠自身劳动还是剥削他人（及剥削是否经常且为主要收入）。三者组合决定类别，对模糊情形以\"主要生活来源靠剥削、生活超过普通中农\"为决定判据归入地主，相邻边界以核心维度（是否出卖劳动力）区分。","p":["怎样分析农村阶级"]}]},{"t":"以实际满足切身需要换取对更高目标的支持","d":"要使对象接受并投入超出其直接利益的更高目标，反复号召与单纯宣传并不足够。须先把对象自身的实际困难当作自己应处理的事项逐项解决，形成真实的利益关联与信任；更高目标由这些切身事情引出，才可能被自愿接受和全力支持。","sub":[{"t":"以解决群众切身生活问题取得中心任务的动员力","d":"面对中心任务需要广泛动员却动员不起来的局面，不能只布置任务而不管群众生活。须查明群众最迫切的实际困难（缺柴、无盐、无房、缺米、疾病、失学、桥梁失修），把从土地劳动到柴米油盐的一切生活问题提到议事日程，逐项讨论、决定、实行、检查，并组织可用力量当场解决；使群众认识领导者与其呼吸相通，再由这些切身事情出发引出更高的中心任务。","p":["关心群众生活，注意工作方法"]}]},{"t":"以实际成效对照判定做法优劣并推广范例","d":"在同类条件下比较不同执行单位的实际结果，把结果差别归因于做法差别，据此判定做法优劣，而不以主张、名义或形式为准。经此判定的较优做法应确立为可学习的范例并推广，由已见成效者带动未见成效者。","sub":[{"t":"从正反实例的成绩差别中判定并推广领导方法","d":"判断领导方法是否可取，不看主张与形式，而取同一任务下不同执行单位作实际对照：一面是只布置任务、不理生活因而会开不成、成绩极少的地方，一面是解决群众具体困难因而扩红与公债成绩突出的地方。把成绩差别归因于方法差别，把成效最好的做法确认为模范并公开树立，反对与之相反的官僚主义方法；再以先进帮助薄弱，使模范由个别扩展为普遍。","p":["关心群众生活，注意工作方法"]}]},{"t":"把目标与实现手段作为同一问题解决","d":"确定目标之后，认识不能停留在目标本身；没有可行手段的目标等于空话，重复申明目标不产生结果。须把\"做什么\"与\"用什么办法做\"当作同一个问题同时解决，并以是否存在具体可行、且为执行对象所能接受的办法，作为目标能否成立的判据。","sub":[{"t":"提出任务的同时解决完成任务的方法","d":"提出任务后不得停留在重复号召——把任务念一千遍也不能成功。须在提出任务的同时把\"用什么办法完成\"作为并列问题处理：确认没有渡河手段则过河只是空话，据此为每项工作（扩红、查田、经济建设、文化教育、新区边区工作）找出实行时的具体办法；并以实际的具体的方法替代官僚主义方法，以耐心说服的方法替代命令主义方法。","p":["关心群众生活，注意工作方法"]}]},{"t":"以主要矛盾的变动重新划分对立面与可联合面","d":"当出现一个压倒性的主要对立力量时，各方之间的关系不再由既有属性和历史立场固定，而应按其与该主要对立面的现实利害重新排列；判定根据是当下的利害结构而非名目与成分。力量应集中于这一唯一目标，其余分歧转为可利用条件，判据是打击面最小、可联合面最大。","sub":[{"t":"依形势根本变动重估各阶级态度以确定策略任务","d":"面对形势的根本变动，先确定其基本特点（主要敌人及其目标的改变），再逐一考察各阶级与政治派别在新环境下的利害得失；对中间对象不按历史成分或固有弱点作固定判定，而检验该弱点在过去时期是否同样存在而当时结果相反、同类分裂在过去是否已实际发生；据此区分对象内部的不同部分，以动摇、中立、可能参加等分层结论代替一次性归类，最后汇总为营垒势力的消长并据以规定策略任务。","p":["论反对日本帝国主义的策略"]},{"t":"以主要敌人为准择敌并汇集一切可争取力量","d":"自身力量不足以单独取胜时，先确定当前唯一的最中心目标，集中射击而不分散目标，避免主要敌人没有打中而次要敌人甚至同盟军身上吃了子弹；再按与该目标的关系重划阵线：把过去是敌人而今日可能做友军的人拉过来，把对方营垒中的一切争斗、缺口、矛盾收集起来作为反对主要敌人之用，以是否有利于打击主要敌人判定他方行为的性质，由此把敌人驱逐到狭小孤立的阵地。","p":["论反对日本帝国主义的策略"]}]},{"t":"由相反两方面的分别估计综合出整体判断","d":"任何整体判断都须由分方面的分别判定综合得出，任一单方面的事实都不足以支持全局结论；对同一对象应同时给出相反两方面的估计并承认两者同为事实，行动方案须同时满足这两方面共同提出的要求，因而既不由有利面推出冒进，也不由不利面推出退缩。","sub":[{"t":"分方面判定成败并以两面估计确定策略","d":"面对对同一事实的对立评价，不接受笼统的整体断语，而把它分解到各具体方面上分别判定得失，再由全体作出结论；对同一形势同时给出相反两方面的估计并承认两者都是事实；策略须同时满足两方面提出的要求——据有利一面抛弃关门主义采取广泛联合，据不利一面防止冒险主义、不到决战时机不进行决战，阶段性转变亦以条件是否具备为标准而非以主观愿望提前。","p":["论反对日本帝国主义的策略"]}]},{"t":"以自身独立力量保证联合关系的可靠","d":"在与不稳定对象结成的联合中，联合能否维持不取决于对方的意愿或承诺，而取决于己方是否拥有不依赖对方的独立力量与在联合中的主导地位；应把扩充自身力量与保持批评权、主导权当作维持联合的条件，而不是把联合本身当作力量的替代。","sub":[{"t":"在联合中保持独立力量与领导权","d":"建立广泛联合时不把联合的可靠性寄托于同盟者的承诺。须同时：努力扩大自己的队伍并使之在政治上坚强，作为联合的中心支柱而不依仗暂时的同盟者；批评同盟者、揭破以革命或半革命面目出现的假革命，承担争取领导权的责任；对挑拨离间、威迫利诱、各个击破以同样的争取手段反制，容许受影响的坏分子退出而吸收对方队伍中可争取的人进来。判据是自身力量是否存在并发展。","p":["论反对日本帝国主义的策略"]}]},{"t":"以主导任务为准调整自身规则与容纳边界","d":"主导任务改变时，组织自身的成员范围与既有规则同样是待调整的对象，而不只是外部对象需要重新判断；调整的唯一判据是是否适合新的主导任务。但扩大容纳不等于改变性质，须同时确定不可让渡的底线与主体地位，使范围的扩大不消解自身成立的根据。","sub":[{"t":"依基本任务调整政权成分与政策边界","d":"基本任务改变时，组织的成员范围与既有政策不应固定不变。以\"是否适合于新的基本任务\"为唯一原则，把容纳范围扩大到一切愿意参加该任务的成分（包括只认同部分目标者），据此对过去的政策作适当修改并限定内部斗争的限度。同时划出不可让渡的边界：与主要敌人利益不可分离的成分不列入容纳范围；基本群众须占主体并保持领导；扩大范围不改变自身的性质。 # Method Dedup Index（13–18 批次） **批次：** 13–18（每 6 篇一个独立 method index 文件） **…","p":["论反对日本帝国主义的策略"]}]},{"t":"使主观指导符合客观实况的两段认识过程","d":"判断的可靠来自对对象材料的占有与加工：先取得材料，经去伪存真、由表及里的加工形成判断，并把双方条件的相互关系计入。这一过程不止于方案成立之时，方案执行本身构成第二次认识，须以新出现的实况检验原判断并据以改变原方案；符合的标准是在有决定意义的部分上符合。","sub":[{"t":"由必要侦察构成判断并在执行中重新认识情况","d":"承认错误的根源是主观指导与客观实在情况不相符合，据此把决策展开为一条来源链：使用一切可能的和必要的侦察手段取得对方材料，作去粗取精、去伪存真、由此及彼、由表及里的思索，再加上自己方面的情况，研究双方的对比和相互关系，构成判断、定下决心、作出计划。计划成立后须在执行中重新检查是否符合实况，不符合就依新的认识构成新判断、改变已定计划。","p":["中国革命战争的战略问题"]},{"t":"以感性材料的丰富合实际为前提经加工上升到理性认识","d":"面对\"如何从实践中形成正确理论认识\"的问题，先通过亲身实践取得十分丰富（非零碎不全）、合于实际（非错觉）的感觉材料；再将材料加以去粗取精、去伪存真、由此及彼、由表及里的改造制作，造成概念、判断、推理的系统，从感性认识跃进到理性认识；并在实践基础上把两阶段统一起来，反对割裂二者的唯理论与经验论。","p":["实践论"]}]},{"t":"按主要矛盾与次要矛盾地位的变化调整当前工作的中心","d":"当所处对象中的若干矛盾（问题）在整体里的主次地位随条件改变时，先确认当下哪一个是主要的、哪一些降为次要，再把当前工作的中心放到解决主要矛盾上；原主要者降次后转为服从地位并作相应调整。判断依据是其相对地位的变化，而非主观愿望或阶段未变时的随意转移。","sub":[{"t":"按主要矛盾地位的变化重新确定阶段中心任务","d":"面对长过程中任务重心的选择，先判定当前各种矛盾在其整体中的主次地位发生了什么变化：哪一对上升为主要矛盾、哪一对降为次要和服从。依据这一变化把当前阶段的中心任务转到解决主要矛盾上来，已降为次要的矛盾转为服从并作适当调整。不在阶段未变时随意转移重心，也不在矛盾比重已变时仍固守旧重心。","p":["中国共产党在抗日时期的任务"]},{"t":"在多个矛盾中找出起领导作用的主要矛盾","d":"研究存在两个以上矛盾的复杂过程时，不把诸矛盾平均看待，而用全力找出其中规定或影响其他矛盾存在和发展的那一个主要矛盾，其余置于次要和服从的地位，捉住它则一切问题迎刃而解。主次不是固定的：外部压迫采取战争形式时对外矛盾成为主要矛盾，内部矛盾暂降为次要；压迫改取较温和形式时内部矛盾又转为主要。每一阶段都须重新判定。","p":["矛盾论"]}]},{"t":"按对象的层级与阶段差别确定规律的适用范围","d":"任何规律都在一定的层级和一定的发展阶段上成立；上位层次的规律不能直接充当下位对象的行动依据，下位对象在共性之外另有自己的情形、性质与关联。接受一项现成结论前须先确定它是在哪一层次、哪一条件下得出的，再判断本对象是否落在其适用范围之内。","sub":[{"t":"按一般与特殊的层级分别研究战争指导规律","d":"面对既有成规与他处经验，先按包含关系建立层级：一般类别的规律、其中某一特殊类别的规律、更特殊的具体对象的规律，逐层追问该层次在情形、性质及其与外部事情的关联上有何不同；再按时间、性质、地域三个条件核对差别，判定哪些成规只是上位层次的规律因而不能呆板移用。对既有经验采取三步处理：着重学习其总结，用自己的经验考证结论，吸收用得着的、拒绝用不着的、增加自己特有的。","p":["中国革命战争的战略问题"]},{"t":"依现阶段条件承认自身形态并以条件变化为改变依据","d":"对自身被视为不体面的特征，不按理想形态否定，也不按现状固守。先确认它由什么条件产生，再判断这些条件在现阶段是否仍存在；仍存在就承认它是现阶段的长处并据此规定日程，不作长时期的具体计划。同时把该特征拆成两面：属于低级阶段遗留而在更高阶段有害的部分逐渐去掉，由现阶段条件决定而当前仍需要的部分必须坚持。改变的依据是条件本身的改变，而非主观上想要进入新阶段。","p":["中国革命战争的战略问题"]}]},{"t":"在总体劣势下按层级分置相反取值以造成可胜的局部","d":"总体力量对比不利，并不等于每一次具体较量都不利。应把总体与具体分为不同层级，允许同一对范畴在两个层级上取相反的值；据此使对方在总体上的优势在具体接触点上转为劣势，其余方向以最小配置维持，损失由主要方向的结果偿还。","sub":[{"t":"以兵力集中把战略上的劣势改变为战役上的优势","d":"承认总体对比上处于劣势和被包围的内线地位，但不把这一地位当作每次具体行动的既定条件。在同一时间内只确定一个主要使用方向，除地方部队和钳制兵力外把突击力量全部集中，对强敌用绝对优势、对弱敌用相对优势，从而把对方的一个大包围改为自己对其一部的许多小包围。相应反对力量平均分配的各种形式；同时保留边界：次要方向仍需钳制力量，配合性的分散力量不予取消。","p":["中国革命战争的战略问题"]},{"t":"按战略与战役两级分置持久与速决","d":"面对快与慢的争论，不在同一层级上取折中，而先判定两个层级各自的决定条件：总体过程的时间长度由双方力量消长规律决定，对方雄厚而己方逐渐生长就必须承认长期性；单次行动的时间长度由自身补给、对方数量与配置决定，补给无来源且对方部队密接就必须迅速解决。据此总体取持久、单次取速决，并为速决准备具体条件；同时各设一条限制：持久不许可无谓拖延，速决之下仍须反对不正当的急躁性。","p":["中国革命战争的战略问题"]}]},{"t":"由部分对整体的决定作用区分轻重","d":"整体不能脱离部分而独立，但各部分对整体的作用并不相等；有些部分的失败不改变整体，有些立即改变整体。轻重不能按事物的一般属性或表面规模判定，只能按当下具体条件确定哪些部分具有决定作用，并据此配置注意力与力量。整体性的关系不能被直接观察，只能由局部经验经思索而把握。","sub":[{"t":"以对全局有决定意义的关节确定指挥重心","d":"面对头绪繁多而精力有限的指导任务，先确认自己所负责的那个整体的边界，即哪些方面和哪些阶段必须由自己照顾；再区分各部分对整体的作用是否具有决定意义，其判定不按一般的或抽象的情况，而按当前具体情况逐一确定；然后把注意力的重心放在这些关节上，而不去忙次要问题。整体性的关系眼睛看不见，须以已有的局部经验为基础用心思索，最终把一切重要问题提到较高的原则性上去解决。","p":["中国革命战争的战略问题"]}]},{"t":"由两端偏差的共同根源确定正确做法的位置","d":"当同一问题上出现两种方向相反的错误时，正确做法不能由否定其中一端得出，也不是两端之间的折中。应先辨明两种偏差共同的发生机制，再把有关判断拆为成对的范畴，分别指明在哪一层次上肯定、在哪一层次上否定，从而得到带有适用层次与限度的方针。","sub":[{"t":"以成对的正反限定确立作战方针","d":"先找出实践中出现过的两种相反错误并指出其同源——轻视敌人与被敌人吓倒，一个只讲进攻不讲防御退却，一个采取非必要的退却，二者都在精神上解除了防御的武装，都由不按敌我实际对比作判断而来。再把方针拆成若干对范畴，逐对指明在哪一面上反对、在哪一面上承认，并注明层次。方针由此不落在任一极端，也不是两端的折中，而带有明确的层次与限度。","p":["中国革命战争的战略问题"]}]},{"t":"以暂时的局部让出换取力量对比的改变","d":"在总体上处于劣势时，力量对比不是固定的前提而是可以改变的结果。让出局部与一时的东西不是失败，而是取得改变对比所需条件的手段；判断得失不按单次、局部的增减，而按它是否使整体的、后续的对比向有利方向变化。因此让步须是有计划、有终点、有条件清单的，而不是被动的溃退。","sub":[{"t":"以有计划的退却创造转入反攻的条件","d":"在劣势而不能迅速击破对方进攻时，把退让当作有计划的步骤，目的是保存力量并造成对比关系的改变。先列出转入反攻所需的若干具体条件并规定至少取得二种以上，再在退让中逐项争取：依靠最有利的支持力量、选择利于己方的位置、使力量完全集中、发现对方最弱部分、使对方在深入中消耗疲劳、必要时人为造成对方过失。终点不预先固定，以整个形势为出发点确定；得失以局部暂时的丧失换全局长期的取得来换算。","p":["中国革命战争的战略问题"]}]},{"t":"由整个过程的预先推演确定起手的一步","d":"在由多个阶段衔接而成的过程中，起手一步的价值不由它自身的成败决定，而由它在整个过程中引起的变化决定。决定之前须对后续各步在成功与失败两种结果下的走向作大体推演，并把本过程之后的下一阶段一并计入；条件不足以支持这一推演时，宁可推迟起手也不冒然投入。","sub":[{"t":"以全战役和下一阶段的通盘计算决定初战","d":"对由若干相互衔接的行动构成的过程，先把同类过程的历次实例逐一列出，把每次的具体条件与最终结果对照，指出胜负所系的条件差别；据此确立三项要求：第一步必须有把握，条件不具备宁可退让、持重待机；第一步的方案必须是整个过程方案的有机序幕，动手前须设想此后各步及胜败两种结果引起的变化，凡不利于整个过程的胜利仍算失败；还须把下一阶段计入，反对走一步看一步。","p":["中国革命战争的战略问题"]}]},{"t":"以事实与后续行动检验言辞而非表面表述","d":"面对一方对自身或事件的言辞表述，不依其表面字句直接接受，而以其实际所指的具体事实与后续客观行动为判定依据；言辞是否可信，由事实与行动检验，不由表述者的自我定性或措辞决定。","sub":[{"t":"以对方自述承诺为标尺考察其后续行动","d":"面对对手公开的表态，先不依其措辞轻信，而将其自述中可取的具体承诺与条件列为待考察项；随后把判定标准交还给对方自己的诺言，以其撤兵后及今后实际行动是否不打折扣地兑现为准，而非以声明文字本身为准。作用：既避免空文搪塞，又给对手以可观察的诚信账本。边界：考察以对方自身承诺为尺，不另设无法验证的他求。","p":["关于蒋介石声明的声明"]},{"t":"按发言的虚实区分可取处与须揭批处","d":"评估一篇含混的政治文献，不整体褒贬，而先逐段判其虚实：对确有可取的具体表态（如\"言必信行必果\"一段）明确肯定；对含含糊糊、曲曲折折、不能满足人民要求的总体表述，指出其未能痛悔已往、开辟将来，不能满足要求。由此把\"值得赞扬\"与\"不能满需\"分别落位，避免以全概偏或以偏概全。","p":["关于蒋介石声明的声明"]},{"t":"以事实力量还原被对手歪曲的命名","d":"当对手用歪曲性名词（如\"反动派\"）指称某类势力却不说明所指，不以名词本身争辩，而列举该命名实际所指的具体事实力量（六类抗日与革命势力），据以揭示其真实性质恰与命名相反，并正告对方改正命名使其名副其实。作用：以事实拆穿命名颠倒，而不陷入语义空战。","p":["关于蒋介石声明的声明"]}]},{"t":"以有原则有限度的让步换取建立统一战线的必要前提","d":"为取得合作联盟所需的共同前提，可以作出让步，但让步须是原则性与有限度的：明确列出让出的具体内容，并规定不可让出的底线（核心领导与独立性）。得失不按单次局部增减计，而按是否换得更大的共同目标。超过底线的让步不被允许。","sub":[{"t":"以有原则有限度的让步换取统一战线的共同前提","d":"为建立全民族所需的共同前提（和平、民主、抗战），可向同盟者作出让步，但让步必须是有原则、有限度的：先列出愿意作出的具体保证（如改变政权军队名称、停止某些方针），同时明确规定不让步的底线——保持自身在特区与军队中的领导权和独立性、批评自由。超过限度的让步不许可。让步是两党的，对方也须抛弃内战独裁不抵抗政策。不把这种让步误认为投降，也不因怕被骂而拒绝必要让步。","p":["中国共产党在抗日时期的任务"]}]},{"t":"在联盟内部按共同总任务区分应停止与应保留的矛盾斗争","d":"在合作联盟内部，局部矛盾与斗争难以完全消除，但应依据联盟的共同总任务设一道标准：凡削弱该总任务的矛盾斗争予以停止，凡增强该总任务的予以保留。判断不属于各矛盾自身的一般性质，而只看它与总任务的关系。","sub":[{"t":"按是否有利于团结抗日区分应停与应存的矛盾斗争","d":"在统一战线（合作联盟）内部，阶级间、党派间、集团间的矛盾和斗争无法避免，但应按一条总原则区分处理：凡是削弱团结抗日的斗争（国内战争、党派敌对、地方割据、过火经济要求等）应当停止；凡是有利于团结抗日的斗争（批评自由、党派独立性、人民政治经济条件改善等）应当保存。区分标准只有一个——是否有助于抗日民族统一战线的增强和扩大。","p":["中国共产党在抗日时期的任务"]}]},{"t":"通过提出共同目标、以身作则、巩固同盟与严格自律实现政治领导","d":"要使自身成为联合力量的政治领导，须：提出可被共同行动的具体目标与动员口号；以模范行动带动；在不失总目标下建立并巩固同盟；同时保持自身队伍的思想统一与纪律。领导权不是自封的，而由执行这些条件去实现，并使联合不被同盟者的动摇所破坏。","sub":[{"t":"通过提口号当模范建同盟强队伍实现政治领导","d":"无产阶级（先锋队）要实现对各革命阶级的政治领导，须同时做到四条：第一，根据历史发展行程提出基本的政治口号，并在每一发展阶段和重大事变中提出动员口号，使全国有具体一致行动目标；第二，以无限的积极性与忠诚成为实现这些目标的模范；第三，在不失既定政治目标前提下，与同盟者建立并巩固适当关系；第四，发展党的队伍、统一思想、严格纪律。这四条是保证领导权不被同盟者动摇性破坏的基础。","p":["中国共产党在抗日时期的任务"]}]},{"t":"在路线问题上同时防范左右两种偏差并以多数和全局为准","d":"当推进一项路线或策略时，须同时防范两种相反偏差：过\"左\"的狭隘排他或冒险，与过\"右\"的妥协退让、迎合对方。正确立场既不取其一端，也不是简单折中，而是依靠多数、照顾全局，并坚持该路线的彻底性。两端偏差都源自脱离实际与多数。","sub":[{"t":"同时防范左右两种偏差并以多数和全局为准","d":"在群众运动与路线问题上，须同时向两种相反的错误倾向作斗争：一端是关门主义、宗派主义、冒险主义（过于狭隘排他、蛮干），另一端是尾巴主义（陈独秀式，降低党的立场、牺牲工农利益去迎合资产阶级改良主义）。正确立场不是两端折中，而是依靠多数、照顾全局，实行坚决的革命政策。同时须在全党提高理论水平，以理论为指南克服上述倾向。","p":["中国共产党在抗日时期的任务"]}]},{"t":"从根本矛盾与总规律出发判定历史阶段","d":"判断历史阶段或形势时，不从一时、局部的现象出发，而先抓住决定事物性质的根本矛盾与各方根本性质，并依据总的历史发展规律；个别的、暂时的后退现象不能代替总规律，据此判定新阶段与新任务是否成立。","sub":[{"t":"以根本矛盾与总规律判定阶段而不为局部一时现象所惑","d":"面对对新阶段与新任务的否认，先确定决定时局的根本之点——日本帝国主义与亲日派的存在使和平不巩固、国民党已开始转变但未彻底转变、资产阶级不得不向无产阶级找同盟军；再把佐藤外交、苏州审判等局部一时现象与总的历史规律区分开，不以后者代替前者，从而判定新阶段与新任务确实到来，并提出\"巩固和平、争取民主、实现抗战\"三位一体口号。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以事物间的互为条件关系安排任务的相互位置","d":"处理多项任务的关系时，先识别它们之间\"互为条件\"的相互依存：一项是另一项的前提与保证，另一项又给该项发展以有利条件；再在条件网络中确定当前阶段的中心任务，以中心带动其余，而非孤立地强调或贬低某一任务。","sub":[{"t":"以任务间的互为条件关系确定中心任务的位置","d":"面对\"只应强调抗日、强调民主错误\"的偏差，先指明民主与抗日互为条件——民主是抗日的保证，抗日给民主运动以有利条件，正如和平是抗日的条件；再把\"争取民主\"确定为新阶段的中心与本质任务，置于与和平、抗战互为条件的网络中，以国民大会与人民自由为中心环节，日常反日斗争与之相配合而不喧宾夺主。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以必经阶段承接当前努力与长远目标","d":"处理当前努力与长远目标的关系时，把当前阶段视为长远目标所必须经过的\"上篇\"，确认二者先后与条件关系；既不放弃长远大目标，也不放松当前阶段的努力，经过一切必要阶段到达，而不跳跃、不拖延、也不因曲折偏离方向。","sub":[{"t":"以必经阶段连接当前努力与长远目标","d":"面对革命前途的模糊与同\"不断革命\"论的混淆，先区分\"两篇文章\"——上篇民主革命做好，下篇社会主义才能做好；再确认当前民主革命是走向社会主义的必经阶段，在民主共和国口号下经过若干发展阶段、争取领导权；据此既以社会主义为大目标，又全力做好今日努力，反对跳过必要阶段的\"不断革命\"论与尾巴主义、冒险主义。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"通过长期艰苦的群众工作使先进方针成为群众的方针","d":"要使先进政党的方针真正发挥作用，不能停留在党内决定，而须经过长期、百折不挠、耐心而不怕麻烦的宣传、鼓动与组织工作，把党的方针变为千百万群众的方针，使群众在自觉基础上接受领导；没有这种努力，一切都不成功。","sub":[{"t":"以长期艰苦的群众工作把党的方针变为群众的方针","d":"面对\"把党的方针变为群众的方针\"这一目的，先明确有待争取的对象——无产阶级、农民、城市小资产阶级的广大群众，以及尚需进一步工作的资产阶级抗日派；再通过长期坚持、百折不挠、艰苦卓绝且耐心不怕麻烦的努力去宣传、鼓动和组织；确认统一战线的组成巩固与民主共和国实现丝毫离不开这一争取群众的努力，争取千百万群众在领导之下则革命任务能迅速完成。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以民主集中制发动全党积极性来锻炼干部、巩固团结","d":"要使政党有力量，不是仅靠集中或仅靠民主，而是实行民主集中制，使集中制密切联系于民主制；以民主制的实行发挥全党积极性，再用积极性锻炼大批干部、肃清宗派残余、把全党团结得像钢铁一样。制度设计以\"积极性\"为中介连接民主与力量。","sub":[{"t":"以民主集中制发动全党积极性来锻炼干部巩固团结","d":"为达\"伟大的革命要有伟大的党与许多最好的干部\"之目的，实行党的民主集中制：在反动内战时期集中制较多，新时期则使集中密切联系于民主；用民主制的实行发动全党积极性，再用积极性去锻炼大批干部、肃清宗派观念残余，把全党团结得像钢铁一样，从而在干部与组织上支撑革命。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以层级递进的团结作为战胜敌人的基础","d":"团结不是一次性、平面地达成，而是按层级递进：先实现先锋队内部的团结，再经过它达到全阶级、全民族的团结，最后凭这种广泛团结战胜敌人、完成任务。每一层级的团结是下一层级的前提，基础的团结决定最终胜利的可能。","sub":[{"t":"以层级递进的团结作为战胜敌人的基础","d":"面对民族与民主革命的任务，先确认党的团结是\"当前民族和民主革命最重要的基础\"；再据\"只有经过共产党的团结，才能达到全阶级和全民族的团结，只有经过全阶级全民族的团结，才能战胜敌人\"的层级递进，把全党在政治上的一致转化为阶级与民族的团结，作为完成革命任务的前提。","p":["为争取千百万群众进入抗日民族统一战线而斗争"]}]},{"t":"以实践作为检验与发展认识的根本标准","d":"认识是否正确、是否需要发展，不依主观认定或理论自身，而由它回到实践后是否达到预想结果来判定。实践因而是检验真理的根本标准，也是理论继续深化与发展的动力；理论若束之高阁不实行，便无从证实也失去意义。","sub":[{"t":"以理性认识回到实践检验并发展理论","d":"面对\"已取得理性认识后如何使其不沦为空谈并继续深化\"的问题，先把理性的认识再回到改造世界的实践中去应用；再看它是否达到预想目的，据此证实或纠正理论。检验和发展理论不是认识终点之后的附加，而是整个认识过程的继续，使理论在尔后实践中被证实或纠正其不完全与错误。","p":["实践论"]},{"t":"以实践结果作为判定认识真理性的标准","d":"面对\"如何判定一个认识或理论是否为真理\"的问题，不以主观上觉得如何、理论上是否自洽而定；而以客观上社会实践的结果如何而定——只有在社会实践过程中，人们达到了思想中所预想的结果时，认识才被证实。据此排斥一切否认实践重要性、使认识离开实践的错误理论。","p":["实践论"]}]},{"t":"以亲身实践为认识之源并据客观性质判定间接知识","d":"对未经亲身经历的事物，要取得直接真知必须亲身参加变革该事物现实的实践，才能触其现象、暴露其本质；对他人的间接知识，不能仅以来源取信或轻视，而须以其是否真实反映客观（科学的抽象）判定可靠与否。","sub":[{"t":"以亲身变革现实的实践取得直接真知并据客观为准对待间接经验","d":"面对\"知识从何而来、如何对待未亲身经历的知识\"的问题，要直接认识某事物，须亲身参加变革该事物的实践，才能触到其现象并暴露其本质；同时承认一切真知源于直接经验，但多数知识为间接经验，对古人与外人的间接知识，须以其是否\"科学的抽象\"（即是否科学反映客观事物）判定可靠与否，不凭来源轻信或轻视。","p":["实践论"]}]},{"t":"使认识随客观过程的推移发展并以具体的历史的统一为准则","d":"认识不是一次完成，须随客观过程由一阶段向另一阶段的推移而发展，及时改正错误方案、提出适合新情况的任务。正确与否的界限是主观与客观、理论与实践、知与行具体的历史的统一，据此反对思想落后于实际与超过阶段的两种偏差。","sub":[{"t":"使认识随客观过程的推移发展并以具体的历史的统一反对左右偏差","d":"面对\"认识如何在变化发展的过程中保持正确\"的问题，从事变革现实者须随客观过程由一阶段向另一阶段的推移而转变主观认识，善于改正错误方案、提出适合新情况的任务；并以\"主观和客观、理论和实践、知和行的具体的历史的统一\"为准绳，反对思想落后于实际（右倾）与思想超过阶段、\"左\"翼空谈（冒险主义）两种偏差。","p":["实践论"]}]},{"t":"由对象内部的对立关系解释其变化，外部影响只作条件","d":"对象为什么变化，首先由它自身内部互相对立的方面决定；外部影响是变化的条件，须通过内部的根据才发生作用。据此解释差异与转化时应先追问对象内部的对立关系，而不把原因外推；外部条件相近而结果不同的事实，正是这一定位的检验。","sub":[{"t":"从事物内部的矛盾寻找变化的根据并把外因定位为条件","d":"面对\"这一事物为什么发生变化\"的解释问题，先拒绝把原因单纯归于外部推动；转而在事物内部找出互相矛盾的方面，把发展看作内部矛盾引起的自己的运动，把与他事物的联系影响列为第二位原因。再把外部影响定位为条件，承认它只有通过内部的根据才起作用；并用外部条件相近而结果不同的对照检验这一定位，从而解释质的差别与互相变化，而不只解释数量增减。","p":["矛盾论"]}]},{"t":"由对象特有的对立关系逐层展开其本质与差别","d":"一类对象区别于他物的本质，由它自身特有的对立关系规定；要把握这种特殊性，须由总体到各个方面、由全过程到各个阶段逐层展开差别，而不能停留在表面或只看一方。层次展开得越完全，对象的本质与它同他物的边界才越清楚。","sub":[{"t":"逐层分析矛盾的特殊性以确定对象的本质与研究范围","d":"认识一类对象时，先注意它与其他运动形式的质的区别，找出其本身特殊的矛盾——这一特殊矛盾构成它区别于他物的特殊本质，研究领域的划分亦据此。再研究其发展长途中每一过程的特殊矛盾；进而从矛盾各个方面着手，了解各方各占何等地位、以何种具体形式互相依存又互相斗争；还要注意各发展阶段的特点及阶段上各方的特点。全过程反对主观性、片面性和表面性。","p":["矛盾论"]}]},{"t":"在个别与一般之间往返以形成并修正共同认识","d":"一般性的认识只能由许多个别对象的特殊性概括而来，形成之后又必须回到新的个别对象中去检查和补充。缺少前一方向，一般就成为凭空的公式；缺少后一方向，一般就会枯槁僵死。认识的深化依赖这两个方向反复联结。","sub":[{"t":"在个别与一般之间双向往返形成并修正共同认识","d":"面对\"一般结论从哪里来、又怎样不至于僵死\"的问题，先由认识许多个别的、特殊的事物的特殊本质入手，逐步概括出诸种事物共同的本质；再以这种共同认识为指导，继续研究尚未研究过或新冒出来的具体事物，找出其特殊本质，用以补充、丰富和发展原有的共同认识。两个过程互相联结、循环往复，每次循环都可能使认识提高一步；据此反对把一般真理看成凭空出现的抽象公式。","p":["矛盾论"]}]},{"t":"解决办法的性质须与问题的性质相应","d":"解决办法不能由一个通用公式给出，只能由问题自身的性质决定；问题的性质变了，办法也应随之更换。冲突是否已取激烈的外部形式同样是一种性质差别，并可依条件互相转化，因而处理方式与限度须按当前性质确定，而不是一律采取最激烈或最和缓的形式。","sub":[{"t":"按矛盾性质的不同选择解决方法与斗争形式","d":"面对\"用什么方法解决这个矛盾\"的问题，先判定该矛盾的质——不同质的矛盾只有用不同质的方法才能解决；过程变化、旧矛盾消灭而新矛盾发生时，方法也随之改变。进一步区分斗争形式：对抗只是矛盾斗争的一种形式而非一切形式，有些矛盾具有公开对抗性，有些则不是，二者依发展可以互相转化。据此对尚未取对抗形式的矛盾既严肃斗争又留出改正机会而反对过火，并反对把任一公式到处硬套。","p":["矛盾论"]}]},{"t":"由取得支配地位的一方判定对象的性质","d":"对象的性质不由并存的各方平均决定，而由当下取得支配地位的一方规定；双方地位随力量消长而互易，性质也随之改变。因此判定性质要先找出当前的主导方面，预判变化要观察力量对比的方向，而不能把任何一方的地位当作永久固定。","sub":[{"t":"由取得支配地位的矛盾方面判定事物的性质及其变化","d":"判定一个事物\"现在是什么\"时，先承认矛盾双方发展是不平衡的：必有一方处于支配地位、起主导作用，事物的性质主要由这一方面规定。再观察双方斗争中力量的增减：新的方面由小变大上升为支配的东西，旧的方面由大变小趋于消亡；一当支配地位易手，事物性质随之变化。据此既承认生产力、实践、经济基础一般起决定作用，也承认生产关系、理论、上层建筑在一定条件下转过来起主要的决定的作用。","p":["矛盾论"]}]},{"t":"对立面的转化以具体条件为限","d":"相反的两方并非彼此隔绝，在一定条件下可以向对方所处的地位转化；但转化不是任意的，能否发生取决于必要条件是否具备。因此判断变化的可能，应把注意力从愿望转向条件的考察；共处的统一是有条件而相对的，双方的相互排斥则是无条件而绝对的。","sub":[{"t":"依一定的必要条件判断对立面的相互转化","d":"判断\"这一事物能否变为它的反面\"时，先确认矛盾双方互为存在的条件、共处于一个统一体中；再找出使转化得以发生的具体的、必要的条件——缺乏这些条件就没有同一性，转化也不可能。据此把现实的、具体的转化同幻想的变化区别开来。进而承认这种统一是有条件的、暂时的、相对的，而斗争贯串始终、是无条件的绝对的，因而应把对立看作可变动、可转化的东西，并通过具备条件促成转化。","p":["矛盾论"]}]}],"2":[{"t":"以解除限制释放主体自身的力量","d":"力量不足时，除增加投入外还有一条途径：解除对被组织者的限制，承认其自主活动的合法性，使其自身力量被释放出来并与专门力量配合。限制不解除，这部分力量就始终不能计入总量。","sub":[{"t":"以解除限制把民众力量转为可用力量","d":"面对己方力量不足，不只在既有专业力量内部想办法，而解除对民众的限制以释放其自身力量：开放爱国运动、废除束缚爱国运动的旧法令、释放政治犯并开放党禁、承认爱国团体的合法地位、武装民众实行自卫，使其配合正规力量作战。并指出联合的名义范围与实际范围不符时，缺席的这部分力量直接造成前线失利。","p":["反对日本进攻的方针、办法和前途","为动员一切力量争取抗战胜利而斗争","国共合作成立后的迫切任务","和英国记者贝特兰的谈话","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"以配套安排落实总方向","d":"一个总方向要真正成立，必须在它所涉及的各个方面都有与之相适应的具体做法；只宣布方向而各方面照旧，方向就落空。做法总是反映着实际奉行的方向，因此确定方向之后应把它贯彻为互相配合的成套安排。","sub":[{"t":"按总方针推导覆盖各领域的配套办法","d":"确定总方针后不停留在宣布，而把它推到各相关领域：逐一检查军事、民众、政治机构、对外关系、民生、教育、财政经济、联合阵线等方面现行做法是否与总方针相适应；凡不适应者一并改变，为每个领域写出具体可执行的政策，使各项互相配合成为一整套。条款化的成套纲领同时可充当多方共同行动的具体基础。","p":["反对日本进攻的方针、办法和前途","为动员一切力量争取抗战胜利而斗争","和英国记者贝特兰的谈话"]}]},{"t":"以必然相连的行为判断真实意图","d":"意图不能直接观察，但与某种意图必然相连的行为可以观察。应先把该意图在实践上必然要求的做法明确列出，再以对方是否采取这些做法作为判据；言辞与实际做法不一致时，以做法为准。","sub":[{"t":"以是否实行配套办法检验表态的真实性","d":"判断一方对已宣布的方针是否真有诚意，不看其言辞与承诺，而看其肯不肯采取并实行与该方针必然相连的那一整套办法。为此先把这套办法明确列举出来，使之成为可核对的清单；再把样样相反的一套同样列出，使两者形成可对照的识别标志；对方的实际取舍即构成判据。","p":["反对日本进攻的方针、办法和前途","和英国记者贝特兰的谈话"]},{"t":"以言行一致与人己同一检验对原则的接受","d":"判断一个人是否真正接受某项原则，不以其是否表示赞成为据，而看两项对照：说的与行的是否一致，对人与对己是否用同一标准。凡赞成而不准备实行、或不准备完全实行、不准备用它代替自己原有的东西者，是把原则当作抽象的教条看待。据此把问题定位为思想方法问题。","p":["反对自由主义"]},{"t":"以必然相连的行为判断真实意图（识破和平烟幕）","d":"判断一方释放的\"和平\"言辞背后的真实意图，不按其表面说辞理解，而追究其达到某一步骤后必然要实现的若干目的（巩固阵地、分裂阵线、拆散国际援助），据此判明和平言辞实为诱降与分裂，并警示动摇者正准备上钩。","p":["和英国记者贝特兰的谈话"]}]},{"t":"把对象拆成已变与未变的方面分别判断","d":"对处在转变中的对象不宜给出单一整体评价。应分别确认哪些方面已经改变、应予承认，哪些方面依然照旧、构成主要障碍；未变的部分往往是为旧任务设计的，与已变部分不相适应，下一步的关键要求正由此决定。","sub":[{"t":"分别判定对象已变与未变的方面以确定关键要求","d":"对一个正在转变中的合作对象，不作整体的好坏评价：先具体列出它已经发生的转变并予以承认；再逐项指出它依然照旧的方面，说明这些方面本为另一种任务设计，用于新任务必然处处不适合，这种不相适应即是当前弱点的来源；由此推出下一阶段的关键要求，指向全部的和彻底的转变而非零星修补。","p":["为动员一切力量争取抗战胜利而斗争","国共合作成立后的迫切任务","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"以可比先例的实际结果支持当前判断","d":"对尚未发生的后果，可用同类情形中已经发生的结果作为依据。应同时取用失败与成功两类可比先例，其中同一对象自身的历史尤为有力；两类并举可避免只见一面，也使当前应采取的做法有据可依。","sub":[{"t":"并举正反可比先例支持当前抉择","d":"面对本方尚未经历、后果只能推想的重大抉择，成组援引可比先例：既举失败的，又举成功的，并优先取用同一关系自身的历史——合作时获得了什么成就、破裂后招致了什么后果。使抽象的后果变成已经发生过的事实，据以要求当前必须采取的行动。","p":["为动员一切力量争取抗战胜利而斗争","国共合作成立后的迫切任务","和英国记者贝特兰的谈话"]}]},{"t":"把可能性归结为互斥路线并追踪其必然结果","d":"当局面因游移不决而难以推进时，可把散乱的可能性归结为若干根本矛盾、不能并存的路线，逐条说明每条路线所要求的做法及其必然结果；结果一旦明确，选择就不能再被回避，摇摆本身也不再是一种可行状态。","sub":[{"t":"以互斥路线及其确定后果排除游移","d":"面对普遍存在的游移、动摇与观望，先把散乱的可能性归结为两条根本矛盾的路线，指明二者不能并存；再为每条路线写出与之相应的成套做法，说明它们各自必然导向的结果；把结果讲到底、不留侥幸余地，使选择及其代价变得明确；最后要求明确地实行一条、反对另一条。","p":["反对日本进攻的方针、办法和前途","和英国记者贝特兰的谈话","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"以共同任务的高低次序统辖局部计较","d":"联合行动中局部利害必然存在，不能靠取消它来求得一致。应确立一个压倒性的共同任务作为高一层的衡量尺度，把各方局部考虑放在它之下判断是否可行，并要求以实际做法而非言辞体现这种从属关系。","sub":[{"t":"以共同的大任务统辖各方局部计较","d":"多方联合行动中出现相互猜疑、打小算盘、阳奉阴违时，不逐件计较是非，而先确立压倒一切的共同任务作为衡量尺度，声明一切局部考虑都归它管着；要求各方从这个尺度上重新安放自己的想法和做法；同时指出团结要做得好看而不只是讲得好听。","p":["反对日本进攻的方针、办法和前途"]}]},{"t":"按能否达到根本目标判定做法的限度","d":"一种做法能取得局部效果，不等于能达到根本目标。评价做法时先确定根本目标，再判断该做法在原理上能达到什么程度；只能取得局部效果者不可作为总方针，须另立能达到根本目标的做法并说明其成立条件。","sub":[{"t":"以能否达到根本目标判定方针的限度","d":"面对一种看似可行的方针，不笼统否定，先承认它能取得的有限效果，再指出它在原理上达不到根本目标；由此判定它不足以作为总方针，另立能够达到根本目标的方针；同时说明新方针成立所必需的前提条件，使它不停留在口号。对以该方针为根据的派生主张一并否定。","p":["为动员一切力量争取抗战胜利而斗争","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"由具体表现、实际损害与来源共同确定一种倾向","d":"对没有明确边界的倾向，单凭定义无法处置。应把它落到可对照的具体表现，说明它造成的实际损害，再追溯其产生来源；三者合起来才使它成为可辨认、可归因、可纠正的对象，纠正办法也由来源而非印象决定。","sub":[{"t":"按表现、危害、来源逐层落实一种弥散倾向","d":"面对一种没有明确边界、人人可能沾染却难以指认的倾向，不停留在定义与总体谴责：先把它在日常关系和工作中的具体表现逐条列出，每条写成可对照自身行为的短句并编号，并声明清单可以再举、不求穷尽；再说明它对整体造成的实际损害；再追溯其产生来源；最后据来源给出克服办法与合格标准。","p":["反对自由主义","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"由客观作用而非主观归属判定性质","d":"一种内部现象的性质不由当事人的自我归属或主观动机决定，而由它在客观上产生的作用决定。应先确定它使整体发生什么实际变化、对哪一方有利，再据此判定其性质，并由性质决定它能否被容许存在。","sub":[{"t":"由客观作用判定内部现象的性质与去留","d":"判断内部一种消极现象能否容许存在，不看当事人是否自认属于本方，也不看其主观动机是否恶意，而看它在客观上产生什么作用：它使整体失掉组织和纪律、使决定不能贯彻、使组织与群众隔离，客观上起着援助对立面的作用。据此判定其性质并明确宣布队伍中不应保留它的地位。","p":["反对自由主义","和英国记者贝特兰的谈话","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"以有原则的争论求得真实一致","d":"回避分歧所得的一致是表面的，会使问题积累并侵蚀整体。应把公开的原则争论当作达成真实一致的手段而非其反面；争论的正当性由目的界定——为把事情弄好而争论是正当的，为个人意气而争论不是；处置的目标是使对方转到正确方面，而不是清除对方。","sub":[{"t":"以有原则的争论求得团结并界定其边界","d":"面对为求和气而回避分歧的状态，先确立关系：积极的思想斗争不是团结的对立面，而是达到团结、使之利于战斗的武器。再界定正当边界：争论必须为了团结、为了进步、为了把事情弄好，凡个人攻击、闹意气、泄私愤、图报复者不属此列。再定要求：无论何时何地坚持正确的原则。最后定目标：使有此倾向的人改变过来。","p":["反对自由主义","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"以共同接受的行动约束换取联合的坚固","d":"多方联合若只靠意愿和一致表态，随情势变化即会松散。应把共同行动方针写成明确纲领，使它同时成为对各方的约束；联合的坚固程度取决于是否存在这样一个各方都受其拘束的共同标准，而不取决于宣布团结的次数。","sub":[{"t":"以共同纲领作为联合的约束","d":"使联合坚固不靠反复宣布团结，而靠一个为各方共同承认并正式公布的行动纲领：先指出仅有一致表态、没有共同纲领，联合就停留在松散状态；再说明纲领既是共同行动方针，又是对各方的约束，像一条绳索把一切加入者紧紧约束起来；再以新的约束代替为旧任务而设的旧约束；最后把纲领内容明确为可执行的条款。","p":["国共合作成立后的迫切任务","和英国记者贝特兰的谈话","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"按阶段与实质判定两种主张能否并存","d":"两种主张看起来不能并存，常因把它们放在同一时间上比较、又只比名义。应先区分各自适用的发展阶段，再把它们还原为实质要求逐项对照；阶段不同或实质一致者可以并存。己方在现阶段收回的做法须说明其客观原因与时间性，以区别于放弃。","sub":[{"t":"以阶段划分与实质对照解除两种主张的表面冲突","d":"面对\"接受对方主张是否等于放弃自己主张\"的质疑，不作名义上的辩解：先按发展阶段区分，说明己方的最终主张属于将来阶段，现阶段实行的是历史规定的另一层任务；再把对方主张逐项还原为实质要求，对照己方历来实行的政策，证明实质上早已在实行；对现阶段收回的做法说明其客观原因与时间性。最后把争论焦点转到对方实行不实行。","p":["国共合作成立后的迫切任务","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"检查执行工具是否适合所要执行的任务","d":"一项任务能否完成，不只取决于任务本身是否正确，还取决于承担它的组织是否适合。应把执行主体单独作为对象检查：它原为什么任务而设、与新任务是否相容；不相容者须改造，且改造可与当前工作同时进行，不必先停下来。","sub":[{"t":"检查并改造执行纲领的组织工具","d":"纲领确定之后，把执行它的组织单独作为对象检查：现有的政府是哪一种性质、现有的军队是哪一种制度，它们原为什么任务设计、与新任务是否相容。判定不相容者必须改造，并给出改造原则；说明改造不必等待当前工作结束，一面做一面即可改变制度；再确定改造的中心任务落在哪一环；最后援引已有的成功前例与失败教训作为样板。","p":["国共合作成立后的迫切任务","上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"以已产生的效果为证据并标明其限度","d":"判断一项新事物的作用，应列举它已经产生的可观察结果作为，而不是重述主张本身；每列一条同时说明这条自身还不足到什么程度，使判断既有根据又不被夸大；全部合起来才支持趋势结论。","sub":[{"t":"列举已产生的效果为证据并同时标明其限度","d":"判断一项新事物是否真正在起作用，不凭主张本身，而列举它已经产生的可观察结果作为：逐条编号列出，每条写清事实内容；同时在每条之后指出这一条自身还不足到什么程度，使肯定与保留同时成立；最后声明根据上述作出趋势判断，使结论的根据可以逐条核对，也使它不被夸大为已经完成的事实。","p":["国共合作成立后的迫切任务","和英国记者贝特兰的谈话"]}]},{"t":"从对立双方成败因素的互含中预判趋势","d":"对一时强弱不宜只按表面胜负下结论。应分辨：己方失败中已孕育的胜利因素、对方胜利中已包含的失败因素；把趋势判据建立在双方成败因素的互相包含之上，而非建立在某一时刻的表面输赢之上。","sub":[{"t":"由失败与胜利中的互含因素判读斗争趋势","d":"面对悲观主义只看见失败、看不见胜利因素，先指出\"失败是成功之母\"，从失败经验中取得的教训即是将来胜利的基础；再揭示当前失败中已包含的胜利因素，同时指出对手在胜利中包含的失败因素；最后据此向群众指明胜利前途与困难暂时性，使摇摆者看清趋势、坚定斗争。判断趋势的依据不在表面的胜败，而在对立双方成败因素的相互包含。","p":["和英国记者贝特兰的谈话"]}]},{"t":"从互相补足的方面拼出完整判断","d":"对一时强弱或局势走向不宜只按某一面下结论。应把局面拆成互相补足的若干方面分别估量，再把各方向并置对照，使完整判断建立在几面的合取之上，而非建立在单一突出的现象之上。","sub":[{"t":"从互相补足的方面拼出对局面的完整判断","d":"面对复杂局势不下单面结论，而把它拆成\"一方面…另一方面…\"等互相补足的方面分别列举事实；再把局面可能的发展方向与各方向的条件并列对照；最后把几方面合起来，才得出对全局的阶段性判断（如\"过渡期\"）。缺任一方面都会要么高估危机、要么低估危险。","p":["上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"按阵营位置分派不同任务","d":"对包含多方的阵线，不宜一刀切地同等要求。应按各组成部分的客观位置划分阵营，由位置决定对该部分的主要任务（巩固先进、争取中间、反对对立），使总体策略建立在对阵线内部结构的判别之上。","sub":[{"t":"按阵营位置分派不同任务","d":"面对一个包含多方的联合阵线，不平均对待，而按各组成部分的客观位置把它分为左、中、右等集团；对最可靠、最先进的左翼集团，任务是扩大和巩固；对动摇的中间集团，任务是争取其进步和转变；对倾向对立的右翼集团，任务是坚决反对。各集团任务由其在阵线中的客观位置决定，并在反对一端的过程中扩大与争取其余。","p":["上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"保持与发展作为不可分离的双重目的","d":"推进事业时，保存既有阵地与扩展新阵地是同一目的的两面，不可偏废。既有阵地是战略出发地，发展新阵地是积极目的；二者互为条件，拆开任一面都会使事业失去依托或失去方向。","sub":[{"t":"把保持阵地与发展阵地作为不可分离的双重目的","d":"推进一项事业时，把目的分为两层：一层是保持已经取得的阵地，它是继续一切工作的战略出发地，丧失则无从说起；但主要目的在另一层，即发展阵地、扩大影响与队伍。两层不可分离：只保不展会萎缩，只发不保会失去依托。以\"保持与发展不可分离\"统摄日常工作与群众动员。 # Method Dedup Index（07–12 批次） **批次：** 07-12（每 6 篇一个独立 method index 文件） **当前覆盖：** 第 07-12 篇 · 6 篇 Evidence · 19 个…","p":["上海太原失陷以后抗日战争的形势和任务"]}]},{"t":"在合作关系中以共认原则作为处置对方越界行为的依据","d":"处在合作关系中而对方从内部造成损害时，处置的依据不能只由自身立场提供，否则处置本身会被当作对合作的破坏。应先确定双方都已承认的原则与共同目标，再把对方行为按这一原则定性，使制止成为执行共同原则的一个环节，而不是对合作的否定。","sub":[{"t":"以双方共认的原则为判据界定破坏行为并据以反制","d":"在与对方存在合作关系而对方从内部进行破坏时，不以己方受损或双方对立为出发点提出指控。先复述双方都已承认的共同前提与共同事业，并把自身既有做法置于该前提之下；再逐项列举对方的具体行为，按同一原则判定其性质与后果，指出它损害的是合作本身与共同目标；进而把取缔说明为增强共同事业力量的必要措施，并在具体条款中援引对方发布的纲领作为推行依据。","p":["陕甘宁边区政府第八路军后方留守处布告"]}]},{"t":"以确定的时点划界使让步不溯及既有成果","d":"作出政策让步不等于承认此前的处置无效。应取一个确定的时点作为界线，把该时点以前已经完成的结果确认为不可变更的既成事实，把此后的行为纳入新原则之下。让步因此只对将来发生作用，不成为对既有成果的清算，界线本身也使双方在什么可以改变、什么不可以改变上有据可依。","sub":[{"t":"以确定时点划界确认既得成果并分类处置","d":"当政策因合作而作出改变、而对方借此要求全面倒退时，先取一个确定的时点作为界线。该时点以前已经完成的处置确认为既得利益，宣布不准擅自变更；该时点以后按合作原则改进和发展起来的事物，另列一类同样加以保护。处置态度按类别分别给出：对既得成果是保护，对新的发展是促进，对破坏行为是制止。政策改变由此只对此后的行为发生作用。","p":["陕甘宁边区政府第八路军后方留守处布告"]}]},{"t":"在实质难以逐项甄别时以统一形式要件与本地报告替代内容审查","d":"当有害行为借合法名义出现、逐项核实其实质代价过高时，判别标准应从\"内容是否有害\"转为\"是否具备统一的形式要件\"，不具备者一概不予通行；同时把发现线索的环节交给最接近事实的一方，并在处置端设置与查实两道关口。开放的声明与统一的限制并列，使简化判别既不放过渗透，也不误伤协助。","sub":[{"t":"在真伪难辨时以统一凭证与群众告发两道程序处理渗透","d":"面对以合法名义出现、逐项核实代价过高的渗透活动，放弃按活动内容逐项甄别，改设两道程序。事前准入：凡从外部进入本区域停留活动者，不论所办事务属于何项，一律须先经主管机关同意并持有证明文件；同时公开声明凡有利于共同事业者无不乐于推行，使管控不变成闭关。事后查处：准许民众告发，再设两道门槛——确实才准许逮捕，讯问查实才予严惩。","p":["陕甘宁边区政府第八路军后方留守处布告"]}]},{"t":"按对方状态在几种相反的做法之间及时切换而不固守一种","d":"条件不断变化的活动中，任何一种做法都只在特定条件下有效，固守一种必致被动。应把可用的做法作为一组并列手段，按当前任务与对方状态选择；每次切换都须设定重心、明确各部分的任务与联络，使切换不流为无计划的乱动。判断力的高低不在于知道手段的多少，而在于是否及时。","sub":[{"t":"按任务与情况在分散、集中、转移之间及时变换力量配置","d":"把力量配置归为分散、集中、转移三种方式，按任务和对方情况、地形、居民等条件变动。分散用于对方取守势、薄弱地区骚扰破坏、减小目标脱离、地形给养受限、广大地区群众工作；分散时须保持较大一部分力量于机动地区，并给各部明确的任务、地区、时期、集合地点与联络方法。集中用于消灭对方，主力用于某一重要方面而其余留置部分力量。转移用于当地不利作战时，须秘密迅速并以声东击西等法迷惑对方。关键在按具体情况及时实行。","p":["抗日游击战争的战略问题"]},{"t":"按对方攻守姿势的变换切换己方的守势与攻势方针","d":"把同一基地上的行动按对方姿势分为两种形势各配一套方针，并规定切换时机。对方进攻时：以次要力量牵制其数路、主要力量对付其一路，用袭击埋伏打击之，围困其占据的城镇，一路打破再转打另一路；对方久踞不去则倒置使用，以主力进攻其来处迫其撤退；同时动员当地武装与群众。对方转守时：不攻其固守阵地，而消灭小股、扩大地区、发动群众、补充训练，休整在做事中完成；随后观察其朕兆及时转回守势。","p":["抗日游击战争的战略问题"]}]},{"t":"按对象条件的组合确定问题所属的层级","d":"一个手段在整体中的地位与它应在哪一层级上被考察，是两个不同的问题，不能由前者直接推出后者。判定后者的依据是对象自身条件的组合：当这些条件使它的活动范围、持续时间和规模超出局部配合时，它就产生成套的全局性问题，必须在更高层级上处理。而它之所以需要单独考察，也正说明上位层级的现成结论不能对它照搬。","sub":[{"t":"以条件反设的对照确定问题应放在哪一层级上考察","d":"对一个在整体中处于辅助地位的手段，先不否认其辅助地位，而单独追问它是否只有局部性的问题。设想若干与本对象条件不同的情形，指出在那些条件下它确实只起近距离配合作用；再列出本对象的实际条件组合，说明这些条件产生出活动范围广、持续时间长、独立作战、规模巨大等后果，于是成套问题随之发生。据此判定它须在全局层级上考察，同时补一条相反的限定：既然它有特殊性，上位层级的现成结论也不能照样搬用。","p":["抗日游击战争的战略问题"]}]},{"t":"以一个贯通全部行动的基本原则作为各层级具体做法的根据","d":"繁多而层级不同的做法要成为一个体系，须有一个能贯穿全部行动的基本原则作根据；各层级的具体规定不是并列的条目，而是执行这一原则在不同条件下的形态。看来与基本原则相反的做法，应通过区分部分与全体、暂时与长久来检验；能被这样解释的即不构成例外，反而是这一原则的必要环节。","sub":[{"t":"以一个基本原则统贯各层级的具体原则并消解表面矛盾","d":"先确定一个能贯穿全部行动的基本原则，并说明它与总目的的联系；再用它检验那些看来与之相反的做法，通过区分部分与全体、暂时与永久，说明二者相反相成而非矛盾；然后把从最低层的技术原则到最高层的全局原则逐层排列，指出每一层原则都只是执行这个基本原则时的条件，使各层级的具体规定获得统一的根据。若对象另有特殊需要，则在基本原则上追加一项而不另立体系。","p":["抗日游击战争的战略问题"]},{"t":"把根本任务贯通到一切具体行动","d":"先确定能贯穿全部行动的根本任务或目的（如\"保存自己、消灭敌人\"），再检验各层级具体原则是否偏离它。看来相反的做法（防御、退却、牺牲）经区分部分与全体、暂时与长久，说明其相反相成、正是执行根本任务的环节；技术、战术、战役、战略各层规定都回到这一目的之下获得统一根据。","p":["论持久战"]},{"t":"在民族解放战争中把国际主义与爱国主义统一","d":"当普遍原则（国际主义）与具体立场（爱国主义）看似冲突时，不把二者对立，而先看历史条件：在被迫侵略国，民族解放正是国际主义的具体实施，保卫祖国即同时实现二者；对侵略国则求其战争失败才符合人民利益。判断\"爱国是否正确\"取决于其历史条件与是否服务于人民解放。","p":["中国共产党在民族战争中的地位"]},{"t":"照顾全局与多数并与同盟者一道工作","d":"领导斗争时先立\"局部需要服从全局需要\"的判断：某项意见局部可行而全局不可行，或反之，都以全局为准。不脱离群众多数单独冒进，注意组织先进分子与广大群众的联系；凡有愿合作的党派人士，采取与之商量、与之共事的态度，独断专行、置同盟者于不顾都不对。","p":["中国共产党在民族战争中的地位"]},{"t":"认清主要斗争形式与组织形式并使一切工作配合它","d":"先判定本国革命的主要斗争形式与主要组织形式（中国=战争与军队），再把其他一切组织和斗争都列为直接或间接地配合它的工作：战前一切组织斗争为准备战争，战后一切组织斗争为配合战争；后方与敌占区的党的工作、民众运动都服从前线要求。全党注重战争、学习军事、准备打仗。","p":["战争和战略问题"]},{"t":"承认有军则有权但坚持党指挥枪、争党的人民的兵权","d":"承认\"有军则有权\"\"枪杆子里面出政权\"是客观真理，劳动人民须觉悟掌握枪杆子的重要性；但明确力量的持有与领导权分离：不争个人兵权、要争党的兵权、人民的兵权、民族的兵权，原则是党指挥枪，决不容许枪指挥党。枪杆子可造党、造干部、造文化，但都服从党的政治领导。","p":["战争和战略问题"]}]},{"t":"在总体与局部两层上分置相反取值并靠局部结果的累积改变总体","d":"总体上不利的态势并不规定每一次具体行动都必须同样取值。应把总体与局部分为两个层级，找出在局部层级上条件适得其反的那些方面，据此取与总体相反的值。这样得到的局部结果不是孤立的战果，而是改变总体态势的材料：只有把足够多的局部结果集合起来，总体上的被动才转为主动。","sub":[{"t":"在总体态势之下于局部取相反取值并以局部结果的累积改变总体","d":"先按双方强弱与攻守关系确定总体上不得不采取的态势；再找出在另一方面适得其反的条件——对方数量不足、己方数量众多、对方是外来者，据此在每一次具体行动上采取与总体相反的取值。执行要求随之具体化：集中尽可能多的兵力，秘密神速，出其不意，迅速解决战斗，力戒消极防御、拖延和临战分散。同时说明累积关系：许多次局部胜利集合起来才达到总体目的，不能包围其全部就包围其一部。","p":["抗日游击战争的战略问题"]},{"t":"以局部优势与主动的累积改变总体态势","d":"在总体上劣势、被动时，不要求每次行动都改变总体，而先在每一战役战斗上人工造成局部优势与主动：以多兵对少兵、从外线包围、迅速解决。把许多这样的局部胜利集合起来，弱者的局部优势与主动累积成战略上的优势与主动，总体态势随之转化。","p":["论持久战"]},{"t":"以战略上相反的具体做法落实总体方针","d":"当总体方针与局部可行做法方向相反（总体防御、持久、内线）时，不把总体方针直接搬到每一仗，而用局部上相反的做法去实现它：战略防御中打战役战斗的进攻战，战略持久中打速决战，战略内线中打外线作战。这种\"相反\"恰是实现总体方针的必要方针。","p":["论持久战"]},{"t":"在力量不利时避免战略决战以空间换时间","d":"在敌强我弱、敌求我主力决战而我不求时，对无把握者避免决战、对赌国家命运的战略决战根本避免。在无可避免时勇敢放弃部分土地，以土地换时间、保存军力，促进并等待国内进步、国际增援与敌之内溃。局部放弃恰为保存全局根本，集合起来为反攻创造条件。","p":["论持久战"]},{"t":"把让步与互助作为积极的环节联系总革命路线","d":"在统一战线中实行互助互让时，不把让步看成纯消极的放弃，而把它当作整个革命政策的一部分、联系于总路线、当作曲线运动的一个片断。用\"让了前者就得了后者\"判断是否达到积极目的；以\"有所不为而后可以有为\"区别积极让步与投降主义式的纯消极让步。局部退让服务于总体积极目的，是总体目的下的相反取值而非对立。","p":["统一战线中的独立自主问题"]},{"t":"在战争全体上以正规战为主、游击战为辅，同时确认游击战极重要战略地位","d":"在战争全体上（全过程三阶段）以正规战争为主要、游击战争为辅助，因为最后命运由正规战解决；同时确认游击战争占极重要的战略地位——大半个中国将成敌后，没有最广大的游击战争则正面主力损伤必大、相持难现、反攻无呼应。二者在分工中互相配合：国民党任正面正规战，共产党任敌后游击战，互相需要、协助。","p":["战争和战略问题"]}]},{"t":"行动的自由由对双方弱点的估计与相应处置产生而非由力量对比给定","d":"处于不利地位的一方并非只能被动。行动的自由不是强者的固有属性，而是从对客观情况的虚心研究、正确估计和相应处置中产生的：把对方的弱点逐项列出，每一项都对应一件自己可以放手去做的事；自身的弱点也不全是负担，其中有的正是取得自由的条件。估计上的两种相反偏差都会使已有的自由丧失。","sub":[{"t":"依据对方弱点逐项确定自己可以放手去做的事","d":"先逐项列出对方的弱点——力量总量的不足、身份带来的与当地人的对立、指挥上的具体失误；再对每一项弱点确定自己可以放手做的一件事：因其力量不足而放手扩大活动地区，因其与当地人对立而放手争取民众拥护，因其指挥笨拙而放手发挥自己的判断。对自身弱点两面处理：在斗争中逐渐减少，同时识别其中哪些反而构成便利。估计上须防两端：悲观与消极、乐观与冒险都会丧失自由。已陷被动时以脱离接触为主要办法。","p":["抗日游击战争的战略问题"]},{"t":"利用民众条件造成敌人错觉与不意争取主动","d":"在敌强我弱下争取主动，不靠兵力优势而靠主观指导与制造敌人失误。先以优越的民众组织封锁消息，再用声东击西等方法有计划造成敌人错觉，出以无准备的攻击（不意）。这是把战争的不确实性给敌人、把尽可能大的确实性给自己，从而以弱者的主观指导夺得主动。","p":["论持久战"]},{"t":"研究并主动制造敌方指挥错误以利用其内部矛盾","d":"系统研究敌方指挥的固有缺陷（逐次增兵、无主攻方向、无战略协同、失时机、包围多歼灭少），再在己方有组织民众掩护下主动制造其错误——声东击西、调动敌人就我范围；同时警惕敌方亦可乘我之隙。敌方内部矛盾（如集团间不协同）是可供利用的客观基础。","p":["论持久战"]}]},{"t":"按配合发生的层级分别规定责任与协调方式","d":"辅助力量对主要力量的配合不是一件笼统的事。应按配合发生的层级分别规定：有的层级上只要行动本身有效即自然构成配合，有的层级上必须依据当时当地情况主动对准对方的要害并建立协调手段，有的层级上必须服从指定任务。不作这种区分，就会以高层级上的自然配合抵消低层级上应尽的具体责任。","sub":[{"t":"按配合发生的层级分别规定辅助力量的责任与协调方式","d":"把配合按发生的层级分为三种，各自规定作用与要求。最高层级上，凡削弱、牵制对方与鼓舞己方本身即构成配合，每一点微小消耗都可计入总账。中间层级上，须按当时当地情况配置力量，向对方最感危害之点和薄弱之点行动，并建立必要的通讯手段；此层级缺失会减少最高层级配合的意义。最低层级上，依主要力量指挥者的指示担负指定任务，无指示时也应自动去做。三个层级的责任由此各自落实。","p":["抗日游击战争的战略问题"]}]},{"t":"长期活动的依托须在活动中由自身逐步造成","d":"在没有现成后方的条件下从事长期活动，依托不是预先给定的场所，而是活动过程本身造成的结果：自己的力量、对对方的实际胜利、当地人的组织三者互相依赖，缺一则其余无从谈起。自然条件只划定可能性的大小而不决定成败。区域的归属不是固定的，应按争取程度分出中间状态，并承认它可以向两个方向转化。","sub":[{"t":"以三个互相依赖的条件造成依托并按转化程度区分区域状态","d":"先由活动的长期性与残酷性推出必须有自己的依托，再把不要依托的想法作为一种思想倾向加以清理，并把清理它列为确立方针的前提。依托的造成不是选址问题：先有自己的武装力量，用它并配合群众战胜对方，再用一切力量发动群众的斗争。自然条件只提供可能性，须按地形分类判定可能程度。同时按控制程度把区域分为三类，转化的判据是消灭对方和发动群众的程度，并承认反向转化同样可能；任务是扩大己方与中间地带而缩小对方地带。","p":["抗日游击战争的战略问题"]},{"t":"以普遍深入的政治动员组织民众为力量依托","d":"没有现成后方与伟力时，把分散民众变为持续力量：先告诉军民战争目的与步骤纲领，再靠口说、文字、戏剧、学校、团体等经常地动员，并联系战争发展与群众生活。依托不在事先给定，而在动员活动本身中逐步造成——组织民众、发动斗争、取得实际胜利三者互相依赖。","p":["论持久战"]},{"t":"以坚持正确立场使进步正义性转化为广泛支持","d":"自身的进步性与正义性不会自动变支持，须在坚持中成为现实：坚持抗战、统一战线、持久战，使进步因素发挥、正义性唤起国内团结并争取国际与敌国人民多助。广泛支持这一依托不在事先给定，而在长期坚持与扩大的活动中逐步造成。","p":["论持久战"]},{"t":"以指导检查与培养提高爱护干部","d":"爱护干部不是放任，而是五件事：指导他们放手负责又适时指示，使其在路线下发挥创造性；给以学习机会提高理论与能力；检查工作、帮助总结经验发扬成绩纠正错误，有委托无检查不是爱护；对犯错误者一般说服帮助，只对严重又不接受者斗争；照顾其疾病、生活、家庭等困难。干部队伍作为事业依托，在放手—指示—检查—提高—照顾的持续活动中逐步造成。","p":["中国共产党在民族战争中的地位"]}]},{"t":"通过变换观察范围识别同一格局中并存的相反关系","d":"同一格局在不同的观察范围下会呈现相反的关系，这些关系并不互相取消，而是同时成立。只从一个范围观察，就会把其中一种关系当作格局的全部，从而把自己一方的处境看成单向的。应依次变换范围与尺度，把各次观察所得的关系并列起来；被忽视的任务往往正是在这种并列中显出其全局意义的。","sub":[{"t":"通过变换观察范围识别同一格局中并存的相反关系","d":"对一个看来单向不利的格局，依次变换观察的范围与尺度：从整体看自己处于对方包围之中；缩小到具体接触点，看到分进的对方每一路都处在自己的包围之中；看单个孤立的基地，它又处在对方包围之中；把各基地彼此联系并与主要战线联系起来看，自己又包围了对方许多点。随后以一个结构相似的对象作比，为各要素找到对应位置，把原来被看作局部生存措施的事情判定为必须列入议事日程的全局任务。","p":["抗日游击战争的战略问题"]},{"t":"从多个相反维度同时观察同一战争格局","d":"对同一战争格局，依次变换观察的范围与尺度，把各次所得关系并列而非互相取消：整体看己在内线、被敌战略包围；缩小到接触点，分进之敌每一路都在己包围中；单看孤立根据地，它又被敌包围；把各根据地彼此联系并与主要战线联系，己又包围敌许多点。多个相反关系同时成立，被忽视的任务在并列中显出全局意义。","p":["论持久战"]}]},{"t":"低级形式向高级形式的转化不以取消低级形式为条件","d":"由低级形式向高级形式提高，须同时在数量与质量两条途径上进行，而不能只靠其中一条。转化的正确形态是在广泛存在的低级形式之中生长出能够承担高级任务的主干，低级形式因此不是被取代的对象，而是主干的依托与来源。把提高理解为取消低级形式，主干就失去羽翼与源泉；把低级形式当作不可变动的常态，提高就无从发生。","sub":[{"t":"以数量集中与质量提高使低级形式向高级形式转化而不取消低级形式","d":"先说明转化的必要与可能同出于活动的长期性与残酷性。转化拆为数量扩大与质量提高两条并行途径。数量上除直接补充外采取集中小单位的办法，并防止只顾局部利益妨碍集中与只图扩充自己不顾扶助地方两种相反错误；具体办法是逐渐地和部分地集中、先协同行动然后合编、不破坏建制不撤换干部。质量上从政治、组织、装备、技术、战术、纪律各方面逐渐仿照高级形式。关键限定是主干周围仍应保有广大的低级形式作为羽翼与源泉。","p":["抗日游击战争的战略问题"]},{"t":"把长期过程分解为阶段并配置相应行动形式","d":"对必然漫长而残酷的总体过程，不求其细节可预断，而先描绘轮廓：把过程分为相继阶段（如防御、相持、反攻），依各阶段力量对比确定主要行动形式。前期形式不是固定终点，后期形式也不取消前期；由低级向高级提高是在广泛低级形式中生长出主干，而非取代低级形式。","p":["论持久战"]},{"t":"军事战略随战争过程分阶段并适时转变，低级形式向高级转化不取消低级","d":"把军事战略按战争过程分为相继的战略时期（国内战争前后两期、抗日战争前后两期），并随过程作战略形式转变（游击↔正规）。转变的正确形态是低级形式（游击战）向高级形式（正规战）提高，同时在广泛低级形式中生长主干，不取消低级形式——抗日正规战以大大减少游击性、变低级为高级的方式出现，游击军仍是转变的依托。","p":["战争和战略问题"]}]},{"t":"以情况能否为决策层掌握划定决策权的界限","d":"决策权应当集中还是分散，不由事项的重要程度决定，而由做出正确决定所需的情况能否为上层掌握决定。凡带有一般性、其条件在上层视野之内的事项应集中，凡随时变化随地不同、远离现场者无从知道的事项应由现场决定。距离越远、情况越复杂，现场的决定权就应越大。两个方向的越界同样有害，因此边界须双向标明。","sub":[{"t":"以情况能否为上级掌握划定集中与分散的界限","d":"先从对象特性排除一端：下级单位低级而分散行动，高度集中的指挥既不应该也不可能；再排除另一端：多支力量同处一区而对方统一对付，故不能没有集中。划界依据不取重要性或级别，而取情况能否为上级掌握。配套规定两条：上级对下级具体行动的意见以建议性文书提出而非不可改变的命令；距离越远、情况越复杂，下级独立权限越应加大。最后以失职、专擅、包办、无自动性四种失当划出双向边界。","p":["抗日游击战争的战略问题"]},{"t":"不自我束缚于\"一切经过\"而按情形分类处置","d":"在合作对象当权且企图限制我发展时，拒绝\"一切经过\"的自我束缚口号。把事项按对方是否可能许可分四类：应先得同意者先奏后斩（如三个师扩编为三个军），可造成既成事实者先斩后奏（如发展二十余万军队），估计其不会同意者暂斩不奏（如召集边区议会），做了妨碍大局者暂不作。底线：不破裂统一战线，又决不自己捆住手脚。 # 待理论层归并的 L1 （暂无）","p":["统一战线中的独立自主问题"]}]},{"t":"以全部互矛盾因素的相互关系判断事物前途","d":"面对前途未定、众说纷纭的大判断，不从单一显著因素推出整体结论，而把互相矛盾的基本特点并列比较、看其相互作用的结果。强弱之外还有大小、进退、多寡之助等维度，整体前途由这些维度的比赛决定，而非由任一维度单独给定。","sub":[{"t":"以全部互矛盾因素的相互关系判断前途","d":"面对一个前途未定、众说纷纭的大判断，先不从一个因素（如强弱）直接推出结论，而把相互矛盾的基本特点全部列出并比较其相互关系。逐项写出对方长处与短处、己方短处与长处，再看这些特点的\"比赛\"产生什么结果。单因素导向片面结论，全部因素的相互关系才给出正确前途。","p":["论持久战"]},{"t":"识别干部依据全部历史与全部工作而非一时一事","d":"识别干部不以一时一事下结论，而看其全部历史与全部工作，这是识别的主要方法。使用干部坚持\"任人唯贤\"标准（坚决执行路线、守纪律、联系群众、有独立工作能力、积极不谋私利），反对\"任人唯亲\"。判断一个对象不据片段，而据其全部材料作全面判断。","p":["中国共产党在民族战争中的地位"]}]},{"t":"以时代根本差异消解旧历史类比","d":"用历史类比论证时，揭示比较双方所处历史时代的根本变化（社会性质、进步性、国际环境），使旧类比赖以成立的共同条件不复存在，从而消解其证明力；旧史例本身可承认，但它的证明力随时代条件变化而失效。","sub":[{"t":"以时代根本差异消解旧历史类比","d":"当对方用历史类比（如\"小国灭大国\"\"落后灭进步\"）支持错误结论时，不否认史例本身，而逐项指出比较双方所处时代的根本变化：今日的侵略国是否处于没落时代、被侵略国是否有新政党新军队新国际条件。时代条件变了，建立在同一条件上的旧类比即失去证明力。","p":["论持久战"]}]},{"t":"在根本性质上保持相对固定，在执行形式上随客观流动适时调整","d":"对指导方针，在根本性质上赋予一定时期的相对固定性，在执行形式上依客观情况的流动适时修改。流动限于执行该方针的各种行动范围，不触及方针根本性质；既反对无计划的相对主义，也反对否认流动性的机械主义。","sub":[{"t":"给方针以相对固定性并随客观流动适时修改","d":"战争只有程度低、时间暂的确实性，故计划不能无、也不能死。给一定时期内的方针以相对固定性（如某阶段\"基本的是游击战，但不放松有利条件下的运动战\"），同时承认方针随客观情况流动、须适时更换或修改。区分\"根本性质的固定\"与\"数的流动\"：方针根本性质在一定时间内不流动，其执行形式则随战争流动。","p":["论持久战"]}]},{"t":"在合作中保持统一性与各主体相对独立性的统一","d":"在合作中既坚持统一（团结对敌的总方针），又保持各参与主体的相对独立性；统一是主导、独立是相对的，抹杀任一方都破坏合作本身。处理合作内关系时，以\"统一+相对独立\"取代\"要么统一要么独立\"的二择一。","sub":[{"t":"在统一战线中既坚持团结又保持相对独立性","d":"坚持统一战线以团结对敌，同时坚持各党派在思想、政治、组织上的相对独立性（相对自由权）。两方面都不可偏废：只谈统一否认独立背弃共同原则；把独立当绝对则破坏团结总方针。阶级与民族斗争同理——阶级斗争利益服从抗日利益，但以互助互让政策调节，不否认阶级存在。","p":["中国共产党在民族战争中的地位"]},{"t":"在统一战线中既统一又独立使民族斗争与阶级斗争一致","d":"以\"用长期合作支持长期战争\"即阶级斗争服从抗日民族斗争为根本原则；在此原则下保存党派与阶级的一定限度权利与独立自主，不因合作牺牲必要权利。阶级的政治经济要求以不破裂合作为条件，一切阶级斗争要求以民族斗争需要为出发点，使统一性与独立性、民族斗争与阶级斗争在抗日原则下一致；把合作变成混一则必然牺牲统一战线。","p":["统一战线中的独立自主问题"]}]},{"t":"把普遍原则与具体实际相结合并通过适宜形式实现","d":"不把普遍原则当作现成教条，而把它与具体对象的实际特点结合，并通过适宜的民族/本土形式实现；原则的力量正在于它与具体实践相联系，脱离形式与特点的原则是空洞的。","sub":[{"t":"把普遍原理与本国具体特点结合并通过民族形式实现","d":"对待普遍理论不把它当教条和词句，而当作行动指南，着重学习其观察与解决问题的立场方法。把它与本国具体特点结合，通过为本国群众所喜闻乐见的民族形式实现；废止洋八股与空洞调头，使理论在每一表现中带着本国的特性。割断历史、离开具体特点谈理论，只会得到抽象空洞的东西。","p":["中国共产党在民族战争中的地位"]},{"t":"在普遍革命原则下按本国条件选择相反的斗争道路","d":"先确认普遍原则（武装夺取政权、战争解决问题）的普遍正确性，再依据本国具体条件选择执行该原则的具体道路，不照搬外国经验。当本国与外国在内部制度、外部处境上根本不同时，敢于走相反道路：资本主义各国走长期合法斗争、先城市后乡村，中国因半殖民地半封建、无议会无合法权利，改为以战争为主要斗争形式、以军队为主要组织形式、农村包围城市。","p":["战争和战略问题"]},{"t":"把战争和战略理论作为一切工作的骨干并使之通俗化","d":"把战争和战略的理论研究作为全党一切工作的骨干，唤起全党注重军事研究；对已有军事与政治工作经验加以总结、综合与系统化，并推进军事知识通俗化，使理论从少数人工作变为全党全国需要。理论不与具体经验结合、不通俗化，就不能成为指导工作的骨干。","p":["战争和战略问题"]}]},{"t":"在贯彻方针时同时防止两种相反方向的偏差而不偏废","d":"贯彻一项方针时，同时防止两种相反方向的偏差（如关门与发展、右与\"左\"、民主与极端民主化），以\"两端并举\"取代偏废一方；判断哪一种偏差当前更须警惕可随形势调整，但不因反一端而放任另一端。","sub":[{"t":"扩大组织时大胆发展又严防奸细混入","d":"为克服困难战胜敌人，党须向广大积极分子开门成为群众性大党，关门主义不容许；同时绝不可放松对奸细、托派、亲日派、投机分子乘机侵入的警戒。\"大胆发展而又不让一个坏分子侵入\"才是正确方针：不可因怕奸细而关门，也不可因大胆发展而疏忽警戒，只顾一方面都会犯错误。","p":["中国共产党在民族战争中的地位"]},{"t":"两条战线斗争同时反对两种相反倾向且切合对象","d":"反对错误倾向时同时防两种相反方向的偏差：当前头等是反右的悲观主义，同时反\"左\"的急性病；在统战、组织、民众问题上反关门主义，也反无条件合作与发展的投降主义。思想斗争必须切合具体对象，不主观地\"乱戴帽子\"；尤须反对阳奉阴违的两面派行为。","p":["中国共产党在民族战争中的地位"]},{"t":"扩大党内民主同时以纪律防止极端民主化","d":"要发挥全党积极性须扩大党内民主生活，使党员敢于提问题、发表意见、监督领导；但民主应为巩固纪律与增强战斗力，军队民主应少于地方。同时重申纪律（个人服从组织、少数服从多数、下级服从上级、全党服从中央），防止走到极端民主化与自由放任主义。一方面扩大民主，一方面以纪律约束。","p":["中国共产党在民族战争中的地位"]},{"t":"在战略转变中同时反对两种相反偏差","d":"在每次战略形式转变中，同时防止两种相反方向的偏差：第一转变中，一方面反对沉溺于游击性、不愿向正规性转变的右的地方主义与游击主义，另一方面反对过分重视正规化、机械搬外国经验的\"左\"倾集中主义与冒险主义。估计敌情与自身任务变化确定转变方向，不偏废任一端。 # Method Dedup Index（13–18 批次） 本文件是 Theory Layer 的候选导航索引，按 `Primary L2 → L1 → Evidence 出处 + 可选 Related L2` 组织，不代表正…","p":["战争和战略问题"]}]},{"t":"立场归属由可观察的实行确定，而非由自称的主张确定","d":"同一主张可以被立场不同的人同时讲出，因此自称不能作为分界。应选定一条与基本群众发生实际关系的行为作为唯一标准，看其是否愿意并且实际去做；标准单一而可观察，归属才不能被口头拥护所替代。","sub":[{"t":"以是否与基本群众结合作为判定立场的唯一分界","d":"判定某一群体中各人的立场归属时，不以其口头宣称的学说或主义为界，而只取一条可观察的行为分界：是否愿意并且实行和基本群众相结合。标准唯一，不叠加第二条；判定按当下的实行状态给出，行为改变则归属随之改变。对自称与实际背离者，直接看其所标榜的每项主张在实做中变成了什么。","p":["五四运动","青年运动的方向"]}]},{"t":"单个事件的性质由它所属过程的整体确定","d":"孤立地看一次事件，只能看到它的表现形式。应把它放回所属过程的完整阶段序列中，既比较各阶段的差别，又就全体判定共同性质，并标明这一过程的起点、当前位置与完成标志；事件的性质和它的进退，只有在这一整体中才能确定。","sub":[{"t":"把单次事件放回完整阶段序列以确定其性质与位置","d":"评价一次已经发生的运动时，不由它的表现形式直接断定性质，而把它放回所属过程的完整阶段序列：依次列出各阶段直到当前阶段，指出各阶段各有特点并找出最重要的一条区别，再就全体判定共同性质；同时给出该过程完成的标志和它在社会制度上的前后位置，由此确定这次事件处在哪一步、比前一阶段进步在何处、离终点还有多远。","p":["五四运动"]}]},{"t":"联合力量须在总体中辨明基础部分与领导部分","d":"需要多方参加的全局任务，不能把参加者当作同质的整体。应在总体中辨明哪一部分构成基础、哪一部分承担领导，二者缺一任务即不能完成；任务的进展程度，由这一结构本身的巩固和扩大来衡量。","sub":[{"t":"在依靠力量的总体中区分根本力量与领导力量","d":"确定一项全局任务依靠谁时，不停在列出参加者的总名单上，而在名单内部再作两重区分：哪一部分是构成基础的根本力量，哪一部分承担领导。用反证确认这一结构不可缺——离开根本力量、离开领导阶级，任务不可能完成。再据此指明当前的根本敌人和根本政策，并把胜利条件表述为这一联合结构本身的巩固与发展程度。","p":["五四运动"]}]},{"t":"行为的性质由其所指向对象的性质决定","d":"同一形式的行为可以有相反的性质，因此不能凭形式判定。应先确定该行为所指向的对象在当前关系中站在哪一边，再由对象的性质推定行为的性质；并可用同一性质的公认先例作反向检验，看判定是否前后一致。","sub":[{"t":"由被反抗对象的性质判定反抗行为的性质","d":"判定一次反抗现有当局的行动是否正当，不看\"反对政府\"这一形式本身，而先确定被反抗者在当前关系中处于什么位置——勾结外来压迫者还是抵抗外来压迫者，推动变革还是压迫变革。对象性质确定后，行动的性质随之确定。再以反问检验：若判该行动为错，则同一性质的公认先例也须一并否定。","p":["青年运动的方向"]}]},{"t":"阶段任务须成套规定并以前后两侧的差别划界","d":"远期目标不能直接给出当前该做什么。应成套地规定对象、承担者、根本力量、性质与目的，用\"不超过什么范围\"限定性质，再以同当前状态和同更远阶段的具体差别划出两侧边界；承认远期方向的同时，不把它的任务提到当前来执行。","sub":[{"t":"用成套问题规定当前阶段的任务并划出双向边界","d":"依次回答一组成套问题：反对的对象是什么、当前对象是什么、由谁去做、动力包括哪些、根本力量是谁、这一阶段的性质是什么、要达到的目的是什么。性质用否定式限定——不超过什么范围、不触动什么。目的用双向差别界定：既不同于当前状态，也不同于更远阶段，差别落在一条可指认的具体点上。承认远期方向，但当前阶段不执行远期任务。","p":["青年运动的方向"]}]},{"t":"长期反复的失败应收敛为一条起决定作用的原因","d":"反复出现的失败不能用每次各自的具体缘由来解释。应先对全过程作统一判定，再把原因归到力量对比的两端，并在己方一端内部区分并列的表现与起决定作用的主因，使一段长历史收敛为一条可执行的根本道理，而不是一份并列的缺点清单。","sub":[{"t":"把长期反复的失败收敛为一条根本原因","d":"先列出各次事件并对每次作胜负双重判定，再对全过程作统一判定：只有暂时的、局部的成功，没有持久的、全局的成功。然后把原因归到力量对比的两端——对方过强、己方过弱；再在己方一端内部区分并列的表现与起决定作用的主因，并指出对立面一贯阻挠。最后收敛为一条可执行的根本道理，并引同期权威当事人的总结加以印证。","p":["青年运动的方向"]}]},{"t":"部分力量应按其在总体中的位置确定自身任务","d":"一支力量即使规模可观、走在前头，也不等于能独立完成任务。应先判明它在总体中属于哪一部分、谁是决定胜负的主力，再据此确定自身任务：不是单独壮大，而是促成主力的组织并与之合为一体；拒绝这种结合，就等于站到总体目标的反面。","sub":[{"t":"按本部分在总力量中的位置确定自身任务","d":"先如实承认本部分已起的作用和规模，再判明它在总力量中是走在前头的方面军还是决定胜负的主力军。若不是主力军，即明确单靠自身不能取胜，并指出谁是主力。据此把自身任务定为到主力中去、把主力动员组织起来并与之结合成一体，而不是单独扩大本部分；凡拒绝结合、反对主力的倾向，判为本运动内部的逆流。","p":["青年运动的方向"]}]},{"t":"局部经验能否立为普遍方向，须经同类对照并归于方向与方法两项","d":"一个局部做法不能凭自身成绩自证其普遍性。应把它在可观察事项上的实际做法与历史的和当下的同类对象逐项比较，看差别落在何处，再把差别归结为方向是否正确和方法是否正确两项；两项同时成立，局部经验才具有普遍意义。","sub":[{"t":"以对照比较把局部经验确定为普遍方向","d":"不凭局部自报的成绩，先把它在可观察事项上的实际做法逐项列出：内部是否团结统一、是否与基本群众结合、学的是什么、做的是什么。再与历史上的旧典型和当下同类的其他单位对照，比较集中在对方缺什么上。最后把差别归结为政治方向是否正确、工作方法是否正确两项；两项同时成立，才宣布该局部的方向就是普遍的方向。","p":["青年运动的方向"]}]},{"t":"改换名目的争论须以论点比对判定是否同一问题","d":"一个未被最后解决的根本问题，会换一套措辞重新出现。判定它是不是新问题，不看名目，而看争论双方的对立结论是否与前次相同；论点相同即为同一问题，性质与位置不变。同时须查明它当初为何只被暂时解决，那些条件仍在，就是它再现的原因。","sub":[{"t":"以论点比对判定换了名目的争论是否同一问题","d":"一个曾被暂时压下的根本问题以新措辞重新出现时，不当作新问题处理，而把两次争论的对立结论摆在一起比较；论点相同即判定为同一问题的再现，性质与位置不变。再追问它当初为何只被暂时解决，把未解决的条件逐条列出——外部的诱惑、外部的妥协企图、内部的动摇——并指明这些条件仍在，正是它再现的原因。","p":["反对投降活动"]}]},{"t":"处于少数的主张必以伪装形式出现，须按言论内容识别其持有者","d":"一种主张若其持有者在人数上只是少数，就不能公开推行，必然转为伪装与欺骗，并批量制造材料以造成舆论。因此本阵线内部也会有它的实际持有者。识别不能凭位置或自称，只能看其所散布的内容是否与公开者一致。","sub":[{"t":"由双方人数构成推断少数一方的手段与其暗藏形态","d":"分析一种主张的推行者时，先算清对立双方的人数与构成。若持有者只是本阵线中一小部分动摇分子，而对立面是全体中的大多数，即判定它不能公开达到目的，必然改用欺骗宣传，并成批制造假消息、假报告、假文件、假决议以造成舆论。据此把推行者分为公开亮明的与仍留在本阵线内部里应外合的两类；后者不由位置或自称识别，而由其宣传内容是否与公开者一致来识别。","p":["反对投降活动"]}]},{"t":"主要危险须连同其必经的先行步骤一并指认","d":"危险不能并列罗列。应在诸项中指认起决定作用的一项，再沿必要条件链找出实现它所必须先完成的一步；这一步骤既是它的前置条件，也是识别它的现成标志。任务由这两者共同确定，从而在危险尚未成形时就能着手反对。","sub":[{"t":"以主要危险及其首要步骤确定当前紧急任务","d":"判断形势时不平列各种危险，而在并列诸项中按各项近期的变化幅度指认起决定作用的一项，作为主要危险。再沿必要条件链找出对方为实现该危险所必须先完成的一步，定为首要步骤；这一步骤于是成为识别主要危险的现成标志：凡进行该步骤者，即在准备该危险。当前紧急任务据此确定为同时反对二者。","p":["反对投降活动"]}]},{"t":"他方善意表示的性质由其根本方针是否改变来判定","d":"让步、示好和调停提议本身不说明性质。应先确定提出者的根本方针有没有改变、它在这一冲突中的一贯打算是什么；方针未变，则表示只是达成原方针的另一种手段。对具体安排，可用已有的同类先例给它定名，使判断从评估好处转为确认归类。","sub":[{"t":"按根本方针判定他方示好与第三方调停的性质","d":"对方的让步示好、第三方的调停安排，不按表示本身判断，而先追问其根本方针是否改变。方针未变，即判定示好为使己方上钩的手段，并指出上钩之后的结果。对第三方，查明它在冲突中的一贯打算——纵容一方、坐观两斗、待机取利，据此判定其提议的实际归属。对具体安排，用已有的同类先例给它定名，把讨论从\"是否有益\"转为\"属于哪一类\"。","p":["反对投降活动"]}]},{"t":"加害行为的归属由执行链条与发生位置的错位判定","d":"一起加害事件的性质不能只看动手者。应循执行链条追到指使者，再比较按常理谁应当做这件事、事情实际发生在何处、加于何人；三者出现错位，就说明动手者已在替应然施害者行事，该行为也就不是孤立的，而是某项更大打算的先行一步。","sub":[{"t":"由执行链条与发生位置的错位追出加害行为的真实归属","d":"先逐层追问执行链条：谁动的手、为什么动手、受谁指使、指使者是谁。再作两项错位比较：按常理应当做这件事的是谁，事情实际发生在什么地方、加于什么人。若动手者不是应然施害者，发生地又在本方后方而非对方控制区，被害者恰是本方最坚决的抗争者，即判定动手者已在替应然施害者行事，并把该行为定位为其更大打算的第一步。","p":["必须制裁反动派"]}]},{"t":"整体的状态由本应出现的反应是否出现来判断","d":"只看发生了什么，不足以判断整体处在什么状态。还应查明针对它本应出现的反应有没有出现、由谁负责、过了多久仍未出现，并用同类情形下的正常处理作对照，排除事情本身不可处理这一解释；应有的反应长期缺席，本身就是整体状态的。","sub":[{"t":"由本应发生而未发生的反应诊断整体状态","d":"不只看已经发生的事，还看针对这件事本应发生的反应有没有出现：指明按职责应当出面的是谁，给出事发至今的确切时长，确认其始终没有出面。再用己方同类情形作对照——同样的事在本方范围内会被立即处理——以排除\"这类事本身无法处理\"的解释；排除之后，剩下的解释落在整体状态本身，据此为当前状态定名。","p":["必须制裁反动派"]}]},{"t":"被对方占用的正当名义应予接受并按根本任务重新界定","d":"一个正当名义被对方用来压制自己时，否弃它等于把它让给对方。应先承认名义成立，再追问它的实际内容与所指，用当前的根本任务重新写定，并落到可用事实检验的机制上；检验一旦出现颠倒，名义就反过来指向占用者。同一做法适用于对方所用的关键词：不弃词，只重派其对象。","sub":[{"t":"接过对方占用的正当名义并按根本任务重派其内容与所指","d":"不否弃对方所用的正当名义，先明确承认它成立，随即追问它到底指什么，用当前的根本任务给它写出内容，并把内容落到一项可检验的机制上。再以现实事实逐项检验：应受赏者是否受赏、应受罚者是否受罚，出现颠倒即判定该名义并未实现，责任归于对方。对方文件中的关键用语同样处理：不弃词，只按同一根本任务重派其所指。","p":["必须制裁反动派"]}]},{"t":"事件的意义由它对各方力量关系的实际改变确定","d":"一个事件的意义不在它自身的形式和说法里。应先指明它由什么条件生成，再按由大到小的层次列出它改变了哪些力量的处境和相互关系，逐层落到具体的得失上；这些改变的总和，就是它的全部意义，此外不必另加评价。","sub":[{"t":"按对各方力量关系的实际改变评定事件的意义","d":"不评论条文、措辞或道义，先指明该事件是什么条件生长的结果，再由外及内逐层列出它对各方力量关系造成的实际改变：对全局格局打破了什么、巩固了什么、保障了什么；对某一具体战区打击了谁、援助了谁；对该战区内部各派增强了谁、打击了谁。最后把逐层改变合起来，归结为它为更大范围的目标提供了什么基础。","p":["关于国际新形势对新华日报记者的谈话"]}]},{"t":"单次结果须放回当事方一贯政策的执行序列中解释","d":"把一次结果归因于紧邻的另一事件，往往会颠倒因果。应先查明当事方近年一贯执行的政策及其真实目的，列出它此前已造成的同类结果，再摆出本次过程中双方各自坚持与拒绝的具体条款；本次结果由这一序列解释，而被误认作原因的事件应按实际时点放回其后。","sub":[{"t":"把单次结果放回当事方一贯政策的执行序列中解释","d":"先直接给出责任判定，再追溯当事方近年一贯执行的政策及其真实目的，列出该政策此前已造成的既成事实清单，说明本次不过是同一政策的又一次实施。随后摆出本次过程的具体事实——起止时间、一方的忍耐、另一方始终坚持和拒绝的条款——指明实际原因，并把被误认作原因的事件放回其实际时点之后。最后给出该政策从开始、到顶点、到破产的完整走向及其必然结果。","p":["关于国际新形势对新华日报记者的谈话"]}]},{"t":"冲突的性质由各方的目的判定，不由各方的宣称判定","d":"冲突各方都会自称正当，宣称因此不能作为判据。应分别查明各方所图为何，并落到实际争夺的具体对象上；各方所图同属一类，整场冲突即按该类定性。还须给出正面标准以说明哪一类冲突才正当，态度则由标准直接推出，不随宣传变动。","sub":[{"t":"以各方的目的而非各方的宣称判定冲突的性质","d":"先声明各方\"自己正义、对方非正义\"的宣称都是欺骗，不予采信；转而分别查明各方的目的，并落到当前实际争夺的具体对象上。各方目的同属一类，整场冲突即按该类定性。随后给出正面标准，指明哪一类冲突才是正当的，并由标准直接推出态度：对不合标准者决不赞助，对合标准者挺身赞助并站在最前线。","p":["关于国际新形势对新华日报记者的谈话"]}]},{"t":"对手的下一步应由不变的根本目的与可变的手段分别推断","d":"对手处境变坏，不等于它的目的改变。应把根本目的与实现手段分开：由其内部分歧只在手段，判定目的不变并标明这一判定的边界条件；再按当前条件推断手段将向哪些方向转移，包括借第三方施压和以让步为钓饵。困难只改变手段，不改变目的。","sub":[{"t":"由不变的根本目的与可变的手段分别推断对手的下一步","d":"先把对手的根本目的与实现手段分开。查明其内部各派的分歧只在手段而不在目的，据此判定根本目的不会变更，并注明边界条件——在其内部发生何种根本变化之前，更换首脑也不改变。再按当前条件推断手段的转移方向：哪一种可能性下降、哪几种将加强、是否借第三方施压，并预判它在适合的时机会以较大让步为钓饵诱使对方接受城下之盟。","p":["关于国际新形势对新华日报记者的谈话"]}]},{"t":"阶段一经转换，总任务须按新阶段的前瞻定名重新确定","d":"阶段的更替不只是形势描述的更替。新阶段应按它所准备的下一步来定名，总任务由这一定名直接推出，而不是沿用上一阶段的任务；同时须计入阶段转换带来的连带变化和仍然存在的力量差距，把总任务拆为维持当前局面与积蓄将来力量两面并行。","sub":[{"t":"按阶段转换重新定名总任务并拆为并行两面","d":"依据外部条件的变化与本方立场的确定，宣布前一阶段完结、新阶段到来。新阶段不按当前态势描述，而按它所准备的下一步作前瞻定义。随即指出阶段内部的连带变化：一条战线的缓和会使另一条战线紧张，对方在后者的压力还会加紧；同时如实对比双方力量，指明差距很远、任务仍严重。最后由前瞻定名直接推出总任务，并拆为维持当前战线与积蓄将来力量两面。","p":["关于国际新形势对新华日报记者的谈话"]}]},{"t":"方向选择须化为互斥前途的对举，并把每项立场落到成对的反对清单上","d":"方向问题不宜以单项劝告提出。应把可能的走向归为互斥的两条并各自标明结果，使选择无从含糊；每项立场再写成坚持与反对的成对形式，并按来源和领域把反对对象列全。立场由此从态度变为可指认、可检查的具体事项。","sub":[{"t":"以互斥的两个前途对举确定立场并按来源列出反对清单","d":"把可能的走向归纳为互斥的两条，每条各由若干并列做法构成并各自标出结果。据此要求采取坚定立场，把每项立场写成\"坚持某项、反对相反运动\"的成对形式。再为每项配一份清单：反对对象按来源列全——公开的与暗藏的、本国的与外国的都不遗漏；涉及面广的一项按领域列全，凡不利于中心任务的思想、制度和办法都要重新考虑和切实改进。","p":["关于国际新形势对新华日报记者的谈话"]}]},{"t":"总判断须以否定式限定圈出其适用范围","d":"一个总判断一经提出就会被推向极端。应声明它成立的条件，声明它不排除相反的个别情形，并区分\"基本上如此\"与\"一切相反可能都没有\"；对用来统摄新局面的概念，还须分清准备与实行、全局与局部。判断的效力由这些限定界定，而不由它的措辞界定。","sub":[{"t":"以一串否定式限定圈出总判断的适用范围","d":"提出总判断后不让它自行扩张，立即用一串否定式圈出边界：先说明成立条件；再声明不排除相反的个别情形并举出例子；再区分\"基本上已经如此\"与\"一切相反可能都没有\"；然后用一个概念统摄新局面的全部内容，并对这个概念本身再加两重澄清——准备不等于立即实行，所讲的是全局层面而非局部层面。限定完成后，才把任务按区域或部门分派。","p":["和中央社、扫荡报、新民报三记者的谈话"]}]},{"t":"应对的着力点由对方当前的主要手段决定","d":"己方该在哪一方面用力，取决于对方目前主要在哪一方面施压，而不取决于自身的偏好或习惯。着力点还须落到一项具体制度上，并说明它同时支撑其他方面；把它接到己方既有的原则之下，新要求就成为旧原则在新条件下的具体内容。","sub":[{"t":"由对方当前的主要手段确定己方应加强的抵抗并落到一项制度","d":"确定己方当前该着重做什么，不从自身偏好出发，先查明对方目前主要使用哪一类手段进攻；对方主要用哪一类手段，己方就特别加强同一类的抵抗。再把这一类抵抗落到一项具体制度上，并说明该制度同时是其他方面力量的前提，而不只是本类事务。最后把这项制度确认为己方一条既有原则在新环境下的主要内容。","p":["和中央社、扫荡报、新民报三记者的谈话"]}]},{"t":"推迟实行的理由须用权威自身的变动与已有事实加以检验","d":"以权威的早期主张为据主张推迟，须先看这位权威本人后来有没有依情势改变说法；以条件不具备为由主张推迟，须先看别处是否已经做成。权威的效力以其自身的最新变动为准，条件之说以既有事实为准，两项检验之后，推迟才谈得上有无根据。","sub":[{"t":"以权威本人的后期变动和已有事实破除\"时候未到\"的借口","d":"对方援引一位公认权威的早期主张作为推迟的依据时，不正面否定这位权威，而举出他本人在后期文件中的实际改变，说明其主张早已依据情势有了变动，据此解除早期分期的束缚。再由当前局面的紧迫程度推出必须立即施行。对\"条件不具备\"一类的反对理由，用已经发生的事实反驳：指出在何地已经实行、哪些职位已由何种方式产生、产生了什么样的人。最后把问题交付公开讨论，而不由己方单方面裁定。","p":["和中央社、扫荡报、新民报三记者的谈话"]}]},{"t":"己方主张须以真敌人的主张为反向坐标校验","d":"主张是否恰当，不能只看它自身听起来是否有理。应先认定谁是共同的真敌人，看它正在主张什么，再逐条取其反面；凡与敌人主张相混同者即须警惕。这一反向坐标同时是一条随时可用的检查尺度：看某项言行使谁痛、使谁快。","sub":[{"t":"以真敌人的主张为反向坐标确定己方口号","d":"确定己方口号时，先认定谁是各方共同的真敌人，再查明它当前正在打出哪几条口号，然后逐条提出与之相反的主张，使己方口号与敌人口号在每一条上都对立而决不相混同。由此归纳出通则：凡是敌人反对的就要拥护，凡是敌人拥护的就要反对。并把这一通则确认为一条明确的政治原则，用以随时检查己方的言行是否使亲者痛、仇者快。","p":["和中央社、扫荡报、新民报三记者的谈话"]}]},{"t":"对内部侵害的反击须以自卫为不可逾越的界限","d":"同一阵线内部的互相消耗应从根本上反对，但一味退让并不能制止它。应给出成对的反应规则：不受侵犯则不动，受侵犯则必回击；同时把回击限定在自卫范围内，并把这一界限作为纪律下达到每个成员。界限不是对回击的削弱，而是使回击不至于变成新的内耗。","sub":[{"t":"以自卫为不可逾越的界限规定对内部侵害的反应","d":"对同一阵线内部互相对消力量的行为，先表明根本反对的立场，不把它当作正常关系的一部分。再对\"对方一定要来\"的情形给出成对的反应规则：对方不侵犯就不侵犯对方，对方侵犯就必须回击，回击须用严正的态度而非退让。同时为回击加上不可逾越的界限——须站在严格的自卫立场上，并把这一界限下达为对每一个成员的纪律，任何人不许超过。举出具体实例与已掌握的，使规则的适用对象可指认。","p":["和中央社、扫荡报、新民报三记者的谈话"]}]},{"t":"好的可能须由具体保证固定，不能只靠各方意愿","d":"两种相反的前景同时存在时，仅靠各方的意愿和相互期许不能排除坏的一种。应先如实承认两种可能并指明它取决于谁的态度，再为好的一种找到具体、可执行的保证事项；有了保证，可能才被固定为方向，否则愿望随时可以反转。","sub":[{"t":"承认两种可能并为好的一种寻找具体政治保证","d":"被问及坏结果是否可能时，不作简单否认，先承认两种可能都存在，并指明它取决于哪些方面的态度、其中尤其取决于谁。再表明己方的既定方针和努力方向，并援引对方已经作过的相关表态。随后指出仅有双方意愿不足以排除坏的可能，必须为好的可能找到政治保证，并把保证写成若干条具体、可执行的事项，而不是相互期许。最后以成对的口号收束，指明除此没有第二条路。 # Method Dedup Index（19–24 批次） **批次：** 19-24（每 6 篇一个独立 method index 文件）…","p":["和中央社、扫荡报、新民报三记者的谈话"]}]},{"t":"对兼具两面性的对象保持双面并防止倒向任一端","d":"对象兼有可合作面与相损面时，方针须同时包含联合与斗争两面；相应地，错误也按方向相反的两端出现，须同时防止，不以反对一端为理由倒向另一端。两面互相约束，斗争形式随关系状态而改变，但两面始终并存。","sub":[{"t":"依对象的二重性确定联合又斗争的双重方针","d":"对既可能同自己合作又可能损害自己的对象，先确认其二重性的经济与政治根据；据此确定方针必须同时包含联合与斗争两面，并规定各自边界：不联合则自己不能前进；联合期间须进行非对抗形式的思想政治组织斗争以保持独立性；被迫分裂时斗争转为对抗形式。三种情形各写明违反后的后果。","p":["共产党人","〈共产党人〉发刊词"]},{"t":"在同一问题上同时防止两端的错误","d":"处理同一个问题时，把可能出现的错误按方向分为相反的两端，分别指出各自的误认：一端把本对象同别处的同类对象看做一样因而否认可以联合，另一端把自己同对象看做一样、忽视原则差别因而丧失独立性。对两端同时进行坚决的、严肃的斗争，不因反对一端而倒向另一端；两端的具体表现由本组织历史上的实际失败来指认。","p":["共产党人","〈共产党人〉发刊词"]},{"t":"放宽入口的同时以证据为限收紧甄别","d":"实行放宽吸收的政策时必须同时建立配套的甄别：明确拒绝对方派遣进来的分子和不忠实分子，态度严肃；已混入者依靠真凭实据、坚决而有分别地清除。随即加一条反向限制：不得因存在混入者就怀疑一般的忠实成员，并严防有人借甄别之名陷害好人。两条要求同时执行，放宽不致失去纯洁，纯洁也不致取消放宽。","p":["大量吸收知识分子"]},{"t":"对兼具两重性的阶级确定联合又斗争的双重方针","d":"对兼具革命一面与妥协一面的阶级，先确认其两重性的经济与政治根据；据此确定方针同时包含联合与斗争两面——因其可合作面而联合，因其相损面而斗争，并以边界条件约束两面，防止只联合或只斗争的偏向。","p":["中国革命和中国共产党"]}]},{"t":"以对方的持续事实为据判定其立场与走向","d":"判定一方的实际立场，或预判它将如何行动，依据是它在同类情境中的连续行为，以及它长期奉行、近期未见变更的基本原则；自我声明、外界传闻和利害相关者的宣传不构成依据。运用时须把该原则具体化为对本事项的可检验条件。","sub":[{"t":"以连续行为记录判定一方政策的实际方向","d":"判断某一方究竟在促成还是在阻止某一后果，不看当前一次孤立行为，也不看它或对手的宣传说辞，而把它在同类问题上较长时期内的连续行为逐项列出，据此确定其一贯政策方向；再看该后果发生之前是谁拒绝了本可阻止它的方案，把责任落到实际拒绝者身上，而不是落到宣传所指的一方。","p":["苏联利益和人类利益的一致"]},{"t":"以已确立的基本原则预判尚未发生的行为","d":"对尚未发生、只在传闻中的行为是否会损害自己，不凭传闻和成见推测。先确认对方长期奉行的基本原则，再把它具体化为对本事项的可检验条件——该行为是否与本方根本利益相冲突；查证对方近期正式表述是否显示原则有变，据此判断该行为若发生会取何种形式，并以同类先例的实际效果作旁证。","p":["苏联利益和人类利益的一致"]},{"t":"以实际行为而非自称区分真伪朋友","d":"面对\"谁是朋友、谁是真正的援助者\"这类判断，不以对方的自我宣称、口头同情或亲疏言论为依据，而以其实际行为（是否真正废除特权、是否在关键时刻实际援助）为据，把自称朋友却无实际行动者判定为假朋友，把有实际行动者判定为真朋友。","p":["斯大林是中国人民的朋友"]}]},{"t":"按事情本身的性质而非当事方身份确定态度","d":"面对相争的双方，先判定所争之事属于哪一类性质，再据此确定支持、反对或不介入；当事方的身份、亲疏与既有关系不能代替对性质的判定，态度的改变须以性质本身发生变化为依据。","sub":[{"t":"按事情性质而非当事方身份决定支持与反对","d":"对一场冲突表态前，先判定所争之事本身的性质——是掠夺他人还是谋求解放，再据此确定态度：性质相同的双方一律反对并严守中立，性质正义的一方给予援助。不因某方与自己有对立或友好关系而改变判定，也不因某方在别处曾受压迫就改变对本次冲突性质的判断；态度的改变只能以性质本身发生必要变化为依据。","p":["苏联利益和人类利益的一致"]}]},{"t":"把牵涉多方的事件按当事方分解后分别判定","d":"对多方参与的事件不作笼统的整体评价，先按当事方分解，对每一方分别确定其目的、地位与行为性质；尤其把统治集团与其治下人民视为不同当事方，避免用其中一方的性质代替全体。","sub":[{"t":"把牵涉多方的事件按当事方分解后分别判定","d":"面对一个牵涉多方、议论糊涂的事件，先分解为发动方、对抗方、当地统治者、当地人民、介入方，对每一方分别考察目的、地位和实际所作所为，逐一判定行为性质与应有态度。特别把一国政府同它治下的人民分作两个当事方：政府可以是应当反对的，人民则是牺牲者。各方结论并列后，事件总体性质自然清楚。","p":["苏联利益和人类利益的一致"]}]},{"t":"不以一种关系的存在推断另一种性质不同的关系","d":"同一对象之间可以并存性质不同的多种关系；断定某种关系存在须有该关系自身的，不能由另一种关系的存在推出；关系在数量或程度上的差别不改变它的性质归属。","sub":[{"t":"区分同一对象上并存的不同性质关系","d":"当同一对象之间可能同时存在多种关系时，不因其中一种关系存在就推断另一种也存在。用同类反例检验：在已有定论的事件中，与甲保持某种关系而实际支持的是与甲敌对的乙，可见该关系并不构成支持。该关系在量上的多少厚薄由对方自己的态度决定，只改变程度而不改变性质归属。","p":["苏联利益和人类利益的一致"]}]},{"t":"以自身力量为主并按利益一致程度分级外部支持","d":"处理对外依靠问题时，把自身力量定为主要依靠，外部支持只作补充；再按其利益与自己是否长期一致把外部支持分为可靠与暂时两类，暂时的可以争取但不作为依赖的基础。","sub":[{"t":"以自身力量为主并按可靠程度分级外部支持","d":"确定对外依靠方针时先定主次：以自身力量为主，同时不放弃一切可能争取的外部援助。再按利益是否与自己长期一致把外援分级——长期一致者为可靠援助者，其余即使可能得到也只看作部分的和暂时的，应该争取但决不可过于依赖。对彼此性质相同、正在相争的各方一律不参加。","p":["苏联利益和人类利益的一致"]}]},{"t":"由对象自身状况确定行动的规定性与基本特点","d":"面对一个需要改造的社会对象，先确定其结构性状况——形态、各成分地位、发展是否平衡；由此推定行动的性质、对象、可依靠的力量与主要形式，而不是从别处的现成结论移用。再从中筛出为本对象所独有的少数基本特点，作为后续全部推演的前提。","sub":[{"t":"认清根本社会性质是推演一切派生问题的基本根据","d":"面对一个复杂社会领域要回答一系列派生问题（对象、任务、动力、性质、前途等）时，先着力判定该领域的根本社会性质，把它作为全部推演的根据；再以这一性质为准绳逐项回答派生问题，不以局部印象、临时口号或个别事件代替对根本性质的判定。","p":["中国革命和中国共产党"]},{"t":"从社会状况推定革命的性质、动力与主要斗争形式","d":"确定一场改造运动\"怎么做\"之前，先确定它所处社会的结构性状况——属于何种社会形态、哪一种经济成分占优势、各方面发展是否平衡、地域条件如何；由这些状况依次推定改造的性质、主要对象、基本动力、可在一定时期一定程度上参加的力量，以及主要的斗争形式。不从别国同类运动的现成结论出发。","p":["共产党人","〈共产党人〉发刊词"]},{"t":"以独有性和不可包含性筛选出基本特点","d":"从大量事实中确定哪些够得上\"基本特点\"，用两条标准筛选：看该项在同类对象中是否普遍存在——各处原则上都一样的关系不算特点，只有本对象独有或显著不同于同类者才算；再看候选项之间是否存在实质包含关系——若某项已被另一项实质包含，则不单列。据此把特点压缩到最少的几条。","p":["共产党人","〈共产党人〉发刊词","中国革命和中国共产党"]}]},{"t":"把基本特点转化为少数根本问题并确定其相互关系","d":"认识一个复杂全局，可把已确定的基本特点各转化为一个必须正确处理的根本问题，连同行动主体自身的建设，构成数量很少的一组；再确定它们之间的工具与使用者关系而非平列关系。掌握这组问题及其相互关系，即掌握全局。","sub":[{"t":"由基本特点推出少数根本问题并确定其相互关系","d":"把每个基本特点转化为一个必须正确处理的根本问题，再加上行动主体自身的建设问题，构成数量很少的一组根本问题；然后确定它们不是平列关系，而是\"工具与使用者\"的结构：由特点直接产生的问题是武器，主体自身的建设是掌握武器的条件，武器之间也有从属。正确理解这组问题及其相互关系，就等于正确领导了全局。","p":["共产党人","〈共产党人〉发刊词"]}]},{"t":"从多个历史阶段的重复情形归纳带条件的关系规律","d":"确定对不同对象应取何种关系时，把已经过去的若干阶段并列比较，从各阶段重复出现的情形中归纳规律，并用正在进行的阶段加以检验；每条规律须标明其成立的时期、条件与程度，不作无条件的表述。","sub":[{"t":"按多个历史阶段的重复情形归纳带条件的关系规律","d":"把已经过去的若干个不同阶段并列，看同一情形是否在各阶段重复出现，从重复者中归纳出若干条规律：哪些对象在什么条件下可以联合、可靠程度如何、哪些始终是对象但在何种条件下可暂时联合、联合期间其行为会是什么。再用当前正在进行的阶段检验规律是否仍在被证明，每条规律都写明时期、条件与程度限制。","p":["共产党人","〈共产党人〉发刊词"]},{"t":"把不同历史时期的同类情形并列以分辨真正可依靠者","d":"要分辨在若干相关方中谁才是真正可依靠的援助者，把已经过去的若干个历史时期并列，看同一情形（是否实际援助我们）在各时期是否重复出现；重复出现者即为稳定可依靠者，反之则否，并以反复出现的同类情形作为结论的根据。","p":["斯大林是中国人民的朋友"]}]},{"t":"以主体自身状况与外部问题处理的互为条件关系考察成败","d":"一个行动主体的进退，同它对若干根本外部问题处理得正确与否直接相关；反过来，主体自身越巩固，处理这些问题就越正确。二者互为条件而非单向决定，也不是先后关系；考察成败须同时从两个方向用历史事实加以验证。","sub":[{"t":"以主体自身建设与外部问题处理的双向联系考察成败","d":"考察一个组织的成败进退，不孤立地看它自身，而把它同必须处理的几个根本外部问题挂钩：正确处理则前进一步，不正确处理则后退一步；再作反向考察：组织自身越巩固就越能正确处理这些问题。用较长时期的历史对两个方向逐一验证，从而把自身建设与外部路线确定为互为条件而非先后关系。","p":["共产党人","〈共产党人〉发刊词"]}]},{"t":"以主要形式为中心把其他必要形式配合起来","d":"确定主要行动形式后，须把它同其他各种必要形式在全局范围内直接或间接地配合起来，而不使其孤立进行；主要形式在各阶段应取的具体形态，由该阶段的条件以及它能否达成目的来确定。","sub":[{"t":"以主要斗争形式为中心把其他必要形式配合起来","d":"确定主要斗争形式后不让它孤立进行，而把它同其他各种必要形式——群众各阶层的、政权的、经济的、锄奸的、思想的——在全局范围内直接或间接地配合起来；再按不同阶段的条件确定该主要形式当前应取的具体形态，判断标准是在特定的落后与长时期条件下何种形态是己方战胜敌人、创造自己阵地所必须依靠的。","p":["共产党人","〈共产党人〉发刊词"]}]},{"t":"把不同时期的失误归到共同的认识根源并从根源上纠正","d":"一个主体在不同阶段所犯的、方向甚至相反的错误，可能出自同一认识根源——未领会已有经验、不了解本对象的状况与规律、对一般理论与本处实践缺乏统一理解。找到共同根源后，纠正的办法是集中经验并使之为全体所掌握，而不是逐条禁止具体错误。","sub":[{"t":"把不同时期的失误归到共同的认识根源","d":"考察一个组织在不同阶段所犯的、性质不同甚至方向相反的错误，不逐项孤立解释，而追问共同的认识根源：是否不虚心领会已有经验、是否不了解本对象的历史与社会状况、是否不掌握其特点与规律、是否对一般理论和本处实践缺乏统一理解。据此纠正办法不是逐条禁止具体错误，而是集中经验并传达全体。","p":["共产党人","〈共产党人〉发刊词"]}]},{"t":"按力量作用的方向分解全局并分别确定内容","d":"处理跨越不同区域的全局时，无论分析对方的方针还是组织己方的任务，都按力量作用的方向分解，对每个方向分别确定目的、主要手段与主次；各方向的性质可以不同，不能由一个方向推断另一个方向，也不能用一套办法覆盖全部方向。","sub":[{"t":"按对方力量作用的方向分列其方针与手段","d":"分析对方的总方针不作笼统概括，而按其力量作用的不同方向分开——已被其控制的区域与尚未被控制的己方区域，对每个方向分别确定目的、主要手段和手段间的主次。特别指出某一方向上其主要手段并非通常预期的那一种（如以政治手段为主、军事手段为辅），并把该手段的具体内容逐项列出，使己方对准其实际手段。","p":["目前形势和党的任务"]},{"t":"按己方所处方向分置性质不同的任务","d":"把总任务落实为行动时按己方力量所处的不同方向分置：在对方控制区以破坏其巩固控制的企图为主并实行有利于当地民众的改革，在双方接触的正面以支持防御、打退局部进攻为主，在己方后方以改革自身政治制度、扩大民意基础为主。三个方向方针性质各不相同而共同服务于同一总目标，同时把自身巩固作为并行任务。","p":["目前形势和党的任务"]}]},{"t":"以对方维持原有行动方式的条件是否存在判定阶段转换","d":"判定形势是否进入新阶段，依据是对方是否还具备维持其原有主要行动方式的条件，而不是某一次事件的发生。判断成立后须同时写明新阶段的实际内容、对方力量将转向何处，以及会使该阶段被逆转的条件，使阶段结论始终附带条件。","sub":[{"t":"由对方的实力条件推出阶段转换并同时给出限制","d":"判断形势是否进入新阶段，依据是对方是否还具备维持其原有主要行动方式的条件——受了多大打击、兵力与财力是否充足；据此判定原有行动方式可能性已不大，确认阶段转换并写明新阶段的实际内容。判断一经作出立即附加限制：不否认对方仍有较小规模行动，指出其力量将转向何处，并列出会使新阶段被逆转的条件。","p":["目前形势和党的任务"]}]},{"t":"把当前现象判定为对方更远目的的准备步骤","d":"判断对方当前行为的意义，须追问它在对方整个计划中的位置——是孤立事件还是通向更严重结果的准备；依据是实施者的利益指向和该行为继续发展所造成的条件。一经判定为准备步骤，就把最大危险定在那个更远的结果上，并围绕阻止该结果组织任务。","sub":[{"t":"把当前现象判定为对方更远目的的准备步骤","d":"判断对方当前一系列行为的意义，不停留在行为本身的直接后果，而追问它在对方整个计划中处于什么位置——是孤立的磨擦还是通向某个更严重结果的准备步骤；依据是实施者是谁、其利益指向何处、行为继续发展将造成什么条件。判定为准备步骤后，把最大危险确定在更远的结果上并据以组织任务。","p":["目前形势和党的任务"]}]},{"t":"以对象内部的区别代替对整类对象的笼统判断","d":"对某一类对象的排斥或接纳，不应基于对整类的笼统判断，而先按所处条件、所服务的对象等维度把该类分解为不同部分；同时把外部力量争夺的紧迫性和己方已具备的驾驭条件计入，据此确定对不同部分的不同方针。","sub":[{"t":"以对象内部的区别代替对整类对象的笼统判断","d":"纠正对某一类人的排斥态度，不直接批评态度本身，而先指出它出自若干具体的\"不懂得\"：不懂得这一类人在本处条件下与在别处条件下的区别，不懂得同一类人因所服务对象不同而分成的不同部分，不懂得外部力量正在争夺他们的紧迫性，不懂得己方已具备驾驭他们的条件。区别列明后，方针自然由笼统排斥转为有区别的大量吸收。","p":["大量吸收知识分子"]},{"t":"在同一大类中按内部区别分级确定方针","d":"对一个笼统的大类（如\"农民\"\"资产阶级\"）不作整体定性，而按其在社会经济中的具体区别分解为若干子类（富农/中农/贫农；带买办性的大资产阶级/民族资产阶级），对每个子类分别判定其立场、可靠程度与应取方针，使方针与内部区别相对应而非一概而论。","p":["中国革命和中国共产党"]}]},{"t":"以低门槛广泛吸收并按程度分层安置","d":"需要迅速扩大队伍时，把入门标准降到少数几条基本条件，凡合乎者先吸收进来，再在实际工作中加以教育与磨练；按合乎程度分层安置于核心与外围，不以最终要求充当入门条件，也不因一部分人不能进入核心就放弃对他们的组织。","sub":[{"t":"以低门槛广泛吸收再按程度分层安置","d":"把入门标准定在少数几条容易达到的基本条件上——认同基本方向、比较忠实、能吃苦耐劳，凡符合者都多方吸收，先进入组织和工作，再在实际工作与斗争中加以教育和磨练。按合乎程度分层安置：具备核心条件的吸收进核心组织；不具备或本人不愿进入的，建立良好的共同工作关系并带领一道工作。数量在前、提高在后。","p":["大量吸收知识分子"]}]},{"t":"以两方同时向对方特质转化消除成分间的隔阂","d":"组织内两类成分之间的隔阂，不靠一方压倒或迁就另一方来解决，而对两方同时提出转化要求：各自补上对方所长而自己所缺的部分，在长期的共同工作中相互靠拢。两个方向的转化同时进行，不分先后。","sub":[{"t":"以两方同时向对方特质转化消除成分间的隔阂","d":"组织内两类成分存在隔阂时，不只要求一方接受另一方，而对两方同时提要求：对排斥新成分的原有干部切实说服，使其懂得吸收的必要，同时鼓励他们加紧学习、补上自己所缺的能力；对新成分则分配适当工作、教育带领，在长期斗争中逐渐克服其弱点，使其向原有成分的特质靠拢并同老干部融洽起来。两个方向同时实现。","p":["大量吸收知识分子"]}]},{"t":"按区域条件调整同一原则的执行标准并保留外围联系","d":"同一原则在条件不同的区域执行时，原则本身基本适用，只按风险程度调整进入核心的具体标准；同时对不进入核心的同情者建立联系并组织到具体工作中去，使覆盖面不因核心标准提高而缩小。","sub":[{"t":"按区域条件调整同一原则的执行标准并保留外围联系","d":"同一原则在条件不同的区域执行时保持基本适用，只调整具体标准：在对方控制或统治的区域，进入核心组织的忠实程度要求更高，以保证组织更加严密。同时对不能或不必进入核心的同情者建立适当联系，把他们组织到各条具体的工作战线中去，使原则的覆盖面不因核心标准提高而缩小。","p":["大量吸收知识分子"]}]},{"t":"以对象在社会经济结构中的位置确定其对某一变革进程的立场","d":"判断一批行动者对某一变革进程的态度与立场，依据的是它们在该社会经济结构中所处的位置，而不是其名称或宣称；位置决定了它们与变革的利害关系，从而决定了立场的可靠程度与可联合的边界。","sub":[{"t":"按各阶级在经济结构中的地位判定其革命立场","d":"分析某一变革进程的参与者时，不依其名称、自我宣称或亲疏关系，而依它们在社会经济中所占的地位来确定其对革命的态度与立场；据此把参与者划分为革命对象、可靠动力、在一定时期一定程度上可联合的动力，并指明态度随其经济地位变化而变化的边界。","p":["中国革命和中国共产党"]}]},{"t":"由当前已存在的方向性内部因素判定事物前途","d":"判断事物前途，不依据当前阶段的外在形式，而依据其内部已经存在并且决定方向的积极因素；这些因素的存量与增长趋势，决定前途的主要可能走向。","sub":[{"t":"由当前已存在的方向性内部因素判定事物前途","d":"判定一个过程的前途时，不只看它当前阶段的形式，而考察其当前内部已经存在、并且决定未来方向的积极因素（如无产阶级领导权比重的增长、劳动人民的合作经济），据以确定前途的主要可能走向，同时不排除当前阶段形式所伴生的其他可能。","p":["中国革命和中国共产党"]}]},{"t":"区分两个性质不同的过程并确认其准备与趋势关系","d":"面对前后相继的两个过程，先确认它们性质不同、不能相互代替；再确认其准备—趋势关系（前者是后者的必要准备、后者是前者的必然趋势），使二者既不混淆也不割裂。","sub":[{"t":"区分两个性质不同的过程并确认其准备—趋势关系","d":"面对前后相继的两个过程（如民主主义革命与社会主义革命），先明确二者性质不同、不能混淆；再确认其相互关系：前一过程为后一过程的必要准备，后一过程为前一过程的必然趋势；据此既防止把两阶段混为一谈，也防止把二者割裂，并明确贯穿二者的领导责任。 # Method Dedup Index（25–30 批次） 本文件是 Theory Layer 的候选导航索引，按 `Primary L2 → L1 → Evidence 出处 + 可选 Related L2` 组织，不代表正式理论结论…","p":["中国革命和中国共产党"]}]},{"t":"用可观察表现判定难以直接观测的品质","d":"对无法直接观测的内在品质或实质作判断时，应把它落实为若干具体可观察、可逐项核对的指标，并同时给出反面征候作对照，再参考与之直接接触者的普遍反应；不以自我声明、名义身份或口号作为判据。","sub":[{"t":"以可检验的具体政策判定同名主张的真伪","d":"同一名称在不同时期、不同人口中内容可能完全不同，不能凭名称判断。先揭出各方同名主张的实质，或以权威原始文本划出新旧时代；再把该名词的实质落实为若干条可逐项核对的具体条件，宣布缺一即为伪；对每条分别论证其不可缺，指出缺此必然滑向反面、没有中间状态。","p":["新民主主义论","团结一切抗日力量，反对反共顽固派","向国民党的十点要求"]},{"t":"以正反两面的可观察表现判定内在品质","d":"判断一个人是否具备某种精神，不看自我表白，而看两类可观察的表现：对工作是否极端负责任，对同志对人民是否极端热忱。同时列出对应的反面征候作对照，再以直接共事者与受助者的普遍反应作旁证，据此作出是否够格的判定。","p":["纪念白求恩"]}]},{"t":"从个别典型提炼可推广的一般要求","d":"需要为群体确立行为标准时，可从已经发生的个别事实出发：抓住其中最难由通常动机解释的部分，把它概括为一般性质，再把这一性质确立为对全体的要求。标准由实有行为提炼而来，而非先行设定后再寻找例证。","sub":[{"t":"从典型行为追问动机并转为全员要求","d":"面对该向谁学习、学习什么的问题，不停留在事迹叙述和哀悼。先找出典型行为中最反常、最难用普通利害解释的一点，由此追问\"这是什么精神\"，把行为归结为一种可命名的精神性质；再把该性质拆成若干可观察的具体表现，最后明确宣布为对全体成员的学习要求，而非只作为对个人的褒扬。","p":["纪念白求恩"]}]},{"t":"依互为条件的关系突破本位界限确定联合范围","d":"多个分散主体面对同一对手时，各自孤立行动难以取胜。应先确认彼此的胜利互为条件，把支援对方认作实现自身目标的必要环节，据此把联合范围扩展到本位界限之外，而不是按亲疏或所属划定界限。","sub":[{"t":"按互为条件的支援关系确定联合范围","d":"处理本方斗争与他方斗争的关系时，不以本方直接利益为唯一出发点。先确认双方在同一对手之下互为条件：一方要拥护另一方的解放斗争，另一方也要拥护这一方，共同的胜利才可能实现。据此把对方的事业当作自己的事业，把联合范围扩展到一切同类力量，以此反对狭隘民族主义和狭隘爱国主义。","p":["纪念白求恩"]}]},{"t":"把评价标准建立在人人可具备的根本条件上","d":"为一类主体设定评价标准时，若把标准挂在天赋、条件或数量上不可控的因素上，多数主体将被排除在外。应改以所有主体都可能具备的根本条件为尺度，使标准既有区分力又普遍可达。","sub":[{"t":"以根本品质而非能力高低设定普遍可达的标准","d":"制定对人的评价标准时，把尺度从能力大小转移到一项人人可具备的根本品质。明确宣布能力有大小，但只要有这点精神就达到标准；并把标准表述为若干层次的具体规定，使不同能力的人都能据以自我衡量并变为有利于人民的人。","p":["纪念白求恩"]}]},{"t":"由基础层的实际性质推定派生层的任务与内容","d":"回答\"应当做什么、建立什么\"的问题时，不从愿望或名义出发，先判定作为基础的现实处于何种性质，再由这一性质推出行动的阶段、对象与派生领域的内容；基础的性质变了，派生层的任务与内容随之改变。","sub":[{"t":"由社会性质推定革命步骤与各领域内容","d":"先判定作为基础的现实处于何种性质，由这一性质推定行动必须分为几个性质不同的步骤，并推定要革除的对象就是现存的旧形态；再按同一关系向派生领域延伸，说明派生领域的新内容以新的基础为根据，因而与基础同属一个范畴。不懂这一历史特点就不能指导全局。","p":["新民主主义论"]},{"t":"使专门刊物从属总任务并规定其内容方向与育人职能","d":"为专门刊物等宣传教育工具确定任务时，不从自身意愿出发，先明确它从属于既定的政治总任务；再把总任务落实为具体工作——通俗解释道理、报道斗争实际、总结斗争经验；同时把刊物办成培养干部的学校，规定干部必备条件（有知识、有能力、不务空名、会干实事），并以没有干部就不能解放论证培养的必要。","p":["中国工人"]}]},{"t":"按事物所处时代条件重新判定其归属","d":"同一性质的事物在不同历史条件下的归属与意义可以完全不同。判定其归属时，除考察自身属性外，必须考察它所处的外部格局与阵线关系；条件已变而仍按旧条件下的结论来引证，就会得出错误定位。","sub":[{"t":"按时代条件变化重新判定同类事物的范畴归属","d":"判断一件事情属于哪个范畴时，不只看它自身的社会性质，还要看它所处的时代格局与阵线关系。依据是外部条件的实际变化，而不是参加者的主观意识；参加者是否意识到并不改变归属。反面标准是离开时间和空间、不顾活的历史环境去引证旧结论。","p":["新民主主义论"]}]},{"t":"依对象内部相反属性分别确定利用与防范","d":"对象常常同时具备可利用与须防范的相反属性，而两者往往出自同一根源。应分别指明其产生条件与显现时机，据以同时确定联合的限度与不可寄托的事项，而不是给出单一定性再据以全用或全弃。","sub":[{"t":"依对象的两面性同时确定联合与不寄托的边界","d":"对态度不确定的对象不作单一定性，先找出其两种相反属性各自的产生根源；再据此分别确定对待方式：不忽视其可用的一面并与之建立联合，同时认定它不能完成根本任务，因而不把关键责任寄托于它。必要时以其他同类对象作对照，说明本对象的特殊之处。","p":["新民主主义论"]}]},{"t":"在既有类型均不适用时确立有时限的中间形态","d":"当现实条件使已有的各种成型方案都不适用时，既不勉强套用，也不因无成例而搁置。可在穷举已有类型并说明其不适用之后，确立一个中间形态，同时明确它的历史时限与在此期内的不可替代性。","sub":[{"t":"在既有类型都不适用时确立有时限的过渡形态","d":"先按一个统一标准穷举已有类型，再逐一说明其为何不适用于当前对象；据此确立第三种形式，并对它作双重限定：它是一定历史时期的形式因而是过渡的，同时在这个时期内是不可移易的必要形式；最后指出它在当前的具体表现形态。","p":["新民主主义论"]}]},{"t":"把实质规定与实现形式分开并要求两者相适应","d":"一项安排同时包含\"实际上谁占据什么地位\"与\"用什么形式实现\"两层。二者应分开表述再相互检查；形式与实质不匹配时，实质无从表现，安排也不能发挥作用，此时应调整形式使之适应实质。","sub":[{"t":"区分实质地位与实现形式并要求两者相适应","d":"把制度安排拆成两个问题分别回答：实质上各方占据什么地位，用什么形式把这种地位组织起来。前者要揭穿以中性名词掩盖实际地位的做法，后者要给出具体组织办法与必备条件。再检查两者是否匹配，不匹配时判定为形式与实质不相适应，须改形式而非改实质。","p":["新民主主义论"]}]},{"t":"以逐条排除替代方案确证方向","d":"正面论证之外，把可能的其他方案穷举出来，逐一从外部条件与自身条件说明其不可行，并指出被引为先例者所依赖的特殊条件已不存在；必要时揭示其被主张的实际动机。排除完毕，所余方向即得到反面证明。","sub":[{"t":"以逐条排除替代方案确证唯一可行方向","d":"把现实中可能被主张的其他方案一一列出，对每一个分别从外部条件与自身条件两面说明其走不通；对被引为先例的个案，指出其成立所依赖的特殊条件已不存在且该个案最终也未维持；同时揭示主张者的现实利害动机，使其失去表面理由。全部排除之后，所留方向即被反面证成。","p":["新民主主义论"]}]},{"t":"按层级区分长远目标与当前任务并各限其适用范围","d":"长远目标与当前任务属于不同层级：当前任务有独立的内容与时限，不能被长远目标替代或提前吞并；长远目标的宣传和它作为方法的运用，也不能直接充当当前阶段的行动纲领。混为一谈会同时损害两者。","sub":[{"t":"以纲领层级把长远目标与当前任务分置","d":"明确宣布两者是有机构成的两个层级：当前任务有自己的内容与相当长的时限，两个阶段必须衔接，不容横插另一性质的阶段，也不容把后一阶段任务合并进来。思想工作上同样分置：既扩大长远目标的宣传与学习，又把这种宣传同当前行动纲领的实践区别开，把作为方法的理论同当前整体方针区别开。","p":["新民主主义论","中国工人"]}]},{"t":"通过分列异同确定合作的基础与界限","d":"面对与自己部分重合的另一主张，应把相同与不同分别列清：相同部分构成合作的现实基础，不同部分标出不可让渡的界限。只看相同会失去自身，只看不同会失去合作，两者必须同时呈现。","sub":[{"t":"以分列异同确定合作的基础与界限","d":"不作整体肯定或整体否定，把对方主张同自己的主张逐项比较：相同部分指出其构成合作的现实基础，忽视它就失去合作可能；不同部分逐条列举（纲领范围、有无更高阶段、世界观、言行是否一致），指出这是不可让渡的界限，忽视它就失去自身。据此既承认合作又保留独立主张。","p":["新民主主义论"]}]},{"t":"对输入资源先分解再按需择取","d":"对外部输入或历史遗留的资源，整体接受与整体拒绝都会失当。应先按可分辨的标准把它分解为不同成分，按当前需要判定何者可用、何者有害，再择取可用部分并使之与自身条件相结合，形成自己的形式。","sub":[{"t":"对外来与既有资源先分解再择取","d":"既不生吞活剥地整体接受，也不整体拒绝。先把资源分解为可分辨的成分——外来者分为精华与糟粕，历史遗留者分为腐朽部分与仍有价值的部分；再按当前需要择取可用部分、排除有害部分；最后使择取来的东西同本身的特点和形式结合，成为可用的自有内容。","p":["新民主主义论"]}]},{"t":"把局部现象放回整体格局中确定其分量","d":"零散出现的不利现象，孤立看会低估或高估其分量。应先辨明整体格局中相反力量的对抗关系，把这些现象归入其中一方的动向，再据此确定态度；同时推演任其发展的后果，使判断不被单个现象的表面威力左右。","sub":[{"t":"把分散的严重现象放回总方向中判断","d":"面对各地接连出现的严重现象，不孤立地逐个看待，而先辨明背后是哪两种相反方向在对抗、双方各处于什么位置。据此得出双重态度：既承认其严重性并坚决反抗，又不被其威力所压倒。同时推演听任其发展的后果，使\"是否坚决反抗\"不再只由眼前一处的得失决定。","p":["克服投降危险，力争时局好转","向国民党的十点要求"]}]},{"t":"以对现存条件的清点确定可承受的行动限度","d":"判断能否采取强硬行动时，应把当下实际存在的、限制对方走极端的条件逐条列出，包括对方所依赖关系的松紧、外部力量的态度、其内部主张极端方案者的实际比重。可承受的行动限度由这些现存条件决定，而不由对破裂后果的笼统担忧决定。","sub":[{"t":"以清点现存有利条件支撑坚决斗争的方针","d":"决定是否采取坚决方针时不凭情绪，也不只从惧怕关系破裂一点设想，而逐条清点当下实际存在的有利条件：外部看对手所依赖的国际关系是否协调、其他力量的处境有无削弱、有无外来援助；内部看己方与中间力量的态度、对方内部主张最坏方案者的数量与地位。由此判定对方不易走到最坏一步，从而支持坚决反抗而非退让。","p":["克服投降危险，力争时局好转"]}]},{"t":"对相反并存的可能同时采取争取与防备两手","d":"当有利与不利两种前途同时存在而尚未定局时，只押一头都会失当。应把争取有利前途的行动与防备不利突变的准备并列为一个方针，两者同时进行且各有具体内容；并对不利可能的当前规模作出限定，使防备不至于取代争取。","sub":[{"t":"以两手并列的方针应对两种前途并存的局面","d":"不选择单一的一手。行动上双管齐下：一面坚决反抗对方的军事与政治进攻，一面积极发展各方面的统一战线并把要争取的对象逐项列出。方针表述上同样并列：力争好转，同时提起对可能发生的突然事变的警觉性，并限定该事变在目前的规模。","p":["克服投降危险，力争时局好转"]}]},{"t":"把对方的公开承诺变为自己主张的着力点","d":"对方公开表态时，其已承诺处可作为共同前提，其回避未提处正是自己应当集中提出的内容。把这些内容表述为可公开传播的具体条目，允许下层按本地情况增补，并规定统一的行动时间，分散的响应才能形成整体声势。","sub":[{"t":"就对方表态的缺口设置公开口号并统一发动","d":"先把对方的公开表态拆成两部分：已承诺的部分予以肯定并当作共同前提，回避未提的部分指明其缺失及后果。再把缺失之处转写成若干条可公开传播的具体口号并发布；要求下级大量使用多种形式宣传，允许按地方情况增补口号；最后规定统一的行动时间，使分散的响应汇成声势。","p":["克服投降危险，力争时局好转"]},{"t":"以对象自奉的标准核对实际行为并据以提出实行要求","d":"对方以某种主义、遗嘱、宪政或机关职责自奉时，不争论名义本身，而以这一自奉标准逐项核对现实行为，揭穿名义与实行的背离（官样文章、口头禅、弃置主义）；据此把要求表述为政府申令严督、从重治罪的具体处置，使要求借对方自己的承诺而无法拒绝。","p":["向国民党的十点要求"]}]},{"t":"按实际行为而非所属身份划分对待界限","d":"内部混杂的一方，按组织归属作统一处置，会同时打击可争取者与放过实际加害者。应改以可指认的实际行为为界，把整体分成必须打击与应当团结两个部分，分别规定对待方式，并申明两者服务于同一目的，使相反的两手不致互相取消。","sub":[{"t":"按实际行为把整体分开并以两条政策服务同一目的","d":"面对\"某一方都是坏人、都应当反对\"的笼统判断，不按组织归属划线，而按实际行为划线：对做出特定行为者（背后打枪、制造惨案、破坏根据地、攻打进步力量）决不容忍、必定还击、决不让步，并说明其行为的客观效果等于帮助敌人；对不属于这些类别、忠心于共同事业的人则表示好意、团结、尊重、长期合作。两套政策同时宣布，并指出漏掉任何一边都是错误；最后点明两者服务于同一个目的，使打击不被理解为破裂。","p":["团结一切抗日力量，反对反共顽固派"]}]},{"t":"把情绪的正当性与结论的正确性分开检验","d":"情绪反应是否正当，与由这种情绪直接推出的结论是否成立，是两个不同的问题。应先承认前者，再单独检验后者；既不用否定情绪的办法去否定结论，也不因情绪正当就接受随之而来的结论。","sub":[{"t":"承认情绪正当但不让它决定结论","d":"当严重事件引起普遍气愤、并由气愤直接推出悲观与无差别打击两个结论时，先明确承认这种情绪完全正当，说明在此情形下不产生这种情绪反而不正常；再把由情绪直推的结论单独提出来逐一检验并否定；最后给出有事实根据的判断和有区别的政策，使情绪得到承认而不成为判断的依据。","p":["团结一切抗日力量，反对反共顽固派"]}]},{"t":"把目标分解为依次为前提的条件链","d":"面对只提最终目标而回避前置条件的主张，应把目标所依赖的条件按依存关系排成次序，指出缺少前项则后项无从实现。这既说明为什么不能孤立强调其中一项，也为判断同类主张是否成立提供了可核对的依据。","sub":[{"t":"以条件间的依存次序反对只强调其中一项","d":"当有人只强调最终目标而回避实现它的前置条件时，把诸项排成依次为前提的链条：只有甲才能乙，只有乙才能丙，只有甲乙丙才能丁。据此说明单提最终目标或回避前置条件在实际上不可能实现，并把这条链条同时用作判断相关主张真伪的基础。","p":["团结一切抗日力量，反对反共顽固派","向国民党的十点要求"]}]},{"t":"以可核对的实绩改变要求的方向","d":"面对要求己方收缩或取消的压力，单纯申辩无效。应列出可核对的实际贡献、承担份额与自身状况，与提出要求者形成对照，使问题从\"是否应当取消\"转为\"应当以谁为标准\"，从而确立看齐的方向。","sub":[{"t":"以可核对的实绩把取消要求反转为推广理由","d":"面对要求己方收缩或取消的压力，不停留在申辩，而列出可以核对的事实：在关键节点上是谁发起并促成了全局性的转变；当前实际承担的份额有多大；自身状况可以逐条列举到什么程度；对自身待遇的约束到什么地步。以这些事实与提出要求者形成对照，把\"应当取消\"的要求反转为\"全国应当学习\"的结论，并据以确立看齐的方向。","p":["团结一切抗日力量，反对反共顽固派","向国民党的十点要求"]}]},{"t":"对危害的公开与暗藏形态分别辨认以确定应对范围","d":"对同一危害或力量的判断不能以公开可见者为限：公开形态有名目易察，暗藏形态匿迹于社会职位与日常行为之中。应循其活动踪迹辨认暗藏形态的构成与渗透范围，据此确定应对不能只针对可见部分，而须覆盖全部形态，不以名义身份为限。","sub":[{"t":"把同一敌人区分为公开与暗藏两形态并据此扩大动员范围","d":"面对可指认的公开之敌，不停留于对其声讨，而追问是否存在未公开的暗藏形态，并按社会角色辨认其成员（贪官污吏即其党徒，磨擦专家即其部下）。据此判定只对付公开者不足，动员须覆盖社会各层面与各界力量，否则暗藏之害不除。","p":["向国民党的十点要求"]}]},{"t":"以受众的可接受与反馈校准专门工作","d":"以广大读者或群众为对象的专门工作，好坏不能由办者自评，而应以受众是否可接受、是否参与为尺度：表达须生动明白、忌死板晦涩；并建立受众的公开反馈渠道，把其意见与好恶作为改进工作的依据。","sub":[{"t":"以读者可接受与反馈参与为标准办好刊物","d":"办好一份刊物（一件专门工作），不以办者自认为好为标准，而以读者的可接受与参与为尺度：内容须生动，忌死板、老套、看不懂、没味道、不起劲；把办好看作办者与看者共同的责任，建立读者反馈——看的人提出意见、写短信短文、表示欢喜什么不欢喜什么——据此改进，使报办得好。 # Method Dedup Index（31–36 批次） 本文件是 Theory Layer 的候选导航索引，按 `Primary L2 → L1 → Evidence 出处 + 可选 Related L2` 组织…","p":["中国工人"]}]},{"t":"新形态的性质须由与对立面和自身前一阶段的双重区别确定","d":"一个新建立的形态最容易被误解为对立面的翻版，或被当作自身旧形态的延续。仅有正面定义不足以排除这两种误解，应同时指出它与这两者的区别，使边界在两个方向上都被划清。参加者由此知道分寸所在，执行才不致向任一侧滑动。","sub":[{"t":"用与对立面和自身前一阶段的双重区别确定新形态的性质","d":"给一个新建立的形态定性时，先作正面定义，指明参加者的范围与专政（或作用）的对象。随后把它与两个最易混淆的既有形态分别区别开：一个是对立面正在实行的形态，一个是自己在前一阶段实行过的形态，两侧的区别程度可以并不对称。两侧都划清之后，性质的边界才算确定；并据此指出，对性质的明确了解和认真执行本身就会产生外部影响，而向任一侧的偏离都会造成极坏影响。","p":["抗日根据地的政权问题","目前抗日统一战线中的策略问题"]}]},{"t":"以分类定额把联合与孤立的策略转为可执行结构","d":"\"团结多数、孤立少数\"若只作原则宣布，执行者无从下手。应按对象的态度分成有限几类，为每类规定确定的份额，并指明每类所连接的更广力量，使策略目标变成可检查的结构。份额本身仍是大体规定，须按各处实际调整，否则结构会退化为凑数。","sub":[{"t":"以分类定额分配席位并为每份指明其争取对象","d":"组织一个联合性质的机构时，不笼统宣布\"团结多数\"，而按政治态度把参加者分成有限几类——自己一方、亲近的进步一方、不左不右的中间一方——各占相同份额。再为每一份额指明它所代表或连接的社会力量：进步的一份联系更广大的基础群众，中间的一份用于争取尚可争取的阶层，而争取这些阶层是孤立主要对手的重要步骤。比例只是大体规定，各地依实际施行，不机械凑数，最下级可变动以防敌对成分把持。","p":["抗日根据地的政权问题","目前抗日统一战线中的策略问题"]}]},{"t":"在必须维持的联合中，斗争是维持联合的手段而非其反面","d":"同并不可靠的一方结成联合时，退让保不住联合，反而取消联合赖以存在的力量对比。应把斗争理解为维持联合的手段：它阻止对方的侵蚀，又使对方因无法得手而更愿意留在联合之中。目的与手段一经分清，\"斗争会破坏联合\"与\"斗争可以无限制\"这两种相反的误解便同时被排除。","sub":[{"t":"以斗争为手段求得团结","d":"在必须同不可靠的一方保持联合的时期，明确团结是目的、斗争是手段，二者不是可以二选一的对立项。判断此刻该强调哪一面：当对方正坚决执行排挤己方的政策并以此为更大退让作准备时，应强调斗争而不强调统一。对采取两面手段的对方以相应的两面政策应对，由其尚愿联合的一面争取其留在联合中，由其侵蚀的一面作坚决斗争。斗争因而同时起到防御侵蚀、保护自身发展、争取动摇的中间力量和避免全面破裂的作用。","p":["目前抗日统一战线中的策略问题","放手发展抗日力量，抵抗反共顽固派的进攻"]}]},{"t":"对不可决裂的对手，斗争须在起因、范围与终点三处自设限制","d":"当对手同时是必须保留的合作方时，斗争不能以消灭对方为目标，只能是有限的。应在三处自设限制：起因上只作还击而不首先发动，范围上择其最甚者且无把握不发动，终点上一有成效即主动停止并重提合作。三重限制使斗争足以达到目的，又不至于把合作本身一并取消。","sub":[{"t":"以自卫、胜利、休战三原则限定对不可决裂对手的斗争","d":"与仍须保留合作的对手斗争时，在三处自设限制。起因上只作还击：决不无故进攻，也决不在被攻击时不予还击，斗争因而具有防御性。范围上择其最甚者：不斗则已，斗则必胜，决不举行无计划无准备无把握的斗争，利用对方内部矛盾，斗争因而具有局部性。终点上适可而止：把进攻打退后即使斗争告一段落，主动重提团结并订立协定，斗争因而具有暂时性。三原则约束的是斗争方式，公开反击与隐蔽积蓄两种处境下同样适用。","p":["目前抗日统一战线中的策略问题","放手发展抗日力量，抵抗反共顽固派的进攻"]}]},{"t":"中心任务须由其成立条件共同维持","d":"一项任务被确立为中心之后并不能自行维持。应辨明使它得以持续的其他条件，把这些条件与它并列为不可分割的整体；只保留中心任务而丢掉其条件，任务就只剩口号，最终会走向自身的反面。","sub":[{"t":"以互为条件的多项方针保障中心任务不落空","d":"提出一项中心任务时，不孤立地强调它，而是同时辨明维持它所必需的其他条件，把这些条件与中心任务并列，宣布为缺一不可、必须合一的方针。再用反证说明：只强调中心任务而丢掉其余条件，中心任务本身将靠不住、不能持久，并终究转化为自身的反面。据此要求各项同时执行，不按轻重先后取舍。","p":["必须强调团结和进步","团结到底"]}]},{"t":"以单一条件界定参加资格，把参加面扩到最大","d":"需要尽可能扩大参加范围时，应只保留一条与当前中心任务直接相关的条件作为资格，并明确宣布其余身份属性一律不构成限制。条件可正可负：或列出唯一必须具备的态度，或列出唯一被排除的那一类。资格条件越少且越贴近任务本身，可联合的范围越大，而联合的方向不致因人员庞杂而偏离。","sub":[{"t":"以单一条件界定参加资格","d":"确定谁可以参加时，不开列正面的资格清单，只设一条与当前中心任务直接相关的条件，其余身份属性一律声明不构成限制。条件可以取正面形式，只要具备某一态度并达到年龄下限即可，不分阶级、民族、男女、信仰、党派、文化程度；也可以取否定形式，只要不属于坚决敌对的那一类即可参加。资格标准同时适用于个人和组织，后者相应获得合法存在与活动的权利。参加面由此扩到与任务相容的最大限度，而方向不因人员庞杂而偏离。","p":["抗日根据地的政权问题","团结到底"]}]},{"t":"以具体对立面界定抽象主张的实际内容","d":"抽象主张若不指明反对什么，就无法判断它是否被执行。应把每项主张对照当前实际，逐条列出与之相违的具体事实，使主张的内容由其对立面确定，从而可指认、可检验，而不能被口头拥护所替代。","sub":[{"t":"把抽象方针转为逐项可指认的反对清单","d":"方针提出后不停留在名词上，为每一项方针对照当前实际，逐条列出与之相违的具体事实——具体的协定、机构、文件、事件、行为都写进去，从最高层级的政治问题一直列到具体的贪腐行为，不避琐细。方针的实际内容由这份反对清单确定：凡不反对清单上的事项者，即未执行该方针。","p":["必须强调团结和进步"]}]},{"t":"由缺失项与多余项的对应关系确定双向任务","d":"确定当前任务时，不能只列出所缺的东西。应同时查明多出来的、正在造成这种缺失的东西，认清两者互为因果；任务因而是双向的：不清除造成缺失的东西，所缺的就建立不起来，单讲建设只是空想。","sub":[{"t":"以缺失项与多余项的对照确定破与立的双向任务","d":"判断当前该做什么，不能只列出所缺的东西。先同时查明两侧主要事实：主要缺少的是哪几件，主要多出来的是哪几件，并指出正因为多了后者才造成前者的缺失，据此判定对象的整体性质。任务因而是双向的：要取得所缺的，就必须坚决彻底地破坏多余的。对\"只要建设，不要破坏\"的说法，用具体对象逐个反问，使抽象争论落到实处。","p":["新民主主义的宪政"]}]},{"t":"按当下条件而非一般优劣在现成方案中作选择","d":"面对多种现成方案时，不按其一般优劣排序取最好者。应逐一检查各方案与当下条件的关系：已经丧失效力、性质变坏者不取，本身可取而条件未到者暂缓，剩下与当前实际相合者即为现阶段的方案。方案的正当性由条件决定，不由其名声决定。","sub":[{"t":"用条件排除法在现成类型中确定当前适用的形式","d":"面对\"要哪一种\"的问题，先给上位概念一个明确定义，再把已有的现成类型逐一摆出并给出各自的排除理由：一种曾经行过、现在已经没落变成反动的东西，万万不能要；另一种本身很好、将来都要实行，但在当前条件下还行不通，只得暂时不要。排除依据是当下条件是否具备，而不是类型本身的优劣排序。剩下与当前实际相合者即为现阶段的形式。","p":["新民主主义的宪政"]}]},{"t":"以对方承认的准则为共同尺度提出要求","d":"向立场不同的一方提要求时，可以引用对方自己公开承认的准则文本作为共同尺度，抠住其中的关键规定，再以其实际行为与该规定之间的落差构成质问，使要求成为对方履行自身承诺的问题，而不是外来的强加。","sub":[{"t":"借对方奉为权威的文本确立己方要求","d":"向不认同己方立场的一方提出要求时，不只从己方立场论证。找出对方公开尊奉、无法否认的文本，抠出其中的关键措辞并逐层解释其分量；再以对方多年未曾实行的事实构成对照，指出其口头假托。这样，己方的要求就转化为对方兑现自身承诺的问题，对方难以从立场上加以拒绝。","p":["新民主主义的宪政"]}]},{"t":"同名事物须按其事实前提区分性质","d":"同一名称在不同条件下可能指向性质相反的过程：一处是对既成事实的确认，一处是对尚未存在事物的争取。判定其性质必须先查事实前提是否具备，不能以名称相同推定过程相同；前提不同，所需的努力与预期也完全不同。","sub":[{"t":"按事实前提区分同名事物的性质","d":"处理一个从外部引入的名目时，先比较本地与外地在事实前提上的差别：外地是某种事实已经成立之后立法予以承认，本地则该事实尚未存在，现有的是相反性质的现实。由此判定同名的过程在本地根本不是承认既成事实，而是争取尚未取得的东西；进而推出即使形式条文齐备也会被现存势力阻挠。据此重新确定工作的性质与难度预期。","p":["新民主主义的宪政"]}]},{"t":"由实际给予而非自我宣称判定主张真伪","d":"对无法直接验证的公开主张，可取其宣称与实际给予之间的落差作判据；并检查同类形式在既往事实中是否曾经具备而实质未至。形式的出现不等于内容的实现，自我声明与\"一贯主张\"不能充当。","sub":[{"t":"以言行落差与同类历史事实判定主张真伪","d":"判断一种公开主张是真是假，不以宣称和自我表白为据，而取言与行之间的落差作判据：一面谈这项主张，一面却不给相关方以丝毫的实际权利，即可判定为假。再检查同类形式在历史上是否已经出现过：形式已有多次，而实质从未随之而来。由此得出形式的具备不等于内容的实现，并提醒本方不要把形式兑现当作目的达成。","p":["新民主主义的宪政"]}]},{"t":"由对抗性行为的既往结局推断当前趋势","d":"判断一种阻碍力量的前途时，可考察同类行为在既往事实中的一贯结局，归纳其中反复出现的规律，再把它应用于当前对手已经公开的计划；结合双方的数量对比，即可在承认困难的同时给出方向判断，而不必凭愿望作乐观或悲观的估计。","sub":[{"t":"由对抗行为的既往结局推断当前对手的前途","d":"面对\"对方如此顽固、事情没有希望\"的疑问，不作情绪鼓动。先指出顽固是有时限的：顽而不固，斗争之下必起变化。再收集同类对抗行为的既往结局构成一组事实，归纳出反复出现的结果——总是以损人开始、以害己告终。把该结论应用于当前对手已经摆出的计划，推出结果必与其愿望相反。最后补上双方数量对比与努力条件，在承认困难的同时给出方向判断。","p":["新民主主义的宪政"]}]},{"t":"划出双向边界后须指认当下更严重的一侧","d":"对可能出现的失误，先在相反的两个方向上划出边界，说明任一侧越界都会造成损害。但对称的告诫不能指导行动，还须依据当前实际判断哪一侧此时更可能发生、危害更大。边界给出限度，主要偏向给出方向，两者缺一，纠偏就无从着力。","sub":[{"t":"划出双向偏向的边界并指认当前更严重的一侧","d":"部署一项有确定性质的工作时，把可能的失误归入方向相反的两类，声明两者都将造成极坏影响，从而为执行划出双边界。但不停留在\"两者都要防\"的对称告诫上：再对照当前实际，指认此刻哪一侧是更严重的偏向，并说明它具体表现为忽视争取哪一部分对象。执行者据此既知道限度，也知道当前应着力纠正的方向。","p":["抗日根据地的政权问题"]}]},{"t":"主导作用来自被自愿接受，而非所占份额","d":"在必须与他人共处的结构中，主导作用不由占有多少位置或握有多少强制手段产生，而由所提主张的正确与自身行为的示范使他人自愿接受。据此，增强主导作用的途径是提高自身质量与说服力；靠扩大份额或加强命令去争取，恰恰会取消主导作用赖以成立的自愿基础。","sub":[{"t":"以质量而非人数保证少数席位中的领导地位","d":"在自己只占少数席位的联合机构中，不靠增加名额取得领导地位，而要求所占名额的人员在质量上具有优越条件；有了这个条件就可以保证领导权，不必有更多的人数。同时明确排除两种取得方式：不是当作口号高喊，也不是盛气凌人地要人服从；而是以正确的政策和自己的模范工作说服教育其他参加者，使他们愿意接受自己的建议。","p":["抗日根据地的政权问题"]}]},{"t":"握有单方面决定能力时须自我设限，合作才不落空","d":"一方握有压倒性手段时，合作最容易退化为形式：决定照旧单方面作出，他人只剩追认。此时应主动放弃直接决定的便利，把商量、取得同意、倾听意见设为必经环节，并在非关键处容许对方保持自身特点。否则名义上的联合会因缺乏实质参与，失去它原本要争取的那部分力量。","sub":[{"t":"握有强制手段时以自我设限保持合作的实效","d":"当自己实际掌握武力与政权、可以单方面作出决定时，要防止以实力代替说服。先把合作安排宣布为真实的政策、不能敷衍塞责，再约束执行者：教育他们克服不愿和不惯同他人合作的狭隘性，遇事先商量、取得多数同意然后去做，主动鼓励对方提意见并倾听。明确禁止因为手里有武力和政权就一切无条件照自己的决定去做。同时不以自己的标准要求对方的生活习惯和言论行动。","p":["抗日根据地的政权问题"]}]},{"t":"依双重矛盾结构而非名义归属确定对象的位置与限度","d":"判断一部分人能否被争取、能争取到什么程度，不看其名义归属或自我宣称，而查它同时卷入的两组矛盾：与压在它上面的力量的矛盾使它可能靠拢，与自己一方的矛盾划定了它不会越过的界线。同一名义整体内部往往并存性质不同的部分，须分别对待，不能以整体的名义代替对其内部结构的分析。","sub":[{"t":"按双重矛盾划分力量并逐部分确定可配合的限度","d":"判断谁可团结、谁须反对，不按名义归属或自我宣称，而查每一部分力量同时卷入的两组矛盾：它同主要统治力量的矛盾使它可能被争取，它同自己一方的矛盾规定了能争取到什么程度。据此把整体分为进步、中间、顽固三部分，再把中间部分按矛盾差异继续分解，逐一确定它能走到哪一步。同一名义组织内部同样并存三部分，最顽固者虽居支配地位却在数量上只占少数，须分别对待。","p":["目前抗日统一战线中的策略问题"]}]},{"t":"第三方的向背取决于自身实力与对主要对手的斗争成效","d":"争取处于两方之间的力量，主要不靠对它本身做态度工作。其向背取决于三项条件：自己是否有足够的力量、是否尊重它的利益、对主要对手的斗争是否确实见效。因为对方也在争取它，条件不具备时它必然动摇甚至倒向对方。第三方的态度因而是力量对比的函数，而争取它与打击主要对手是同一件事的两面。","sub":[{"t":"争取第三方以自身实力与对主要对手的斗争成效为前提","d":"争取处在两方之间的力量时，不把它当作单纯的说服对象。先承认对方也在极力争取它，争取失败的后果是它动摇甚至变为对方进攻自己的同盟军。再列出争取得以成立的条件：自己有充足的力量，尊重对方的利益，对主要对手作坚决斗争并能一步一步取得胜利。据此，对主要对手的斗争与对第三方的争取不是两件事；第三方力量很大，往往成为决定胜负的因素，须采取十分慎重的态度。","p":["目前抗日统一战线中的策略问题"]}]},{"t":"以对方公开承认的纲领为据行动，使阻挠者失去正当性","d":"同立场不同的一方共处时，可选取对方已公开宣布、无法否认且已为众人知晓的纲领作为共同依据，自己认真实行。因对方并不能实行，正当性随之转移：依纲领行动者合法，阻挠者违背自己宣布的东西而失去正当性。采用时须只取纲领本身，不连同对方的整套观念一并接受，否则借来的依据会反过来同化自己。","sub":[{"t":"以对方公开的纲领为据行动使阻挠者失去正当性","d":"选取对方自己公开宣布、并已普及于人民中间的纲领，确定为共同纲领，逐条列出后以布告、宣言、传单、论文、演说、谈话等形式反复发布。关键在于自己认真实行而对方除个别条目外并不能实行，由此形成落差：依这些纲领行动的一方是合法的，反对别人实行的一方就成了非法的。在自己控制的区域它是行动纲领，在对方区域是宣传纲领。同时划清界限：只取纲领本身，绝不连同对方的思想体系一并接受。","p":["目前抗日统一战线中的策略问题"]}]},{"t":"方针的统一由共有条件决定，差异只改变实现方式","d":"面对以情况特殊为由拒绝统一行动的主张，不必否认差异。应指出各处共有的、决定行动前提的条件，由它推出统一的方针；差异只决定用什么方式实现，不决定是否实现。把差异摆在共性之前，方针就无法落地；因差异而改动方针本身，分别对待就变成了放弃。","sub":[{"t":"以同一性压倒特殊性确立统一方针的适用","d":"下级以本地情况特殊为由不执行统一方针时，不逐条驳斥各处的差异。先把可能被援引的差异一一列出并承认各有特殊性，再指出各处共有的、决定行动前提的那一条件，由它直接推出统一的行动结论。同时对两者作强调次序上的排序：应强调同一性，不应强调特殊性。差异因而被移出\"是否要做\"的判断，只保留在做法层面，不能再充当不执行的理由。","p":["放手发展抗日力量，抵抗反共顽固派的进攻"]},{"t":"按己方控制状况分设两套实现方式而保持基本方针一致","d":"在不同区域行动时，先按自己能否控制该区域分类，分别规定行动方式。能控制的区域公开推进，独立自主地建立各项机构；对方控制的区域则荫蔽精干、长期埋伏、积蓄力量、以待时机，只在对方规则所许可的范围内稳扎稳打，并广泛打入其各类团体。组织上相应加严：机关极端秘密，人员逐一审查，有暴露危险者转移调离。但基本方针在两类区域保持一致，改变的只是实现方式。","p":["放手发展抗日力量，抵抗反共顽固派的进攻"]}]},{"t":"凡须自主推进的事，其内容应由不依赖对方许可的动作界定","d":"一项要靠自己推进的方针，最容易在等待许可、等待委任、等待上级供给中落空。界定它的内容时，应先声明不受对方限制、不要对方委任、不靠上级供给，再列出可以自己动手的动作，并给出范围、数量与期限。方针由此变成可检查的自主行动，而不是有待批准的请求。","sub":[{"t":"把方针定义为不依赖对方许可的具体行动并加指标","d":"提出一项容易被架空的方针时，不停留在词上。先用一组否定划定其独立性——不受对方限制，超越对方所能允许的范围，不要别人委任，不靠上级供给；再列出可以自己动手的正面动作，扩大力量、建立据点、设立自己的财政与经济机关、办学校培养干部。随后落到可检查的具体项：指明地理范围，给出数量指标与完成期限，并追问执行进度。","p":["放手发展抗日力量，抵抗反共顽固派的进攻"]}]},{"t":"对每一项施压以对等的反要求应对，而不以辩解应对","d":"面对连续的指责与限制，逐条辩解只会把自己固定在被审查的位置上，压力在自己一侧累积。应对每一项施压提出一项对等的反要求，使对方也必须作答。只要所提之事有理，提出者的层级就不构成限制，下级同样可以向对方的上级提出。压力由此被转回对方。","sub":[{"t":"对每一项施压提出对等的反要求","d":"面对对方连续的要求、指责与限制，不逐条辩解，也不退让，而对每一项提出一项对等的反要求：对方要求己方一部移动，就以断然不动的态度对付，并反过来请准调动另一部反向移动；对方指责己方妨碍某事，就请其扩大己方在该事上的合法范围；对方指责己方宣传有误，就请其取消自己的同类宣传与限制法令；对方发动进攻，就实行反攻。提出的资格由事情是否有理决定，不由层级决定。","p":["放手发展抗日力量，抵抗反共顽固派的进攻"]}]},{"t":"对形势须同时估计相反两面，并按已然与未然给事态定级","d":"对形势作单面估计，无论悲观还是乐观，都会使行动失据。应同时肯定相反的两面：危险的加重与克服它的可能并存。再对当前事态逐项标明它已经是什么、还不是什么，把程度差别写清楚。两面估计防止情绪化，逐项定级使任务有确定的对应，估计本身也因此成为可被检查的对象。","sub":[{"t":"由相反两面估计形势并按\"已是什么、还不是什么\"给事态定级","d":"估计形势时同时肯定相反的两面：危险确已大大加重，克服这种危险的可能性仍未丧失。再对当前事态逐项定级，每一项都指出它现在是什么、还不是什么——是局部的还不是全面的，是试探性行动还不是决定性行动，是准备某一步骤还不是实行该步骤。任务由这一定级直接对应地提出。最后把估计本身列为风险来源：估计若出现过左过右的意见而不加以说明和克服，同样是极大的危险。","p":["放手发展抗日力量，抵抗反共顽固派的进攻"]}]},{"t":"局部的安全由他处的进展提供，退让换不来对方的克制","d":"一个局部的处境不由该局部单独决定。他处的胜利与发展会牵制对手，使其在本处不敢轻动，因此扩大他处的行动正是保全本处的必要步骤。与之相反的估计——自己愈退让，对方愈克制——把对手的行为看作对自己态度的回报；而对手的行为取决于力量对比，不取决于自己的姿态。","sub":[{"t":"用他处的进展说服局部的畏难","d":"某一局部因怕引起对方进攻而不敢行动时，不在该局部内部争论利害。列举其他方向已经发生的自卫作战与发展的事实，判定它们不但必要正确，而且正是使对方在本局部不敢轻动的必要步骤。关系写成单调递增：他处愈胜利、愈发展，对方在本处愈不敢轻动，本处的事情就愈好做。同时点名否定相反的估计——以为自己愈发展对方愈走向决裂、自己愈退让对方愈克制。","p":["放手发展抗日力量，抵抗反共顽固派的进攻"]}]},{"t":"打击面须由实际数量分布确定，并压缩到坚决者的极少数","d":"划定反对谁时，容易按名义或表面态度把范围扩大。应以调查得到的实际分布为据，把反对面压到态度坚决的极少数，其余一概列为争取对象，并对其中被迫的、动摇的、一时错的再作区分。打击面越小、争取面越大，联合才可能成立；范围一旦按印象扩大，就会把本可争取的人推到对面去。","sub":[{"t":"以坚决程度划定打击面并用调查数据压缩其范围","d":"确定反对谁、团结谁时，不按名义、党派或表面态度划线，而以态度是否坚决为唯一分界：只把敌人和其中态度坚决的那一类列为反对对象，其余一切人都列入团结对象。再用一次实地调查的数字支持这一限定，指出坚决敌对者在实际人员构成中只占极小比例，其余都是希望共同做事的。对被划入团结面的人还作进一步区分——两面派、被迫的、一时之错的——一律争取。打击面因而由可核查的数量分布确定，团结面被扩到最大。","p":["团结到底"]}]},{"t":"两侧偏差须各自绑定一条具体政策，并在所有相关领域同时防范","d":"只宣布\"两个方向都要防\"，执行者仍然不知道该做什么。应为每一侧写出对应的正确做法，并给该侧的失误一个确定名称，使偏差可以被指认。两条政策成对出现、缺一不可；再把这一成对要求推广到所有相关领域，防范才不会因领域不同而出现遗漏。","sub":[{"t":"为两侧偏差各配一条政策并推广到所有相关领域","d":"处理一个两侧都可能出错的问题时，不作笼统的\"两者都要防\"的告诫。为每一侧写出对应的正确做法，并给该侧的失误一个确定的名称和后果判定：对坚决敌对者不容忍、必须站在自卫立场打退其进攻，做不到即为一种机会主义；对非坚决敌对者必须争取团结，做不到即为方向相反的另一种机会主义。两条成对出现，缺一不可。随后把这一成对要求推广到所有相关领域，规定每个领域的政策都必须同时反对两侧偏差，并给各领域一个共同的出发点。","p":["团结到底"]}]},{"t":"以放弃渗透权利和态度可逆换取合作方的信任","d":"与他方合作时，向对方内部渗透最能瓦解信任，即使可行也应主动放弃，并把这一自我约束定为己方纪律加以检查。同时使自己的态度随对方当前行为而定：不敌对即友好，曾敌对而停止亦恢复友好。合作的条件因而是可查验的当前行为，而不是历史表现；对方也才有停止敌对的动力。","sub":[{"t":"主动放弃向合作方内部渗透的权利并使态度随其行为可逆","d":"与他方保持合作时，主动宣布放弃一项自己本可行使的权利：不在对方的组织内部发展自己的组织。这一自限被定为决定而非姿态，并附带检查要求——尚未严格执行的下级单位应即加以纠正。同时使己方态度随对方的当前行为而定：凡未向自己发动摩擦者一律采取友好态度；即使曾经发动过摩擦，在其停止之时也应恢复友好关系。合作的条件因而是可查验的当前行为，而不是对方的历史表现或立场归属。 # Method Dedup Index（37–40 批次） 本文件是 Theory Layer 的候选导航索引，按…","p":["团结到底"]}]},{"t":"在敌对力量内部识别并利用其矛盾以分化瓦解","d":"敌对阵营并非同质整体。应辨识其内部不一致与利害冲突，扩大争取多数、孤立并逐个击破少数，以对手内部的分裂削弱其整体力量。","sub":[{"t":"利用矛盾、争取多数、反对少数、各个击破","d":"在与敌对阵营斗争时，不把它当作铁板一块，而是识别并利用其内部矛盾：扩大争取其中多数可争取的力量，集中反对少数最顽固者，再对顽固者分化瓦解、各个击破；在外交上同样依苏联与各国、英美与德意、人民与政府、不同时期的区别来利用矛盾、争取多数。使自己的力量通过分化对手而相对放大。","p":["论政策"]},{"t":"公开揭露对方阴谋以分化其阵营、争取舆论","d":"把对手不愿暴露的完整阴谋计划公之于众，使广大群众以最大的警惕性注视事变发展；同时点明对方阵营内部的裂缝——许多人一时受蒙蔽、反共多被迫、有觉悟可能。公开揭露本身成为武器：既警觉舆论、凝聚警惕，又动摇对手阵营、争取中间与被迫者，使其阴谋在阳光下破产。","p":["为皖南事变发表的命令和谈话"]}]},{"t":"具体政策须设定合理限度、兼顾同盟者以避免过左","d":"在联合阵线内部制定具体政策时，须为同盟者留出可接受的空间、设定合理界限，避免因追求彻底而越过限度、把同盟者推向对立，从而损害统一战线本身。","sub":[{"t":"具体政策须兼顾同盟者利益、设定合理限度以克服过左","d":"制定统一战线中的各项具体政策（政权、劳动、土地、税收、锄奸、人民权利、经济、文教、军事）时，不为彻底而超越同盟者的接受限度：政权实行三三制、切忌包办；劳动改良切忌过左；土地减租减息同时规定交租交息；税收按收入；锄奸重、决不多杀；放手吸收知识分子与同情分子。以合理界限替代过左，使政策能真正发动同盟者。","p":["论政策"]},{"t":"在缓和表象下保持警惕、持续执行既定正确政策并纠正过左","d":"在局势走向暂时缓和时，不为表象所惑：国民党压迫决不会放松，须提高警惕、坚决打退进攻；各根据地须坚决执行中央去年十二月二十五日的指示（即《论政策》）、加强策略教育、纠正过左思想、长期坚持；并反对\"国共已最后破裂或很快就要破裂\"的错误估计。把警惕、执行既定正确政策与防止两种误判统一起来。","p":["打退第二次反共高潮后的时局"]}]},{"t":"依据对象的实际区别制定差别化对策","d":"复杂对象内部并非同质的。应首先辨析对象在性质、态度、时期上的真实区别，并据此分别规定不同的应对方式；差别化对策的有效性来自对区别的准确识别，而非来自对对象整体的标签化判定。","sub":[{"t":"在区别上建立政策的多重差别化区分","d":"面对性质混杂的对象，不笼统地一视同仁或一棍打死，而是按对象的性质、态度、时期、所属阵营作多重区别——把动摇的两面分子与坚决的反动分子区分开，把尚能合作的一面与坚决敌对的一面区分开，把不同时期的同一势力区分开。每做一次区别，就为其规定相对应的联合、斗争、孤立或争取政策；差别化政策的正当性全部建立在这些区别之上。","p":["论政策","关于打退第二次反共高潮的总结"]},{"t":"对具有两面性的对象实行对称的两面政策","d":"当对象本身具有两面性（如顽固派既尚能抗日又坚决反共、汉奸亲日派中既有两面分子又有坚决汉奸、英美派大地主大资产阶级抗日与反共各有两面性）时，使对策的结构与对象的两面性相对称：对对象的抗日/动摇方面实行联合或拉拢，对其反共/亲日方面实行孤立或打击；并在政策执行中把动摇的两面分子与立场坚决的反动分子明确区分开，避免一概而论。","p":["论政策","关于打退第二次反共高潮的总结"]}]},{"t":"以综合联合与斗争的统一战线政策替代两个极端的片面政策","d":"当两种相互对立的片面做法都失败时，不应在二者间简单取舍，而应回到它们共同忽视的对象实际，把被各自丢掉的那个方面重新纳入，形成兼顾两端的统一策略。","sub":[{"t":"以综合联合与斗争的统一战线政策替代两个极端的片面政策","d":"当面对两种片面倾向（一端只讲联合否认斗争、一端只讲斗争否认联合）并都已被证明造成损失时，不直接折中，而是回到对象本身：它既有可联合的方面、又有须斗争的方面。据此把两方面综合为\"既联合又斗争\"的统一政策，而不是在两个极端间选边。","p":["论政策"]},{"t":"统一战线政策即阶级政策，民族斗争与阶级斗争一致","d":"在抗日时期，党对国内各上层中层还在抗日的人们只有一个完整的、包括联合与斗争两面的民族统一战线政策；统一战线政策\"就是阶级政策，二者不可分割\"。党对党内和人民的教育也包括联合与斗争两方面——教导无产阶级、农民和其他小资产阶级如何与资产阶级地主各阶层在各种形式上联合抗日，又与其各种程度的妥协性、动摇性、反共性作各种程度的斗争。把统一战线与阶级立场对立起来是误解。","p":["关于打退第二次反共高潮的总结"]}]},{"t":"政策须随历史阶段与条件变化而更新，反对教条式沿用","d":"政策的有效性依附于其成立的历史条件。当阶段转变时，原适用的具体政策可能失效甚至有害，应根据新阶段的实际重新制定，而非把旧经验当作普遍适用的教条。","sub":[{"t":"按革命阶段的变化更新政策，不把旧阶段政策套用于新阶段","d":"制定当前政策时，先辨明当前历史阶段与以往阶段的根本区别（如抗日民族统一战线时期与土地革命时期的不同、中国革命半殖民地资产阶级民主革命与长期性这两个基本特点），确认过去某阶段成立的政策在当前条件下已不成立，主动停用并代之以适应当前阶段的新政策，反对不加辨析地把旧阶段的具体政策简单搬用到新阶段；反过来，也不能在反共高潮压力下错误地回退到旧阶段的土地革命政策。","p":["论政策","关于打退第二次反共高潮的总结"]}]},{"t":"综合多方矛盾合力研判时局走向","d":"时局走向不是由单一事件决定，而是由国际格局、对手内部矛盾、国内民心与我方政策等多重力量的合力塑造。应综合这些矛盾力量的方向和消长来研判走向，而不被表面事件迷惑。","sub":[{"t":"综合多方矛盾合力研判时局走向","d":"研判时局走向时，不凭单一表面事件下结论，而是综合四重力量的合力：国际格局（敌对帝国主义集团斗争前夜，使英美派须谋缓和）、对手内部矛盾（中央与地方、各派系之间及系内多重矛盾）、国内民心（人民反对专横、同情我方）、我方政策（持续抗议运动）。据此判断\"暂时缓和\"而非破裂，使对策建立在合力分析而非表面现象上。","p":["打退第二次反共高潮后的时局"]},{"t":"以民族矛盾是基本矛盾、阶级矛盾从属为总前提研判形势","d":"研判国内形势时，先确立矛盾的主次：中日民族矛盾依然是基本矛盾，国内阶级矛盾处在从属地位，\"一个民族敌人深入国土这一事实，起着决定一切的作用\"。据此，即使大地主大资产阶级全部叛变，也\"决不能造成一九二七年的形势，重演四一二和马日事变\"。以基本矛盾压倒从属矛盾为总前提，防止把反共高潮误判为一九二七年重演。","p":["关于打退第二次反共高潮的总结"]}]},{"t":"以有理有利有节的斗争艺术改变力量对比、争取主动","d":"对顽固派的斗争不是一味硬顶或一味退让，而须讲究分寸与节奏：在有理、有利、有节的前提下，通过斗争本身改变力量对比、提高己方地位、迫使对手重新考虑，从而争取主动。","sub":[{"t":"以有理有利有节的斗争改变力量对比、争取主动","d":"面对反共高潮不回避斗争，而是通过有理、有利、有节的反攻（提出两个十二条、拒绝出席参政会、发动全国抗议），使\"国民党地位的降低和共产党地位的提高\"形成力量对比变化的关键，\"迫使蒋介石重新考虑他自己的地位和态度\"。斗争本身改变力量对比、提高己方地位，从而把主动争取到手，而非被动承受。","p":["打退第二次反共高潮后的时局"]},{"t":"以退让与反攻的阶段转换、有理有利有节地掌握斗争节奏","d":"斗争不是恒定硬顶或恒定退让，而是按阶段掌握节奏：高潮初起时采取\"顾全大局委曲求全的退让政策\"（佳电）以争取同情，皖南事变后转入\"猛烈的反攻\"，并始终以\"有理、有利、有节\"把控分寸。退让与反攻的阶段转换，加上有节的分寸，使斗争既坚定又可持续，对打退高潮\"完全必要且已收得成效\"。","p":["打退第二次反共高潮后的时局"]},{"t":"针锋相对地和国民党反共政策作战，且有理有利有节三者缺一不可","d":"与国民党反共政策作战不能粗心大意，需要一整套战术。除对其反革命政策作\"针锋相对的斗争\"外\"便无他路可循\"；但斗争必须同时做到\"有理、有利、有节\"，三者缺一不可，缺一则\"就要吃亏\"。以项英同志机会主义失败为全党深戒。把针锋相对（守住立场、以眼还眼）与有理有利有节（把控分寸）结合为完整的斗争战术。","p":["关于打退第二次反共高潮的总结"]}]},{"t":"在敌强我弱环境中采取隐蔽积蓄、长期待机的斗争方式","d":"当自身处于弱势、环境不利公开活动时，不应硬碰硬，而应采取隐蔽、精简、长期积蓄力量的方式保存和发展自己，等待条件转化。","sub":[{"t":"在敌占区与国统区采取荫蔽精干、长期埋伏、积蓄力量、以待时机的政策","d":"在敌占区和国民党统治区这类不能公开活动的环境中，一方面不放弃发展统一战线工作，另一方面把组织方式和斗争方式转为\"荫蔽精干、长期埋伏、积蓄力量、以待时机\"：缩小目标、保存骨干、积累实力，等待有利时机再展开，而不是在不利条件下强行公开暴露或正面决战。","p":["论政策"]}]},{"t":"在遭受打击后迅速完成组织接续与内部团结以稳住阵脚","d":"当组织遭受重大突然打击时，不应陷于混乱，而应迅速指定新的领导核心、整饬内部、团结军民，以最低代价恢复战斗力并展示不屈的决心，防止对手借机瓦解。","sub":[{"t":"在遭受打击后迅速重建组织、团结内部以稳住阵脚","d":"当组织遭受突然打击、骨干被俘或受损时，不陷入混乱或溃散，而是立即指定新的领导核心（代理军长、副军长、政委、参谋长等），并明确整军方针（整饬该军、团结内部、协和军民、巩固并扩大统一战线），以最短时间完成组织接续，表明不屈服、不溃散，稳定军心民心并展示持续斗争到底的决心。","p":["为皖南事变发表的命令和谈话"]}]},{"t":"面对局部事件应追溯其系统来由与完整计划以判明性质","d":"面对看似孤立的突发事件，不应就事论事，而应追溯其来龙去脉，把事件放回对方早已酝酿的完整计划中去判断其性质、走向与应对。","sub":[{"t":"把孤立事件还原为对方系统计划以判明其性质","d":"面对看似孤立的突发冲突或事件，不就事论事，而是回溯其\"酝酿已久\"的来由，把事件放回对方早已酝酿的完整计划中去审视：列出对方从舆论动员、局部打击到全面摊牌的逐步步骤，证明该事件只是系列事变的\"开端\"。据此正确判断事件性质（属于何种更大图谋的一部分）与未来走向，避免低估局势、被动应对。","p":["为皖南事变发表的命令和谈话"]}]},{"t":"以对对手弱点的系统分析确立斗争信心","d":"在严重危局中确立信心，不能靠空喊，而应系统列举对手在政治、军事、民心、国际等方面的多重弱点，使必胜信念建立在对其必败根据的分析之上。","sub":[{"t":"以对对手必败根据的系统分析确立斗争信心","d":"在最黑暗的局势下不靠空喊信心，而是系统列举日寇与亲日派必然失败的七大根据：中共已独立坚强、其他党派不愿投降、军队反共多被迫、人民不愿亡国、帝国主义后台靠不住、各国革命将配合、苏联必助中国。使\"我们有能力收拾时局\"的信心建立在对其弱点的客观分析之上，而非盲目乐观。","p":["为皖南事变发表的命令和谈话"]}]},{"t":"以明确可核验的条件清单划定斗争底线并预留转圜余地","d":"在尖锐斗争中既坚持严正立场，又以明确可核验的条件或限度划定底线，同时给对方留出回头与事态平息的具体路径，使斗争有节、留有余地。","sub":[{"t":"提出可核验的条件清单划定斗争底线并预留转圜余地","d":"把原则性的严正斗争转化为一份具体、可核验的条件清单（如十二条要求），逐条列明对方必须做到的事项（取消反动命令、惩办祸首、恢复人员、交还人枪、撤军、释放政治犯、废止一党专政等），并声明\"如能实行，则事态自然平复，必不过为已甚\"。既亮明不可退让的底线，又给对方留下回头与平息事态的具体路径，使斗争有节、留有余地。","p":["为皖南事变发表的命令和谈话"]},{"t":"明确让步的限度、把合作主动权交还对方","d":"在斗争中明确让步的边界：\"我们的让步是有限度的，我们让步的阶段已经完结了\"；同时声明仍珍重合作，\"但必须他们也珍重合作\"，并指出对方已经造成的深重伤害。既保持合作姿态、不让主动权流失，又让对方清楚越过限度的后果，把合作能否维持的责任交还对方，避免无原则退让或被一味牺牲。","p":["为皖南事变发表的命令和谈话"]}]},{"t":"在阶段性胜利后仍需持续施压、不松懈","d":"在取得阶段性成果、局势出现缓和后，不能就此松懈；只要根本争点未得合理解决，就应持续严正抗议、扩大宣传、保持施压，直到问题真正解决。","sub":[{"t":"在争点未决前持续严正抗议、扩大宣传、不松懈","d":"在打退高潮、局势显出缓和后，不把阶段性胜利当作结束：只要\"国共间各项主要争点未得合理解决\"，就仍应\"继续严正的抗议运动，扩大第一个十二条的宣传，不要松懈\"。把阶段性胜利与根本争点的解决区分开，不因一时缓和而停手，持续施压直到问题真正解决。","p":["打退第二次反共高潮后的时局"]}]},{"t":"在准备最坏可能性的同时不抛弃好可能性，以充分准备争取好结果","d":"在局势存在恶化可能时，应认真准备最坏一种可能性；但准备最坏不是抛弃其他可能性，而是以充分的底线准备使对手不敢轻举妄动，从而反过来争取和实现好的可能性。","sub":[{"t":"准备最坏可能性但不抛弃好可能性，以充分准备争取好结果","d":"面向时局最坏一种可能性作充分准备\"是完全必要的\"，但这不是抛弃好的可能性，而\"正是为着争取好的可能性并使之变为现实性的一个条件\"。本次充分准备对付国民党的破裂，就使国民党\"不敢轻于破裂了\"。底线准备与争取好结果不是互斥，而是以充分的底线准备使对手不敢轻举妄动，从而反过来争取和实现好的可能性。","p":["关于打退第二次反共高潮的总结"]}]}],"3":[{"t":"从客观实际出发认识问题","d":"认识必须以对实际情况的直接了解为基础，用恰当的分析框架把握对象真实结构，反对凭主观、本本或道听途说作判断；真实情况须深入对象内部、向掌握实际经验者直接求教获取第一手材料。","sub":[{"t":"以阶级分析的社会调查了解实际情况","d":"面对不了解下情的领导危险，以向社会作调查为唯一方法；抓住几个城市、乡村，用马克思主义阶级分析作周密调查，从而获得对中国社会问题最基础的知识。对象须是各阶级的生动实际，而非书本或主观想象。","p":["农村调查"]},{"t":"开调查会向群众获取可靠材料","d":"为得忠实可靠的第一手材料，须开调查会：眼睛向下、甘当小学生，找真正有经验的中下级干部或老百姓；每次三五至七八人，给时间、备调查纲目，自己口问手写并展开讨论；无满腔热忱与求知渴望便做不好。","p":["农村调查"]},{"t":"实事求是：从客观事实引出固有规律","d":"面对认识与决策，不凭主观想象、一时热情或死书本，而凭客观存在的事实，详细占有材料，在马列一般原理指导下从中引出其固有的（非臆造的）规律性，找出事变内部联系作为行动向导，形成科学结论。","p":["改造我们的学习"]},{"t":"按社会阶级构成确定政策的照顾重心","d":"制定政策前先判明社会阶级构成：中国\"两头小中间大\"，无产阶级与地主大资产阶级都占少数，最广大的是农民、城市小资产阶级和其他中间阶级；据此使政策顾及一切抗日阶级的利益、特别照顾人数最广大的中间阶级，并保障其说话权利，否则国事办不好。","p":["在陕甘宁边区参议会的演说"]},{"t":"提高鉴别嗅觉独立思考不盲从以抵制主观主义","d":"面对主观主义、宗派主义、党八股的货色，须提高嗅觉，对任何东西都用鼻子嗅一嗅、鉴别好坏，问一个为什么、经自己头脑周密思考是否合乎实际、是否真有道理，绝对不盲从、不提倡奴隶主义。","p":["整顿党的作风"]}]},{"t":"在复杂对象中区分差异避免片面认识","d":"面对含多重属性的对象，须分别把握其不同侧面并按程度差异施策，防止以单一原则覆盖全部、陷入片面简单。","sub":[{"t":"在复杂对象中区分两重性避免片面","d":"面对统一战线等复杂环境，须按对象差异与程度分别对待：对地主资本家既联合抗日又斗争其动摇反动，土地政策既减租减息又交租交息，政治权利既保障又防范。须明确分清界限，防止把一面误推为全部。","p":["农村调查","在陕甘宁边区参议会的演说"]},{"t":"区分教条主义与经验主义两种主观主义并优先克服更危险者","d":"面对主观主义，先区分其两种根源：教条主义停于现成书本字句、经验主义停于局部经验，二者都只看到片面。再按危险程度施策——教条主义易装出马克思主义面孔吓唬人、更危险，故优先克服教条主义，以促成书本知识者与经验者结合、使经验上升为理论。","p":["整顿党的作风"]}]},{"t":"调查先于结论的认识前提","d":"判断与发言须以对对象的实际调查为前提，先掌握材料再下结论，反对未经验证便作普遍化指责或推论。","sub":[{"t":"调查先于结论的判断纪律","d":"任何结论、意见、批评都须建立在周密调查之后。印材料只为指出方法而非记结论；对只懂理论不懂实际者，调查尤为必要以使理论联系实践；\"下车伊始\"未调查就发议论十个有十个失败，须坚持没有调查就没有发言权。","p":["农村调查"]},{"t":"系统周密地调查研究现状","d":"针对材料零碎无系统、凭一知半解发号施令的缺点，对敌友我三方经济、财政、政治、军事、文化、党务等各方面动态作详细调查、详细占有材料，系统周密研究后引出应有结论以决定政策；没有调查就没有发言权，现象罗列无用。","p":["改造我们的学习"]}]},{"t":"在理论与实际结合中认识问题","d":"以真实问题为牵引组织理论研习与运用，用理论提供的立场、观点、方法去分析具体实际、解决问题，使理论原则与具体对象相结合，而非为理论而理论、孤立静止地钻研。","sub":[{"t":"以实际问题为中心组织理论学习","d":"针对为学习而学习、生吞活剥的毛病，确立以研究中国革命实际问题为中心、以马列原则为指导的方针，废除静止孤立研究马列的方法，引导用其立场、观点、方法具体分析中国现状与历史、解决中国问题。","p":["改造我们的学习"]},{"t":"有的放矢：以问题为的定向研究理论","d":"研究马列理论须有目的：以中国革命为\"的\"、马列为\"矢\"，为解决中国革命的理论与策略问题而到马列中找立场、观点、方法，使理论与实际运动结合，而非为学理论而学理论。","p":["改造我们的学习","整顿党的作风"]},{"t":"使书本知识者与工作经验者互相结合以克服主观主义","d":"面对主观主义，须使两类片面知识的人互相向缺乏方面发展：有书本知识者参加实际工作、向实际发展以免教条主义；有工作经验者认真读书、向理论发展使经验上升为理论以免经验主义。二者结合才产生比较完全的知识。","p":["整顿党的作风"]},{"t":"以能否应用马列立场观点方法分析实际问题判定真正理论家","d":"判定真正理论家、知识分子，不以读书多少、背诵熟否为准，而以能否依据马列立场、观点、方法正确解释历史与革命中的实际问题为准；真正理论从客观实际抽出又在客观实际中证明，书本词句未经应用不算理论家。","p":["整顿党的作风"]}]},{"t":"分门别类研究后综合把握","d":"对缺乏整体理解、内部多领域的复杂对象，先聚集力量分工、按领域（如经济、政治、军事、文化）逐一深入分析，再以分研究为基础作综合把握，避免整体混沌与片面。","sub":[{"t":"分工研究历史再作综合","d":"针对割断历史、对中外历史漆黑一团，聚集人才分工合作，先分经济史、政治史、军事史、文化史等部门作分析研究，在分部门研究基础上才有可能作综合研究，真正懂得中国昨天和前天。","p":["改造我们的学习"]}]},{"t":"从对手手段的阶段性转换识破其持续图谋","d":"面对又打又拉的对手，识别其手段变化只是同一图谋的阶段转换而非目标改变；某一手段暂停时，预判并警惕其后续手段，避免把战术间歇误判为威胁解除。","sub":[{"t":"识别敌人\"军事进攻→诱降活动\"的阶段转换","d":"面对又打又拉的对手，识别其军事进攻与政治诱降只是同一图谋的不同手段阶段；当军事攻势告一段落，不视为危险解除，而预判其必然继之以诱降活动，把\"一打一拉\"视为长期不变策略，主动揭破并反对。","p":["揭破远东慕尼黑的阴谋"]}]},{"t":"识破配合政治诱降的谣言挑拨战","d":"对手在主力攻势之外发动谣言与挑拨，意在制造内部裂痕、为政治诱降铺路；须识别舆论操纵并揭破其与内部呼应者，防止假信息瓦解自身阵线。","sub":[{"t":"揭破敌伪谣言攻势与挑拨离间","d":"识别对手在发动军事或政治攻势的同时发动谣言攻势，以\"不愿配合作战\"\"扩大地盘\"等污蔑挑拨内部关系、制造裂痕以利诱降；须揭破这类舆论操纵，并警惕内部媒体与之呼应者。","p":["揭破远东慕尼黑的阴谋"]}]},{"t":"以自身客观事实成绩回应污蔑、巩固立场","d":"面对系统性污蔑，不以空泛辩解应对，而以自身可验证的实际行动与成绩作为回应，既反驳虚假指控、又巩固自身立场与正当性。","sub":[{"t":"以实际战绩反驳污蔑、反对投降主义","d":"面对\"叛变\"\"游而不击\"等污蔑，不陷入空辩，而发扬自身持续作战与主动配合友军的实际战绩（如晋南战役华北各线全面出击），说明污蔑目的在使抗战失败以利投降，从而反对失败主义与投降主义。","p":["揭破远东慕尼黑的阴谋"]}]},{"t":"识破大国牺牲弱国的妥协阴谋","d":"面对强权之间的幕后交易，识别其以牺牲弱国或第三方利益换取自身战略目的的本质，从全局高度主动揭破、防止自身被当作交易筹码。","sub":[{"t":"揭破大国牺牲弱国的妥协阴谋","d":"把握强权之间以牺牲弱国利益换取自身战略目的的幕后交易（\"东方慕尼黑\"），从全局高度识别日美蒋之间牺牲中国、造成反共反苏局面的新阴谋，主动揭破并反对，防止被当作交易筹码。","p":["揭破远东慕尼黑的阴谋"]}]},{"t":"以共同敌人为枢纽组织统一战线","d":"面对多元力量与共同威胁并存的局面，把识别出的共同敌人作为枢纽，将国内与国际、不同战线上的相关力量凝聚到反对该敌人的统一阵线中，使分散行动围绕同一目标协同，并清除破坏团结的内部因素。","sub":[{"t":"以坚持国内统一战线援助国际反法西斯斗争","d":"面对国际共同斗争，先把国内战线做扎实：坚持抗日民族统一战线与国共合作，驱逐日本帝国主义出中国，用本国战场的实际胜利直接援助苏联与世界反法西斯的神圣战争；把国内统一战线的巩固视为国际统一战线的一环，而非孤立事务。","p":["关于反法西斯的国际统一战线"]},{"t":"坚决反抗国内反动分子的反苏反共活动","d":"在统一战线内部，对大资产阶级中反动分子的任何反苏反共活动必须坚决反抗；维持阵线团结不能仅靠联合，还要警惕并回击从内部破坏共同事业的力量，防止其瓦解反法西斯的协同。","p":["关于反法西斯的国际统一战线"]},{"t":"在外交上联合一切反对共同敌人的力量","d":"在外交战线上，主动同英美及其他一切反对德意日法西斯统治者的人们联合，反对共同敌人；对外联合以\"是否反对同一法西斯敌人\"为标尺，超越意识形态与制度差异，把一切可联合力量纳入统一战线。","p":["关于反法西斯的国际统一战线"]}]},{"t":"以开放外部意见校正自身的封闭性","d":"当行动主体自成小圈子、以自身判断为唯一标准时，认识与工作难以纠偏；须主动打开边界，保障外部意见充分表达并接受其监督，把外部意见与内部自我教育共同作为校正自身的渠道，同时划清不予接纳的敌对界限。","sub":[{"t":"以保障党外人士发言权实行民主合作","d":"面对自身是少数、外部人士是多数的合作局面，把合作确定为义务而非权利：不得一意孤行、把持包办；必须倾听意见、给别人说话机会，说得对就欢迎并学习其长处，说得不对也让其说完再解释，不可自以为是；只有勾结敌伪、破坏抗战团结者没有说话资格。","p":["在陕甘宁边区参议会的演说"]},{"t":"以内部教育与外部监督共同纠正自身缺点","d":"面对自身的关门主义、宗派主义等毛病，先不怕说出而承认它，再从两条渠道纠正：加强内部教育提高认识，同时经由与外部人士的民主合作接受监督，形成\"内外夹攻\"；并确立自身应受人民监督、站在民众之中而不在民众之上。","p":["在陕甘宁边区参议会的演说"]},{"t":"以联合党外多数力量克服对外宗派主义","d":"反对对外宗派主义，须牢记党员始终占人口极少数，对一切愿合作者只有联合义务、绝无排斥权利；须尊重党外人员长处、密切联系群众，使党内团结与团结全国人民并举，才能战胜敌人，防止脱离群众的自造宗派思想作怪。","p":["整顿党的作风"]}]},{"t":"以现实条件而非理想标准确定当前任务限度","d":"面对\"应当做到什么程度\"的选择，判断依据不是哪个方案在原则上更可取，而是当前条件是否具备；据此把任务限定在条件允许的范围内，并让一切具体问题的解决都不越出这一范围。","sub":[{"t":"按现实条件限定当前纲领的范围","d":"面对是否推行更高纲领的选择，先承认更高制度本身可取，再单独判断当前是否具备实行条件；条件不具备时不提出该要求，而把当前纲领确定为条件允许的方案，并使一切实际问题的解决都不超出这一范围，使纲领与国情相合而非与愿望相合。","p":["在陕甘宁边区参议会的演说"]}]},{"t":"以整体利益高于局部与个人协调内部关系","d":"面对内部多部分、多成员的关系协调，以整体（共同）利益高于局部与个人为准则，防止本位主义与派别倾向瓦解统一；各关系方须互相尊重、取长补短，使整体队伍整齐、步调一致。","sub":[{"t":"以党的利益高于个人和局部利益为准则处理党内关系","d":"反对党内宗派主义，须在局部与全体、个人与党的关系上以全党利益为出发点：反对闹独立性、个人第一主义，提倡顾全大局；外来与本地、军队与地方、老与新干部须互相尊重取长补短，使全党队伍整齐、步调一致，以利战斗，达到完全团结统一。","p":["整顿党的作风"]}]},{"t":"纠正错误须以建设与挽救为目的而非整人","d":"纠正可改正的错误，揭发批判是手段而非目的；须以挽救、建设为归宿，采用科学分析与治病态度，避免以整人为目的的伤害性处理。","sub":[{"t":"以惩前毖后治病救人的方针对待思想错误","d":"对待思想与政治毛病，须持两条宗旨：一是\"惩前毖后\"，无情揭发过去错误、以科学态度分析批判以便今后慎重；二是\"治病救人\"，揭批目的如医生割阑尾是为救人而非整死人，须以建设性、老老实实的态度矫治，绝不鲁莽乱打。 # Method Dedup Index（07–12 批次） 本文件是 Theory Layer 的候选导航索引，按 `Primary L2 → L1 → Evidence 出处 + 可选 Related L2` 组织，不代表正式理论结论。 **批次：** 07-12（每…","p":["整顿党的作风"]}]},{"t":"从对象的实际状况出发决定作用于它的方式","d":"凡要作用于对象的活动，效果不由行动者的意愿决定，而由对象的实际状况决定。应先弄清对象是谁、处在什么情况、能接受什么，再据此选择方式；对象不同，方式就应不同，不能从自己的习惯和现成形式出发。","sub":[{"t":"以对象调查校准宣传的表达方式","d":"动手前先确定是给什么人看、给什么人听，对宣传对象作调查、研究和分析，弄清其处境、关切与能懂的说法；据此选择用语、篇幅和形式，把对象的真实情况写进去，并以对方是否真懂作为检验。不作调查而按自己的习惯乱讲，等于下决心不要人看。","p":["反对党八股"]},{"t":"按对象性质区分批评与斗争的手段","d":"队伍内部处理错误时先分析对象属于哪一类，再决定手段：确系敌人或敌对思想的采用严厉斗争；只是偶然犯错误的同志用批评和自我批评——先重重给一个刺激使其知病，再好好叫他治疗。不作分析而一律套用严厉字眼，剩下的只是吓人，对敌人无用，对同志有害。","p":["反对党八股"]},{"t":"依据形势阶段变化事先预见困难并主动调整政策","d":"面对进入新阶段的形势，领导人员须事先看到其不同于以往的特点，预见即将出现的极端困难（\"暗礁\"），唤起同志注意并据以调整政策；若不能预见，只会随波逐流而损害事业。核心是看清趋势、提前预警、主动调整，不为现状迷惑。","p":["一个极其重要的政策"]},{"t":"使组织机构适应客观条件以克服鱼大水小的矛盾","d":"当根据地缩小、客观条件变化后，原适应过去的庞大战争机构已与战争情况发生矛盾；须缩小机构、兵精政简，使组织形式适合实际条件，克服\"鱼大水小\"矛盾而更有力量。核心是判断组织与条件是否匹配，不匹配则调结构而非硬撑。","p":["一个极其重要的政策"]},{"t":"破除现状与习惯对变革的束缚主动变换形式","d":"现状与习惯易束缚头脑，即使革命者也难下决心缩小自己创造的庞大机构。须认识气候变则衣服须变，主动褪\"冬衣\"换\"夏服\"；以孙行者变小虫、黔驴之技为喻，把自身变小却更扎实，破除惯性、轻快应敌。","p":["一个极其重要的政策"]},{"t":"以受众实际水平为基线把握普及与提高的转化关系","d":"处理普及与提高，须以受众当前实际水平为基线：普及是向工农兵普及、提高是从工农兵基础上提高，不是从空中提高；普及基础上的提高、提高指导下的普及，二者不能截然分开，群众文化水平提高后又要求提高，如此循环上升。","p":["在延安文艺座谈会上的讲话"]},{"t":"在统一战线上以团结为主并在各问题上既有团结又有斗争","d":"党的文艺工作者应以抗日、民主、现实主义方法与党外文艺家团结；但在统一战线不同问题上有团结也有斗争与批评，只有团结无斗争或只有斗争无团结都错；小资产阶级文艺家是重要力量，应帮助其克服缺点。","p":["在延安文艺座谈会上的讲话"]},{"t":"以实力与企图的匹配程度判断战略是否陷入绝路","d":"评估一项强势扩张计划能否成功，先看行动者的实际力量（实力）与其想同时达成的目标范围（企图）是否相称。若企图超出实力可支撑的限度，就会分散力量、顾此失彼；当缺口大到无法弥补，计划即陷绝路，表面强势不改必败。成败由实际状况而非主观企图决定。","p":["第二次世界大战的转折点"]},{"t":"在反保守与反空想的两条战线上按具体条件确定发展限度","d":"确认发展路线正确后，不把方向正确当作规模不受限制：以此时此地的具体条件为尺度校准发展的规模与项目，条件不能支撑的大计划一律不采用；同时在两个相反方向上设防——既反对只在存量上收缩的陈旧保守观点，又反对空洞不切实际的大计划，作为同一工作中两条战线的斗争。","p":["抗日时期的经济问题和财政问题"]}]},{"t":"从力量配置、进程节点与攻防性质判断对手的真实处境与败局","d":"判断一个对手的真实处境与败局，不能只看单一战况或一时起伏，而须从力量配置、进程中的决定节点与攻防性质综合把握：多处兵力是否匹配企图、关键节点是否已被锁定、是否陷入多面合围、是否已从进攻转入防御。这些态势共同决定其存亡走向。","sub":[{"t":"在全局进程中识别决定胜负的关键节点","d":"在漫长对抗中判断胜负走向，须找出对全局有决定意义的\"决定点\"：把当前斗争与可比的历史案例对照，确认哪一处失败使对手一蹶不振；一旦锁定这一节点，即可判定整个冲突的转折点已到，而不被过程起伏所乱。","p":["第二次世界大战的转折点"]},{"t":"从多战线合力夹击判断对手败局已定","d":"判断对手是否真正走到尽头，不只看单线战况，而是盘点同时压向它的各条战线：正面主力、预期的第二条战线、其内部酝酿的人民起义。当几条相互独立又彼此呼应的力量汇成合围，对手即陷多面夹击，据此可断定其败局已定。","p":["第二次世界大战的转折点"]},{"t":"以攻防性质判断敌人力量的生死","d":"判断一个倚仗进攻立国的力量是否仍有生命力，看它处在进攻还是防御。此类力量的政治与军事生命从出生起就建立在进攻之上，一旦被迫转入战略防御，进攻一完结，其生命也即完结。据此，当对手从进攻转为防御，即可判定其已丧失根本活力。","p":["第二次世界大战的转折点"]},{"t":"从力量对比与攻防态势的转化识别世界反法西斯阵线的全局转折点","d":"判断一场伟大斗争是否到达转折点，先看力量关系是否发生根本变化（红军由单独抵抗到力量壮大、希特勒攻势破产）；再由\"被动抵抗→主动进攻\"的攻防态势转换，判定转折点已经到来；并把它同时提升为具体战争与整个世界阵线的转折，使注意力从\"是否必胜\"转向\"如何促成胜利\"。","p":["祝十月革命二十五周年"]}]},{"t":"按事物的内部联系而不是外部标志认识问题","d":"依外部标志分类只能得到互不相关的概念的排列，看上去有条理，实际上没有触及对象本身，还会使人满足于现象罗列而不追究本质。要认识一个复杂对象，必须找出它内部的矛盾和联系，经调查、提出、分析而后综合，才能说明它的性质并据以处理。","sub":[{"t":"按内部联系提出、分析并解决问题","d":"不按外部标志把材料排成清单，而按内部联系走完一道程序：认定问题即事物的矛盾，先作大略的调查研究以发现并提出问题；再作系统周密的分析，暴露内部联系；然后综合起来，指明问题的性质并给出解决办法；重要的带指导性质的文件都应走完这道程序，并表明赞成什么、反对什么。","p":["反对党八股"]}]},{"t":"从生成来源与现实条件解释思想现象","d":"一种思想现象既不是凭空出现，也不能只凭其内容判定。要理解它，须查明它在既往运动中继承了什么、反对了什么，并找出使它得以持续存在的现实条件；来源与条件清楚了，对它的处理才有确定的性质和分寸。","sub":[{"t":"从历史来源与社会土壤诊断流行的思想错误","d":"面对队伍内部流行且难以根除的错误，不当作偶然现象：追查它反动于此前哪一场运动的积极因素、又继承了其中哪一种消极成分，再找出使它不断被再生产出来的社会成分与人员来源；据此确定今天批判它的性质与限度。","p":["反对党八股"]}]},{"t":"通过可见的形式清算难以直接把握的内容","d":"难以直接指认的内容，总要借某种可见的形式存在和传播。抓住这种形式并逐条揭穿，内容就失去藏身之处，众人也得到了辨认它的标志；而且形式本身有约束作用，形式不更换，被它妨碍的东西仍旧不能生长。","sub":[{"t":"抓住表现形式清算隐蔽的思想倾向","d":"思想倾向抽象难打、容易躲藏时，先找出它借以存在和传播的固定形式与工具，把这种形式当作独立对象提出来，逐条列举它可见的坏处并公开揭穿，使人一见就能辨认；同时指出形式本身会窒息被它妨碍的东西，因此不能只批内容而保留形式，须一并提出新的形式取而代之。","p":["反对党八股"]}]},{"t":"把作用于他人的产出当作须经检验才能交付的东西","d":"产出一旦作用于他人，其中的错误就不止损害自身。因此交付之前应先有准备，交付之后也不能靠一次成形：须按对象的复杂程度反复检查、删改，未经检验的宁可不交付。","sub":[{"t":"以反复检查对待要影响他人的表达","d":"认清拿出去的东西专为影响别人的思想和行动，因而先研究、先准备，多看看、不看到一点就写，写不出时不硬写；写成之后不立即发出，反复看、认真删改，把可有可无的字、句、段删去；拿不出来的东西就不拿出来。","p":["反对党八股"]}]},{"t":"从多处既有成果中鉴别并吸收仍有生命的成分","d":"自身资源不足时不必闭门生造。既有成果分布在不同来源之中，其中一部分仍然有效，一部分已经失效。应逐处鉴别，取其仍有生命者为我所用，弃其已死者，而不是整体照搬或整体拒绝。","sub":[{"t":"从群众、外来与古人三处吸收有生命的语言","d":"承认语汇贫乏不是天生如此而是没有下过苦功，随后分三处取材：向人民群众学习生动的、表现实际生活的语汇；从外国语言中吸收于我适用的新鲜成分而不硬搬滥用；继承古人语言中仍有生气的东西，同时弃用已经死了的语汇和典故；取来的成分用在实际的写和讲上。","p":["反对党八股"]}]},{"t":"从实际出发而非从抽象定义出发认识问题","d":"面对需要确定方针办法的问题，不应从教科书的抽象定义或概念出发去套，而应先确认客观存在的事实，从分析这些事实中找出方针、政策与办法；认识人的感情、爱、人性等也应从客观实践出发，而非从抽象观念出发。","sub":[{"t":"从客观存在的事实出发而非抽象定义讨论问题","d":"讨论复杂问题，不从教科书里找\"什么是文学、艺术\"的定义再按定义规定方针、评判见解；而作为马克思主义者，先列出实际存在、不可否认的事实，从分析这些事实中找出方针、政策与办法，使结论建立在事实而非概念之上。","p":["在延安文艺座谈会上的讲话"]},{"t":"从客观实践出发而非抽象观念认识爱与人的阶级性","d":"阶级社会里只有带着阶级性的人性，没有超阶级的人性；爱是观念的东西、是客观实践的产物，世上没有无缘无故的爱与恨。认识人的感情、爱与人性，须从其所处阶级地位与客观实践出发，而非从抽象定义出发。","p":["在延安文艺座谈会上的讲话"]}]},{"t":"把服务的根本对象与立足点作为面向群众工作的首要前提","d":"一项面向群众的工作，须先把\"为谁服务\"确定为统摄其余问题的根本前提，并真正把立足点移到服务对象一方；不解决为什么人与立场，其余工作就都没有正确标准，须通过深入对象、改造自身思想感情来实现。","sub":[{"t":"先确定工作为什么人的根本对象并据以统摄方向","d":"开展面向群众的工作前，先明确它服务的根本对象是谁；文艺的根本问题是\"为什么人\"，须确定为工人、农民、武装的工农兵和城市小资产阶级这最广大的人民大众。不解决这一点，态度、普及提高、方法等都无正确标准，须以此统摄其余问题。","p":["在延安文艺座谈会上的讲话"]},{"t":"通过深入群众改造思想感情使立足点转向服务对象","d":"要真正为工农兵服务，不能只停留在口头，须把立足点移到工农兵与无产阶级方面：长期无条件深入群众实际斗争，学习群众语言，在结合中改造自身思想感情，使自己与群众打成一片。不经历这一变化，作品与群众格格不入。","p":["在延安文艺座谈会上的讲话"]}]},{"t":"到对象的实际生活中去获取工作的真实源泉","d":"一切认识与创作的真实原料只存在于人民群众的实际生活与斗争中，这是唯一源泉；须长期、无条件、全心全意地深入其中观察、体验、研究、分析，否则劳动没有对象，只能成为空头。","sub":[{"t":"到群众的实际斗争生活中去获取创作与认识的唯一源泉","d":"文学艺术的唯一源泉是人民群众的生活与斗争，过去作品只是\"流\"而非源；必须有出息的文艺家长期、无条件、全心全意到工农兵中去，观察、体验、研究、分析一切人、一切阶级与斗争形式，获取原始材料后才能进入创作。","p":["在延安文艺座谈会上的讲话"]}]},{"t":"以政治与艺术统一、动机与效果统一评价精神产品","d":"评价面向群众的精神产品，政治标准放第一位、艺术标准放第二位，二者统一于革命的政治内容与尽可能完美的艺术形式；判断动机须看其在社会大众中产生的效果，动机与效果辩证统一。","sub":[{"t":"以政治标准第一、动机与效果统一为原则的文艺批评","d":"文艺批评有政治标准（第一位，看是否利于抗日团结、鼓励进步）与艺术标准（第二位，看艺术性高低），统一于革命政治内容与完美艺术形式。评价作家动机须看其作品在社会大众中的效果，动机与效果辩证统一。","p":["在延安文艺座谈会上的讲话"]}]},{"t":"透过表象与实质的背离识别对象所处的真实阶段","d":"凡属将要灭亡的势力常在最后阶段作最猛烈的挣扎，其表面强势恰与实质虚弱呈逆向背离。识别对象时须警惕这种表象与实质相反的情形，不为外强中干所惑，才能判断它究竟走向覆灭还是仍在上升。","sub":[{"t":"识破反动势力\"最后挣扎\"外强中干的本质","d":"面对看似凶猛、占据攻势的对象，先识别它是否正处在灭亡前的最后挣扎阶段：这类势力将亡时常作孤注一掷的猛烈表现，外表愈凶、实质愈虚。据此把它表面强势误判为有力、把自身胜利看远，都是被假象迷惑；应透过凶恶面孔看到它快要消灭、自己快要胜利的实质。","p":["第二次世界大战的转折点"]}]},{"t":"在共同阵线中从全局趋势把握自身斗争的前途与任务","d":"当自身斗争是更广阔共同阵线的一部分时，先认清局部与全局在方向上的统一（局部胜利即全局胜利的一环）；再从全局胜利趋势判断自身前途的确定性与临近度；最后把全部努力集中到本阵线的中心任务，不被局部艰苦模糊方向。","sub":[{"t":"把自身斗争汇入世界反法西斯阵线、从共同胜利确认前途并集中力量于中心任务","d":"认清自身斗争是更广阔共同阵线的一部分，盟友的胜利即自身胜利的一环；据此从全局胜利趋势判断本国斗争前途的确定性与临近度（\"不但确定，而且不远\"）；进而把一切努力集中于本阵线的中心任务，不为眼前艰苦模糊方向。","p":["祝十月革命二十五周年"]}]},{"t":"从决定性的基础层面而非派生层面解决困难","d":"一个层面上的困难常由另一个层面决定。只在被决定的派生层面上加加减减，无论怎样收缩都不能解决问题。应先辨明何者是基础、何者是派生，把力量投向扩大基础；在自身直接可控的范围内也直接扩充基础，同时说清这种做法所依赖的特殊条件。","sub":[{"t":"从决定性的经济基础而非收支科目上解决财政困难","d":"先辨明财政政策能影响经济、但决定财政的是经济；据此否定只在收支上打圈子、靠收缩必不可少开支渡难关的办法，把力量转到发展生产、开辟财源上；同时在自身直接可控范围内动手建立自给经济以扩大基础；并申明这种自给做法是当前特殊条件下的特殊产物，不作为普遍合理的形式。","p":["抗日时期的经济问题和财政问题"]}]},{"t":"在索取的同时培育来源并以根本目标判定当前限度","d":"凡长期依赖某一来源的活动，不能只按眼前需要索取。索取的同时须采取使来源本身增长的办法，令其有所失又有所得且所得大于所失；当前限度由根本目标能否实现来判定——既不因眼前关切放弃必要的索取，也不因当前需要耗尽来源；条件一经好转即减轻索取以恢复来源。","sub":[{"t":"在取之于民的同时增长民力并按根本利益确定负担限度","d":"一面取之于民，一面对其农牧、手工、盐业、商业采取帮助发展的适当步骤，使人民有所失同时有所得且所得大于所失；以战争能否胜利这一根本利益判定何为大仁政，既反对不顾战争需要的单纯施惠，也反对竭泽而渔、诛求无已；把负担按阶段安排，以自身生产发展作为减负条件，守住\"负担虽重而民不伤\"的限度。","p":["抗日时期的经济问题和财政问题"]}]},{"t":"把行动者自身当作可改造的条件使消耗转为产出","d":"困难不全在外部条件，行动者自身的规模、结构与作风同样是构成困难的一部分。应把自身当作可改造对象，按明确要求彻底缩减消耗性部分、统一分散的系统、提高效能并清除内部积弊，使自身由单纯消耗转为同时产出，从而同时减轻自身与外部来源的压力。","sub":[{"t":"以五项要求彻底改造自身机构使消费性支出转为生产性收入","d":"改造须严格、彻底、普遍而非敷衍、局部：以精简减少消费性支出、增加生产收入并减轻外部负担；克服不统一、闹独立性、各自为政，建立政策制度能贯彻到底的统一工作系统；由统一增进效能；厉行节约省去浪费性支出；清除贪污、摆空架子、无益的\"正规化\"、文牍主义等官僚主义。 # Method Dedup Index（13–18 批次） **批次：** 13-18（每 6 篇一个独立 method index 文件） **当前覆盖：** 13、14、15、16、17、18（本批次 13–18 全…","p":["抗日时期的经济问题和财政问题"]}]},{"t":"在组织骨干与群众积极性的结合中形成可持续的行动力量","d":"仅靠骨干积极性会成少数人空忙，仅靠群众积极性难持久、难走向正确方向。须以从实践中自然形成的骨干把分散的群众积极性组织到正确方向上，并保持骨干随实践新陈代谢。","sub":[{"t":"领导骨干与广大群众相结合","d":"任何有群众处都有积极、中间、落后三部分人。领导者团结少数积极分子为以首要负责人为核心的骨干，提高中间、争取落后；骨干须从群众斗争中自然形成，并随斗争新陈代谢。","p":["关于领导方法的若干问题"]},{"t":"以组织劳动力为中心开展群众性大生产","d":"在战争条件下自己动手、克服困难开展大生产，中心关节是组织劳动力：按家计划、劳动互助（变工队）、运输队、互助社、合作社，在自愿等价原则下把几万党政军与几十万群众劳动力组织起来；实行首长负责、自己动手、领导骨干与群众结合、一般号召与个别指导结合、调查研究分别缓急轻重。","p":["开展根据地的减租、生产和拥政爱民运动","组织起来"]}]},{"t":"用公开立场与实际行动的对照揭示真实意图","d":"当一方公开宣称与其具体行为不符，或与其所反对一方行为高度一致时，不靠直接断定，而通过并列对照与归谬反问，使真实立场与前提由对方自身言行显明，无法回避。","sub":[{"t":"以公开口号与具体行为的反差揭露自相矛盾","d":"面对宣称高尚原则的一方，逐项列举其具体行为与该原则的正面冲突，使\"宣称\"与\"事实\"并置，由其自身言行暴露矛盾，无需外部断言即可启动质问。","p":["质问国民党","评国民党十一中全会和三届二次国民参政会"]},{"t":"以与所反对对象言行的高度一致反证真实立场","d":"不直接断定对方勾结，而是并列列举对方与其公开反对的敌人/汉奸在一系列诉求与行动上的完全一致，使\"立场相同\"由对方自身言行显明，从而质问其真实关系。","p":["质问国民党"]},{"t":"以归谬式反问迫使对方暴露隐藏前提","d":"以假设性反问把对方表面合理的前提推至荒谬或无法自圆，迫使对方公开其隐含逻辑前提，使隐藏立场不得不面对质问。","p":["质问国民党"]},{"t":"以对方自身诺言与实践的长期对照暴露其无诚意","d":"面对要求对方\"实践诺言\"的指责，反将对方自己在不同时间作出的诺言逐条列出，以长期事实对照其是否实践；由对方自身承诺与实践的反差，暴露其毫无诚意。","p":["评国民党十一中全会和三届二次国民参政会"]}]},{"t":"在普遍动员与具体突破的往返中确立并检验部署","d":"面对需广泛推开的任务，先以一般号召打开局面，再通过具体深入的\"点\"取得可验证经验，反哺并修正普遍部署。认识在普遍动员与具体突破的往返中确立，而非从抽象原则到抽象原则。","sub":[{"t":"一般号召与个别指导相结合突破一点","d":"先提出一般号召动员群众；领导人员再具体地、直接地深入若干组织突破一点取得真实经验，用以指导其他单位。如此考验一般号召是否正确、充实其内容，避免号召落空。出自整风经验。","p":["关于领导方法的若干问题","开展根据地的减租、生产和拥政爱民运动"]}]},{"t":"在从分散到集中、再到实践检验的无限循环中逼近正确认识","d":"认识正确与否不靠主观自定，而靠把分散实践经验集中为系统判断，再放回实践检验并循环提升。每一次循环都更正确、更丰富，使领导认识与实践相互校正。这是马克思主义认识论。","sub":[{"t":"从群众中来、到群众中去","d":"把群众分散无系统的意见集中为系统意见，回到群众中宣传、化为群众意见并见之于行动，在行动中考验，再集中、再坚持，无限循环，一次比一次更正确更丰富，即马克思主义认识论。","p":["关于领导方法的若干问题","组织起来"]}]},{"t":"先以主要力量服务群众生产、再以少量提取维持","d":"要从群众取得资源，须先以主要力量帮助群众发展生产；服务到位则提取自然轻而易举，二者次序不可颠倒，否则便成只知要粮要款的片面观点。","sub":[{"t":"以绝大部分精力帮助群众生产、以少量精力取税收","d":"县区党政工作人员在财政经济问题上，应以百分之九十的精力帮助农民增加生产，再以百分之十的精力从农民取得税收；对前者用了苦功，对后者便轻而易举。反对只知向群众要粮要款的国民党观点。","p":["开展根据地的减租、生产和拥政爱民运动","组织起来"]}]},{"t":"在分工与统一的结合中通过关键责任人贯通执行","d":"任务落实不能靠条线割裂的部门对接，而要通过被授权的关键责任人对整体负责，使分工与统一在一元化下贯通，把多部门力量组织到同一任务上。","sub":[{"t":"通过主要负责人一元化分工落实","d":"上级向下传达应通过下级机关主要负责人使其负责，做到总负责人与分负责人都知道、都负责，分工而又统一，避免只由上级部门分别找下级对应部门造成力量分散。","p":["关于领导方法的若干问题"]}]},{"t":"在多任务约束下通过统筹确定并坚守单一重心","d":"任务再多也不能平均用力。须依据具体历史与环境条件区分主次，确定单一重心并坚持贯彻取得结果，避免多中心并行导致的凌乱与无确定结果。","sub":[{"t":"统筹全局确定单一中心工作","d":"一定时期内一个地区只能有一个中心工作，辅以第二位、第三位。总负责人统筹全局决定重心与秩序并坚持贯彻取得结果，反对来一件做一件形成的多中心凌乱。","p":["关于领导方法的若干问题"]}]},{"t":"以群众自身斗争为主体落实惠及群众的政策","d":"惠及群众的政策不能由上面恩赐，必须发动群众自己起来斗争争取，领导只作帮助与调节立场；自上而下给予的\"好处\"若不走群众斗争，便不巩固。","sub":[{"t":"减租须发动群众斗争而非恩赐式落实","d":"减租是农民的群众斗争，党的指示与政府法令是领导和帮助斗争，而非给群众恩赐。须检查落实、发现模范推动他处，成立或改造农民团体，政府站在执行减租法令、调节东佃利益立场；不发动群众积极性的恩赐减租不巩固。","p":["开展根据地的减租、生产和拥政爱民运动"]}]},{"t":"以定期公开自我批评（只批己不批对方）维护多方团结","d":"巩固联盟不靠互相指责，而靠各方定期公开、群众性自我批评（只批己不批对方），反复宣示公约以改正各自缺点、维护团结，避免对立激化。","sub":[{"t":"以年度公开群众性自我批评巩固军政军民团结","d":"各根据地于每年正月普遍无例外举行拥政爱民与拥军优抗群众运动：军队重新宣布公约、开检讨会、赔偿道歉、联欢；群众重新宣布公约、劳军；彻底检查各自缺点错误并坚决改正。再三再四宣读公约，各方面只公开批评自己、不批评对方。","p":["开展根据地的减租、生产和拥政爱民运动"]}]},{"t":"在客观局势的结构变化中判明各方利害与走向","d":"不凭愿望或口号判断对手，而把各有关力量放到国际国内大势的客观结构中，看其在变化中实际感受到的利害，从而判明其真实动向与政策可能的调整。","sub":[{"t":"依据各方在大变局中的客观位置判明其利害与动向","d":"观察国际局势的决定性变化（如苏联反攻、德日困局），把每一有关力量置于该结构变化中，看其实际感受到的利害与恐惧，从而判明其政策走向。对国民党，则据其\"喜欧洲解决、惧法西斯垮台\"的矛盾处境，推断其可能另打主意。出自本文对时局的总评。","p":["评国民党十一中全会和三届二次国民参政会"]}]},{"t":"通过枚举可能走向并逐一检验其可行性来把握不确定局势","d":"面对不确定的对手或局势，不武断下结论，而枚举其若干可能走向，逐一以事实与逻辑检验每条能否成立、导向何种结局，从而把握局势与各方向的现实权重。","sub":[{"t":"枚举对手可能的若干走向并逐一检验其可行性与后果","d":"面对不确定的对手动向，先枚举其可能的若干方向（如投降、拖、改方针），再以事实与逻辑逐一检验：哪条有事实支撑、哪条自相矛盾、各导向何种结局（死路 / 非生路 / 生路）。从而把模糊时局化为可判断的分支，明确警戒所在。出自本文对国民党三方向的判定。","p":["评国民党十一中全会和三届二次国民参政会"]}]},{"t":"以持续的自我批评防止已克服的错误倾向复萌","d":"认识与作风的保持并非一劳永逸。对已通过批评与斗争克服的错误倾向（如脱离群众的官僚主义、军阀主义），须以经常性、持续的内部自省反复清除其重新沾染的可能，防止在成绩面前自满而令坏作风复萌。","sub":[{"t":"以经常性自我批评防止脱离群众的倾向复发","d":"把\"天天洗脸、天天扫地\"作为持续的内部自省：在已克服官僚主义、军阀主义等脱离群众倾向后，仍须时时批评自身缺点、抑制自满，因坏作风会随时重新扑来；不与群众结合、沾染官僚主义灰尘者须以自我批评洗净。","p":["组织起来"]}]},{"t":"以对象的实际构成与当下状态取代整体沿袭的结论","d":"对复杂对象的判断不能用一个整体结论或沿袭下来的名目代替，应按其实际构成分方面分别判定，并在需要时继续向下一层区分；具体情况具体分析优先于绝对肯定或绝对否定的简单判断。","sub":[{"t":"对复杂对象作两方面分析而非绝对肯定或否定","d":"面对内部正误混杂的对象，不作绝对肯定或绝对否定的简单结论，而分两方面判断：既指出其主要方面的错误，又指出仍属正确、彼此一致的部分；对已判定的方面继续向下一层分析。评价历史文件与组织合法性同理：肯定其进步作用与合法性，同时指出缺点并作为教训。","p":["学习和时局"]},{"t":"按问题当下的实际存续状态重新确定工作对象","d":"对历史上出现过的问题先核实其是否仍以原有纲领与组织形态存在：已消失者只指出它曾存在并起过不良作用，不再以旧名目继续斗争；再指认当前真正普遍存在的倾向，分析其社会历史根源与教育不足的主观原因，据此改用说服教育、去盲目增自觉的方式。","p":["学习和时局"]}]},{"t":"在澄清错误根源与宽待犯错者的并行中实现团结","d":"清算错误若只追究个人责任，既不能使人真正认识错误的由来，也会失去可共事的人。应把错误当作由环境和根源产生、可被分析的对象彻底弄清，同时把对人的处理与对错误的判定分开并从宽，使认识澄清与队伍团结同时成立。","sub":[{"t":"以环境与根源分析处理历史错误、对人取宽大","d":"清算一段历史错误时不着重个别人的责任，而着重分析当时环境、错误内容及其社会根源、历史根源与思想根源，使干部在思想上完全弄清；对犯过错误者作结论时取宽大慎重方针，既不含糊敷衍又不损害同志，以同时达到弄清思想与团结同志两个目的。","p":["学习和时局"]}]},{"t":"以外部方针的转折划分阶段、逐段对照自身消长以总结经验","d":"总结经历不按主观感受或时间等分，而按外部条件与对手方针的实际转折分段；每段并列外部政策、自身可比消长与自身偏向的产生与克服，使一段历史的升降趋势与可继承的经验由对照本身显出。","sub":[{"t":"按敌我方针转折划分阶段总结一段工作经验","d":"以对手方针的实际转折（由重此轻彼改为重彼轻此）为界划分阶段；每阶段并列对手政策、自身处境与可比数量（党员、军队、根据地人口）的消长、学会了哪些新工作，以及本阶段党内产生的右的或过左的偏向及其克服；最后归纳上升、下降、再上升的总趋势与经验。","p":["学习和时局"]}]},{"t":"以将要承担的任务倒推当前必须完成的准备","d":"行动方向不只由当前能做什么决定，还应从将要承担的更大任务出发，反查现有力量与经验的欠缺，把它转化为若干必要的准备，并在现有条件下先行演练尚未做过的部分。","sub":[{"t":"以将要担负的任务倒推必需的思想与物质准备","d":"从判断今后要担负更重大的责任出发，反查现有力量与工作的薄弱环节（力量不够强大统一、长期处在农村而城市和交通要道工作很差），据此列出必要的思想准备与物质准备，并在现有条件下预先演练尚未做过的工作，明确没有这些准备就不能完成任务。","p":["学习和时局"]}]},{"t":"以自觉性代替盲目性、解除主观负担并主动运用思索","d":"妨碍正确判断的常常不是外部条件，而是主体对自身处境的评价（成败、资历、出身、专长）在盲目状态下变成负担，并压缩其思考能力。应把这些自我评价本身当作认识对象自觉解除，同时主动运用思索与分析，使主观状态由被动变为可用。","sub":[{"t":"放下精神包袱并开动思想机器","d":"先检查精神上的负担：犯错与未犯错、有无成绩、资历长短、出身、专长乃至年龄，凡陷入盲目性者都可能成为包袱；以自觉性代替盲目性把它放下，这是联系群众和少犯错误的前提。继而主动使用思想器官，凡事多想，学会分析事物的方法、养成分析的习惯，既是轻装又会思索。 # Method Dedup Index（19–24 批次） **批次：** 19-24（每 6 篇一个独立 method index 文件） **当前覆盖：** 19、为人民服务；20、评蒋介石在双十节的演说；21、文化工作中的…","p":["学习和时局"]}]},{"t":"在任务间隙中组织自我保障生产","d":"当常设任务占满主线时，利用其间隙组织自我保障性的生产活动，既补供给又增强主体韧性，使保障不脱离执行单元本身。","sub":[{"t":"组织部队机关在战斗间隙开展生产自给","d":"一切部队机关在战斗训练工作间隙一律参加生产，并组织专人创办农场作坊合作社建立\"家务\"；以按质分等分红刺激生产，首长负责、自己动手推进。","p":["必须学会做经济工作"]},{"t":"在敌占威胁下以武装掩护与灵活手段保障土地与群众生产","d":"在敌人直接威胁的空间里，不以退让缩限活动范围，而用武装月夜强种堡垒下土地、化装耕种据点旁等灵活手段夺回生产空间；同时以武力掩护、劳力（农忙半数力量无代价）帮助群众生产，使军民生产互相带动。","p":["游击区也能够进行生产"]}]},{"t":"以实际取得的成果事实替换主观“不可能”成见作为可行性判断","d":"面对“某条件下不能”的成见，不以推论或疑虑作判断，而枚举该地区已实际取得的成果事实逐条检验；以既成事实替代主观推定，使“能”从信念变为可办。","sub":[{"t":"以既成事实成果破除“环境不能生产”的主观成见","d":"面对“某环境下不能生产”等成见，不空辩，而以该地区已取得的实际成绩（给养改善、盈利、战果）为证逐条检验；用可核查事实替代主观疑虑，使“能够”从认识变为可普遍办理。","p":["游击区也能够进行生产"]},{"t":"以已具备的可数条件与纵向历史比较判断目标可实现性","d":"提出重大目标后先设问“能不能实现”，不以决心作答；逐项列出已具备的可数条件（组织规模、控制区域人口与武装、群众支持、外部支援），再与自身历史上同类条件纵向比较，由条件的现实状态而非愿望得出可能性判断。","p":["两个中国之命运"]}]},{"t":"以服务对象的利益为取舍与评判的根本标准","d":"把宗旨转化为日常判断尺度：不看来历，只看主张或行为对服务对象（人民）是否有利；利益归属决定采纳、改正与价值轻重的取向。","sub":[{"t":"以人民利益为采纳与改正的取舍标准","d":"面向外部批评与建议，不以提出者身份而以\"对人民是否有利\"为唯一取舍尺度：说得对就改正，办法对人民有好处就照办，并主动为人民的利益坚持好的、改正错的。","p":["为人民服务"]},{"t":"以服务对象的归属划分行为价值轻重","d":"面对牺牲与奉献，用\"为谁而死、为谁而做\"衡量意义轻重：为人民利益而死比泰山重，替压迫人民者而死比鸿毛轻，使价值判断有可操作的区分标准。","p":["为人民服务"]}]},{"t":"用制度化仪式把分散个体凝聚为奋斗整体","d":"通过可复制、成制度的共同形式，把个体的哀思与认同转化为集体的团结与动员，使分散人群围绕共同事业凝聚。","sub":[{"t":"把追悼制度化以凝聚共同奋斗的群众","d":"把为有益者送葬、开追悼会定为制度并推广到百姓中，使哀思有统一寄托形式，从而把分散个体凝聚成团结的人民整体，把纪念转化为组织动员。","p":["为人民服务"]}]},{"t":"在共同目标下以相互关怀维持集体韧性","d":"在艰难处境中，以共享的长远目标牵引注意力，以成员间相互关心爱护支撑勇气，用目标与互助共同维持集体持续奋斗的韧性。","sub":[{"t":"在艰难中以共同目标和互相爱护维持勇气","d":"困难时主动看到成绩与光明、提高勇气；以\"全民族解放\"共同目标团结五湖四海的人；干部关心战士、人人互相关心爱护帮助，并尽量减少不必要牺牲。","p":["为人民服务"]}]},{"t":"用对立方利益指向的事实检验言词归因的真伪","d":"当某方把不利批评归因为对手造谣时，枚举\"被批评现象是否恰好符合对方利益\"的事实：若对手反而欢迎、保存、称赞该现象，则批评源于事实而非虚构。以利益一致性检验归因真伪。","sub":[{"t":"用敌方对批评事项的欢迎事实反证\"批评出自造谣\"","d":"当对手把针对其缺失的批评一律归因于\"敌寇汉奸造谣作祟\"以封口时，枚举敌方/汉奸对被批评事项的实际态度——欢迎、称赞、保存其利益。若被指为\"造谣\"的批评恰是敌方所乐见，则证明批评基于事实而非虚构，归因被推翻。","p":["评蒋介石在双十节的演说"]}]},{"t":"由实际行为反推真实意图，不采信口头宣称","d":"当言词与行动背离时，以可核查的实际部署、制度措辞和兵力调动为据推断真实意图，而不将公开宣称当作事实。言词可被修饰，行动难以伪装。","sub":[{"t":"以对方实际部署反推其口头否认的真实意图","d":"当对手公开否认危险意图却摆出矛盾言行时，核查具体行动与制度铺垫：把\"讨伐叛逆\"措辞、\"七十七万五千人包围八路军\"等事实与其\"无内战\"表态对照，推出真实意图与口头相反。","p":["评蒋介石在双十节的演说"]}]},{"t":"从方法自身矛盾推出其不可行与自反后果","d":"当一种作法在内部逻辑上自相矛盾（口头与行动、宣称与目标相悖），可据其矛盾本身推出它不可行，并终将反噬施行者。方法的结构已预示其失败，不必待结果发生。","sub":[{"t":"把对方坚持的错误方法揭示为终将自食其果","d":"面对对手固执错误作法、反寻内战借口时，指出该作法\"绝对行不通\"会\"搬起石头打自己的脚\"：其压制言论、拒绝改组、准备内战的方法自身矛盾，必然反噬自身，从而把自我辩护转化为失败的预言。","p":["评蒋介石在双十节的演说"]}]},{"t":"把既有的落后力量当作可改造的可用资源而非排斥对象","d":"当新的力量不足以覆盖任务时，判断的起点不是既有力量够不够好，而是排斥它们会让谁占据阵地。承认其可用性并先取得联合，改造才有着力点；排斥与迁就是同一错误的两端。","sub":[{"t":"以先团结后改造的方式联合既有落后力量","d":"按条件差距确定联合广度，把旧人员与旧形式（旧知识分子、旧艺人、旧医与兽医、旧村塾、旧戏班、旧秧歌队）视为可用力量纳入而非排斥，新旧并举；纳入后按\"第一团结、第二批评教育改造\"逐步改造，既不迁就（投降主义）也不鄙弃（宗派主义）。","p":["文化工作中的统一战线"]}]},{"t":"改变的时机由对象的客观需要与主观自愿共同决定","d":"推动改变的依据不在推动者的良好愿望，而在对象一侧：需要须是客观存在的，接受须是对象自己作出的。两个条件缺一，改变或者落空，或者只剩形式。","sub":[{"t":"以群众的实际需要与自愿为推行改革的前提","d":"先分辨需要是群众实际上的还是自己幻想出来的，再检查群众是否已有觉悟和决心；客观有需要而主观未自愿时耐心等待并继续做工作，直到多数自愿才实行，决心由群众自己下而不代替群众下决心。","p":["文化工作中的统一战线"]}]},{"t":"使主观认识与方针符合客观环境实际","d":"面对复杂任务，先准确判定所处环境的根本性质，再让方针从该实际出发；脱离真实条件的方案看似高效，实则无效。环境判定是后续方法成立的前提。","sub":[{"t":"从被分割的农村游击环境出发确定经济方针","d":"先确认所处环境是建立在个体经济基础上、被敌人分割、游击战争的农村根据地，使一切经济决策从这唯一实际出发；不从城市观点等别处出发，以免主观计划脱离实际碰壁。","p":["必须学会做经济工作"]}]},{"t":"立足自身力量而非外部依赖解决困难","d":"在资源受限时，把解决困难的支点放在自身可调动的力量与创造力上，而非寄望外部援助；外部支持可作补充，不能成为主要依赖。","sub":[{"t":"以自力更生发动军民生产运动保障供给","d":"不依赖外援、依靠全体军民创造力解决物资供给；欢迎外援但不依赖，用军民两方同时发动大规模生产运动自己动手满足衣食所需，反对专靠外国。","p":["必须学会做经济工作"]}]},{"t":"在统一目标下分散执行","d":"当执行单元分散、条件各异时，保留统一的目标与领导，把具体经营下放给分散单元灵活实施，以统一性与灵活性结合适配分散环境。","sub":[{"t":"对分散的农村生产供给采取\"统一领导、分散经营\"","d":"因农村人力物力分散，生产与供给实行统一领导下分散经营：集中确定目标方向，把具体经营放到分散单位灵活执行，兼顾集中调控与分散实际的适配。","p":["必须学会做经济工作"]}]},{"t":"以利益激励与组织协作提升生产力","d":"对分散的小生产者，先调整利益关系激发其内生动力，再以协作组织放大个体劳动效率；以自愿示范代替强制，使改变来自对象自身而非外力压服。","sub":[{"t":"用减租减息与劳动互助提高个体农民生产力","d":"针对分散个体农民，减租提高生产兴趣、劳动互助提高劳动生产率；以耐心说服、典型示范代替强迫命令，使多数农民自愿组织进生产互助团体。","p":["必须学会做经济工作"]}]},{"t":"按对象条件差异分设不同执行标准","d":"同一总目标下，按执行单元所处条件的可达性分设不同标准，使要求与实情相称；既不因最差者拉低全局，也不因最好者强求一律。","sub":[{"t":"按地区条件分设不同生产自给标准","d":"依巩固区、边沿区、游击区不同条件分设自给标准：后方可达100%，巩固区约50%，边沿游击区15–25%；标准随地区可达性调整，不强行划一。","p":["必须学会做经济工作"]}]},{"t":"从长期全局出发规划资源配置","d":"作资源决策时以长期与全局而非眼前一时为尺度，既节约存量又发展增量，使当前行动服务于延续多年的目标链条。","sub":[{"t":"从起始年作长期打算、爱惜物力并发展生产","d":"任何地方从起始年就计算到长期战争、反攻与战后建设；一面决不滥用浪费人力物力，一面努力发展生产，以长期全局视角统筹节约与发展。","p":["必须学会做经济工作"]}]},{"t":"多元主体协同经营完成目标","d":"对覆盖面广的生产目标，由公、私、合作等多类主体并行经营共同完成，兼顾规模与质量，集多方力量于一项目标。","sub":[{"t":"以公营、私营、合作社三方经营完成工业品自给","d":"对花纱布铁纸等工业品做到完全自种自造自给、不靠外面；任务由公营、私营、合作社三方面共同完成，产品既求数量多、又求质量好耐穿耐用。","p":["必须学会做经济工作"]}]},{"t":"在冲突约束中把对立任务统一为相互支撑的实践","d":"当两项任务看似相互排斥（如作战与生产）时，不视为取舍关系，而把其组织为同一实践：以一方保障另一方、另一方反哺一方，使约束转化为互促。","sub":[{"t":"以劳力与武力相结合在游击区武装掩护下组织生产自给","d":"在敌后游击区恶劣环境下，把战斗任务与生产任务同样看重，不视为取舍；派专门部队打击敌人并作政治攻势作武装掩护，于战争间隙组织生产。生产改善给养、提高战斗力，证明战斗与生产互不排斥且互促，使约束转化为韧性。","p":["游击区也能够进行生产"]}]},{"t":"以并存可能结局的对置确定当前行动方向","d":"面对结果尚未确定的局势，不预设某一结局必然到来，而把并存的对立可能明确摆出，指明关键节点之后它们仍然并存；行动方向由“争取其一、反对其一”确定，而不由眼前进展自动给出。","sub":[{"t":"以并存前途的对置确定当前任务与政策基本点","d":"在结局尚未确定的转折关头，不把眼前胜利当作最终结果，而把并存的对立前途明确对置，指出关键事件完成之后两种前途依然并存；再从“用全力争取其一、反对其一”推出当前任务，并把该任务确定为政策的基本点，使方向判断与具体政策同一。","p":["两个中国之命运"]}]},{"t":"在条件转好时以自我约束保持完成任务的能力","d":"条件有利与地位上升本身不保证结果。越是力量增长，越需要把自我约束和服务目的当作与政策同等的完成条件，使优势不被主观骄躁消耗。","sub":[{"t":"在力量上升与形势有利时以自我约束维持任务完成","d":"当条件空前有利、自身已成为承担任务的重心时，不把优势当作结果，而同时提出谦虚、谨慎、戒骄、戒躁的自我约束，并以全心全意为服务对象服务确定目的；把自我约束与正确政策、一致努力并列为任务完成的条件。 # Method Dedup Index（25–30 批次） **批次：** 25-30（每 6 篇一个独立 method index 文件） **当前覆盖：** 《论联合政府》（25）·《愚公移山》（26）·《论军队生产自给，兼论整风和生产两大运动的重要性》（27）·《赫尔利和蒋介…","p":["两个中国之命运"]}]},{"t":"从群众实际出发并依靠其自觉行动","d":"面对需要群体参与的任务，从对象的实际状况与利益出发，依靠其自觉自愿的行动而非外部强制来推进，并把对象的真实意愿与觉悟程度作为校准工作的尺度。","sub":[{"t":"以群众路线发动和组织人民","d":"面对各项任务，从最广大人民的最大利益出发，深入群众、倾听呼声，按群众觉悟程度启发提高，在群众自愿原则下帮助其逐步组织起来，与群众打成一片。","p":["论联合政府"]},{"t":"在群众工作中区分命令主义与尾巴主义","d":"面对领导群众前进的任务，以群众实际觉悟程度为尺度校准节奏：超过觉悟强推即命令主义（急性病），落后于觉悟做尾巴即尾巴主义（慢性病），据此避免两种偏差。","p":["论联合政府"]},{"t":"让知识分子与农民结合开展农村工作","d":"面对农村工作，工作者须脱下学生装、穿起粗布衣，深入农民实际环境、放下外来视角，了解其要求并帮助其组织起来，才能真正有效动员。","p":["论联合政府"]},{"t":"用寓言具象化抽象战略任务以动员群众","d":"面对需要群众长期自觉参与的根本斗争，取群众熟悉、形象鲜明的寓言，把抽象战略矛盾映射为具象可感的对象，把决定性力量重新定义为群众自身，让战略任务变得可感、可信、可参与，激发其自觉自愿一起奋斗。","p":["愚公移山"]},{"t":"以\"统一领导、分散经营\"放手发动下面自力更生","d":"面对极端困难且分散作战的供给任务，上级不包揽一切物质责任，而提出明确任务、把握统一方向，把办法与权限下放，让下面广大人员自力更生、各显其能，从而解除上面窘境、更完善地满足需求并调动群众积极性。 ---","p":["论军队生产自给，兼论整风和生产两大运动的重要性"]}]},{"t":"通过比较对立主张把握事物根本","d":"面对纷繁现象或含混口号，剥离出相互对立的两种根本主张或方案，比较其立足点与后果，往往能直抵矛盾本质，避免停留在表面分歧。","sub":[{"t":"以两条路线对比识别问题关键","d":"面对复杂局势下\"问题关键何在\"的争论，先分辨出并存且对立的两条指导路线（人民战争的全面抗战路线与压迫人民的片面消极抗战路线），再据以判断一切具体分歧的根源都在于路线之争，从而抓住总枢纽。","p":["论联合政府","愚公移山"]},{"t":"区分专制统一与民主统一以判断统一性质","d":"面对\"统一\"口号，比较独裁者的专制统一与人民大众的民主统一两种对立实质：前者终致分裂，后者才是真统一。通过辨明名义背后的根本分歧，避免被共同口号掩盖矛盾。 ---","p":["论联合政府"]}]},{"t":"以可观察事实对照检验主张真伪","d":"面对相互竞争的主张，选取可观察的客观结果作逐项对照，让事实反差说话，比依赖宣示或名义更能检验主张的真伪与优劣。","sub":[{"t":"以两个区域的实际比较检验路线优劣","d":"面对\"哪条路线正确\"的争论，选取军事、经济、民生、自由等可观察维度，把中国解放区与国民党统治区逐一对照，用事实反差而非口号证明路线的胜负。","p":["论联合政府"]},{"t":"用两种方案的可见后果对照选定政策","d":"面对\"哪种办法更好\"的选择，把两种对立方案摆到一起，经一段实际试行后，用双方可观察的后果（生活是否改善、要求是否满足）作对照，让事实反差说话，再据以选定更优方案，而非仅凭名义或宣示。 ---","p":["论军队生产自给，兼论整风和生产两大运动的重要性"]}]},{"t":"以客观结果是否促进社会进步作为评判根本尺度","d":"面对对主张或政策\"好不好\"的争执，将其落到可检验的客观结果——是否促进整体社会的进步与发展，而非停留于动机宣示或名义。","sub":[{"t":"以生产力标准评判政策的根本作用","d":"面对评判各政党政策好坏大小的争论，把尺度落到客观结果：归根到底看其对中国生产力发展是否有帮助、是解放还是束缚生产力，以此区分革命民主派与反动集团。","p":["论联合政府"]},{"t":"区分形式倒退与实质进步以评判非常规做法","d":"面对表面上违背常理、看似\"落后倒退\"的做法，不简单按形式否定，而放回具体条件区分形式与实质：形式上是否违背分工是一回事，在贫困分裂与分散游击条件下能否改善生活、减轻民负、争取拥护、支持长期战争是另一回事；据实质结果判定其历史进步性。 ---","p":["论军队生产自给，兼论整风和生产两大运动的重要性"]}]},{"t":"区分对象内部层次以精准定位真正对手","d":"面对一个被整体贴上\"敌\"或\"友\"标签的群体，细分其内部不同层次（人民/政府、决策层/执行层），才能避免一刀切、孤立真正的责任方，并保留争取其余部分的可能。","sub":[{"t":"区分敌友阵营内部层次以精准定位对手","d":"面对含混敌对标签，不整体对待而细分内部层次：第一区分该国人民与其政府，第二区分政府中决定政策者与下层普通工作人员。据此不扩大打击面、争取可争取者、把斗争矛头对准真正决策者，同时保持原则立场。","p":["愚公移山"]},{"t":"区分代言人表态与背后集团立场以正确归责","d":"面对一个代言人的公开表态，不把它简单归为个人意见，而进一步判断其是否代表背后更广的集团立场（如赫尔利声明实为美国政府中一群人的意见）；据此把政策责任归于结构而非个人，避免低估其持续性与危险。 ---","p":["评赫尔利政策的危险"]}]},{"t":"从宏观历史趋势与根本矛盾判断斗争前途","d":"面对一时强大的反对力量，不只看表面强弱，而从世界历史主流与根本矛盾的发展趋向着眼，判断哪一方的方向具有历史必然性。","sub":[{"t":"以世界潮流与根本矛盾看清斗争前途","d":"面对反动力量一时猖狂、看似占优的局面，不据一时强弱下结论，而把当前斗争置于更广阔的世界历史趋势中：民主是主流、反民主反动只是逆流；并援引根本矛盾仍在且更尖锐，判断反动逆流终将被克服、人民方向必然胜利。","p":["愚公移山"]},{"t":"以政策反对的历史必然力量判断其危险","d":"面对一项对手政策，先辨明它实际助长哪一方（反动势力）与反对哪一方（要求独立自由统一的觉醒人民），再据被反对力量的历史必然性与不可阻止性，判定该政策增大危机、必然失败且将反噬其主张者，从而估计其现实与长远危险。","p":["评赫尔利政策的危险"]},{"t":"把党内反错误路线的胜利联系到更广泛的人民事业前途","d":"面对本运动内部反对错误路线的斗争，不把评估局限于\"内部正确与否\"，而把它置于更广阔的世界历史潮流与两国人民共同事业中衡量，确认其意义会向外辐射，成为更大人民事业的组成部分而非孤立事件。 ---","p":["给福斯特同志的电报"]}]},{"t":"通过言行对照揭露自身矛盾以识别欺骗","d":"面对以言辞包装欺骗的对象，将其公开表态与实际做法（或前后表态之间）并置对照，让内在矛盾自行显现；矛盾的存在即可作为不诚信与欺骗的，无需另立外部指控。","sub":[{"t":"以言行对照揭露欺骗性矛盾","d":"面对用高调辞令包装欺骗的当权者，先收集其自身前后声明与公开承诺，再与其实际行为或另一处自述逐项对照，找出内部矛盾（如称无民意团体却去\"聆取意见\"、愿\"还政\"却不行民主改革），以矛盾本身证明对方无诚信，而不是陷入对方设定的议题去争论。 ---","p":["赫尔利和蒋介石的双簧已经破产","评赫尔利政策的危险"]}]},{"t":"区分表层议题与根本诉求以守住问题实质","d":"面对以形式或程序议题替代实质要求的情形，先将二者判为相互独立的不同事项，坚持实质诉求不可被程序让步所替换或拖延，从而守住问题的根本。","sub":[{"t":"区分程序议题与实质诉求以守住问题根本","d":"面对用次要程序议题转移视线、回避实质要求的对手，先把两件事项明确拆开认定为相互独立：程序议题可暂缓，但实质诉求必须立即落实；拒绝让后者被前者稀释或偷换。 ---","p":["赫尔利和蒋介石的双簧已经破产"]}]},{"t":"通过被牺牲者与反对广度判断权力同盟的脆弱性","d":"面对内外配合的权力同盟，以其共同牺牲的对象与反对力量所跨阵营的广度，衡量其正当性与稳固性；牺牲广大群众且遭普遍反对的同盟，内部已失根基、趋于破产。","sub":[{"t":"以被牺牲方与反对广度判定双簧同盟的破产","d":"面对内外勾结、一唱一和的权力同盟，先辨明其共同牺牲的对象，再清点反对力量跨越的阵营广度；当被牺牲的是广大群众、且反对遍及各方时，即可判定该同盟失去正当性、走向破产。 ---","p":["赫尔利和蒋介石的双簧已经破产"]}]},{"t":"依靠最广大群体的力量解决根本问题","d":"面对看似超出自身实力的根本难题，把立足点放在动员和组织最广大的相关群体上，使其各自承担适配角色、形成合力，而非依赖少数精锐或外部条件。","sub":[{"t":"以人民战争路线组织军民力量","d":"面对强敌，确立军队全心全意为人民服务的宗旨，划分主力兵团与地方兵团，发展民兵自卫军，发动全体人民支前与生产自给，依靠最广大群体形成不可战胜的人民战争。 ---","p":["论联合政府"]}]},{"t":"在根本目标一致下分阶段推进并辨明实质","d":"面对长远而受阻的根本目标，先以各方可接受的阶段性步骤推进，同时警惕以形式替代实质的\"假推进\"，始终把住目标内核而非表面程序。","sub":[{"t":"分两步走建立联合政府并辨别真假","d":"面对废止一党专政的任务，先经各方协议成立临时联合政府，再经自由选举成立正式联合政府；同时辨别\"真做\"（联合政府）与\"假做\"（包办国民大会、维持独裁），坚持历史必然趋势。 ---","p":["论联合政府"]}]},{"t":"以稳定总原则指导随条件变化的具体策略","d":"面对长期任务，先确立不易动摇的总原则以锚定方向，再允许具体策略随条件变化而调整，避免要么僵化、要么失去方向的两种偏向。","sub":[{"t":"以一般纲领与具体纲领分层指导","d":"面对长期斗争中政策既要稳定又要应变的矛盾，把纲领分为不变的一般纲领（新民主主义）与随敌友变化的具体纲领，使稳定方向与灵活策略并存。 ---","p":["论联合政府"]}]},{"t":"在民主与集中之间建立有领导的统一","d":"面对既要广泛参与又要统一行动的组织难题，把决定权建立在广泛民主之上，再把执行权集中于被委托的机关，使活力与秩序兼得。","sub":[{"t":"以民主集中制组织政权","d":"面对民主与效率的矛盾，采取\"民主基础上的集中、集中指导下的民主\"：由人民代表大会决定大政方针、选举政府，既表现广泛民主又集中处理国事。 ---","p":["论联合政府"]}]},{"t":"通过持续反思纠正偏差保持组织健康","d":"面对组织或个体易于积累偏差的问题，建立经常性的检讨与批评机制，把偏差消灭在萌芽，以\"治病救人\"而非排斥的态度实现自我净化。","sub":[{"t":"以自我批评清除思想与组织灰尘","d":"面对党内不纯思想与组织懈怠，定期检查工作、推广民主作风，不惧怕批评与自我批评，以\"惩前毖后、治病救人\"为宗旨整风，纠正错误思想、保持肌体健康。 ---","p":["论联合政府"]}]},{"t":"抓住决定全局的关键环节","d":"面对必须整体推进的长期斗争，先辨认出决定全局走向的少数\"关键环子\"，在适当时机集中力量抓住它们，以带动整个链条或系统前进，而非平均用力或只盯局部。","sub":[{"t":"抓住整风与生产两个关键环节带动全局","d":"面对必须整体推进的长期斗争，先辨认出决定全局走向的少数关键环子，在适当时机集中力量抓住它们；本文认定整风作用于精神生活、生产作用于物质生活，二者是革命链条上缺一不可的环节，抓住它们就能带动整个链条前进，否则斗争无法继续。 ---","p":["论军队生产自给，兼论整风和生产两大运动的重要性"]}]},{"t":"以共同生产劳动带动组织全面转变","d":"面对军队内部关系、劳动观念、纪律与军民关系等组织问题，不只靠教育整顿，而让成员共同参加具体生产劳动；在共享的劳作中，关系、观念、纪律会随实践本身一并被重塑，使一项具体活动同时撬动多重组织作风的转变。","sub":[{"t":"以生产劳动为杠杆综合改造军队作风","d":"面对军队内部关系、劳动观念、纪律与军民关系等问题，让官兵共同参加生产劳动：在共同劳作中官兵亲如兄弟、二流子习气被改造、劳动纪律反哺战斗纪律、有了\"家务\"便少侵扰百姓并增益军民互助，使一项具体实践同时撬动多重组织作风的转变。 ---","p":["论军队生产自给，兼论整风和生产两大运动的重要性"]}]},{"t":"透过政治路线背后支撑的阶级力量判明其实质","d":"面对一条政治路线或主张，不据其自我标榜或表面形式判断，而揭示其所反映、所依附的社会阶级力量，并据该力量的地位与利益判明这条路线的本质与后果。","sub":[{"t":"透过政治路线背后支撑的阶级力量判明其本质","d":"面对一条以理论或纲领自我包装的政治路线，不据其表面主张判断对错，而追问它反映并服务于哪一社会阶级力量；路线的本质、对错与后果，由其所依附力量的地位与利益决定。","p":["给福斯特同志的电报"]},{"t":"追踪同一反动势力跨国扩展以预判连锁危险","d":"面对本国出现的反动政治现象，不只在本国范围内孤立评判，而识别其背后支撑的同一反动资本/社会力量是否正向他国扩展；一旦确认是同一力量越界扩张，便据其已显现的利益取向，预判它对另一国人民将造成的连锁危险，从而把分散的局势连成同一力量作用下的整体。 --- # 待理论层归并的 L1 # Method Dedup Index（31 批次） **批次：** 31-31（每 6 篇一个独立 method index 文件，本批次为末尾余数组，仅 1 篇） **当前覆盖：** 《对日寇的最…","p":["给福斯特同志的电报"]}]},{"t":"根据根本形势变化调整行动总方针","d":"外部决定性条件骤变使全局进入新阶段时，应先重新判断阶段性质，再将分散力量整合为统一总攻方向，并主动与关键外部力量协调，避免以旧节奏应对新形势。","sub":[{"t":"借势转攻：依形势转折发动全国规模反攻","d":"当外部盟军参战使战争进入最后阶段，先判断总形势根本转变，再把分散抗日力量统一组织为全国规模反攻，并密切协同盟军与同盟国。核心是借形势转折迅速升级行动总方针。 ---","p":["对日寇的最后一战"]}]},{"t":"以内外协同的多线力量瓦解对手","d":"面对据点强敌、仅靠正面难以速决时，应同时组织深入敌后的机动力量破坏枢纽，并在其控制区内部发动群众形成内应，使内外线互为条件、合力破敌。","sub":[{"t":"内外线配合瓦解敌占区","d":"在正面进攻外，成批武装工作队深入敌后破击交通，同时发动沦陷区群众组织地下军准备起义，配合外部进攻。核心是内外两线同时发力、相互策应，从内部瓦解敌人。 ---","p":["对日寇的最后一战"]}]},{"t":"在推进主攻的同时巩固既有阵地","d":"推进主要进攻时不能忽视已得阵地巩固与内部建设，以民生、组织与纪律的巩固作为持续进攻的支撑，防止扩张快于巩固而造成反复。","sub":[{"t":"进攻与巩固统筹","d":"在扩大解放区同时，冬春普遍减租减息、发展生产、组织政权武装、加强民兵与军纪、坚持统一战线、防止浪费。逻辑是既有阵地巩固支撑持续进攻，避免只攻不守。 ---","p":["对日寇的最后一战"]}]},{"t":"在关键转折期防范内部风险把握方向","d":"事业临近决定性胜利、外部目标将达成时，更易被内部冲突消耗；应提前识别并遏制内部分裂风险，明确共同政治方向，以团结保全已到来的胜利机会。","sub":[{"t":"警惕胜利前夜的内战风险","d":"在全力对敌之际明确制止内战危险、促成民主联合政府、号召团结。要点是在外部胜利在望时主动防范内部冲突打断大局，以政治方向保障军事胜利果实。","p":["对日寇的最后一战"]}]}],"4":[{"t":"以对象的实际行为而非其宣称为判断依据","d":"判断一个对象的性质、走向以及应当如何应对时，可靠依据是它已经做过和正在做的事，而不是它对自己的说明。行为具有连续性，宣称可以随场合更换；应对方式也应由对方实际采用的方式决定，而非由己方愿望单方面确定。","sub":[{"t":"以历史行为推断对手的现行方针与未来动向","d":"判断对手将要怎么做时不以其声明为准，而取出它过去一段完整时期的行为记录，再看它在当下形势中的实际做法，用两者的一致性外推将来方针。若过去与现在一贯，即可判定其方针已定，不因己方意愿而改变，据此确定危险的性质与程度，并转为本方的准备依据。","p":["抗日战争胜利后的时局和我们的方针"]},{"t":"依据对手实际采取的手段确定己方对等做法","d":"先调查对方实际使用的是什么手段，再依次弄清它有什么用处、要用来对付谁，然后调查己方是否具备或能造出同类手段，最后按对方的办法采取对等做法。对等只在斗争形式上成立，不延伸为对具体得失的机械固守：可主动放弃某一具体阵地，再在有利时收回。","p":["抗日战争胜利后的时局和我们的方针"]},{"t":"从对不同对象的差别处置判明真实的敌友划分","d":"判断一个主体真实的敌友划分时不看它宣称属于哪一阵营，而把它在同一事项上对不同对象的处置并列比较：对谁下达约束与防范，对谁给予职权与信任。若对名义上的敌人宽、对名义上的同伴严，则其宣称的阵营划分不成立。差别处置由实际利害支配，一经做出即构成其真实关系的自我供述。","p":["蒋介石在挑动内战"]},{"t":"从理由的更替判明目的先定于理由","d":"当对方为同一行动方向先后提出不同理由时，不逐个纠缠理由本身，而把它们按提出顺序排列，检查前一个被事实或舆论否定后是否放弃原来的行动。若理由更换而行动方向不变，说明理由是为已定目的临时寻找的。据此把重点放在制止该行动上，并预计新理由还会出现，不因驳倒其中一个而认为危险解除。","p":["蒋介石在挑动内战"]},{"t":"以指令间的相互矛盾与差别对待判定指令不公","d":"面对对方下达的指令，把它与其他指令并列对照：同一指令者对己方与对他方下达的指令若互相矛盾，且只对己方施加不利的一条，则由指令文本自身即可判定其不公。判定依据是对方实际发出的指令及其差别，不需另行证明其动机。","p":["第十八集团军总司令给蒋介石的两个电报"]},{"t":"区分口头宣称与实际行为以判明真实意图","d":"判断对方真实意图时，把它的口头宣称与实际下达的安排并列比较：一面宣称服从与避免内战，一面实际叫人民军队驻防待命、叫敌人汉奸维持治安。从宣称与安排的反差中读出真实意图，不依赖对方自我说明。","p":["评蒋介石发言人谈话"]}]},{"t":"把应然判断与实际可能分开处理","d":"一件事应当如何，和它实际会如何，是两个必须分别回答的问题。前者由道理决定，后者由力量对比决定，不能由前者推出后者。分开之后再按实际条件把对象分类，对不同类别采取不同程度的争取。","sub":[{"t":"区分应然归属与实际得失并按力量分类争取","d":"把\"应当归谁\"与\"实际会落到谁手\"分作两个问题。前者按谁付出劳动与牺牲判定权利归属；后者按双方在各处的实际力量分布逐项估计，分为对方占优势必被取走、双方相近须争取、己方足以取得三类。对第一类不作幻想，对第二类明确力争，对第三类确保取得并连成整块。把应然直接当作实然而不去争取的即是机会主义。","p":["抗日战争胜利后的时局和我们的方针"]},{"t":"凡能争得者用全力争之并控制一切可控制的","d":"面对大城要道暂时不能属于我们、部分地盘仍可力争的形势，先区分哪些能争得、哪些暂不能得；对凡能争得者用全力争之，对凡能控制者均控制之哪怕暂时也好，同时广占乡村和城镇，继续攻势以扩大控制。不因暂不能全得而放弃可得，不因控制是暂时的而放弃控制。","p":["中共中央关于同国民党进行和平谈判的通知"]},{"t":"把纸面协议当作需要努力实现的对象","d":"谈判取得成果后，不把纸上的协议当作已经实现的事实，先区分已达成与未达成部分；以坚持协定、要求对方兑现为继续任务，同时准备以自卫斗争粉碎对方的进攻。纸面承诺转化为现实，靠的是持续的努力与斗争，而不是协议文本本身。","p":["关于重庆谈判"]}]},{"t":"权利与代表资格由实际承担的份额决定","d":"对成果的处置权和对整体的代表资格，不由名义地位或既有身份自动产生，而由各方在事情中实际投入和承担的份额产生。判定时先核算谁做了什么、承担了多少，再据此确定谁有权处置、谁能代表；未曾承担者不因居于名义地位而取得权利。","sub":[{"t":"按实际承担的份额确定权利与代表资格","d":"对\"谁有权处置成果、谁能代表整体\"的争议，不按名义地位、职衔或既有承认判定，而先核算各方实际承担了多少：在什么条件下开展工作、独力完成了哪些部分、承担的比例有多大。以此与几乎未承担者对照，确认权利归于实际承担者，再由这一判定推出由谁出面处置、由谁参加后续安排。","p":["蒋介石在挑动内战","第十八集团军总司令给蒋介石的两个电报"]}]},{"t":"以自身可支配的条件为方针立足点","d":"外部条件不受自己控制，随时可能改变或撤回，凡以其为前提的方针都随之动摇。应把行动成立的条件收在自己能够支配的范围内，外部因素只作可变量处理，外部的许诺与威胁都不作为改变方针的理由。","sub":[{"t":"把方针的基点放在自己可支配的力量上","d":"确定方针时先分清哪些条件由自己支配、哪些依赖外部，再把方针成立的基点放在前者上。承认存在外部的同情者与朋友，但不把外部帮助当作方针成立的条件。对外部势力保持两条：不相信其许诺的好处，也不因其威胁而改变既定方针。对方若把外部依靠当作方针基本点，这一点本身即构成可判明的弱点。","p":["抗日战争胜利后的时局和我们的方针"]},{"t":"困难地区不依靠谈判而依靠自身力量与人民","d":"力量较困难时先判明困难非无办法，只要军事政策与团结人民的政策不犯大错误、谦虚谨慎即能立足；除上级必要指示外，必须独立分析环境、解决问题、冲破困难。绝对不依靠谈判、不指望对方发善心，把生存发展的依靠放在自己手里的力量、行动指导的正确、组织内部团结和对人民良好关系上。","p":["中共中央关于同国民党进行和平谈判的通知"]}]},{"t":"以根本原则划定让步的边界","d":"与对手谈判协商中的让步既有必要也有界限。让步的必要性由争取主动与团结的需要决定；让步的边界由更根本的原则划定，在此原则之内可以让，越出原则不让。妥协不是无原则的退让，而是以根本原则为尺度的有边界妥协。","sub":[{"t":"以不伤害人民根本利益为限度的必要让步","d":"在谈判中预判对方必然提出的要求（缩小解放区、缩减军队等），承认无让步不能击破对方阴谋、取得主动与同情、换得合法地位，故准备必要让步；但让步以不伤害人民根本利益为边界，凡在此原则之内者可让，越出此原则者不让，让与不让都以根本原则为裁量标准。","p":["中共中央关于同国民党进行和平谈判的通知","关于重庆谈判"]}]},{"t":"把已形成的判断转化为组织的共同准备","d":"判断只存在于少数人头上时，并不改变组织应对突变的能力。危险判断必须在事发之前被反复传达，成为全体的共同预期；准备还应覆盖不同强度的局面，而不是只针对其中一种。","sub":[{"t":"把已判明的危险转化为全体的预先准备","d":"领导层判明危险后不停在判断本身，而在危险尚未发生时反复讲明，使执行者、组织成员和群众事先进入准备状态。准备内容包括对最坏情况的接受和对次坏情况的估计：最严重局面哪一天出现都要能应付，同时承认局面也可能被限制在较小范围。以往因无准备而丧失已得成果的经历，是衡量此项工作是否做够的对照。","p":["抗日战争胜利后的时局和我们的方针"]}]},{"t":"不利状态不会自行消退，须有力量实际到达","d":"任何不利状态都由某种条件维持着，不会因时间推移或旁处声势而自行消失。要改变它，必须把力量实际送到它所在的地方去作用于它。声望和影响是力量到达后的结果，不能替代到达本身。","sub":[{"t":"以力量的实际到达清除落后状态","d":"承认错误思想不会自动去掉、反动的东西不打就不倒。先判明它实际存在于何处，再把自己的力量派到那个地方，用切实的宣传教育、组织工作和实际行动逐处清除。仅靠远处的声望和政治影响不能起作用，影响要在力量到达之后才充分发生效力；范围大时按处逐一进行，不等待外部条件自行改变局面。","p":["抗日战争胜利后的时局和我们的方针"]}]},{"t":"把错误认识追溯到其产生条件","d":"孤立地纠正一个错误看法作用有限，因为产生它的条件仍在继续起作用。应把认识偏差看作某种来源的产物，先与事实对照确认其错误，再查明它由什么立场和什么渠道输入，清除工作因此针对来源而非仅针对个别结论。","sub":[{"t":"追溯错误认识的来源并作经常性清除","d":"发现队伍内部流行某种看法时，先把它与可核对的事实对照；不符则不停在指出错误，而进一步追问这种看法从何而来，指认其产生的立场基础和具体传播渠道。确认来源后，把这类认识列为需要经常清除的对象，而不是一次纠正即算了结，因为来源持续存在，认识就会反复产生。","p":["抗日战争胜利后的时局和我们的方针"]}]},{"t":"以主张实现后的必然结果判定其真实内容","d":"一项主张的真实内容不在它的自我表述里，而在它被完全贯彻后必然形成的状态中。判断时应沿其自身逻辑推到底，看它要求什么、导致什么，再与提出者公开自任的立场对照；二者相反时公开立场不成立，那个必然结果即其实际内容。","sub":[{"t":"用主张贯彻后的必然结果检验其真实立场","d":"面对无法直接核对意图的主张或指令，不在字面用语上争辩，而把它按自身逻辑推行到底：先问完全照它执行会要求什么行为，再问会产生什么必然结果，然后把结果与提出者公开自任的立场对照。结果与公开立场相反时，公开立场不成立，该结果即其实际目的。推演只用对方主张已含的内容，不添加外部假设。","p":["蒋介石在挑动内战"]}]},{"t":"以双方共同承认的准则为判定尺度","d":"争议双方互指对方无理时，任何一方的自我评价都不能作为判定依据，各自另立的标准也无法互相说服。可靠办法是找出双方都已承认的准则，把各自的实际行为与准则条款逐一对照。尺度的效力来自对方同样承认，因此结论不随立场不同而失效。","sub":[{"t":"以双方共同签字的准则对照判定是非","d":"双方互指对方非法时，不采信任何一方对自身的评价，也不援引己方单方面的标准。先找出双方都已正式承认、对方本人签署过的准则文本，取出与争点直接相关的条款，再把双方各自下达的指令和实际行动逐一对照，由符合与违反的对比得出判定。尺度既是对方自己承认的，结论对方无从否认。","p":["蒋介石在挑动内战"]}]},{"t":"以事由陈述与利害权衡为依据作出判断","d":"判断与处置宜先立于对事由和现状的陈述，再作利害权衡，最后形成结论。事实在前、利害居中、处置在末，结论因此可被核证，而非凭空断言。","sub":[{"t":"先述事由再陈利害以定处置","d":"对一项指令或主张作出取舍前，先陈述相关事由与现状，再对照利益权衡利害，最后形成判断与处置。事实陈述在先、利害判断随后、处置决定在末，结论因立于可核验的事由与利害而获得依据，而非凭空断言。","p":["第十八集团军总司令给蒋介石的两个电报"]}]},{"t":"把复合要求拆分为可逐项核验的条目","d":"复杂的要求或安排宜分解为边界清楚的独立条目，使每项都可被单独回应与核验。条目化是主张得以落实、责任得以明确的前提。","sub":[{"t":"分条列明要求以便逐项核验","d":"把复合的整体要求拆分为若干独立条目，逐条列明，每条附以内容、依据与边界，使对方可以逐项回应、执行方可以逐项检验。整体笼统的表述被拆解为彼此清楚的单项，便于落实与核验。","p":["第十八集团军总司令给蒋介石的两个电报"]}]},{"t":"以多方独立权威声明印证单方判断","d":"单方的事实判断宜借助独立于争端的权威来源印证。来源越独立、越成系统，判断越可靠，也越能免于被指为一面之词。","sub":[{"t":"援引多方独立权威声明佐证事实判断","d":"证明一项易受质疑的事实判断时，援引多个独立于争端的权威声明作佐证，用多方一致印证己方判断，再据此反推对方主张的错误。佐证来源越独立、越多，判断越难被否认。","p":["第十八集团军总司令给蒋介石的两个电报"]}]},{"t":"以事实对照检验主张与称谓","d":"对对方的命题、分类或新称谓，不按字面接受，而以可核验的事实与历史记录逐一对照，由对照结果判定称谓适用于谁、断言是否成立。检验材料优先取已被公认或难以否认的事实，结论不随表述而定。","sub":[{"t":"以事实对照检验对方的称谓与断言","d":"对方提出新的称谓或断言时，不按字面接受其自指用法，而取出相关各方的实际行为与历史事实逐一对照：该词的标准是什么、谁的行为符合这一标准，断言的前提与事实是否一致。由对照结果决定称谓适用于谁、断言是否成立。","p":["评蒋介石发言人谈话"]}]},{"t":"以排除竞争解释与反事实检验确认因果","d":"因果判断的可靠性来自排除法与反证法并用：既排除被事实否定的竞争解释，又追问\"若无此因结果是否仍会出现\"，以此检验归因。仅凭单一正例不足以确认因果，须同时说明为何其他解释不成立。","sub":[{"t":"以排他对照与反事实追问检验因果解释","d":"对存在竞争解释的因果问题，逐项排除被否定的竞争性原因（不是因对方强大、不是因和平呼吁、不是因让步服从），再用反诘追问检验：若无此真正原因，结果是否还会出现。排除与反证并用后锁定成因。","p":["评蒋介石发言人谈话"]}]},{"t":"以历史行为序列定位当前事件的性质","d":"单个事件的意义不由其自身单独决定，而取决于它在主体既往行为序列中的位置。判断当前行动时先看与此前行动的连续性，区分有计划延续与孤立偶然，防止把有计划的部分误读为突发事件，也防止把偶然当作计划。","sub":[{"t":"追溯既往行为序列以判定当前事件的性质","d":"判定当前事件性质时，不孤立看待，而把它与此前一段完整时期的行为序列并列，看是否指向同一目标；行为一贯指向同一方向时，判定为有计划延续而非孤立偶然，据此定性并决定应对。","p":["评蒋介石发言人谈话"]}]},{"t":"以对方原初表述为争论对象展开回应","d":"展开争论或回应之前，先固定对方公开发出的原初表述，以其实际说出的话为对象复述并逐层揭示其含义与后果，再作回应。不针对转述、推断或扩写的版本，使双方所指一致，反驳不致落空。","sub":[{"t":"先复述对方原话再逐层揭示其含义并回应","d":"面对对方刚发表的命令性话语，先完整复述其原话，再逐层揭示每句的实际含义与所指——对己方意味着什么、对整个形势意味着什么，最后就这一已固定的立场展开回应。争论对象锁定在对方自己说出的原话上，不针对推断或扩写的版本。","p":["评蒋介石发言人谈话"]}]},{"t":"对多种可能结局分别预作对策","d":"当前景存在多种可能时，不因偏爱一种可能而放弃其他准备。对每种可能出现的结果分别研究其条件并备好相应对策，使己方在任何一种局面下都有确定的行动方针；准备某一可能，不等于放松对另一可能的应对。","sub":[{"t":"对谈判结果的两种可能分别预作对策","d":"对谈判这种前景未定的局面，把可能出现的结果分别估计出来——和平合作与内战破裂两种都考虑；对每种可能分别研究其出现条件并备好对应行动方案（和平局面则学会合法斗争、加紧国统区三大工作；内战局面则自卫战争消灭来犯者）。不为一种可能放松另一可能的准备，绝不放警惕。","p":["中共中央关于同国民党进行和平谈判的通知"]}]},{"t":"以斗争求团结的策略原则","d":"对必须联合又存在利益冲突的对象，团结不靠单方面退让取得，而以斗争为手段达到团结目的。斗争要有理有利有节，利用对方内部矛盾，争取多数、反对少数、各个击破，在斗争中巩固联合并壮大自己，不因对方声势而畏惧退缩。","sub":[{"t":"又团结又斗争、有理有利有节的斗争原则","d":"对必须联合又存在冲突的对象，坚持又团结又斗争，以斗争之手段达团结之目的；斗争讲求有理有利有节，利用对方内部矛盾，争取多数、反对少数、各个击破。开展武装自卫时不轻易打、打则必胜，绝不被对方其势汹汹吓倒，也不因谈判而放松斗争。","p":["中共中央关于同国民党进行和平谈判的通知"]}]},{"t":"从多方面综合因素认识复杂事物","d":"复杂事情的结果由多方面因素共同决定，判断时不以单一因素或单方面事实定论，而把主观愿望、客观制约、己方条件与第三方力量一并纳入，容纳相互矛盾的方面，形成兼顾两种可能的综合判断。","sub":[{"t":"从各方面综合判断复杂形势","d":"面对关于前景的单方面悲观判断，不据此定论，先列出影响事情的多方面因素——对方的主观愿望、客观制约力量、己方实力、第三方态度；再综合两方面作出判断：既要准备谈判破裂、坚持斗争，又承认对方存在客观顾忌、谈判仍有空间。综合判断使行动同时覆盖两种可能。","p":["关于重庆谈判"]}]},{"t":"按形势选择斗争形式","d":"斗争的原则不变，但实现原则的具体形式不固定，由形势决定。同一原则可以通过不同甚至相反的形式表现出来，形式的选择以争取主动、达成目的为标准，不把一种形式固定化为唯一做法。","sub":[{"t":"针锋相对要看形势","d":"坚持针锋相对时，不把谈或不谈固定为唯一做法，而按形势选择：形势有利则去谈，以击破对方谣言、争取道义主动与群众同情；对方进攻则以自卫战争粉碎之。谈与打都是针锋相对，形式服从形势，目的都是争取和平。","p":["关于重庆谈判"]}]},{"t":"承认困难与曲折道路","d":"客观困难不以主观愿望为转移，只有先如实承认其存在与数量，才能有效对待。不回避、不否认困难事实，承认之后分析并与之斗争，同时为曲折的过程作好准备，不贪便宜、不存侥幸。","sub":[{"t":"以承认困难为前提主动承担困难并作斗争","d":"面对困难不采取\"不承认主义\"，有多少困难承认多少，进而分析困难、向困难作斗争，准备走曲折的路；对待工作任务，认识工作就是为解决困难而斗争，主动选择困难任务，把重担留给自己、享受让给别人。","p":["关于重庆谈判"]}]},{"t":"以同群众的结合作为开展工作的根本方法","d":"在新环境开展工作，以同当地群众的结合为根本依托。先与群众建立联系、关心并帮助解决其困难，再依靠群众力量推动工作、发展壮大；脱离群众则工作无从着落。","sub":[{"t":"同群众结合、在群众中生根开花","d":"干部到新地区，先做好精神准备，把自己看作种子、人民看作土地；到当地后同群众结合，关心群众、帮助解决困难，在人民中间生根、开花；进而团结广大人民、放手发动群众、壮大人民力量，工作才有着落。 # 待理论层归并的 L1","p":["关于重庆谈判"]},{"t":"援引共同承认的文本佐证己方主张","d":"己方主张被对方拒绝时，援引对方不便否认的、多方共同承认的文件，说明己方主张正是这一主张、实现它即可达成共同目标，再点出真正条件。本文以苏美英克里米亚公报佐证\"联合政府\"主张。暂未确定合适的上位 L2。 # Method Dedup Index（07-12 批次） **批次：** 07-12（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 07、国民党进攻的真相；08、减租和生产是保卫解放区的两件大事；09、一九四六年解放区工作的方针；10、建立巩…","p":["评蒋介石发言人谈话"]}]},{"t":"以长期持续筹划支撑持久任务","d":"在需要长期维持的斗争中，从持续支持而非一时得失出发配置人力物力，以节约、生产自给与长远安排使有限力量能够支撑到任务完成。","sub":[{"t":"以长期打算爱惜物力争取胜利","d":"面对持久斗争，坚决同人民一道关心经济困难，以减租生产为人民解难赢得真心拥护；同时从长期支持着想，爱惜人力物力，事事作长期打算，使有限力量在持续配置中支撑最终胜利。","p":["减租和生产是保卫解放区的两件大事"]},{"t":"作持久打算、力戒侥幸","d":"面对时局曲折与新区域不巩固、财政困难等现实困难，不论时局发展如何都在一切工作布置中作持久打算：正视困难、十分注意人力物力的节省使用、力戒侥幸成功的心理；一面坚持自卫立场巩固已得果实，一面扩大统一战线，以持续安排支撑全局。","p":["一九四六年解放区工作的方针"]},{"t":"部队机关生产自给以减轻人民负担","d":"面对大量脱离生产人员专靠人民供给不能持久的危险，除负有重大作战任务的野战兵团外，一切部队和机关在战斗和工作之暇从事生产，一九四六年立即计划、不可空过，以自身生产减轻人民负担，支撑长期坚持。","p":["建立巩固的东北根据地"]},{"t":"以持久打算和生产自给保障战争供给","d":"面对自卫战争的长期物质需要，作持久打算：十分节省地使用人力物力、力戒浪费、检查纠正贪污；努力生产使必需物资（首先是粮食和布匹）完全自给；财政供给上既满足战争需要又使人民负担减轻，一切依靠自力更生、军民兼顾，立于不败之地。","p":["以自卫战争粉碎蒋介石的进攻"]}]},{"t":"依靠群众自觉斗争推动社会变革","d":"完成利益调整与变革时，可靠方式是发动对象群体的自觉行动，而非自上而下的恩赐；过程中出现的偏差，仍可借群众自身的自觉斗争加以校正，从而让变革建立在稳固的群众基础之上。","sub":[{"t":"以群众斗争实现减租而非政府恩赐","d":"面对利益调整类任务，不把成果当作自上而下恩赐，而发动群众自觉斗争使其成为结果；过火可在真正群众自觉斗争后改正，再说服群众让地主活下去；方针保持减租不没收土地，并帮助农民组织农会。","p":["减租和生产是保卫解放区的两件大事"]},{"t":"有领导的群众运动发动并组织群众","d":"面对新区群众尚未翻身、不能区别国共优劣的问题，发动大规模的、群众性而有领导的减租减息运动（工人酌量增加工资），使群众获得实际利益、翻过身来并组织起来，成为自觉的主人翁；老解放区则复查巩固；把减租与生产视为决定全局胜负的根本任务。","p":["一九四六年解放区工作的方针"]},{"t":"以群众工作为工作重心、给群众看得见的物质利益","d":"在敌强我弱、群众尚未发动的局面下，把工作重心放在群众工作上：从发动群众斗争、替群众解决问题、一切依靠群众出发，通过清算汉奸、减租增资、生产运动给群众看得见的物质利益，并组织群众团体、建立党的核心与群众武装政权，把经济斗争提高到政治斗争，使群众拥护己方、反对敌人进攻。","p":["建立巩固的东北根据地"]}]},{"t":"从客观实际出发认识问题","d":"认识形势与确定行动方向时，不以主观愿望、急躁情绪或侥幸心理为据，而以调查研究获得的客观实际（力量对比、地理民情、占领格局）为依据，据以校正主观估计并选择能够立足巩固的行动空间。","sub":[{"t":"以力量对比校正对敌我形势的估计","d":"面对对形势的悲观估计，不以恐惧或对敌人表面声势的过高估计为据，而比较双方力量与实际条件的对比和发展趋势（人心向背、士气、经济等），确认人民民主力量超过反动力量并正向前发展，据此判断战争危险虽存在但必能克服，校正过高估计敌人、过低估计人民的偏差，树立必胜信心。","p":["关于目前国际形势的几点估计","以自卫战争粉碎蒋介石的进攻"]},{"t":"依据敌我占领格局选址远离敌人控制中心的地区","d":"面对敌人已占或将占大城市和交通干线、不容许我们在其近旁立足的局面，依据客观的敌我力量分布，把巩固根据地确定在距敌人占领中心较远的城市和广大乡村，近敌地区只作游击区和第一道防线，据此部署力量、引导全党向此目标前进。","p":["建立巩固的东北根据地"]},{"t":"以调查研究校正干部对敌我形势的主观估计","d":"面对外来干部地理民情不熟、对艰苦工作不耐心等主观困难，反复教育干部注重调查研究、熟悉地理民情、和人民打成一片，并双面校正对敌估计——对敌人既不可估计太低、也不可觉得大得了不得，扫除依靠意外便利、侥幸取胜的心理。","p":["建立巩固的东北根据地"]}]},{"t":"以对方自有的不可抵赖材料反证其主张","d":"反驳一个虚假的公开主张时，可靠依据是主张者自身无法否认的材料——由其自己人提供的证言，或其自己颁发、缴获自其手的命令与文件，而非仅以另一套说法相对抗。证明力来自材料来源正是主张者自身这一事实。","sub":[{"t":"以敌方自有人证物证反证其公开谎言","d":"面对对手公开宣称与事实相反的说法，不从正面争辩，而收集对手自身无法否认的材料：被俘官兵可证明自己从何处奉命进攻，缴获的对手自己颁发的命令与文件是其行动铁证；再把这些材料对应到对方的每一条谎言逐条反证，并在多战区重复以显出系统模式而非孤例。","p":["国民党进攻的真相"]}]},{"t":"识破延时性提议并以必要前提反制","d":"面对以中立面目出现、实则延宕真实矛盾的提议，不停留在接受或拒绝，而指认其延时功能，并将真正必要的前提条件置于其之前；原提议因前提未立而无法成立，反而成为证明真实意图的材料。","sub":[{"t":"识破缓兵之计并以条件前置反制","d":"当对手提出一项看似中立、合理的程序性措施，而其真实作用是争取时间、掩护实质行动时，先判定其为缓兵之计；不按对方设定的顺序接受，而提出必须先行解决的根本条件，使该措施只有在真实问题解决后才可执行，从而把提议本身转为暴露其真实意图的。","p":["国民党进攻的真相"]}]},{"t":"通过组织协作放大个体生产能力","d":"将分散的个体生产者以互助组织联合起来，并配给必要资金保障与时机安排，使个体能力在协作与统筹中被放大，从而完成单靠分散个体难以达成的整体生产目标。","sub":[{"t":"以组织化生产互助推进生产运动","d":"面对分散生产者的增产任务，关键在把大多数生产者组织进生产互助团体；政府发放农贷工贷提供资金，不违农时减少误工，研究调节战争动员与农时，部队机关学校亦适当参加以减轻负担。","p":["减租和生产是保卫解放区的两件大事"]}]},{"t":"以分工明责保障核心任务落实","d":"在多重任务并存时，按任务性质划分责任边界，使各着力点专注于各自关键职能，从而保证虽处复杂局势、核心任务仍被优先且持续地落实。","sub":[{"t":"前后方分工保障两件大事落实","d":"面对战争与建设并重的复杂局势，明确分工：前方领导专注指挥作战不分心，后方领导除直接援前线外须不失时机布置减租与生产，尤其新解放区冬春发动减租、年内推动生产新发展，不因战争疏忽根本大事。","p":["减租和生产是保卫解放区的两件大事"]}]},{"t":"借助外部专业力量补齐能力短板","d":"进入陌生或专业领域时，不回避既有社会专业力量，而主动与之合作并向其学习技术与管理，以外部专业能力补己方不足，实现对新领域的有效掌握。","sub":[{"t":"利用社会人才掌握城市经济","d":"面对新接管的城市经济，将发展工商金融列为重要任务，利用一切可用的社会现成人材，说服党员与之合作并向其学习技术与管理方法，以补齐我党在城市经济领域的能力短板。","p":["减租和生产是保卫解放区的两件大事"]}]},{"t":"内外配合从内部瓦解对方阵营","d":"面对实力或团结程度高于己方的对手，不从单一正面对抗，而在外部施压的同时从对方内部进行转化——以宣传瓦解其成员意志，并策动其内部力量转向己方，使对手自身发生分化，从而削弱其整体对抗能力。","sub":[{"t":"分化瓦解敌军：政治攻势与组织起义相配合","d":"对准备进攻的敌军，在自卫立场上两手并用：由我军进行公开的广大的政治宣传和政治攻势瓦解其战斗意志，同时从敌军内部准备和组织起义，使大量敌军在战争紧急关头站到己方来；并设置专门部门、调派大批干部专做，领导机关密切指导。","p":["一九四六年解放区工作的方针"]}]},{"t":"以互教互学普及群众技能","d":"提升群体整体技能时，不依赖少数专门人员单向传授，而让群体成员互为师生、互相教学，使掌握者在教学他人中得到检验和传播，能力在群众内部普及提高。","sub":[{"t":"群众性互教互学练兵","d":"军队已组成、扩兵应停止时，利用作战间隙练兵；开展官教兵、兵教官、兵教兵的群众练兵运动，让官兵互为师生；内容上以提高射击、刺杀、投弹等技术程度为主、战术为辅，特别着重练习夜战；并改进政治工作、克服教条主义和形式主义作风。","p":["一九四六年解放区工作的方针"]}]},{"t":"统筹兼顾多方要求的资源配置","d":"面对有限资源与多方并存的正当需求，不作偏废，而在对立侧面（军民、公私、集中与分散、生产与节约）之间统筹兼顾，同时量入为出、避免过重负担，使有限资源能够支撑长久坚持。","sub":[{"t":"财经工作统筹兼顾原则","d":"因紧张工作增重的财政负担须有计划有步骤转到正常状态：人民负担过重者酌量减轻，脱离生产人员不超过当地财力负担所许可的限度；坚持兵贵精不贵多；以发展生产保障供给、集中领导分散经营、军民兼顾公私兼顾、生产和节约并重为方针，以利持久。","p":["一九四六年解放区工作的方针"]}]},{"t":"培养依靠本地力量使组织扎根","d":"组织力量进入新地区时，外来骨干不以优越自居，而主动识别、培养、提拔本地成员，以本地力量充实组织，使组织在当地生根；轻视本地人的作风被视为妨碍扎根的障碍而受批评。","sub":[{"t":"爱护本地干部使党扎根","d":"在解放区有大批外来干部做各级领导工作的情况下，谆谆告诫外来干部以充分的热情和善意爱护本地干部，把识别、培养和提拔本地干部当作重要任务；批评外来人轻视本地人的作风，使我党在解放区生根。","p":["一九四六年解放区工作的方针"]}]},{"t":"组织力量下沉基层与群众结合","d":"组织力量（军队等）要发挥作用并真正扎根，须划分到确定的地区并承担具体任务，使力量下沉基层、与人民群众直接结合，在发动群众、建立政权与组织武装中巩固自身；脱离地区任务的上层集中无法与人民结合。","sub":[{"t":"以确定地区和任务使军队与人民结合","d":"为稳固地方、配合野战军粉碎敌人进攻，迅速划分军区和军分区，把军队分为野战军与地方军，将正规军相当部分分散到各军分区从事发动群众、消灭土匪、建立政权、组织游击队民兵自卫军；一切军队均有确定的地区和任务，才能迅速和人民结合。","p":["建立巩固的东北根据地"]}]},{"t":"把是非二选一改写为程度与时机判断","d":"面对被呈现为非此即彼的问题，先判断其是否真正是\"是否\"的择一问题；当问题实为程度、时机或幅度的差异时，将其改写为程度与时机的判断，并明确其中关键词语的确切含义，避免在虚假二元框架内作答。","sub":[{"t":"把国际关系的是非二选一改写为迟早判断","d":"面对\"或者妥协或者破裂\"的是非式提问，不在此二选一中择一作答，而识别问题实质是\"或早或迟妥协\"的程度与时机判断，并界定妥协指和平协商、迟早指几年十几年或更长时间，从而否定虚假的择一框架。","p":["关于目前国际形势的几点估计"]}]},{"t":"为一般判断划定适用范围与限度","d":"一般性判断成立后，须进一步界定其适用的对象范围、时间限度与层面界限，防止有限结论被无限推广或跨层面机械传导，使判断只在自身有效的边界内指导认识与行动。","sub":[{"t":"为一般判断划定适用对象、近期限度与层面界限","d":"对一个已成立的判断，进一步界定其适用的对象范围（若干问题而非一切问题）与近期限度（目前短时期内不会很多），并明确其不跨层面机械传导——国际妥协不要求各国人民随之国内妥协，各国人民仍按不同情况进行不同斗争。","p":["关于目前国际形势的几点估计"]}]},{"t":"以对象的实际行动原则为参照采取对等原则","d":"确定己方对敌的行动原则时，不以良好愿望或抽象道义为据，而以对方实际奉行的行动原则为参照，采取与之对等的应对原则，使对策建立在对对象真实行为方式的把握之上。","sub":[{"t":"参照对方行动原则确定对等斗争原则","d":"确定对敌斗争原则时，先观察对方实际奉行的原则——\"能够消灭者一定消灭之，暂时不能消灭者准备将来消灭之\"，针对这种情况对敌采取同样的对等原则，使己方原则与对方原则相对应。","p":["关于目前国际形势的几点估计"]}]},{"t":"以最终目标为尺度取舍局部得失","d":"面对必须付出局部代价才能达到整体目标的任务，不以一时一地的得失评价当前取舍，而以最终目标为尺度，主动接受必要的局部退让与牺牲，并使参与者理解其意义、提前作好心理准备。","sub":[{"t":"以暂时放弃局部城市换取最终胜利","d":"面对敌强我弱、需持久作战的形势，采用运动战为主的作战方法；若干地方和城市的暂时放弃不可避免且必要，是为保存有生力量、取得最后胜利；并将此取舍提前向全党全民说明，使其有精神准备。","p":["以自卫战争粉碎蒋介石的进攻"]}]},{"t":"按对象性质区别对待以扩大团结面","d":"面对由不同性质成员构成的对象群体，不作整体化处理，而依据成员的性质与立场区别对待——对可争取者放宽、对顽固敌对者从严，借以扩大联合面、缩小敌对面，使多数团结、少数孤立。","sub":[{"t":"区分对象宽严有别以团结多数孤立少数","d":"为粉碎进攻，必须与人民群众亲密合作、争取一切可能争取的人；对敌人阵营内部不同成分加以区别——对富农中小地主放宽、对汉奸豪绅恶霸从严；在城市团结中间分子、在敌军中争取反内战者，孤立反动派与好战分子，借以减少敌对分子、巩固解放区。 # 待理论层归并的 L1","p":["以自卫战争粉碎蒋介石的进攻"]},{"t":"争取工人和知识分子参加根据地建设","d":"鉴于工人和知识分子的动向对建立根据地和争取将来胜利关系极大，应充分注意大城市和交通干线的工作，特别是争取工人和知识分子；除国民党占领区的地下工作外，还应尽可能吸引工人和知识分子参加军队和根据地的各项建设工作。 # Method Dedup Index（13-18 批次） **批次：** 13-18（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 13、和美国记者安娜·路易斯·斯特朗的谈话；14、集中优势兵力，各个歼灭敌人；15、美国“调解”真相和…","p":["建立巩固的东北根据地"]}]},{"t":"以本质和长时段判断力量对比，而不以当前表象","d":"一个对象在某一时刻显示的力量，不等于决定结局的力量。前者可以在短期内很盛，后者要在长时段中才显出来。判断强弱应看哪一方的力量是长期起作用的，并可用同类对象已知的结局作对照。这样得出的判断只适用于长远和全局，不取消当前的实际损害。","sub":[{"t":"区分表象力量与决定胜负的力量","d":"先把对象引人注目的表面力量与最终决定结局的力量分开：新式武器、控制范围、声势属于前者，长期起作用的多数人的力量属于后者。再取历史上同类对象，核对其表面力量是否决定过最后结局。结论只用于长远和全局判断，同时如实承认表面力量在当前造成的实际损害。","p":["和美国记者安娜·路易斯·斯特朗的谈话"]},{"t":"在不利的当前局面下以长期起作用的民众力量判断最终结局","d":"判断冲突会延续多久、结局如何，先分清哪些现实条件可使之结束（外部停止援助、撤军、遵守共同协议），条件具备则早结、不具备则可能长期化；对最终结局不按当前压迫力量的表象判断，而按长期起作用的民众团结力量判断——人民的独立和平民主任务一定要实现，任何内外压迫力量不能阻止；同时如实承认当前会受痛苦，此判断只用于长远和全局。","p":["美国“调解”真相和中国内战前途"]},{"t":"在确认胜利前途的同时逐项估计困难并作有计划克服的准备","d":"既确认取得最后胜利的把握，又不回避困难，把困难逐项具体列出（斗争长期性、敌人全力反对、部分力量暂时损失、人力物力消耗），准备用百折不回的毅力有计划地克服；以双方本质区分克服可能——接近死亡的没有前途的势力其困难不可克服，新兴的有光明前途的势力其困难可以克服。","p":["迎接中国革命的新高潮"]}]},{"t":"从对象的实际处境判断其行动的真实指向","d":"一个对象宣称的目标与它的力量实际落处常常并不一致。要确定其行动的真实指向，须先查明它当前直接面对哪些矛盾、力量正在作用于谁，再据此判断其言辞在现时起什么作用。承认宣称的方向可能确有准备，并不妨碍指出它现时的主要作用在别处。","sub":[{"t":"把对外敌对口号还原为宣传者当前的实际矛盾","d":"不按口号字面所指的对象理解，也不简单斥之为虚假。先分两面：一面承认它确在为所宣称的方向作准备；一面列出宣传者当前直接面对的实际矛盾，看口号在现时对这些矛盾起什么作用。再由它同时正在做的事确定口号的现时实际意义，并以历史上同类托辞作对照。","p":["和美国记者安娜·路易斯·斯特朗的谈话"]},{"t":"按中间地带的实际状态判断进攻方向与直接受害者","d":"先看一方与其宣称的远处目标之间实际隔着哪些中间对象，再看它是否已压服这些对象；未压服之前，对远处目标的进攻谈不到。据此确定其力量现时的实际落点：布置虽指向远处，首先受侵害的是布置所在之地，这些直接受害者可能由被控制者转为反对者。","p":["和美国记者安娜·路易斯·斯特朗的谈话"]},{"t":"以政策实际后果检验其宣称的掩护性质","d":"不按政策自称的目标认定其性质；先核对该政策在实际中造成的后果——增强了谁、压向谁、使谁得以发动战争与压迫——再看宣称与实际作用是否矛盾；矛盾时判定宣称只是掩护，真实作用在别处，并预告其继续实行必激起受害者的坚决反抗。判断以可核实的事实后果为据，不以宣称本身为据。","p":["美国“调解”真相和中国内战前途"]}]},{"t":"依局部力量对比决定集中一点或分击数点，务求形成局部优势","d":"面对由多部分构成或整体较强的对象，不把力量平均铺开；先判明各部分强弱与支援关系，把优势资源压向最易突破的一环以形成局部绝对优势，解决一处再及其余。当己方在某处已具优势时，亦可同时压向数点。","sub":[{"t":"战役部署上集中绝对优势兵力先歼一路较弱之敌","d":"当敌军以多个旅分几路向我军前进时，先在其诸旅中识别较弱、少援或地形民情对我最有利者，集中六倍、五倍、四倍或至少三倍于敌的兵力于适当时机包围歼击该旅，同时以少数兵力牵制其余各旅使其不能迅速增援；得手后依情况续歼敌一至数旅或收兵休整。反对平分兵力对付诸路以致一路也不能歼灭的被动打法。","p":["集中优势兵力，各个歼灭敌人","三个月总结"]},{"t":"战术部署上集中兵力猛攻一点再扩张战果","d":"当已集中绝对优势兵力包围敌军一路时，不企图同时全部歼灭而处处平分兵力；应集中优势兵力并集中全部或大部炮兵，从敌军诸阵地中选择较弱的一点（不是两点）猛烈攻击、务期必克，得手后迅速扩张战果、各个歼灭该敌。","p":["集中优势兵力，各个歼灭敌人"]},{"t":"按敌我攻防地位与兵力对比选择同时攻若干或逐个夺取","d":"敌处进攻、我处防御时必用集中优势兵力各个歼敌之法；敌处防御、我处进攻时分两种：若我军兵力多、当地敌弱或出敌不意举行袭击，可同时攻击若干部分敌军（如同时攻胶济津浦、陇海线十数城镇）；若兵力不足，则对敌所占诸城一个一个夺取，不同时攻击数点。","p":["集中优势兵力，各个歼灭敌人"]}]},{"t":"以数量构成分解推演力量消长","d":"判断双方力量将向哪一方倾斜，不满足于总量印象，先盘清总量与补充上限，再按职能分解构成，结合自身消减数与对方自身消耗，逐项相抵后推演其趋势；力量消长由构成与消耗的算术关系决定。","sub":[{"t":"从敌方内在矛盾与兵力构成推演其消长","d":"先指出对方内在不可克服的矛盾，再盘清其兵力总量与补充上限、按守备与野战分解构成，对照我方歼敌数与对方自身消耗，逐项相抵后推演其必然趋势，得出\"越打越少\"式的结论。","p":["三个月总结"]},{"t":"以歼敌数量、兵力对比与士气判断战局主动权的转换","d":"先统计已歼灭敌军有生力量的数量、月均歼敌数与占其总兵力的比例，对照敌军兵力不敷分配、补充不足与士气下降等内在矛盾，判断攻守主动权的转移，再据此提出下一阶段可量化的歼敌目标并预估其完成后的形势变化。","p":["迎接中国革命的新高潮"]}]},{"t":"以全局意义评价局部行动","d":"评价或衡量局部行动与局部事件，不只看其自身表现，还把它放回全局图景确定真实分量：局部贡献在于对整体进程的直接援助与长远作用，局部失利亦须由全局判断是否损伤大局；以全局意义给局部以正确评价与定位，防止只从局部自身作判断。","sub":[{"t":"评价配合作战单元的全局价值","d":"先如实记录承担牵制、开辟新根据地等配合作战单元的实际战况，再说明其对全局的直接援助与长远作用，把局部行动放进全局图景给予明确评价，防止总结只覆盖主战场。","p":["三个月总结"]},{"t":"以全局形势衡量局部失利的分量","d":"发生局部失利（如首府被占）时，不孤立看待该事件，而把它放回全局形势衡量：只要不改变全局的力量对比与胜利前途，即判定其为无损大局的局部挫折；据此稳住整体判断，不因局部被占而动摇对整个斗争前途的结论，并以对全局的判断指导向各方的说明与动员。","p":["中共中央关于暂时放弃延安和保卫陕甘宁边区的两个文件"]}]},{"t":"把不受支配的外部条件分解为其内部的对立关系","d":"外部条件看起来不可支配，往往是因为把它当成了一个整体。凡由人构成的一方，内部都存在利害相反的部分，其对外表现取决于这些部分的力量消长。认识的着力点应放在它的内部对立关系上：找出推动不利做法的部分和能够牵制它的部分，条件的可变处就在这里。","sub":[{"t":"把外部条件分解为对方内部的对立力量","d":"不把不受自己支配的外部一方当作单一整体接受其现状。先在其内部分出相互对立的部分，判明真正推动不利做法的是哪一部分、另一部分是否具备牵制它的力量，再看不利做法的推行是否必须以先压制这一部分为前提。由此把\"外部态度如何\"转换为\"该方内部力量对比如何变化\"。","p":["和美国记者安娜·路易斯·斯特朗的谈话"]}]},{"t":"以削弱对手持续能力为优先目标而非以占取表面物为优先","d":"面对资源有限的交锋，把手段优先用于消灭或削弱对手继续行动的能力，而非用于占有象征性或表面的对象；必要时以暂时放弃表面对象换取对能力来源的打击，但关键处仍须保住。","sub":[{"t":"以歼灭敌军有生力量为主而非以保守或夺取地方为主","d":"集中兵力各个歼敌以歼灭敌军有生力量为主要目标，不以保守或夺取地方为主要目标。为集中歼敌或避免主力受严重打击以利休整，可允许放弃某些地方；凡能大量歼灭敌有生力量者（含保安队、还乡队等地方反动武装）均奖励。但凡在力量对比上能保守或夺取、且战役战术上有意义的地方，则必须保守或夺取，否则是错误。","p":["集中优势兵力，各个歼灭敌人"]}]},{"t":"集中主力决战时须以分散力量牵制配合","d":"面对须以主力集中解决主要部分的问题，同时以分散的力量在别处积极活动，牵制、困扰对手其余部分，使主力得以在关键一点形成并保持优势；外围分散与主力集中互为支撑，局部小仗亦沿用集中原则。","sub":[{"t":"主力集中歼敌与地方兵团民兵积极配合","d":"我军主力集中歼敌时，必须同地方兵团、地方游击队和民兵的积极活动互相配合，使主力集中用兵不被敌其余部分干扰；地方兵团在打敌一团一营一连时，同样适用集中兵力、各个歼敌的原则。","p":["集中优势兵力，各个歼灭敌人"]}]},{"t":"以共同承认的协议为尺度裁量合作与反对","d":"判断一个对象是否可与之共事、某一事项是否可接受，依据双方共同承认的协议与决议，而不依据其名义地位或单方面提出的要求；照协议行事则合作，违协议而单方操办则反对。","sub":[{"t":"以共同承认的协议为尺度决定合作或反对","d":"面对对象的地位宣称与单方面要求，不以名义头衔为据，也不以单方面要求为据，而以双方共同承认的协议与决议为尺度：按协议处理问题则愿意共事，违反协议提出片面要求则拒绝；凡按协议应由各方共同办理的事项（如国民大会），单方操办者坚决反对。","p":["美国“调解”真相和中国内战前途"]}]},{"t":"以客观实绩校验既有认识判断","d":"对一个时期前景或方针的判断最终是否成立，不以开始时的信心或论证为据，而以该时期内实际发生的结果为据；阶段结束后应拿实绩对照原判断，成立者确认，不成立者据实调整，使认识建立在可核实的事实之上。","sub":[{"t":"以阶段实绩核验既定判断","d":"面对此前对前景或方针所作的判断，不重开争论，先保留原判断，再汇总本阶段的实际战果与数字逐项对照核验，用结果证明判断成立，为继续执行提供依据。","p":["三个月总结"]}]},{"t":"把总目标拆解为递进阶段并逐级预估后果","d":"面对改变全局的总目标，一次完成不现实时，先确定可量化的下一阶段目标并预估其达成后必有的形势变化，据此再排再下一阶段；把长远目标化为连续可执行的近期步骤，并说明当前一步的关键性。","sub":[{"t":"把改变形势的总目标拆为递进量化阶段并预估后果","d":"先定出下一阶段可量化的具体目标并预估其完成时必有的形势变化，据此再设定再下一阶段的目标与后果，用\"阶段→后果→再阶段\"的链条说明当前一步在改变全局中的关键位置。","p":["三个月总结"]}]},{"t":"按归因分类分别处置损失与挫折","d":"遇到阶段损失，先把损失按原因分类：不可避免者坦然接受并说明恢复条件，可避免者检讨教训、防止重犯；分类后分别给处置办法，并预留给将来同类情形沿用的原则。","sub":[{"t":"按原因分类处置阶段内的损失","d":"先按原因把损失分为不可避免、应当主动放弃者与打得不好被迫放弃者两类，前者坦然接受并说明可恢复，后者检讨吸取教训避免重犯，并为将来同类情形预留处置原则。","p":["三个月总结"]}]},{"t":"以执行差异的后果对照确证方针有效性","d":"确证一项方针是否必要，可以比较同类对象按不同执行程度带来的实际后果——执行坚决者获益、执行不力者受损；用结果差异倒证方针的正确，再把它转为必须照办的要求，使方针从经验判断升为硬性任务。","sub":[{"t":"以执行差异对照确证方针必要性","d":"对同一方针按执行好坏列出对照结果——坚决迅速执行者有何收益，不坚决、迟缓或机械执行者有何损失——用差异明显的实际后果证明该方针成立，再转为今后必须执行的硬性要求。","p":["三个月总结"]}]},{"t":"按必要代价倒推资源保障方案","d":"实现目标须付出的代价是可统计的；先估算完成单位任务所耗成本，再据此推导为支撑持续行动所需补足的资源，逐项安排人力、训练、生产、财政等保障，使目标可行性与资源安排相互衔接。","sub":[{"t":"由必要代价推导资源保障安排","d":"先统计达成单位战果所须付出的代价比例，再据此推导支撑长期作战的资源缺口，逐项安排扩兵、训练干部、发展生产、整理财政等保障措施，按既定原则组织实施。","p":["三个月总结"]}]},{"t":"以多维度形势汇总校正内部预期","d":"当内部对前景产生悲观情绪时，不从口号而是从多个维度汇总客观存在的有利条件与对方的不利处，指出悲观认识的缺口并向持此认识者作解释，同时在承认现实困难的前提下确立对最终结果的坚定判断。","sub":[{"t":"多维度汇总形势校正内部预期","d":"先从国内、国际等多个维度汇总有利条件与对方不利之处，指出认识不足的具体表现并对持此认识者作解释，同时如实承认敌人有力量、斗争长期残酷，把\"必能胜利\"的确信作为全党须巩固建立的认识要求。","p":["三个月总结"]}]},{"t":"以敌我双方多领域力量对比与矛盾的综合判断阶段转折","d":"判断一个历史阶段是否到来或转换，不凭单一方面、一时一事或主观愿望，而是综合敌我双方在政治、军事、经济、国际等各领域的实际力量对比与矛盾展开，得出阶段判断后再据以规定任务。","sub":[{"t":"综合多领域敌我力量对比与矛盾判断革命阶段转折","d":"判断革命是否进入新阶段，不依据单一事实或主观愿望，而是汇集军事（歼敌数量与主动权转换）、蒋管区人民运动、经济危机、政治孤立、国际局势等各领域敌我力量对比与矛盾展开，综合得出新的人民大革命阶段即将到来并可取得胜利的判断，再据以规定全党的任务。","p":["迎接中国革命的新高潮"]}]},{"t":"依靠放手发动群众完成变革并以保护中间力量巩固之","d":"重大社会变革的完成与巩固，靠放手发动群众自下而上推动而非包办代替；变革过程中坚决保护中间力量利益、团结绝大多数、孤立极少数反动分子，变革才彻底且能持久。","sub":[{"t":"放手发动群众完成土地改革并保护中农巩固成果","d":"完成土地改革须放手发动群众实现耕者有其田；对已解决而不彻底的地区认真检查、填平补齐；坚决联合中农、绝对不许侵犯中农利益，如有侵犯必须赔偿道歉，对富农和中小地主适当照顾；以团结百分之九十以上群众、孤立少数封建反动分子完成巩固任务。","p":["迎接中国革命的新高潮"]}]},{"t":"以发展生产与兼顾各方利益解决供给与财政问题","d":"供给与财政问题的根本出路在于发展生产、厉行节约以扩大可支配总量，并兼顾军民公私各方利益、按实际情况使统一领导与分散经营相配合；不从单方面挤取或一律集中。","sub":[{"t":"在生产节约基础上以三原则解决财政供给问题","d":"解决长期战争的财政问题，先作长期打算、努力生产、厉行节约，再在生产与节约基础上处理财政；坚持发展生产保障供给、军民兼顾公私兼顾、统一领导分散经营三原则，并分别反对忽视生产、只顾一方、一切集中等片面观点。","p":["迎接中国革命的新高潮"]}]},{"t":"分清敌我界限以壮大自身、孤立敌人","d":"在斗争中扩大团结面与划清界限是同一过程的两个方面：团结一切可以团结的阶层，同时把混入己方的隐蔽分子暴露出来；界限越清楚，自己的队伍越巩固壮大。","sub":[{"t":"扩大团结面、划清敌我界限并暴露隐蔽分子以壮大队伍","d":"巩固统一战线既扩大团结面，吸收党外进步分子与中间分子参加工作，又明确敌我界限，拒绝敌人制造的孤立手段（如伪国大）；对隐藏在民主阵线中的欺骗分子，让其最终暴露并清除，队伍因分清界限而更加壮大。","p":["迎接中国革命的新高潮"]}]},{"t":"借对手自身的行动暴露其欺骗本质","d":"对手以欺骗为目的的接触与宣称，不简单地拒绝；拒绝反而使欺骗保有市场。利用接触本身，让对手的行动与承诺在实际兑现中自我暴露，从而保持己方主动。","sub":[{"t":"对敌人的和谈骗局采取不拒绝谈判以揭露欺骗的方针","d":"面对敌人为取得休整补充、借款军火、缓和人民愤怒而提出的和谈要求，先识别其争取时间再攻的欺骗性质，再采取不拒绝谈判的方针，借接触本身揭露其欺骗，保持政治主动。","p":["迎接中国革命的新高潮"]}]},{"t":"由行动的自然后果与行动者处境反推其真实状态","d":"判断一方真实状态，不以行动自身的声势为据；声势可以伪装，行动必然引起的后果（自我揭破、失去欺骗作用、不得人心）与行动者当下的战略处境（能力枯竭、危机深刻化）难以掩盖。以自然后果与处境反推真实力量，把示强反读为败象。","sub":[{"t":"由敌方示强行动的后果与处境反推其真实虚弱","d":"面对敌方占据要地、发动攻势等示强行动，不按声势判定其强大：先看该行动必然引起的政治后果（欺骗被揭破、不得人心、自陷绝境）与行动者的战略处境（进攻能力枯竭、危机深刻化），把示强反读为虚弱与败象；据此向各方充分说明，把敌人行动转化为团结己方人民的教材。","p":["中共中央关于暂时放弃延安和保卫陕甘宁边区的两个文件"]}]},{"t":"识破对手的整体图谋并按其环节对应部署己方","d":"对手的进攻常服从一个整体图谋：先处一方、再及其余。识破图谋须看清单个动作在图谋链条中的位置，不因眼前一事定对策；再使己方力量与组织逐项对应其图谋环节，就地坚持使逐出领导机关的图谋落空、分设机构承担须转移的工作，以对应部署挫败其各环节图谋。","sub":[{"t":"识破敌方整体图谋并按图谋环节对应部署己方","d":"面对敌方的一连串行动，先判明其背后的整体图谋（先除一方、割断联系、驱逐领导机关、再攻一方，各个击破），看清单个行动在图谋链条中的位置；再按图谋每一环节安排己方对应部署——就地坚决战斗保卫发展边区、领导机关留驻条件好的地区、分设机动机构承担须转移的工作，使敌之各环节图谋落空。 # Method Dedup Index（19-24 批次） **批次：** 19-24（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 19、关于西北战场的作战方针 · 2…","p":["中共中央关于暂时放弃延安和保卫陕甘宁边区的两个文件"]}]},{"t":"区分表面现象与实质基础判断对象强弱","d":"面对貌似强大的对象，不以其暂时、表面的声势定强弱，而分析其支撑基础是否真实，区分表面现象与实质基础以判断对象真实强弱。","sub":[{"t":"区分表面声势与实质基础识破外强中干","d":"面对貌似强大的对手，不被其暂时表面的声势吓住，而分析其统治基础是否真实牢固；判明其强大只是暂时的、表面的，本质是外强中干，因而其进攻是能够打败的。核心是透过声势看实质基础。","p":["蒋介石政府已处在全民的包围中","目前形势和我们的任务"]}]},{"t":"根据对象差异分级确定处置方式","d":"面对同类对象的多种形态，先按关键属性（强弱、规模）排序分级，再为各级规定差异化的处置原则，使行动既有统一次序又不一刀切。","sub":[{"t":"按打击次序与守备强弱分级统一作战处置","d":"先规定打击次序（先打分散孤立之敌后打集中强大之敌，先取中小城市和广大乡村后取大城市），再以歼灭敌人有生力量为主要目标、每战集中绝对优势兵力力求全歼，并按据点守备强弱分级处置（守备薄弱坚决攻取、中等程度且环境许可相机攻取、守备强固暂弃置），使全军按统一原则行动。","p":["解放战争第二年的战略方针","目前形势和我们的任务"]}]},{"t":"条件不成熟时以持续机动积蓄制胜条件","d":"面对尚不具备决战条件的对象，不强求正面摊牌，而是通过一段时期的持续非决战式行动（反复周旋、消耗）逐步改变力量对比，待决定性条件形成再行动。核心是把“取胜”从一次性事件转为对条件的积累过程。","sub":[{"t":"以\"蘑菇\"战术先耗后歼","d":"面对强敌不宜早决战，先判敌疲劳与补给程度；拒绝急于北上或南下的决战冲动，在现地区与敌持续周旋约一月，以反复机动加深敌疲惫与缺粮；待敌十分疲劳、完全断粮时再寻机歼击。核心是“先耗后歼”，把胜利建立在条件成熟之上。","p":["关于西北战场的作战方针"]}]},{"t":"以主动机动塑造敌势并破坏其支撑","d":"在对抗中不以静态布防应对，而是依对方动向主动调整自身位置，牵引对方进入不利态势并割裂其资源供给，使对方在运动中暴露弱点。核心是借机动改变相对位置与支撑结构来创造优势。","sub":[{"t":"依敌之调动方向机动牵引并断其补给","d":"根据敌之推进与回折方向，灵活部署己方部队：先引敌向北，再攻其薄弱部分并引敌向东，复折向安塞引敌向西；同时准备一部兵力南袭，切断敌粮运线。通过主动机动塑造敌之运动路线与暴露面，并破坏其后勤支撑，为歼击创造位置与条件。","p":["关于西北战场的作战方针"]}]},{"t":"从客观力量对比而非主观愿望认识对抗形势","d":"面对对抗双方强弱的判断，不以主观愿望或固有样式设想代替实际，而是比较双方真实力量并以事变检验，从客观力量对比而非主观设想认识形势。","sub":[{"t":"以客观力量对比判明敌我强弱","d":"面对敌我强弱的估量，不以主观愿望或\"事物样式不可改变\"的假定代替实际，而是比较双方真实力量：既看对方一时军事占领与表面声势，更看人民真实力量，并以是否经得起事变检验为判断准绳。","p":["蒋介石政府已处在全民的包围中"]}]},{"t":"从对象自身行动的反面效应认识其走向","d":"面对一个反动或错误对象的走向，不只在外部找其失败原因，而是分析其自身行动与政策如何制造反对自身的力量，使矛盾向其反面转化。","sub":[{"t":"从反动政策的自我反噬看清其必然孤立","d":"面对反动统治为何走向失败，不去外部找原因，而是分析其自身政策（卖国内战独裁、经济掠夺）如何把各阶层推到饥饿死亡线上，迫其团结自救，从而自己制造了反对自己的全民族统一战线。核心是敌人自己的政策产生其反面。","p":["蒋介石政府已处在全民的包围中"]}]},{"t":"从局部斗争的扩展联系认识整体运动","d":"面对分散的斗争，不只看单一战线，而看到多战线并存与局部高涨对整体的必然推动，从局部斗争的扩展联系认识整体运动。","sub":[{"t":"以第二条战线认识人民斗争的连锁扩展","d":"面对人民斗争形势，不只看军事第一战线，还要看到学生运动等政治第二条战线的出现；认识到局部斗争（学生运动）是整个人民运动的一部分，其高涨必然促进整体人民运动的高涨，从而把握多战线并存下的扩展联系。","p":["蒋介石政府已处在全民的包围中"]}]},{"t":"以对象自我暴露和实际发展检验认识","d":"面对判断是否正确，不固守成见，而以事变走向与对象自身表演是否印证来检验，让实际发展与对象自我暴露修正认识。","sub":[{"t":"以敌人自我暴露与事变发展检验认识","d":"面对对敌判断是否正确，不固守成见，而是看敌人自己的政治欺骗如何因其迅速扮演而破产、人民如何从自身经验中认清敌人面目；用\"一切事变是否证明估计正确\"来检验并修正既有判断。","p":["蒋介石政府已处在全民的包围中"]}]},{"t":"以阶段结果数据评估既有方针成效","d":"一个阶段性任务结束时，不以主观印象或口号评估，而以实际产出与所付代价的双向数据衡量成效，并据此确认或修正既有方针。","sub":[{"t":"以战绩与代价的双向盘点总结作战年度","d":"总结一个作战年度，既统计歼敌数量（敌之损失），也如实计入己方伤亡与土地代价（己方消耗），再评估这一交换对敌我态势的影响（敌受严重打击、我军锻炼壮大），从而确认既有方针的成效并作为后续任务设定的基础。","p":["解放战争第二年的战略方针"]}]},{"t":"以形势阶段变化为依据调整目标任务","d":"面对目标任务设定，先识别所处阶段的条件变化，再据此重新界定任务的主次与分工，使方针随阶段转换而调整而非沿用旧设定。","sub":[{"t":"以内线与外线分工界定新阶段作战任务","d":"面对新阶段方针，先判断战争由战略防御转入战略进攻的阶段转换，再据此界定基本任务（主力打到外线、将战争引向国民党区域）与部分任务（部分主力和地方部队在内线歼敌收复失地），使主次任务按阶段需要分工。","p":["解放战争第二年的战略方针"]}]},{"t":"以困难与可克服条件的对照论证方案可行","d":"面对一项须坚持而又有困难的方案，不因困难而否定，而将困难清单与克服困难的客观条件相对照，以两者能否抵偿来论证方案是否可行。","sub":[{"t":"以困难与可克服条件的对照论证方针可行","d":"先如实列出执行新方针的困难（建立新根据地需时间、需反复机动等），再逐项对照可克服的客观条件（敌被迫分散、有广大战场、当地民众拥护、敌战斗力削弱），由此得出困难必须且能够克服的可行性结论。","p":["解放战争第二年的战略方针"]}]},{"t":"以决定性少数条件确定行动关键","d":"面对复杂任务的成败关键，从众多因素中提炼极少数决定性条件作为行动焦点，以有限的关键要求统摄执行，而非平均用力。","sub":[{"t":"以决定性条件的最小集合确定取胜关键","d":"面对复杂任务，不从全部因素逐一布置，而提炼极少数决定性条件（善于捕捉战机、坚决争取群众）并分别落实为明确要求，使执行聚焦于关键点以争取胜利。","p":["解放战争第二年的战略方针"]}]},{"t":"以量化测算设定可核验阶段目标","d":"面对阶段目标设定，不以笼统愿望替代，而以对方总量与分布的数字分解和推进速率的推算，得出可核验的数量目标，并据此预判后续态势变化。","sub":[{"t":"以敌情量化测算设定阶段歼敌目标","d":"先分解敌军总数与分布（南线、北线、后方），区分机动与守备兵力，再按当前歼敌速率（平均每月八个旅）推算所需歼敌量（九十六至一百个旅），据此设定年度目标并预测敌军被迫转入全面防御。","p":["解放战争第二年的战略方针"]}]},{"t":"以就地取给与基础建设并举支撑长期任务","d":"面对长期任务，不以一次性外部供给为唯一依靠，而以就地取给维持当前消耗，同时配套基础建设与节约，形成可持续的支撑结构。","sub":[{"t":"以就地补充与根据地建设并举支撑长期作战","d":"以俘获敌人的武器与兵员就地补充自己、主要向敌军和国民党区域求补充，同时在新老解放区坚决实行土地改革、发展生产、厉行节约、加强军事工业建设，形成作战取给与后方建设并举的持久支撑结构。","p":["解放战争第二年的战略方针"]}]},{"t":"以统一明文标准规约分散实践","d":"面对同类规范长期实施而各地内容出入时，不以各自参差做法为准，统一作出明文规定作为共同标准，并要求依此推行执行，以保证行动一致。","sub":[{"t":"以统一明文重行颁布纪律并强调教育执行","d":"面对长期实行、各地各军内容出入的纪律规范，统一作出明文规定并重行颁布，要求以此为准，通过深入教育与严格执行消除执行出入，使全军行为规范归于一致。","p":["中国人民解放军总部关于重行颁布三大纪律八项注意的训令"]}]},{"t":"在统一标准之外依具体情况补充规定","d":"面对统一标准难以覆盖的具体事项，不强行一律，将补充权授予了解具体情况的执行层，由其依当地实际规定项目并以命令形式施行，使规范兼具统一性与灵活性。","sub":[{"t":"授权执行层依具体情况以命令补充规定","d":"面对统一规定未覆盖的其他注意事项，不强行以统一条文包揽，将补充权授予熟悉具体情况的各地最高首长，由其根据具体情况规定项目并以命令施行。","p":["中国人民解放军总部关于重行颁布三大纪律八项注意的训令"]}]},{"t":"以持久起作用的因素判定根本趋向","d":"判断对抗或事业的根本趋向时，把一时一事的优势、援助与由性质和人心支撑的持久因素区分开，以持久起作用的因素而非暂时因素作为基本判断依据，从而不被一时的强弱颠倒所左右。","sub":[{"t":"以经常起作用的因素判定胜负前途","d":"面对能否打败强大对手的判断，先如实列举敌我双方力量清单（军队数量装备、外援、人口、后方），再把各项因素分成两类：军事优势、外部援助为暂时起作用的因素，战争性质、人心向背为经常起作用的因素；以经常因素定基本判断，不以暂时因素动摇信念，并以十八个月战争实践检验论断。","p":["目前形势和我们的任务"]}]},{"t":"以最广大联合与最小打击面组织力量","d":"面对多元社会力量，先分清依靠、联合与打击的对象结构，把打击面缩到最小、联合面扩到最广，并以不损害同盟者利益为政策边界，由此组织起压倒性的多数力量。","sub":[{"t":"划分依靠联合打击对象并守护同盟者利益","d":"在土地改革中划分对象：以贫农团为领导骨干、依靠贫农雇农，巩固地联合中农，消灭地主阶级与旧式富农的封建剥削；掌握满足贫雇农要求、不损害中农利益两条基本原则；打击对象仅约百分之八而可联合者占百分之九十以上，据此防过左防过右。","p":["目前形势和我们的任务"]}]},{"t":"以自我批评整肃组织与群众保持一致","d":"当组织因成分或作风不纯而脱离群众时，通过内部批评与自我批评彻底揭发错误思想与现象，整编队伍，使组织重新与群众站在同一方向，以内部自我清理恢复组织与群众的联系。","sub":[{"t":"以批评自我批评整编党的队伍","d":"面对组织成分与作风不纯，先查明地主富农流氓分子混入、把持组织、脱离群众的问题，再在党内展开批评和自我批评，彻底揭发离开党的路线的错误思想和严重现象，整编党的队伍，使党与最广大劳动群众站在一个方向。","p":["目前形势和我们的任务"]}]},{"t":"区分不同范畴的斗争并以总目标校准政策","d":"当政策涉及对象的多重属性时，把不同范畴的斗争分开处理，不因政治打击扩展到经济消灭，并以总体目标校准每一项具体政策，防止范畴混淆导致政策越界。","sub":[{"t":"区分政治打击与经济消灭划定政策边界","d":"对待可争取的中间阶级，先把政治上的打击与经济上的消灭分作两件事，防止混同；明确革命消灭对象只是封建主义和垄断资本主义，对民族工商业与小资产阶级坚决保护；以发展生产、繁荣经济、公私兼顾、劳资两利为总目标校准一切政策，防止重犯过左错误。","p":["目前形势和我们的任务"]}]},{"t":"在广泛联合中坚持核心领导","d":"广泛联合多数力量时，联合范围应尽可能大，但联合本身不足以保证胜利，必须由一个坚强核心掌握领导权；放弃领导权则联合战线不能胜利，这是联合行动的一般前提。","sub":[{"t":"在最广泛联合中坚持核心领导","d":"先以正确政策（彻底的土地政策、保护群众利益的城市政策、军事胜利）争取最大多数群众，使统一战线比任何时期更广大更巩固；同时认清没有党的坚强领导统一战线不能胜利，反对放弃对群众和武装力量领导权的投降主义，以发展进步势力、争取中间势力、孤立顽固势力的路线执行领导。","p":["目前形势和我们的任务"]}]},{"t":"以行为序列而非声明判断对象一贯性质","d":"判断对象性质时不以其当下声明为准，而取出其完整历史行为序列，看其一贯表现与内在逻辑，以历史连续性确证当前判断。","sub":[{"t":"以历史行为序列论证对象的一贯性质","d":"面对判断对象当前行为的性质，不从眼前一事论偶然，而取出其完整历史行为序列（背叛联盟、长期内战、破坏和谈、全面进攻、镇压人民运动、出卖国家权利等），以序列的连续性证明其性质的一贯性，从而把当前事件论证为历史必然结果而非偶然现象。","p":["中国人民解放军宣言"]}]},{"t":"以时序对比的幅度判定形势变化的程度","d":"判断形势是否发生根本变化时，以同一对象在不同时间点的态势对比为基础，按差异幅度判定变化是否达到基本程度，避免以模糊印象代替对比。","sub":[{"t":"以时序对比判定形势已起基本变化","d":"面对形势是否已经转变的判断，取同一对象在两个时间点的态势作对比（一年前处于防御、现在转入进攻，敌人望风披靡、人民欢声雷动），以对比差异的幅度判定变化是否达到\"基本\"程度，并以此作为宣布新方针的形势前提。","p":["中国人民解放军宣言"]}]},{"t":"分条列明纲领并声明适用范围与依据","d":"面向公众公布方针纲领时，分解为明确条目逐一列明，并同时给出适用范围、执行承诺与正当性依据，使受众可逐项核验、执行者可逐条落实。","sub":[{"t":"分条列明纲领便于逐项核验执行","d":"面对需要公布的政策纲领，不笼统陈述，而将总目标分解为若干明确条目逐一列明（八项基本政策），随后立即声明适用范围与执行承诺（所到之处立即实施）及正当性依据（适合百分之九十以上人民要求），使纲领可逐项核验、逐条执行。","p":["中国人民解放军宣言"]}]},{"t":"按罪责轻重分级分别对待对象","d":"面对复杂阵营的成员构成，按罪责或责任轻重分级，为各级规定差异化处置，既保证重点打击又为可争取者留出转变空间。","sub":[{"t":"按罪责轻重分级分别对待敌方人员","d":"面对敌方阵营的复杂人员构成，先按罪责轻重分级（首恶、胁从、立功者），再为每级规定不同处置（必办、不问、受奖），对主要对象坚决打击，对次要人员留出转变空间，避免一概排斥或一律打击。","p":["中国人民解放军宣言"]}]},{"t":"以利害警告与出路保证促使对象转变","d":"对可争取对象，既告知其继续原路径的利害后果，又给出停止后的具体出路与待遇保证，以双向信息促使对方在权衡中转变。","sub":[{"t":"以利害警告与出路保证促使对象转变","d":"对尚可争取的蒋方人员，同时给出双向信息：一方面明确告知继续为恶的利害后果（赶快停止作恶、勿同流合污），另一方面给出具体出路与待遇保证（将功赎罪、放下武器不杀不辱、愿留收容愿去遣送、起义受奖），使对象在权衡中转变立场。","p":["中国人民解放军宣言"]}]},{"t":"按对象处境分层分派任务","d":"需要向广泛受众发出行动号召时，先按对象所处条件分层，再为每层规定相应的具体任务，使号召与处境匹配而可执行。","sub":[{"t":"面向不同对象分层号召分派任务","d":"面对需要动员的广泛受众，先按对象所处区域与身份分层（国统区同胞、解放区人民、全军将士），再为每层规定与其处境相应的行动任务（武装斗争与抗丁抗粮、土改生产支前、提高军事艺术觉悟性纪律性），使号召具体可落实。 # Method Dedup Index（25-30 批次） **批次：** 25-30（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 25、关于建立报告制度；26、关于目前党的政策中的几个重要问题；27、军队内部的民主运动；28、在不同地区…","p":["中国人民解放军宣言"]}]},{"t":"依靠骨干与区别对待各阶层相统一","d":"面对由不同成分构成的群众整体，既依靠核心骨干又不排斥其他群体：骨干的带头作用表现为团结多数一道行动而非包办，对不同对象分别划定政策界限，以扩大联合而不是缩小联合。","sub":[{"t":"依靠基本群众并界定骨干带头作用","d":"把贫雇农利益与贫农团带头作用放在第一位，但把带头作用界定为团结中农和自己一道行动，而不是抛弃中农由贫雇农包办一切；明确乡村与全国都是各劳动阶层、各界人士联合在工人阶级（经过共产党）领导之下行动，不是少数人包打天下。","p":["关于目前党的政策中的几个重要问题"]},{"t":"对各阶层分别采取避免冒险的政策","d":"对中农、中小工商业者、知识分子、开明绅士等分别规定有区别的政策：改正订错的成分并退还，确立富农剥削标准，保护有益国民经济之工商业并只没收官僚资本与真正恶霸反革命分子者，对知识分子分别情况团结、教育、任用，对开明绅士分别情况照顾安置，区分新富农与旧富农。全部以“避免冒险、分别对待”为限。","p":["关于目前党的政策中的几个重要问题"]},{"t":"先建立贫农团骨干再扩展为包括中农的农民协会","d":"群众组织建设分先后：先组织贫农团作为骨干，几个月后再组织农民协会；严禁地主富农分子混入任何组织；贫农团积极分子充当农民协会领导骨干，同时必须吸收中农积极分子参加农会委员会，吸引中农参加斗争并照顾其利益，使骨干组织不脱离多数。","p":["新解放区土地改革要点"]},{"t":"有限度任用旧出身支持者并防止其把持权力","d":"对地主富农家庭出身但赞成土地改革的本地革命知识分子，吸收其参加建立根据地的工作，但加紧教育、防止其把持权力妨碍土地改革；一般不宜让他们在本区本乡办事，干部任用上着重选择农民家庭出身的知识分子，以身份限制防范权力失控。","p":["新解放区土地改革要点"]}]},{"t":"限定打击对象并保存改造多数","d":"变革中把消灭对象限定在制度与极少数罪大恶极者，把大多数作为保存和改造的对象；对须打击者也限定范围、程序与方式，防止打击面扩大。","sub":[{"t":"限定打击面并保存改造大多数","d":"把土地改革中心规定为平分封建阶级土地而不强调斗地财；在打击对象上依次区别地主与富农、大中小地主、恶霸与非恶霸；坚持少杀、严禁乱杀，只对真正罪大恶极者经法庭审判与上级批准处决；把消灭对象限定为封建制度与地主之为阶级，把大多数地主富农个人作为劳动力保存改造，给以不高于农民的生产资料与生活资料。","p":["关于目前党的政策中的几个重要问题","新解放区土地改革要点"]}]},{"t":"按对象实际条件差异分类施策","d":"对统一目标或法令不按单一标准一刀切执行，而先以对象的实际条件（发展程度、觉悟水平、问题解决程度、工作基础）划分类型，再分别为各类型确定不同的实施策略与工作中心，使同一政策在差异条件下都得到可行落实。","sub":[{"t":"按地区实际条件划分类型后差异化实施土地政策","d":"面对统一法令在差异悬殊地区的实施，先以群众觉悟与组织程度、土地问题解决程度、我方工作基础三项现实条件为据把地区划分为老区、半老区、新区，再分别为各类型确定不同工作中心与政策界限：老区不重新分配、以整党与调整领导成分为中心；半老区普遍彻底分配并复查；新区分阶段推行。领导力量配置也随阶级结构而定。","p":["在不同地区实施土地法的不同策略"]},{"t":"区分巩固区与游击区规定不同工作内容","d":"先按军事与群众基础条件把地区分为巩固区和游击区：巩固区逐步进行土地改革；游击区只作宣传工作和荫蔽的组织工作、分发若干浮财，不公开成立群众团体、不进行土地改革，以防止敌人摧残群众，使工作内容与地区安全条件相称。","p":["新解放区土地改革要点"]}]},{"t":"按条件成熟度分阶段渐进推进变革","d":"当实施目标所需条件尚未具备时，不强行一步到位，而按敌我力量对比与群众发动程度把变革划分为阶段与步骤，先打击主要对象、后处理次要对象，以充分时间等待条件成熟，急躁求快则事必办不好。","sub":[{"t":"新解放区土地改革分两阶段分步骤渐进推进","d":"对群众尚未发动、敌方势力尚大、我方无基础的新解放区，不急于一次实行土地法，而把改革分为两个阶段：第一阶段中立富农、专门打击地主，依次完成宣传、初步组织、分浮财、分大中地主土地并照顾小地主等步骤，组织贫农团为领导骨干；第二阶段再分配富农出租和多余土地及部分财产，并补分第一阶段不彻底部分。每阶段给以足够时间，太急了必办不好。","p":["在不同地区实施土地法的不同策略","新解放区土地改革要点"]},{"t":"依环境群众觉悟与干部条件确定变革速度","d":"土地改革不预定急躁的时间表，而依据环境、群众觉悟程度和领导干部强弱三项条件决定工作进行的速度，准备用两三年完成全区土改，不企图几个月内完成；此原则同样适用于老区和半老区，使推进节奏服从于客观条件与工作基础。","p":["新解放区土地改革要点"]}]},{"t":"以固定周期的综合回流掌握分散实际","d":"分散执行一旦铺开，中枢对实际的了解就不能依赖偶发的、由下位自行判断是否值得上报的信息，而须把情况回流规定为按固定节奏发生的经常动作，并要求它同时覆盖动态、问题与已采取的办法，中枢才具备事先或事后介入的条件。","sub":[{"t":"以定期综合报告把分散执行情况汇集到决策中枢","d":"对受上级委任、代表上级执行任务的各层机关，规定固定周期与固定发出时点，由其向中枢提交覆盖各条战线的综合报告：既写各项活动动态，也写活动中发生的问题和倾向，还写对这些问题和倾向的解决方法，使中枢能在事先或事后介入纠偏。经常性报告之外保留临时性请示；时点遇特殊情况可调整，但须申明原因。","p":["关于建立报告制度"]}]},{"t":"按接收端的使用条件限定上报信息","d":"信息送达不等于信息可用。若不由接收端一侧反向规定上报的形式与内容层级，上报就会被篇幅和事务性细节淹没，接收端仍无法据以判断。故须限定长度、要求指明问题与分歧所在，并把决定性内容与事务性内容分立各自的报送口径。","sub":[{"t":"限定报告篇幅与详略以保证信息可用","d":"为经常性报告规定字数上限，要求内容扼要、文字简练，并明确要求指出问题或争论之所在；一次写不完全部问题时，采取分两次写，或本次着重写几个问题、其余只略带几笔，下次再对调详略，使有限篇幅内始终有被充分展开的内容。报告按规定日期、用最快的通讯方式发出。","p":["关于建立报告制度"]},{"t":"把政策性报告与技术性、临时性报告分开规定","d":"不以一种报告承担全部上报任务，而按内容对决策的决定性程度分类立制：方针一类随时报告请示；战绩、损耗、实力一类按月例行报送；政策性综合情况与请示另立经常制度；临时性请示照旧不并入。数类并行保留，防止下位以技术性报告或例行报表代替对重要活动和政策内容的报告。","p":["关于建立报告制度"]}]},{"t":"把制度要求落实到可追责的具体主体","d":"一项要求若只落在机关而不落在人，执行就会被转手、代办和形式化稀释。须为每项经常性义务指定唯一承担者，规定其缺位时的替代者，并对合作完成的部分要求共同署名，使制度在任何时刻都有可以追问的具体对象。","sub":[{"t":"以本人执笔、指定代理和联合署名落实报告责任","d":"把经常性上报的义务落到具体个人而不是笼统落到机关：由主要负责人本人动手，不交辅助人员代劳；本人因故不能承担时，须指定代理人或副职承担相应部分的报告；涉及专门领域的部分由该领域主管起草，主官审查修改并共同署名。责任人清晰之后，报告是否作出、是否真实，才有可追问的对象。","p":["关于建立报告制度"]}]},{"t":"按总体与局部分层作相反估计","d":"认识对象力量时，把总体（战略）层次与局部（具体斗争）层次分开，分别作相反取向的估计——总体敢于轻视、局部必须重视，防止把某一层次的估计无条件推广到另一层次而陷入片面。","sub":[{"t":"战略上藐视与战术上重视的统一","d":"面对强大敌人，在全体上、战略上估计其力量时敢于轻视（确信可以战胜），在每一个局部、每一个具体斗争问题上则决不轻视，集中全力、谨慎从事、讲究斗争艺术、争取一切应争取的同盟者。两个层次的态度同时并用，防止在全体上估计过高而犯右倾错误，也防止在局部上轻敌而犯“左”倾错误。","p":["关于目前党的政策中的几个重要问题"]}]},{"t":"依据具体态势确定纠偏方向","d":"纠正偏向不依固定成见，而依据具体态势判断当前主要危险方向：在容易产生“左”倾向的环境防“左”，在容易产生右倾向的环境防右，使纠偏方向随条件变化。","sub":[{"t":"依据具体情况决定反倾向方针","d":"反对党内错误倾向不预先固定方向，而依据具体态势决定：打胜仗时防止“左”倾、打败仗时防止右倾；群众未认真发动时反对右倾、群众已发动并展开斗争时防止“左”倾。以态势判断当前主要危险方向，再决定反“左”还是反右。","p":["关于目前党的政策中的几个重要问题"]}]},{"t":"批评斗争的双向约束","d":"对犯错误者展开批评斗争的同时，同时约束斗争者与被斗争者——规范群众的斗争方式避免粗暴，要求被批评者保证不报复，并赋予群众最终处置权，使斗争既开展又不失控。","sub":[{"t":"对犯错误者的批评斗争与双向约束","d":"对犯重大错误的干部党员和工农群众中的坏分子必须进行批评和斗争，但一方面说服群众采取正确的方法与方式、避免粗暴行动，另一方面使被批评者提出保证、不对群众报复；宣布群众有权放手批评，必要时撤职或建议撤职、建议开除党籍，直至送交人民法庭审处。","p":["关于目前党的政策中的几个重要问题"]}]},{"t":"组织形式依据对象性质与实际阶段确定","d":"确定组织形式时先明确对象的性质（阶级构成），再依据现阶段实际条件选择具体形式；性质决定形式的基本规定，形式随阶段条件调整。","sub":[{"t":"依据政权性质与阶段条件确定组织形式","d":"先明确政权性质（工人阶级领导的人民大众的反帝反封建政权）与权力机关（各级人民代表大会及其选出的各级政府），再按现阶段条件规定具体选举办法：乡村可依农民要求召集农民大会选举乡村政府、区农民代表大会选举区政府，县市以上召集人民代表大会选举各级政府；将来全国胜利后，中央和地方各级政府均由人民代表大会选举。","p":["关于目前党的政策中的几个重要问题"]}]},{"t":"领导地位通过被领导者的实际受益确立","d":"领导不靠名义地位，而通过两个条件实现：率领被领导者对共同敌人斗争并取得胜利，并给以物质福利（至少不损害其利益）与政治教育；使被领导者实际受益，领导才能稳固。","sub":[{"t":"以斗争胜利与物质福利及政治教育实现领导","d":"领导阶级和政党要实现对被领导者的领导，必须同时具备两个条件：率领被领导者向共同敌人作坚决斗争并取得胜利；对被领导者给以物质福利（至少不损害其利益）并给以政治教育。以中农为例逐项落实：共同斗争分地、吸收积极分子参加政权并按数量规定、成分税赋公道、给以政治教育，缺一则不能实现领导。","p":["关于目前党的政策中的几个重要问题"]}]},{"t":"集中领导下放手发动群众参与以达到组织目的","d":"组织内部的群众参与不是自发自流，而是在统一领导框架内放手发动；放手发动群众与集中领导并行，把群众力量导向明确的组织目的，防止参与失序。","sub":[{"t":"以集中领导下的民主运动实现部队建设目的","d":"部队政治工作不靠单向下命令，而放手发动士兵群众、指挥员和一切工作人员，通过集中领导下的民主运动，达到政治团结、生活改善、军事提高的三大目的；放手发动与集中领导并存，民主不脱离领导而自流，各具体形式再配以权限限定。","p":["军队内部的民主运动"]}]},{"t":"群众参与组织事务须明确权限与范围边界","d":"让群众参与组织内部事务（管理、监督、选拔）时，须同时规定其权限与适用范围：参与而不越权，特殊权利仅在必要时行使，并信任群众能正确行使权利，使群众作用与既有组织秩序相协调。","sub":[{"t":"以士兵代表协助连队管理给养伙食","d":"在经济生活管理上由士兵选出代表，协助（不是超过）连队首长管理连队的给养和伙食；把士兵代表的权限定位为“协助”，既引入士兵参与日常管理，又用明确边界防止代表越权代替连队首长。","p":["军队内部的民主运动"]},{"t":"赋予士兵对干部的揭发权与必要时的推选权","d":"赋予士兵群众揭发干部中坏分子错误和罪恶的权利，同时相信士兵对一切好的和较好的干部必然爱护；在下级干部极端缺乏时，允许士兵从群众中推选其信任的下级干部候选人以待上级委任；推选不是普遍的，只在必要时进行。","p":["军队内部的民主运动"]}]},{"t":"把完成具体任务的办法建立在群众集体经验之上","d":"面对练兵、作战等具体任务，不把完成任务的办法局限于上级规定或少数人设计，而通过相互教学与集体讨论把方法建立在群众集体经验之上，并以实践成效判定方法的可靠性。","sub":[{"t":"以官兵互教与火线集体讨论完成练兵和作战任务","d":"练兵时实行官兵互教、兵兵互教；作战时在连队首长指导下，于火线开各种大小会议，发动士兵群众讨论如何攻克敌阵、如何完成战斗任务，连续几天的战斗应开几次；并以蟠龙、石家庄战役的实际成效证明此法只有好处、毫无害处。","p":["军队内部的民主运动"]}]},{"t":"防止以局部代替整体","d":"由多个相互联结部分构成的对象，其任何一个部分都不能脱离整体而单独充当整体来传播或判断；判断部分是否失真，须回到整体结构重新定位其地位，防止片面突出代替全面认识。","sub":[{"t":"对照完整路线校正片面宣传","d":"对一段时期的宣传内容，先与党的完整路线逐项对照，检查是否把路线的一个侧面（如依靠贫雇农）孤立突出而丢掉其他组成部分（联合中农、团结一切劳动人民与爱国分子等）；凡属“只宣传一侧、删除其余”者，即判定为原则性错误并纠正，使宣传恢复反映完整路线。","p":["纠正土地改革宣传中的“左”倾错误"]}]},{"t":"在对立两端之间同时划界定位","d":"认识与表达一项政策或立场时，不单向地只反对一种偏向，而同时否定两个相反方向的极端；正确位置由两端界限共同确定，只堵一端往往使认识与实践倒向另一端。","sub":[{"t":"政策宣传须同时划清两个相反偏向的界限","d":"在涉及成分、土地改革速度、领导与群众关系等政策问题的宣传中，同时表明“既反对这一偏向、又反对相反偏向”：既反对忽视成分又反对唯成分论，既反对观望不前又反对急性病，既反对命令主义又反对尾巴主义；使宣传对两端同时划界，防止助长任何一种极端。","p":["纠正土地改革宣传中的“左”倾错误"]}]},{"t":"区分成绩与错误以全面评估工作","d":"评估一段时期的工作不作笼统的肯定或否定，而先分清成绩与错误两部分：确认成绩的主要地位、指明错误的性质与特点，再分别处理（发扬成绩、纠正错误），防止以错误否定全部或由成绩掩盖错误。","sub":[{"t":"全面检查宣传并分清成绩与错误后分别处理","d":"面对一段时期内带有偏向的工作，先作全面检查：确认成绩占主要成分并予以承认，再指出错误的性质与特点（“过左”、违背原则与路线）；据此发扬成绩、纠正错误，并责成主管部门负主要责任，以机关名义写出政策性报告向上级报告。","p":["纠正土地改革宣传中的“左”倾错误"]}]},{"t":"以局部试点经验带动逐步推广","d":"大规模变革不全面同时铺开，而先选干部在若干地点试行，以局部实践取得的经验作为逐步推广的依据，波浪式向前发展；推广的根据来自先行试点的实际成效，避免因全面展开而来不及纠正失误。","sub":[{"t":"以干部先行试点取得经验后波浪式推广","d":"大规模变革不全面同时动手，而选择强的干部在若干地点先行试行，取得经验后再逐步推广，波浪式地向前发展；这一推进方式在整个战略区、在一个县内以及老区半老区均适用，以局部先行实践及其经验作为扩大推广的前提。 # Method Dedup Index（31-36 批次） **批次：** 31-36（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 31、关于工商业政策 · 32、关于民族资产阶级和开明绅士问题 · 33、评西北大捷兼论解放军的新式整军运动…","p":["新解放区土地改革要点"]}]},{"t":"依形势规律把握偏向并分清主次纠正","d":"处理工作与政策执行中的偏向时，不孤立看待某一表现，先把握偏向随形势变化而发生的规律（如与对方合作时期易出右的偏向、分裂时期易出\"左\"的偏向），区分当前主次，再集中用力纠正，避免平均用力或只治标不治本。本思想把\"区分主次、依规律纠偏\"确立为纠正偏向的上位认识原则；评价经验亦持分析态度，不因纠偏否定一切。","sub":[{"t":"分清主次偏向并依历史规律着力纠偏","d":"纠正党内政策偏向时，先掌握偏向发生的形势规律，据此判定当前以何种偏向为主、何种为次；再逐一列明该偏向的具体表现，认清其可纠正性与须着力的环节；最后由各级领导者着重用力、彻底纠正，避免主次不分或纠正半途而废。","p":["关于情况的通报"]},{"t":"从两方面审查并逐项纠正工作偏向","d":"评价一段工作，须从反对右的偏向与纠正\"左\"的偏向两方面同时审查，不因一面成功忽视另一面问题；对具体偏向（扩大打击面、侵犯工商业、乱打乱杀）逐项分析纠正，使工作走上健全轨道。核心链：从右左两方面对照检查 → 逐项列明并纠正 → 恢复健全发展。","p":["在晋绥干部会议上的讲话"]},{"t":"总结经验采取分析态度并把握分寸","d":"全面总结反右反\"左\"经验时采取分析态度：肯定成绩（反右认真、充分反映群众运动）也承认缺点（弓弦拉得太紧、\"左\"的偏向），不否定一切；认识从没经验到有经验是一个过程；纠偏把握\"一张一弛\"的分寸，使头脑清醒。核心链：全面总结 → 分析评价 → 过程认识 → 把握分寸。","p":["对晋绥日报编辑人员的谈话"]}]},{"t":"以群众性运动整顿组织并提高能力","d":"处理组织内部问题或提高集体能力时，依靠群众自身的诉苦、自查与互教发动其积极性，使问题在群众参与中解决、能力在群众性活动中提高，而非仅靠自上而下的命令与灌输。本思想把群众参与确立为整顿与提高的基本方式。","sub":[{"t":"以诉苦三查与群众练兵整训军队","d":"整训部队时，依靠群众性方法而非单靠上级命令：通过群众诉苦发动阶级觉悟，通过三查（查阶级成分、查工作、查斗志）清理队伍、提高纪律，通过官教兵、兵教官、兵教兵的群众练兵提高军事技术战术；由此发动全军积极性、讲明各项政策，达到战斗力的整体增长。","p":["关于情况的通报"]},{"t":"邀集党外积极分子参加支部会议推动整党","d":"整顿党组织，邀集党外群众中的积极分子参加支部会议，展开批评和自我批评，借以改变组织内成分不纯或作风不纯现象，使党与群众密切联系起来；对犯错误但可教育的党员干部，教育而不是抛弃。核心链：引入党外参与 → 批评自我批评 → 改变组织作风 → 密切党群关系。","p":["在晋绥干部会议上的讲话"]},{"t":"集合相关人员集体解决具体问题","d":"面对个别具体问题（如报上错字）长期得不到解决、少数人关起门来办不了的问题，把问题涉及的全体人员集合起来，专门讨论这一件事；讲清楚错误的情况、发生错误的原因、消灭错误的办法，要大家认真注意；反复讲三五次使问题得到纠正。核心链：集合相关者 → 讲清情况原因办法 → 反复讲解 → 问题纠正。","p":["对晋绥日报编辑人员的谈话"]}]},{"t":"区分对象性质确定方法适用边界","d":"面对不同性质的对象，方法不能机械通用；先辨识对象所属类别与应保留、应消除的部分，再划定方法的适用边界，才能避免错用。本思想是防止政策或工作方法跨领域误植的上位原则。","sub":[{"t":"区分对象性质防止政策方法错误移植","d":"当把一套在某领域有效的方法推广到另一领域时，先分析目标对象的性质与边界：区分应消灭的（如封建剥削）与应保护的（如合法工商业），区分正确综合方针与片面狭隘方针，再把方法限制在适用范围内，防止机械移植造成伤害。","p":["关于工商业政策"]},{"t":"按阶级属性与革命作用划分统一战线成分边界","d":"面对统一战线内部的多类力量，先辨识其阶级属性（民族资产阶级、开明绅士、劳动人民）及其在革命中的实际作用，区分主体与部分、敌人与革命者、决定革命性质的力量与非决定力量，再划定团结政策的边界。关键是把盟友定位于\"人民大众的一部分\"而非\"决定力量\"，防止误判革命性质。","p":["关于民族资产阶级和开明绅士问题"]}]},{"t":"以对象对革命的实际利害与作用作为政策依据","d":"对中间势力的团结或保护政策，不以其自身力量大小或阶级名分而定，而以其对革命的实际利害（经济重要性、可参加反敌）与实际作用（争取他方、孤立敌人）为根据。本思想把政策依据从对象名分转向其对革命的具体贡献。","sub":[{"t":"据经济地位与政治利害确定对中间阶级的保护与团结","d":"对民族资产阶级，依其在经济上的重要性及可参加或中立于反美蒋的政治利害，决定在原则上一律保护、慎重处理其经济地位；否则便在政治上犯错误。把经济地位与政治利害作为团结保护政策的依据，而非以抽象阶级名分替代具体利害判断。","p":["关于民族资产阶级和开明绅士问题"]},{"t":"以对象对革命的实际帮助而非其力量大小作为团结依据","d":"团结开明绅士，不是因其政治力量大或经济重要，而是因其在争取知识分子、民族资产阶级、开明绅士及孤立主要敌人上有实际帮助作用；以此实际作用（而非自身力量大小）为团结依据，并在团结中教育他们，要求其赞成反美蒋、民主与土改。","p":["关于民族资产阶级和开明绅士问题"]},{"t":"对中间力量以团结为主、按社会基础择时争取","d":"对处于中间立场的民主人士，不因其持有错误观点或历史幻想而排斥：采取团结的政策，对其错误观点作适当批评；透过其表现认识其所代表的社会基础（民族资产阶级）的实际重要性，估计到须待我方形势完全判明、条件成熟才争取成功，据此决定吸收其参加政府的时机。","p":["关于情况的通报"]}]},{"t":"以对象构成数据评估其实际强弱","d":"评估对象的实际实力与弱点，不凭整体印象或名分，而以构成数据为据：统计其组成部分的数量、被消耗的历史、分布状态与任务，据以判断其整体强弱与可被击破的空虚点。本思想把定量构成分析作为实力研判的依据。","sub":[{"t":"以量化敌情研判对方弱点","d":"评估对象实际强弱时，逐项统计其构成（旅数、被歼历史、补充情况、分布地区与守备任务），据以推断其精锐损耗、空虚部位与无法阻止己方行动的程度；以量化构成为据推其弱点与行动空间，不以整体印象代替分项计算。","p":["评西北大捷兼论解放军的新式整军运动"]},{"t":"按实际构成而非名义番号评估敌我力量","d":"估计敌我军事力量时不轻信名义番号：扣除空番号与被歼尚未补充部分，区分受过与未受歼灭性打击的部队，核算总兵力与每旅人数实际消长，结合各战场主动被动态势，得出敌我真实强弱与总体形势的判断。","p":["关于情况的通报"]}]},{"t":"以稳扎稳打的可控节奏推进长期任务","d":"对需要长期完成的任务，不求速效、不冒进，以可持续的量化节奏稳步推进，使进度可控、能够坚持到底，并以对客观条件的估计作为进度依据。本思想把\"稳扎稳打、可控速率\"确立为长期任务推进的进度原则。","sub":[{"t":"以稳扎稳打与量化目标推进长期战争","d":"面对长期战争，不追求速效、不因一时顺利而冒进：定下稳扎稳打的方针，以可持续的量化目标（平均每月歼敌八个旅左右、每年约一百个旅）为推进标准，按敌我力量消长的实际估计安排进度，并据实际进展估计完成整个任务的年限。","p":["关于情况的通报"]},{"t":"有步骤有分别地推进制度变革","d":"推进消灭封建制度这类深刻变革，依据环境许可情况与群众觉悟、组织程度决定斗争策略；分地区、分阶段，分别地主富农的大中小与恶霸非恶霸，给予不同待遇；不企图在一个早上消灭全部，控制打击面在实际允许范围，事后转入恢复发展生产。","p":["在晋绥干部会议上的讲话"]}]},{"t":"以事前政策宣讲统一行动认识","d":"行动前使执行者明了指导其行动的原则与边界，是把分散行动纳入统一认识、避免盲目偏差、发动对象积极性的前提。本思想强调以事前讲明替代事后补救。","sub":[{"t":"行动前讲明政策统一政策领导","d":"在每一次具体行动之前，先把\"按情况规定的政策\"向党员和群众讲清楚，使行动建立在自觉的政策认识上；若不预先讲明，群众会脱离政策领导而盲目行动，最终实行错误政策。","p":["关于工商业政策"]},{"t":"以政策公开宣传发动群众","d":"把政策方针经报纸、刊物、电台向广大群众公开，使群众知道真理、目的与自身的利益，形成共同目的；由少数人知道扩展到多数人知道，发挥被领导者的积极性和创造力，使群众齐心动起来。核心链：政策公开 → 群众知悉目的与方法 → 齐心行动。","p":["对晋绥日报编辑人员的谈话"]}]},{"t":"以历史发展过程认识对象政治态度的变动性","d":"对象（尤其中间势力）的政治态度并非固定，随历史条件变动；不凭一时表现定类，而从各阶段立场的发展过程判断当前多数可争取、少数须孤立，据以定政策。本思想是避免以静态定类替代动态认识的上位原则。","sub":[{"t":"以历史发展过程判断阶级政治态度的可争取性","d":"对中间阶级不凭一时表现定类，追踪其在各历史阶段（如一九二四—一九二七年、一九二七—一九三一年、抗日时期、现阶段）的政治立场变化，判断当前多数可争取、少数须孤立，据以决定\"争取多数、孤立少数\"的策略；不在其某段动摇后否定整体可争取性。","p":["关于民族资产阶级和开明绅士问题"]}]},{"t":"以客观条件成熟为前提决定重大行动时机","d":"采取重大步骤之前先据客观条件判断时机是否成熟，未成熟即等待并创造条件，成熟后才行动；避免凭主观意愿或固定日程抢先或拖延。本思想把\"条件成熟\"确立为重大行动时序判断的客观依据。","sub":[{"t":"以客观条件成熟为前提决定重大步骤时机","d":"决定成立中央人民政府等重大政治步骤时，不以主观愿望或既定日程为据，先判断时机是否成熟；时机未熟即不急于行动，并具体列出须满足的客观条件（更大胜利、夺占大城市、区域连成一片等）；同时着手创造条件（统一区域领导、集中力量支援作战），待条件齐备再行动。","p":["关于情况的通报"]},{"t":"按群众觉悟程度把握行动时机","d":"领导群众行动时，先判断群众的觉悟程度与意愿，据此决定行动时机：群众还不觉悟时不进攻，硬要领导群众干其不愿干的事必然失败；群众要求前进时不前进就是右倾机会主义。以群众觉悟程度校准领导行动，划清冒进与右倾的界限。","p":["对晋绥日报编辑人员的谈话"]}]},{"t":"以客观实际为据作出认识与决策","d":"认识与决策的依据是客观实际情况本身，而非主观愿望或抽象原则；凡离开当时当地的实际作判断与决定，必然产生错误。方针政策的正确与否，以其是否切合客观实际来衡量。本思想确立判断与决策正确性的根本尺度。","sub":[{"t":"按照实际情况决定工作方针","d":"决定工作方针时先掌握当时当地的实际情况，据以确定方针；凡离开实际、主观决定方针必然犯错误。核心链：考察当时当地实际 → 据以决定工作方针 → 以是否切合实际检查错误。不以原则或主观愿望替代对实际状况的把握。","p":["在晋绥干部会议上的讲话"]},{"t":"教育者先向群众与实际行动学习","d":"承担教育群众任务的人若对实际事物缺乏经历，先要做去看、向群众学习：轮流参加群众工作、土地改革等实际工作，多看多研究群众运动材料，把别人的经验变成自己的，使自己成为有经验的人，才能教育群众。核心链：承认不懂实际 → 做和看 → 积累经验 → 具备教育能力。","p":["对晋绥日报编辑人员的谈话"]}]},{"t":"从政策导向与执行方式两端定位偏差","d":"执行出问题，根因可能在导向（方针本身混淆）也可能在方式（落实方法失当）；诊断时两端并列排查，避免只归咎于下层执行。本思想适用于纠正政策落实偏差的定位工作。","sub":[{"t":"从方针与方法两端检查执行偏差","d":"发现政策执行出现偏差或破坏时，不只看下面\"没照办\"，而同时从两端检查：一端查领导方针是否本身混淆了界限、定错了区别；另一端查领导方法是否联系不密、纠偏不及时。两端并查才能找到根因。","p":["关于工商业政策"]}]},{"t":"通过过程监控与及时纠偏控制执行偏差","d":"对执行过程保持持续感知，在偏差刚出现时纠正，比积累到末期集中清算代价更小；过程化纠偏是降低损失的基本方法。本思想强调以常态化监控替代滞后总结。","sub":[{"t":"随时监控及时纠偏替代算总账","d":"方针与指示下达后，建立与下级的持续联络渠道（电报、电话、谈话、报纸等），随时掌握工作进程、交流经验、发现即纠正错误；不在数月乃至一年后才开总结会\"算总账\"。越早发现纠偏，损失越小。","p":["关于工商业政策"]}]},{"t":"在人民实践中检验并校正政策","d":"认识政策正误的根本尺度是人民的实行过程（经验）；政策的成立与程度由实践判定，实践因而成为检验与校正的依据。本思想把实践置于政策判定之上位位置。","sub":[{"t":"在人民实践中检验政策正确性","d":"把政策交给人民实践去检验：政策的正确与否、正确程度，只能在党员和群众实行政策的过程与归宿（即经验）中判定；以此把实践作为判定政策正误的根本尺度，而非凭主观预定。","p":["关于工商业政策"]}]},{"t":"先陈述可核实事实再立总体判断","d":"对整体性评估不先立结论，先把可核实的具体事实（战果、经过、数字）逐一摆出，再在材料基础上形成总体判断；判断须由事实支撑，避免脱离材料先入为主。本思想把\"材料先行、论断随后\"确立为论证的基本顺序。","sub":[{"t":"先报战果后立形势判断","d":"评估整体形势时，先完整摆出支撑该判断的具体战果（战役经过、歼敌数字、敌方投入规模），再据以作出形势判断；事实报告与总体评估分两步呈现，判断随材料自然得出，避免先立结论后补材料。","p":["评西北大捷兼论解放军的新式整军运动"]}]},{"t":"由结果反推并鉴别主导原因","d":"面对显著结果，先承认原因是多元并列的，不把成效归于单一因素；再从各因素对结果的实际解释力中鉴别出主导原因，使因果判断既全面又有重点。本思想规范\"从结果追问原因\"时的归因次序，防止平均化或单一化。","sub":[{"t":"从显著结果倒推并鉴别主因","d":"面对显著成效，先承认\"原因甚多\"、各项因素都须指出，再从并列原因中鉴别出最值得注意的主导因素；通过\"原因多元、主因突出\"的归因次序，防止把成功归于单一偶然因素，也防止平均罗列各因、抓不住关键。","p":["评西北大捷兼论解放军的新式整军运动"]}]},{"t":"由个案成效上升为可推广的普遍方法","d":"从单个单位或局部检验中确认某方法的实际成效后，把\"成效—方法\"的对应提炼为一般性认识，进而判定该方法可向同类对象普遍推行。本思想提供从个案到普遍的方法论证路径，避免只停留在个案经验层面。","sub":[{"t":"从个案成效推广为普遍结论","d":"从单次战役的战果增幅（歼敌由两个旅到五个旅）确证方法的实际效力，把效力归因于该方法的实行，再据此判定该方法已在同类单位普遍实行并将产生普遍效果；以个案验证支撑方法的普遍有效性，使个别经验上升为一般结论。","p":["评西北大捷兼论解放军的新式整军运动"]}]},{"t":"对群众意见分析正误分别引导","d":"判断群众意见是否正确，不能凭其\"来自群众\"而一律照办或一律排斥，而须分析其内容的正误：正确的意见依据情况领导实现，不正确的意见教育改正。本思想确立领导在群众意见面前分析、引导的认识原则，防止命令主义与尾巴主义两个极端。","sub":[{"t":"执行群众正确意见并教育改正错误意见","d":"对待群众意见作清醒分析：凡属人民群众的正确意见，党依据情况领导群众加以实现；凡属不正确意见，教育群众加以改正；既反命令主义也反\"群众要怎样办就怎样办\"的尾巴主义，保持党与群众的正确关系。","p":["在晋绥干部会议上的讲话"]}]},{"t":"以全局方向统摄局部工作","d":"具体工作与政策的执行须以总体方向（总路线、总政策）为基准统摄与定位；只记住局部而忘记全局方向，执行中必然迷失方向、左右摇摆。本思想确立处理全局与局部关系的认识原则。","sub":[{"t":"以总路线总政策统摄具体政策执行","d":"执行各项具体工作路线与政策时，同时牢记其所从属的总路线总政策为方向基准；只记具体政策而忘记总路线，执行中就会迷失方向、左右摇摆、贻误工作。核心链：把握总路线总政策 → 统摄各项具体政策 → 保持清醒方向。","p":["在晋绥干部会议上的讲话"]}]},{"t":"真理表达须旗帜鲜明","d":"真理的传播与动员要求表达立场鲜明、直接有力；含混吞吞吐吐会损害真理的传递效果。面对立场与认识问题，应把立场的坚定性转化为表达的清晰与力度，不回避、不含糊，才能有效教育对象、动员行动。","sub":[{"t":"以旗帜鲜明的战斗风格宣传","d":"坚持真理并把真理旗帜鲜明地表达出来：宣传要生动、鲜明、尖锐，毫不吞吞吐吐，不隐瞒自己的观点，以战斗风格教育人民认识真理、动员人民为解放自己而斗争。核心链：坚持真理 → 旗帜鲜明 → 生动尖锐表达 → 教育动员。 # 待理论层归并的 L1","p":["对晋绥日报编辑人员的谈话"]},{"t":"在群众基础上自下而上建立代表机关","d":"建立真正的人民代表会议，以真正广大群众意志为基础，在贫农团、农会基础上自下而上逐级建立（区村→县→县以上）；一经建立即作为当地权力机关，一切应有权力归于代表会议及其选出的政府委员会；自然地而非勉强地联合各民主阶层。暂未确定合适的上位 L2。 # Method Dedup Index（37-42 批次） **批次：** 37-42（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 37、再克洛阳后给洛阳前线指挥部的电报；38、新解放区农村工作的策略问…","p":["在晋绥干部会议上的讲话"]}]},{"t":"按查明的实际关系分层处置，不按名义类别整体对待","d":"面对成分复杂的对象群体，其名义所属并不决定应当受到的对待。应先逐部分查明它与关键属性的实际关系或实际责任，再按查明结果分出层次，对不同层次给予不同强度的处置。名义相同而实际不同者不能一并处理，否则处置范围会随标签扩大而失去可核对的依据。","sub":[{"t":"按查明的实际经营主体划定没收界限","d":"处置成分复杂的经营组织时，不按经营者的政治身份一概归类，而是逐个查明经营主体究竟是谁：确实由各级政府经办的收归新的管理机构；由中小官员和地主所办的不在处置之列；一般工商业者经营的严禁侵犯。名声显赫者所办的企业按同一标准处理，不另设办法。界限落在事实核对上，而不在身份标签上。","p":["再克洛阳后给洛阳前线指挥部的电报"]},{"t":"区分主要责任者与一般成员并把处置权收归正式机构","d":"清理旧的统治体系时把成员分作两类：只处置其中的主要责任者，不牵连太广；一般成员以清理和登记的方式纳入管理。处置权统一由新的正式行政机构依法行使，不允许其他群众团体自行进入该区域执行；确属罪大恶极者才依其请求移交。打击面限于少数主要者，执行过程被纳入可控程序。","p":["再克洛阳后给洛阳前线指挥部的电报"]},{"t":"把打击面限于少数主要反革命分子而不按名义类别扩大","d":"在新解放区确定主要打击对象时，不把斗争面扩大到一般地主富农或广大群众，只限于政治上站在国民党方面、坚决反对我党我军的重要反革命分子，如同抗日时期只逮捕汉奸。打击强度以实际政治立场与行为为准，而非以名义身份整体对待。","p":["新解放区农村工作的策略问题"]}]},{"t":"按前提条件成熟程度分阶段推进深层变革","d":"深层社会变革不应一步到位。当局面未安定、群众未组织、外部威胁未移除时，先实行较浅改变以稳住秩序；待前提条件（环境安定、群众觉悟组织、威胁远离）具备，再推进更彻底的阶段。推进节奏由客观成熟度决定，而不由愿望或口号决定。","sub":[{"t":"依环境成熟程度把农村社会改革分为先减租减息后分地分财两阶段","d":"面对新解放区农村社会改革，不立即推进土地改革，先以减租减息、调剂种子口粮和合理负担稳住局面、保全资源。明确进入分浮财分土地阶段的客观前提：国民党已灭、环境安定、群众觉悟组织、战争推远，通常需一两年甚至三年。前提未成熟不越过该阶段。","p":["新解放区农村工作的策略问题"]},{"t":"以三项客观条件划定变革范围并对条件不备地区改用过渡政策","d":"决定一个地区今年能否开展土地改革，先按三项客观条件逐条核对：敌方武装已全部消灭、环境安定；基本群众绝大多数有分配土地要求；干部在数量质量上确能掌握。任何一项不具备即不列入今年范围，改在该类地区实行减租减息、调剂种子食粮与合理负担等过渡政策，联合或中立可联合或中立的社会力量；不分土地、不分浮财。","p":["一九四八年的土地改革工作和整党工作"]}]},{"t":"集体决策须先经有主责的事前准备形成成文方案","d":"重大集体决定不能从零开始靠临场议论，那样难以得到明确而周密的结论。应先由少数负责者提出问题、分析问题并形成经斟酌的方案文本，会议的作用是讨论、检验、补充并定稿；方案先于讨论，结论才能明确周密。","sub":[{"t":"以少数人负责的事前准备和成文方案开好决定政策的会议","d":"决定政策的干部会议不靠临场议论。会前由少数人商量（一人负主责），提出问题、分析问题、写出成文纲要并斟酌内容文字（简明扼要，反对长篇大论），再作报告、讨论、吸收意见、补充修改为定论。反对经验主义方法——事前毫无准备、听凭杂乱议论。会议规模按性质配置：讨论政策人数少、时间短，传达政策人数可多、时间不可过长。","p":["一九四八年的土地改革工作和整党工作"]},{"t":"以会前商谈和会议程序约束保障集体会议出实效","d":"面对集体会议流于形式、做不出决定或妨碍正常工作的问题，须在正式会议之前对复杂而有分歧意见的重要问题作个人商谈，使委员有思想准备，以免会议决定流于形式或不能做出决定；同时控制会议时间与次数、不沉溺于细小问题的讨论以免妨碍工作，并把常委会与全体会分开、不混在一起。","p":["关于健全党委制"]}]},{"t":"权属变更中以功能不中断为先决约束","d":"权属的转移可以在短时间内完成，接手一方的管理能力却往往滞后于它。这段时间内应把系统继续运转当作先决条件，宁可暂时保留原有承担者，或由内部人员先行组织起来，也不让功能因交接而停顿；正式替换在具备能力之后进行。","sub":[{"t":"接管能力不足时先维持原有运转","d":"接手一个正在运转的组织，若一时来不及或没有能力自行管理，不使其停业或空置，而是暂时委托原负责人继续管理、照常开业，直到能够派人接管为止。原负责人已经离去、组织已经停歇的，由内部业务人员选出代表组成管理委员会先行管理，随后再委任负责人与原有人员共同管理，并信任其管理能力。","p":["再克洛阳后给洛阳前线指挥部的电报"]}]},{"t":"以客观条件而非愿望决定改善的时机与幅度","d":"改善处境的要求本身正当，但何时提出、提到什么幅度，取决于所处系统的实际承受状况以及情况是否已经查明。局面尚未稳定、情况尚未弄清时按愿望提出要求，可能使原有的运转难以维持。因此应先稳住局面、查清情况，再按客观状况的变化确定改善的幅度。","sub":[{"t":"秩序与情况未明前推迟改善性要求","d":"进入新接管区域之初，不轻易提出提高待遇、缩短劳动时间一类要求，也不急于组织改善生活的群众性行动。先使管理有了头绪、人心安定，再经过周密调查弄清情况并备好妥善办法，然后按具体情况酌量处理。此前维持原有水平即算好的结果，此后改善幅度依经营是否向上发展来决定。","p":["再克洛阳后给洛阳前线指挥部的电报"]}]},{"t":"解决匮乏须用可持续的安排而非一次性给予","d":"一次性分配能立即缓解匮乏，却不改变匮乏的来源，同时会改变受助者的预期，使其转为依赖供给一方。因此应把资源投入有计划的、能够持续的供给安排，按轻重缓急逐步解决，并注意不使受助者失去自行维持的状态。","sub":[{"t":"以有计划的逐步供给替代一次性发放","d":"面对新接管区域的生活困难，先指定当前的中心问题即基本生活物资的供应，有计划地加以处理；对贫困人口的生活问题自接管之日起有计划地逐步解决，不采取一次性开仓分配的办法，也不提这类口号。理由有两条：一次性分配不解决供应本身，并且会使受助者养成依赖救济的心理。","p":["再克洛阳后给洛阳前线指挥部的电报"]}]},{"t":"归属转变后须整体重定对待方式","d":"一个对象由外部转为自己长期负责之后，它的损耗与破坏都由自己承担，原先基于对立关系形成的对待方式便全部失去依据。此时需要的不是逐条修补旧办法，而是换一个出发点重新确定全部做法，并按长期负责的预期约束当下的消耗行为。","sub":[{"t":"按归属转变重定对待方式并以长期负责约束当期行为","d":"当一个对象由对方管理转为自己负责管理，原先对待它的整套政策与策略即全部失去依据，必须以\"今后由自己负责管理\"为出发点重新确定，而不是逐条修补旧办法。据此一切按长期打算安排，严禁破坏生产资料、浪费生活资料与铺张消费。仍按对待对方管理时的办法行事，被判定为完全错误，而不作程度问题处理。","p":["再克洛阳后给洛阳前线指挥部的电报"]}]},{"t":"已定准则须经人选与训练到达执行层","d":"一项准则作出之后并不自动生效，执行者若不掌握它，仍会按原有习惯行动。因此要在关键位置上放置真正掌握该准则的人，再由其向全部执行人员逐条讲明，使准则成为执行层的共同依据，而不停留在作出决定的一端。","sub":[{"t":"以懂政策的主官和对全员的训练把政策送到执行层","d":"新政策确定之后不假定它会自动被执行。先在主要负责位置上委派确实懂得政策并且有能力的人，再由这些负责人对所属的一切工作人员加以训练，把各项政策和策略逐条讲明。经过这两步，执行者才不会沿用原来的习惯做法。政策是否起作用，取决于它有没有到达执行层。","p":["再克洛阳后给洛阳前线指挥部的电报"]}]},{"t":"选择能实现目标而不破坏既有系统稳定的手段","d":"追求既定目标时，优先选取能在不分散既有资源、不破坏社会秩序、不把负担不当转嫁的前提下实现收益的手段；避免表面上直接达成、却会迅速耗散资源或动摇支撑系统的做法。手段有效性以是否保全系统稳定来校验。","sub":[{"t":"以普遍减租减息加合理负担替代过早分浮财分土地","d":"在改革第一阶段，不以过早分配浮财与土地去\"解决问题\"，改为普遍实行减租减息使农民得实益、合理负担使地主富农多出钱。既让基本群众得实际好处，又不使社会财富迅速分散、不使军需负担过早落在农民身上，从而保全社会秩序与资源集中。","p":["新解放区农村工作的策略问题"]}]},{"t":"复杂变革须展开为完整环节序列并使执行者掌握全过程","d":"一项大任务若只抓其中一环，执行者便看不到其余环节如何衔接，容易顾此失彼。应把任务展开为按次序衔接的完整环节，限定时段全部完成，并让执行者了解全过程；全过程的完整性本身即是对片面性的纠正。","sub":[{"t":"把从土地改革到恢复生产的全部环节按时序衔接为完整工作过程","d":"在一个明确的季节窗口内，把从乡村调查到恢复生产的全部环节——调查、整党、发动群众、划分阶级、分配土地、建政、发证、调整负担、整理支部、转入生产——依次列定并限定全部完成，使干部了解整个工作过程；分配结果须使各主要阶层感觉公道，负担调整守公私兼顾原则。目的在于避免工作的片面性。","p":["一九四八年的土地改革工作和整党工作"]}]},{"t":"按客观具体情况区分对象以决定任务与方法","d":"任务与方法应随对象的具体情况而变化：地区类型、历史条件、问题是否已解决等不同，不能按同一套任务套用。先分析对象所处的实际阶段与条件，再据此确定其当前的任务与方法；对象性质已变化的，及时改换任务。","sub":[{"t":"从不同地区的具体情况出发区别对待以决定任务与方法","d":"不按统一公式决定任务，而以当地当时的具体情况为根据：教育干部分析具体情况，区别城市与农村，区别老区、半老区、接敌区和新区。封建制度已根本消灭、贫雇农已得大体平均土地的地区，认定土地问题已解决，不再提土地改革，中心任务转为恢复和发展生产、整党建政与支前；个别乡村有未完成事项的按实际补办。","p":["一九四八年的土地改革工作和整党工作"]}]},{"t":"统一决策的调整权集中于作出决定的一端而执行层不得擅自变更","d":"一项统一决定在贯彻中发现不适应时，允许执行者提出意见，但变更与否的决定权须保留在作出决定的一端。允许提出意见与允许自行改动是两回事：前者保存了下情上达的渠道，后者会破坏统一意志与统一纪律。","sub":[{"t":"维护统一纪律使执行层不得擅自变更既定政策","d":"已定政策须由执行层全部遵守，不许擅自修改；发现不适合当地情况者可以提出修改意见，但必须取得中央同意方能实行。坚决克服无纪律状态或无政府状态——既指擅自修改中央或上级政策策略、执行自以为是的不合统一意志的办法，也指以工作繁忙为借口事前不请示事后不报告；将一切可能和必须集中的权力集中于中央和中央代表机关。","p":["一九四八年的土地改革工作和整党工作"]}]},{"t":"信息与纠错须跟上行动节奏以及时具体的联系替代迟滞的总结","d":"行动快速展开、错误代价高昂时，纵向联系不能等待周期性总结：等来的信息已过时，纠错已来不及。应利用多种渠道保持高频、及时、具体的互通与纠正，使指示跟上运动进程；时效性优先于报告的完整性。","sub":[{"t":"以多种联系方法保持上下及时互通并随时纠正错误","d":"从中央到支部，利用无线电、有线电、电话、邮递、专人送信等通讯方法，小型会议、区域会议、个别谈话等会谈方法，小型巡视团、个别有威信委员的巡视方法，并利用通讯社和报纸，密切互相联系，掌握运动动态、随时互通情报、交流经验、及时纠正错误。不要等候数月后的总结性报告和一般性指示——往往过时、失去作用，来不及纠正、损失太大；需要不失时机的、生动的、具体的报告和指示。","p":["一九四八年的土地改革工作和整党工作"]}]},{"t":"重大决心须配以相应的计划与资源准备","d":"当决心超出既往规模或改变既有打法时，仅有意愿不能成立：须同步重新设计实施方案，并配足所需资源与善后安排；计划、资源与善后是决心的组成部分，而非事后的补充。","sub":[{"t":"为适应大决心相应重算作战计划并筹办军需善后","d":"确立超出既往规模的作战决心（攻占枢纽并打大歼灭战）之后，不使决心停留在愿望上，而重新考虑作战计划，并据此筹办全军军需（粮食、弹药、新兵等）和处理俘虏事宜，使两项决心具有相应的计划、资源与善后安排支撑。","p":["关于辽沈战役的作战方针"]},{"t":"按任务规模有计划地准备干部","d":"先估定新任务（接管新区、管理城市）所需的干部数量与层级，分级提前训练，使干部能随任务进程成批使用；来源上以老解放区为主，同时从国民党统治的大城市吸收文化水准较高的工人、知识分子，并利用旧机构中除去反动分子外的可用人员，以弥补供应不足。","p":["中共中央关于九月会议的通知"]}]},{"t":"集中完成主要任务时保持对全局工作的领导平衡","d":"领导重心转向某一主要任务时，其他方面并不因此失去重要性。应在力量集中投入当前中心的同时，把其余方面仍放在领导工作的适当位置，防止因专注一面而在整体上造成偏废。","sub":[{"t":"在突出主要任务时保持对全面工作的领导平衡","d":"安排领导工作时，把城市工作和农村工作、工业生产任务和农业生产任务放在适当位置，不因领导土地改革和农业生产而忽视或放松对城市工作和工业生产工作的领导。理由：已有许多大中小城市和广大的工矿交通企业，忽视或放松这一方面就要犯错误。","p":["一九四八年的土地改革工作和整党工作"]}]},{"t":"以决定全局的枢纽为着力点集中突破","d":"面对多个并列方向或对象而力量有限时，不以平分求全，而以能否决定全局为取舍标准识别枢纽，集中主要力量突破，敢于暂置其余；枢纽的取得即换取整体主动，次要者留待枢纽解决后再处理。","sub":[{"t":"置次要方向于不顾、集中主力攻取枢纽点","d":"面对多个可攻方向，不分散主力逐点应对，而以能否决定全局为标准选定枢纽方向（锦榆唐线），置次要之敌（长春、沈阳）于不顾，将主力集中于此线攻取诸点；因该线之敌互相孤立、攻歼确实可靠，枢纽一经取得，即使其他目的未达也能确保主动权。执行中始终以枢纽作战为注意中心。","p":["关于辽沈战役的作战方针"]}]},{"t":"攻其必救以调动对方在运动中解决","d":"当对方依托有利态势难以强攻时，不正面攻坚，而攻击其必须回应的关键点，迫使其脱离原有态势分兵来应，在对方被调动、运动与分散的状态中取得解决机会，变对方的有利条件为不利条件。","sub":[{"t":"攻其必救以诱敌分兵、在运动中连续歼击","d":"歼灭据守之敌的大兵团，不强攻坚固设防，而攻击其必须援救的枢纽点（锦州），迫使敌主力脱离阵地前来救援，创造连续大举歼灭援敌的战机；为此须确立打前所未有的大歼灭战、在敌全军来援时敢于同它作战的决心。","p":["关于辽沈战役的作战方针"]}]},{"t":"依双方态势的相对变化相机调整部署","d":"执行重大行动时方案不预先锁死，而以双方态势的实际相对发展为依据临机调整：快的先阻其进，慢的纵其深入再包围；判断随信息更新，部署随判断调整，而非按固定计划一用到底。","sub":[{"t":"按攻敌与援敌的相对进度相机决定阻援部署","d":"阻援与歼援的部署不预先固定，而以我方攻城进度与东西两路援敌进度为据临机决定：援敌进得快、需先阻其前进时，以总预备队加入阻援方向首先停止其前进；我方将克城而援敌进得慢时，则纵其深入大凌河以北，再转移兵力包围歼击。判断随情况更新，部署随判断调整。","p":["关于辽沈战役的作战方针"]}]},{"t":"重要问题由集体讨论决定而非个人包办","d":"面对重要问题，认识上应确认：决定权属于集体而非个人——问题愈重要，愈须交集体共同讨论、充分发表意见、形成明确决定后执行；集体的一致以实质一致而非形式一致为检验，个人负责只能在集体决定之下起作用。","sub":[{"t":"重要问题交委员会集体讨论并做出明确决定后执行","d":"面对领导机关个人包办重要问题的习气，应建立健全党委会议制度：一切重要问题（排除无关紧要的小问题及已讨论决定只待执行的问题）均须交委员会讨论，由到会委员充分发表意见，做出明确决定，然后分别执行；适用范围覆盖从中央局至基层的各类党委、党组及高级机关部委校室。集体领导与个人负责不可偏废，军队作战时首长有临机处置之权。","p":["关于健全党委制"]}]},{"t":"以可核实的力量对比核定任务目标","d":"重大任务是否成立、目标定多大，不由愿望或需要决定，而由双方力量的数字对比与已往实际成绩这类可核实材料决定；先作数量核算，再与实绩对照验证可达性，任务目标才可靠。","sub":[{"t":"以双方力量的数量对比核定战略任务目标","d":"面对重大战略任务，先核实敌我双方现有力量的数字（兵力、部队数、控制区与前后方分布），据此核定分阶段任务目标（每年歼敌数、总歼敌数），再以已往实际战绩核验可达性，最后按目标部署行动方向；大量利用俘虏补充兵源。任务目标建立在可核实数量材料之上，而非愿望之上。","p":["中共中央关于九月会议的通知"]}]},{"t":"依形势的阶段性转变调整组织方式与工作重心","d":"组织方式与工作重心不是固定的，应随形势的阶段转变（分割→统一、游击→正规、乡村→城市）而调整；先确认形势的根本变化，再判定旧方式在新形势下的弊端，据此改换权力配置与工作重心，使组织形态与新阶段相适应。","sub":[{"t":"依形势转变集中权力并转移工作重心","d":"确认形势由分割到统一、由游击战争到正规战争、由乡村到城市的转变后，判定旧组织方式造成无纪律无政府、地方主义与游击主义等弊端，据此把可能且必须集中的权力集中于中央，使战争过渡到正规战争，工作重心由乡村转到城市，并掌握近代交通工具、加强城市与工业管理。","p":["中共中央关于九月会议的通知"]}]},{"t":"从互补来源并行解决同一困难","d":"单一来源不足以满足的需要，可分解为两个性质互补的方向并行推进（如就地取给与恢复产出），并明确两方面缺一不可；以节约减少无谓消耗相配合，才能保证全局任务的完成。","sub":[{"t":"前方取给于敌与后方恢复生产双线解决资源困难","d":"面对物资、兵员与财政困难，先查明困难及成因，再把解决途径分解为两个互补来源——前方进入国民党区域就地取给、大部或全部自行解决军事需要，后方努力恢复发展老区工农业生产；同时改善组织工作、领导市场、解决交通与原料问题，并反对浪费、厉行节约；两方面任务都完成才能保证全局任务。","p":["中共中央关于九月会议的通知"]}]},{"t":"在推进任务的同步中纠正伴随产生的错误","d":"大规模推进一项任务时，须认识它会伴生组织、思想、作风上的不纯和政策越界的错误；不因错误而停止任务，也不放任错误，而是在推进的同时分别加以克服与纠正，借斗争与纠错提高组织成熟程度。","sub":[{"t":"在发动群众斗争中同步纠错整党","d":"发动大规模群众运动时，预见到并识别随之伴生的党内成分、思想、作风不纯和侵犯中农、破坏工商业、越过政策界限等\"左\"的错误；一方面通过整党克服不良现象，另一方面认真纠正政策越界，并以提高干部理论水平、扩大党内民主生活巩固成果，从而提高全党的政治成熟程度。 # Method Dedup Index（43-48 批次） **批次：** 43-48（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 43, 44, 45, 46, 47, 48","p":["中共中央关于九月会议的通知"]}]},{"t":"从内部关系而非表面强弱判断力量真实状况","d":"判断一个力量的真实强弱，应依据其内部关系结构（内部是否团结、与人民的关系、内在矛盾）而非其表面规模或声势；表面强大而内部关系破裂者，其实力基础已然虚弱，因而可胜。","sub":[{"t":"透过内部关系判明力量的真实强弱","d":"面对强大对手、需要判断胜负前景时，不以对方表面规模、武器或声势定强弱，而考察其内部关系：是否内部分崩离析、是否脱离人民、是否受无法解脱的经济危机困扰。据此判明其基础虚弱、能被战胜；同时避免对自己革命力量的过低估计。过高估敌、过低估我，是极大错误。","p":["全世界革命力量团结起来，反对帝国主义的侵略"]}]},{"t":"从对象所处的关系而非对象本身确定着力点","d":"处理一个对象时，决定能否成功的常常不是它自身的强弱，而是它与周围力量的联系。应先判明哪些力量与它相连、能起什么作用，再把主要力量用于减少这些联系的实际作用，对对象本身只投入达成所需的最低限度。","sub":[{"t":"按可能来援的力量确定攻击与阻援的兵力比例","d":"确定要歼灭的目标后，不把力量都投向该目标，而先判明有哪些力量可能前来援救、从哪些方向来。按固定折算比率算出攻击所需的最低兵力并留出余量，其余兵力全部用于阻援、打援和牵制，且须占总兵力一半以上。攻击部分只求够用，对付来援的部分宁多勿少；不作这样的分配，歼灭目标就达不到。","p":["关于淮海战役的的作战方针"]},{"t":"以多方向的次要行动降低对手可投入的援救力量","d":"当对手有若干可以互相增援的集团时，不把阻挡任务全交给正面阻援。在其侧翼、后方和交通联络线上分别布置小股力量：攻取侧后要点形成威胁，侧击交通线，在另一集团附近持续活动。每处用兵都不多，目的不是歼灭这些集团，而是使它们各自留出兵力自保，减少可以投入援救的份额。","p":["关于淮海战役的的作战方针"]},{"t":"先断退路、按决定全局的关键点确定攻击次序","d":"确定多处之敌的进攻优先序时，不按对象本身的大小或显眼程度排序，而先判断其唯一或主要退路，把首要兵力部署于控制退路的要点而非主城；先攻取决定全局的关键点（如控制海口的塘沽）使全局获得主动，把已孤立的最后目标留到最后解决。","p":["关于平津战役的作战方针"]}]},{"t":"按对象的实际状态而非表面估量其力量","d":"估量对象的力量时，不以名义规模、表面声势或局部较强部分为准，而以其整体的当前实际状态（士气、处境、动向）为依据；并计入估量双方常有的偏差——容易高估对方、对方也易高估自身，据此校正判断。","sub":[{"t":"依据对象整体实际状态估量其力量并校正估计偏差","d":"估量对手力量时，先看其整体当前实际状态——攻击精神、处境与被围程度——而不因个别部队较强就夸大整体；同时把双方常有的估计偏差纳入校正：敌人往往高估自身力量、低估我方的积极性，我方过去也吃过过高估计敌人战斗力的亏。","p":["关于平津战役的作战方针"]}]},{"t":"以客观事实破除主观愿望形成的幻想判断","d":"判断形势或处境时，不能以\"希望如此\"为准，而须以客观事实为准。对基于主观愿望形成的乐观判断——如以为尚有退路、外援将至、装备占优——要用具体可验证的事实逐条推翻；幻想破除后，对形势与选择的认识随之落到实际。","sub":[{"t":"以具体战绩事实破除敌方侥幸幻想","d":"对陷于包围而仍抱突围、靠拢外援或装备优势幻想的敌军，先作\"山穷水尽\"的总判断，再逐条否定其各条可恃之路——突围突不出去、外援已断、洋装备敌不过土炸药，并以损失师数、伤俘过半、阵地缩小等具体数字印证，使其认清绝境、放弃抵抗依据。","p":["敦促杜聿明等投降书"]},{"t":"以长期行为记录而非主观愿望判定对象的可变性","d":"判断能否对对象妥协时，不以己方善良愿望或对象一时的姿态为准，而以其长期历史行为记录为据：检验善意是否改变其本性一分一厘，判定其本性不可改，从而破除对对象改好的幻想，决定彻底消灭而不怜惜。","p":["将革命进行到底"]}]},{"t":"按行动实施时对象的预计状态作准备","d":"对象在行动开始之前还会继续变化，按其当前状态配置的力量，到实施时可能不足。准备应以实施时刻的预计状态为准，而这一预计要依据对象已经出现的变动迹象作出，不凭空加码。","sub":[{"t":"按目标届时可能达到的力量预估攻击兵力","d":"为尚未开始的阶段配置攻击力量时，不按目标当前的实有力量计算，而按发起行动时它可能达到的力量计算。先从对方已经发生的调动中判明可能增加的来源、方式与数量，把现有与预增相加，再按同一折算比率得出所需攻击兵力；其余主力仍按原则担任打援和钳制。","p":["关于淮海战役的的作战方针"]}]},{"t":"按问题结构的同一性移用已验证的做法","d":"两件事的对象和场合不同，但如果起决定作用的关系是同一结构，前一件中已经见效的做法就可以直接移用。移用的是关系比例和处理原则，不是具体安排；判断能否移用的依据是结构相同，而不是题材相似。","sub":[{"t":"判定新任务与旧任务同构后沿用其部署原则","d":"面对新任务时，先判断它与已完成的某次任务是否处在同一关系结构中，即是否同样存在\"要歼灭一部、而对方另有力量可援\"的关系。结构相同则直接沿用上次已见成效的部署原则，不重新设计；目标、地点和数量按新任务替换，比例原则本身不变，并明确指出不照此办理就达不到目的。","p":["关于淮海战役的的作战方针"]}]},{"t":"把连续过程切分为各有单一重心和明确时段的段落","d":"一个不能一次完成的过程，只有被切分成前后相接的段落才可估计、可调配。切分依据是每段的重心不同，一段之内只服务一个主要目标；时段以幅度给出并依次相接，前一段的完成时点即后一段的起点。","sub":[{"t":"把长过程分成各有单一重心的阶段并逐段给出时间幅度","d":"一次完不成的任务，按方向或对象分成若干阶段，每阶段只确定一个重心目标，其余力量都围绕这个重心配置，阶段之间不并行推进。每阶段给出完成时间的幅度而不是单一日期，各段相加得出全过程的时间幅度。阶段一经划分，力量也随之在各阶段之间重新配置。","p":["关于淮海战役的的作战方针"]},{"t":"把当前任务排入后续任务序列以确定其完成时点","d":"为一项任务定下部署后，把它之后的若干项任务按时间顺序一并排出：本任务的完成月份、随后的休整时段、下一步与友邻的协同作战及其要达到的状态、再后一步的主要行动。后续各项只标明时段与性质，不作具体部署。当前任务的完成时点由此固定下来，后续各项也各自获得起止范围。","p":["关于淮海战役的的作战方针"]}]},{"t":"以先进力量为首的统一组织聚合分散的力量","d":"面对共同强敌而力量分散时，以公认先进、已验证的领先力量为首，把多层次、分散的力量纳入统一组织与共同方针之下，方能形成战胜强敌的合力；分散各自为战则不能胜利。","sub":[{"t":"以先进力量为首组织多层次的统一战线","d":"面对强敌、分散的革命力量各自为战时，先确立公认先进、已验证的领先力量为统一的首脑；再把两个层次的力量都组织起来——每一国内部一切革命力量先团结，进而一切国家的革命力量团结；在首脑领导下组成统一阵线，并遵循正确的政策。不如此组织则不能胜利。","p":["全世界革命力量团结起来，反对帝国主义的侵略"]}]},{"t":"以已验证的范式参照建立自身的同类力量","d":"在需要新建一类组织而缺乏经验时，以历史上已证明有效的同类范式为参照来建立自身组织，而不是凭空设计；可移用的是其根本理论与作风，具体环境按自身情况替换。","sub":[{"t":"以已验证的榜样为参照建立自身的革命力量","d":"要建立自身的革命组织而缺乏现成范式时，先找到已被历史证明有效的同类组织（其理论、作风、建党建军经验），把它作为榜样；再依其范式建立和发展自身的组织，不另起一套。中国共产党的建立即依苏联共产党的榜样。","p":["全世界革命力量团结起来，反对帝国主义的侵略"]}]},{"t":"以时间序列数量对比支撑形势判断","d":"判断形势是否发生根本变化，不以单一时点或笼统印象为准，而把同类数量按时间先后排出并逐期对比，以增减的方向、幅度及其时段位置支撑\"已经转变\"的判断。","sub":[{"t":"用逐时点兵力数量对比判定优势转化","d":"判断双方力量对比是否根本变化时，把双方兵力按战争之初、第二年底、第三年度头四个月后等时点排出，逐期列出数量增减，并给出损耗与补充的差数说明增减原因；总量序列之外另取具体时段内的突变数据，以增减方向与幅度支撑\"优势已转化\"的结论。","p":["中国军事形势的重大变化"]}]},{"t":"以新旧判断对照显示认识修正幅度","d":"当事实变化使旧判断失效时，把旧判断与新判断并置对照，用两者的差别幅度标明认识须修正的方向与程度，并区分不同层面的完成时限，不把趋势判断误当完成状态。","sub":[{"t":"以新旧时限估计对照修正预判","d":"当新数据使原有判断失效时，先复述原估计，再给出依据新数据形成的新估计，两相对照使修正的必要与幅度一目了然；并区分完成时限不同的层面，避免对判断的过度延伸。","p":["中国军事形势的重大变化"]}]},{"t":"判断之后限定适用范围并保留未竟条件","d":"作出向好或根本性的判断后，主动划定其覆盖范围，明确指出尚未完成部分仍需的时间与条件，把判断与行动要求相接，防止把趋势判断当作已完成状态。","sub":[{"t":"判定根本变化后补足未竟条件与行动要求","d":"提出\"力量对比已根本变化\"的总判断后，随即补上限定：指出判断未覆盖的部分尚需较多时间，明确提出实现最终结果所需的条件（各界团结一致、加紧努力），使乐观判断不脱离完成目标所需的后续行动。","p":["中国军事形势的重大变化"]}]},{"t":"为完成整体准备而有意节制局部行动","d":"当整体目标尚须先完成准备、而过早的局部行动会促使对象提前作出破坏性决策时，应主动节制局部行动的强度与时机：能暂缓解决的暂缓，只作必要的隔离与包围，把决定性动作保留到整体条件成熟之后。","sub":[{"t":"以围而不打、隔而不围的区分控制歼灭时机","d":"在全局部署尚未完成、敌人又有逃跑倾向时，把\"暂不歼灭\"与\"只作隔离\"区分使用：对已包围的要点暂缓攻击（围而不打），对只需防止其逃走的敌人只作战略包围、隔断联系（隔而不围），避免过早打掉诸敌迫使其余敌人迅速决策逃跑；待部署完成后再逐点歼击。","p":["关于平津战役的作战方针"]}]},{"t":"分割孤立相互联系的对象后逐个解决","d":"当对象由若干相互联系、能互援或联动的部分构成时，先以力量切断各部分之间的联系，使整体化为互不相连的孤立部分，再逐一对孤立部分采取行动；切断联系本身即是削弱整体力量的主要手段。","sub":[{"t":"以多方向兵力分割孤立相互联系的诸敌","d":"对相互毗邻、可能互援或联动的多处敌人，用多方向兵力威胁使其不敢妄动，再用部分兵力插入诸点之间隔断联系，并构筑两面阻击阵地，使敌人既不能互相援救也不能跑掉；然后休整部队，逐个攻歼较小之敌。","p":["关于平津战役的作战方针"]}]},{"t":"以利害并陈与出路保证促使对方转变决策","d":"要使对抗或犹豫中的对方改变选择，单靠施压不够。须同时使其看清继续对抗的必然代价，并给出可信、低风险的出路：以同类先例证明可行，以明确保证降低顾虑，最后把选择交还对方由其权衡自决。","sub":[{"t":"以先例与生命保证促敌选择唯一生路","d":"破除幻想后，从敌方将领对部下与家属的责任切入，举同类部队放下武器的先例，明确承诺保证高级将领与全体官兵生命安全，把放下武器框定为唯一生路，留出对方自决余地，并断言继续抵抗终将被全部解决。","p":["敦促杜聿明等投降书"]}]},{"t":"以对象既有手段的失效预见其手段的转换","d":"判断对抗对象时，不假定其按原有方式一成不变；当其一类手段已被现实证明失效时，应预见其转向另一类手段，并具体查明新手段的形式，再据此组织对策。","sub":[{"t":"预见敌方策略随形势转换并查明其新手段形式","d":"面对不会自行退出的对抗对象，先断定其原有手段已不能阻止局势发展，预见其转向新的手段类型（如由军事转向政治斗争），具体查明新手段的形式（\"和平\"阴谋、混入阵营组织反对派），并以确凿情报核实后再组织对策。","p":["将革命进行到底"]}]},{"t":"以排除中间项的明确抉择迫使相关方选择立场","d":"当各方须在重大问题上表态时，把问题提炼为非此即彼的明确抉择，分别讲清两条路的后果，要求每个相关方必须选择并表明态度，同时把\"中间路线\"\"反对派\"等模糊中间项排除，使立场清晰、行动统一。","sub":[{"t":"以排除中间路的明确抉择迫使各方表明立场","d":"把复杂问题提炼为\"是……还是……\"的非此即彼抉择，分别说明两条路线的后果，要求每个相关团体必须考虑、选择并表明态度，把\"反对派\"\"中间路线\"等中间项排除在外，使各方立场清晰、行动统一。","p":["将革命进行到底"]}]},{"t":"联合阵营在扩大中坚持巩固、防止异质力量混入","d":"建设联合阵营时，扩大与巩固必须同步：扩大即容纳一切愿意参加者并记住朋友，巩固即不容坏人混入、不容错误主张获胜；以对共同敌人的实际态度划界，扩大而不失纯洁。","sub":[{"t":"革命阵营在扩大中坚持巩固、防止异质力量混入","d":"建设统一阵营时，把扩大与巩固同时进行：扩大即容纳一切愿意参加革命事业的人、记住真正的朋友；巩固即不容许坏人侵入、不容许错误的主张获胜；并以对人民和敌人的实际态度划界，识别谁是人民的朋友。 # Method Dedup Index（49-54 批次） **批次：** 49-54（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 49、评战犯求和；50、中共中央毛泽东主席关于时局的声明；51、中共发言人评南京行政院的决议；52、中共发言人关于命令国民党…","p":["将革命进行到底"]}]},{"t":"以行为与自供而非声明判断意图","d":"判断一种主张的真实意图，不以自我标榜的理由为据，而以可观察的行为、主动声明与出场时机为依据；行为事实与自供往往比第三方反驳更直接、更可靠。","sub":[{"t":"以是否执行逮捕战犯等具体行动检验和谈诚意","d":"面对自称急切求和、标榜\"以拯救人民为前提\"的对手，不理会其自我表白，而提出必须立即执行的具体行动——重新逮捕已获释战犯、逮捕内战罪犯、防止战犯逃跑；对方所称\"先决条件\"实为其已承认惩办战犯为谈判基础后自然产生的后续要求，以是否执行这些行动检验诚意，若战犯跑掉则其\"和平诚意\"无从表现。","p":["中共发言人关于命令国民党反动政府重新逮捕前日本侵华军总司令冈村宁次和逮捕国民党内战罪犯的谈话","中共发言人关于和平条件必须包括惩办日本战犯和国民党战犯的声明"]},{"t":"以对手求和行动本身作为认识其意图的证据","d":"判断对手公开主张的真实意图，不以其宣称的正当性为准，而以\"谁、何时、为何主动提出\"这一行动事实为；劣势一方主动求和，说明所谓\"和平\"正是其迫切所需，出场即供词。","p":["评战犯求和"]},{"t":"以是否商讨具体条件检验和谈诚意","d":"面对对方以\"先无条件停战再谈判\"之类的抽象前提回避实质协商，不纠缠其口号，而要求先商讨和平的基本条件并订立双方同意的停战协定；以对方是否愿意进入具体条件的商讨、是否愿意取消无理前提作为检验诚意的尺度，推出\"不肯谈具体条件即无诚意\"的判断。","p":["中共发言人评南京行政院的决议"]},{"t":"以逐层追问因果由来揭示主张的真实性质","d":"对方标榜\"缩短战争时间\"\"以拯救人民为前提\"，不采信其标榜，而逐层追问其求和主张的由来：为什么求和（因打了败仗）、为什么打败仗（因发动反人民的国内战争）、何时发动（日本投降以后）、打谁（人民解放军和人民解放区）、以何力量（从人民方面捉来和刮来的力量）；把\"和平\"还原为战败与不义战争的必然产物，真实性质与标榜的反差自行显露。","p":["中共发言人关于和平条件必须包括惩办日本战犯和国民党战犯的声明"]}]},{"t":"在表象主张与实际利益的对照中揭示对象真实性质","d":"面对对象的抽象主张，将其逐条还原为具体利益主体与真实所指；措辞与所指的反差本身即暴露主张的真实性质与目的，而非停留在字面论证。","sub":[{"t":"逐条转译对方抽象措辞为具体利益所指","d":"对以正当化抽象措辞包装的主张，不逐字辩难，而将每条措辞还原为具体阶级主体与利益所指；措辞与利益结构并列呈现时，真实目的自行显露。","p":["评战犯求和"]},{"t":"以实质条件清单判别和平真伪","d":"面对对方自称\"和平\"的和谈建议，不以其言辞、身份或愿望为据，而逐项审查其附带条件；条件仍保存伪宪法、伪法统、反动军队等根本性反动安排时，即为\"继续战争的条件\"而非\"和平的条件\"，可判定提议虚伪；只有对方放弃反动条件、承认我方条件清单，所建立的和平才是真正的和平。","p":["中共中央毛泽东主席关于时局的声明"]}]},{"t":"以主张作出主体的权限与程序资格判定其效力","d":"判断一个决定能否成立，不只看其内容与措辞，还要核查作出它的机构是否具有相应职权与程序资格；越权主体擅自作出的决定不具效力，也不得推翻有权主体的既有决定。","sub":[{"t":"以职权范围判定决议是否越权无效","d":"对下级机构作出的决议，先明确该机构的职权边界，再对照决议内容是否越过职权、是否擅改上级既有决定；越权主体作出的决议即无资格、不具效力，无权推翻有权主体的建议。","p":["中共发言人评南京行政院的决议"]},{"t":"以对方主体实体存在核查判定其要求与指责的效力","d":"对方以\"态度不够郑重\"之类的指责要求调整我方姿态，不与之处处辩解，而逐点核查其自称身份的实体存在——行政机关有无、行政首脑有无、驻地何所在；南京无行政机关、广州无行政首脑、上海两者皆无、奉化只有宣布\"退休\"的伪总统，主体至多为假定的象征性存在；实体资格既缺，其指责与要求即失去效力与分量。","p":["中共发言人关于和平条件必须包括惩办日本战犯和国民党战犯的声明"]}]},{"t":"以可核查的数量核算检验虚张声势","d":"对夸张的数量宣称，以可核查的基数按字面核算，或以对方自身前提归谬；演算结果或推演结论自相矛盾时，即可判定虚夸，而非空泛争论规模。","sub":[{"t":"按字面演算与归谬检验对方数量宣称","d":"对夸张的数量宣称，将倍数、比例按字面代入已知基数演算，使结果荒谬到不攻自破；亦可接受对方前提归谬，令自辩解导出自相矛盾结论，检验并戳穿虚张声势。","p":["评战犯求和"]}]},{"t":"以受众实际反应判断言论的实际效力","d":"判断言论或宣传的实际效力，以受众与市场的可观察反应为检验依据，而非言论自身的宣称与声势；反应冷淡即说明其缺乏现实基础与说服力。","sub":[{"t":"以受众市场反应检验言论销路","d":"判断公开言论是否真有效力，不以其自我声势为准，而观察受众与市场反应——物价走势、民众态度、外部反映等可观察信号；信号冷淡即判定其无销路、无人信服。","p":["评战犯求和"]}]},{"t":"主张与实力准备并行","d":"提出主张时必须同步保持使主张得以实现的力量准备；主张与实力并行，才不至使主张沦为空谈或软弱，也才能在对方不接受主张时保有强制其接受的能力。","sub":[{"t":"谈判主张与战斗准备并行","d":"在提出和平谈判主张的同时，明确在谈判目标真正实现以前不放松斗争准备；以军事力量为后盾，对任何敢于反抗的反动派坚决、彻底、干净、全部地歼灭，使和平主张不因争取和谈而松懈战斗努力。","p":["中共中央毛泽东主席关于时局的声明"]}]},{"t":"以主张者自身前后承诺的一致性检验新主张","d":"判断一个新主张是否有效，不以孤立字面为据，而将其与主张者自己此前的正式承诺并置对照；同一主体的前后主张相互冲突、自我推翻时，新主张即丧失效力，无需另行辩难。","sub":[{"t":"以对方先后声明相互对照判定新决议无效","d":"面对对手另立的新决议，不孤立辩其内容，而将其与自己先前正式声明及双方既有建议并置对照，指出其既不拥护也不反对既有建议、直接推翻己方总统声明；随即质问应以何者为准，前后矛盾即判定新决议不能成立。","p":["中共发言人评南京行政院的决议"]}]},{"t":"以方案提出时的事实为基准判定完备性并随新事实更新方案","d":"判断一个既有方案或判断是否完备，以它提出时已存在的事实为基准；方案确立之后由对方行动新产生的事实，必须被方案补充覆盖而非拒之门外；此时补充要求不是节外生枝，而是对既有基准的忠实延续，制造新事实者应承担方案随之变动的责任。","sub":[{"t":"以事实发生的时间点对照判定议题归属并更新方案","d":"对方把新出现的问题斥为\"节外生枝\"\"与谈判无关\"，不与之抽象辩难，而以时间点对照：既有方案提出时该事实尚未发生，事实在方案确立之后由对方行动新造成，故新问题属于谈判范围、方案必须以补充项目覆盖之；判定归属以\"方案提出时该事实是否存在\"为基准，制造新事实者才是真正的节外生枝者。 # Method Dedup Index（55-60 批次） **批次：** 55-60（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 55、四分五裂的反动派为什么还要空…","p":["中共发言人关于和平条件必须包括惩办日本战犯和国民党战犯的声明"]}]},{"t":"在表象主张与实际行动、立场的对照中揭示对象真实性质","d":"面对对象的表面主张，将其与实际立场、内部矛盾和客观效果对照；当主张与真实处境、意图相冲突时，这一反差即暴露其本质与目的，而非停留在口号本身。","sub":[{"t":"从口号主张与实际立场的矛盾中揭露真实目的","d":"面对一个政治集团高喊的冠冕口号，不就口号论口号，而是把它与其实际立场、内部状态和真实意图对照：当主张（如“全面和平”）与其四分五裂、互相矛盾的现实处境和“取消和平、妄想再战”的实际意图相冲突时，二者的反差本身就揭示了口号的真正目的。","p":["四分五裂的反动派为什么还要空喊“全面和平”？"]},{"t":"用对方内部局部立场的相互冲突反证其整体立场的虚假","d":"当对手以“全面/整体”名义发声时，不正面与其整体口号缠斗，而是考察其体系内部各局部（下级单位、派系）之间是否相互矛盾；若其自身各局部立场彼此冲突、互不支持，便说明它根本不存在所声称的统一整体立场，从而反证其整体口号的虚假。","p":["四分五裂的反动派为什么还要空喊“全面和平”？"]},{"t":"追溯政治口号的外来来源与客观效果以判定其工具性质","d":"对一项被包装为善意的政治举动（如“和平攻势”），不只看其名义，还追溯其外部来源（出自何方、受谁指使）与客观效果（是否反噬其主张者）；当来源揭示其为外来工具、效果证明适得其反时，即可判定该举动的工具性质而非真诚主张。","p":["四分五裂的反动派为什么还要空喊“全面和平”？"]},{"t":"以对象自身前后主张与行为的反差揭示其真实立场","d":"面对一个政治集团，先固定其早先公开主张（如“以拯救人民为前提”“呼吁和平”），再提取其后来实际立场与行动（如主战、保护战犯），将二者并置；当同一对象的前后主张自相冲突时，这一反差本身即暴露其真实立场与目的，无需另作推论。","p":["国民党反动派由“呼吁和平”变为呼吁战争"]},{"t":"用对方曾加诸我方的罪名返还其自身以证其自相矛盾","d":"当对手曾把某一罪名（如“拖延时间，延长战祸”）加于我方时，先固定该罪名原由其自身所下定义，再指出对手当前行为恰符合该定义；将对手自己的指控框架返还其身，使其自我指涉地暴露前后矛盾与虚伪，比正面争辩更有力。","p":["国民党反动派由“呼吁和平”变为呼吁战争"]},{"t":"以可计算的具体事实对比检验抽象口号的合理性","d":"面对一个抽象口号（如“以拯救人民为前提”），引入可计算的客观事实（如四亿七千五百万人口对一百几十个战犯的数量关系），要求按事实做具体比较；当数量反差使口号涵盖对象与真实受益者明显错位时，抽象宣称的合理性即被具体事实压垮，立场归属随之显形。","p":["国民党反动派由“呼吁和平”变为呼吁战争"]},{"t":"从对方辩解的内部矛盾推出其不敢承认的结论","d":"面对对手关于自身责任的辩解，按对方自己的前提推出其不敢接受的结论（既然\"应剿匪\"就应\"戡乱\"，为何停战求和），再对照其措辞与条款的让步变化（改称\"共党\"、取消原有条款），指出其自相矛盾；从矛盾处判定对方口头主张与实际承认之间的差距，逼出其不敢承认的结论。","p":["评国民党对战争责任问题的几种答案"]},{"t":"以各方对检验条件的接受与回避差异判定真实立场","d":"面对同一阵营内各方对责任问题的不同说法，以统一检验条件（是否接受惩办战犯、是否以八条为谈判基础）比较各方的接受、回避与变通程度；敢于承认、吞吞吐吐与以\"不公平\"搪塞的差异，本身就是其真实立场与自知有罪程度的直接表现，无需追问其自称立场。","p":["评国民党对战争责任问题的几种答案"]},{"t":"以实际行动倾向而非口头宣言判别政治集团的性质与分化","d":"面对一个政治集团，不停留于其口头宣言，而按实际行动倾向将其内部分为坚持敌对、愿意转变、徘徊观望等类别，再据各类别的实际构成判断整个集团的真实性质与地位。","p":["南京政府向何处去？"]},{"t":"以最低限度的具体处置事件检验和谈诚意","d":"对方宣称接受和谈条件时，不以宣言为凭，而以能否处置一件具体事件（如逮捕并严惩制造惨案的主凶与反革命首要）作为最低限度的诚意标准；做不到即应协助我方直接办理，用具体行动上的检验戳穿空谈、换取立功自赎。","p":["南京政府向何处去？"]}]},{"t":"从多重任务中抓住中心环节带动全局","d":"面对同时并存的多种任务，不平均使用力量，先识别决定全局的中心环节，以它统摄其他工作并为它服务，保证全局不偏离主要目标。","sub":[{"t":"确定中心工作以统摄其他工作","d":"当多项任务并存而力量有限时，先根据当前阶段决定全局的中心问题确定一个中心工作，把其他一切工作安排为围绕并服务于此中心的工作，避免平均用力、盲目乱抓乱碰、忘记中心任务而导致全局失序。","p":["在中国共产党第七届中央委员会第二次全体会议上的报告"]},{"t":"中心工作与各方面工作统筹兼顾","d":"像弹钢琴一样，先抓紧中心工作，同时围绕中心兼顾其他方面工作，凡有问题的地方都要点到，有节奏地互相配合，不因只注意一部分而丢掉别的。","p":["党委会的工作方法"]}]},{"t":"以实际力量分布作为判断政治形势基本事实的依据","d":"面对政治形势，先识别各力量的实际分布与整合程度，把“谁实际掌握全面力量”这一结构性事实作为判断的基本依据，而非依据口号或名义。","sub":[{"t":"以实际力量分布作为判断政治形势基本事实的依据","d":"判断政治形势时，不被各方口号迷惑，而是确认哪一方实际掌握“全面”的力量（组织、军队、民心、同盟），哪一方业已四分五裂；把“谁握有全面力量”这一结构性事实作为任何郑重判断都不可忽略的基本事实。","p":["四分五裂的反动派为什么还要空喊“全面和平”？"]}]},{"t":"从认识对象的自我承认与供词中获取判断依据","d":"判断一个对象时，对象在无意中承认或暴露的事实与供词，比其自觉的论证更可靠；把对方的自我承认与其结论分离，按对象自己的逻辑推行，即可直接获得支撑判断的，无需外部举证。","sub":[{"t":"把对方无意承认的事实与供词转化为己方证据","d":"当对手言论中无意说出对己方有利的事实（战争浩劫的实况、己方迷信武力发动战争），把这一自我承认与其辩解结论剥离，再按对方自己的逻辑推行——\"战犯的应当惩办，是浩劫的逻辑的结论\"——把供词直接转化为己方主张的，不依赖外部举证。","p":["评国民党对战争责任问题的几种答案"]}]},{"t":"从决定全局的基本国情出发认识问题","d":"制定全局性政策时，先确认决定全局的最基本客观国情（如经济结构比重、各经济成分的性质与地位），把它作为一切认识与决策的出发点，并同时防止只看到一端而犯右倾或“左”倾错误。","sub":[{"t":"以基本国情为政策推导的出发点","d":"面对全局性政策决策，先确认决定全局的最基本社会经济事实（现代工业与个体农业在国民经济中的比重、各经济成分的性质与地位），以此为一切问题的出发点逐条推导政策；同时防止只看一端——忽视进步成分或忽视落后成分——导致的右倾或“左”倾错误。","p":["在中国共产党第七届中央委员会第二次全体会议上的报告"]}]},{"t":"按具体条件在两种极端之间掌握分寸","d":"认识上不把对象当作单一性质，而是把握其两重性（须利用又须限制），据此明确两端的错误，再按具体条件在极端之间确定恰当分寸，避免绝对化。","sub":[{"t":"在两种倾向之间恰如其分地确定政策界限","d":"面对具有两面性质、须利用又须限制的对象，先明确两端各会导致的错误（放任不管或限制过死，迁就或关门），再按各地、各业、各时期的具体情况，在两端之间确定恰如其分、有伸缩性的政策界限，既保留积极作用又限制消极作用。","p":["在中国共产党第七届中央委员会第二次全体会议上的报告"]}]},{"t":"在阶段转折中预见新的矛盾与危险","d":"阶段转折不会消灭矛盾，只是更换矛盾的形式；胜利、顺利本身会带来新的危险，认识上须预见转折后的新矛盾并预先防范。","sub":[{"t":"预先估计新阶段的危险并防范","d":"在形势根本转折（如由夺取胜利转为巩固胜利）时，不只看到有利一面，预先估计新阶段将产生的危险（骄傲、贪图享乐、被捧场软化），把问题向党内讲明白，从思想上充分准备，用批评和自我批评的武器保持优良作风，防止在新条件下打败仗。","p":["在中国共产党第七届中央委员会第二次全体会议上的报告"]}]},{"t":"原则性与灵活性相统一","d":"坚持根本原则与策略上的灵活并不矛盾：原则必须坚定，灵活性服务于并实现原则；在原则与策略的张力中掌握统一，才能达到目的。","sub":[{"t":"原则性与灵活性相结合","d":"面对复杂对手的谈判或合作，先确定必须坚持的原则，再围绕原则安排一切许可的和必需的灵活性（交换条件、局部让步），并准备清醒的头脑对付对方策略，做到原则坚定、方法灵活。","p":["在中国共产党第七届中央委员会第二次全体会议上的报告"]}]},{"t":"认识与本领随任务转换而更新","d":"任务改变了，认识与本领必须跟着改变；把学习新本领作为完成新任务的前提，通过组织学习补足能力差距，才能在新任务中站住脚。","sub":[{"t":"以学习补足新任务的本领差距","d":"当任务转换而自身本领不足时，不回避新任务，把新任务所需的知识和技能列为必须学会的对象，用极大努力去学习，并把整个组织作为培养本领的场所，以学习缩小本领差距、保证新任务完成。","p":["在中国共产党第七届中央委员会第二次全体会议上的报告"]}]},{"t":"依托集体成员完成组织任务","d":"领导任务不能靠负责人个人包办，而要依靠集体各成员发挥作用；负责人通过宣传、组织与协调成员关系，使集体行动整齐，才能完成整体任务。","sub":[{"t":"班子负责人带头带动一班人","d":"领导集体负责人不单靠个人发号施令，先学习研究，再向成员做宣传与组织工作，善于处理与委员的关系、把会议开好，使一班人动作整齐，从而带动整体完成任务。","p":["党委会的工作方法"]}]},{"t":"成员间公开交流信息与意见以形成统一共识","d":"集体决策与共识的质量，取决于成员间能否公开交流彼此掌握的信息与对问题的意见；信息封闭、问题积压与背后议论会使集体认识分裂、问题久拖不决，须以公开交流消除隔阂。","sub":[{"t":"问题摆上桌面公开讨论解决","d":"有了分歧和问题不在背后议论，及时开会把问题摆到桌面上公开讨论，规定几条形成决议；同时成员间互相谅解，避免问题积压拖延而长期不得解决，甚至一拖几年。","p":["党委会的工作方法"]},{"t":"成员间互通情况形成共同语言","d":"各成员把彼此知道的情况互相通知、互相交流，使集体拥有共同的信息与语言，避免彼此封闭造成的认识隔阂与\"没有共同语言\"。","p":["党委会的工作方法"]}]},{"t":"决定形成前先采集实际意见并加以分析","d":"决策者不能强不知以为知，应先向实际知情者请教，收集材料与意见并加以分析，正确者采纳、错误者批评，以综合后的实际意见作为形成决定的基础。","sub":[{"t":"决策前向下级请教并甄别意见","d":"对不懂不解之事先做学生向下级请教，听取并分析其意见：正确的采纳照做，错误的也要听但不照做并予批评；在综合下级材料与意见的基础上再作决定，先听后断、先学后教。","p":["党委会的工作方法"]}]},{"t":"重点事项落实依靠持续用力","d":"重要事项的推进，形式上的开始不等于落实；关键在于保持紧抓不放的持续用力，一旦放松即等于没有抓，实质成果取决于用力程度。","sub":[{"t":"对主要工作紧抓不放","d":"对主要工作不但要\"抓\"，而且要\"抓紧\"，紧抓不放才能落到实处；只做表面姿态而放松用力，等于不抓，难以取得实效。","p":["党委会的工作方法"]}]},{"t":"以数量分析把握质量界限","d":"任何质量都表现为一定的数量；判断问题须从数量方面入手，掌握基本统计与数量界限，才能把握质量、作出有根据的决定，避免主观臆断。","sub":[{"t":"用数量统计与数量界限支撑判断","d":"判断情况先注意数量方面，掌握基本统计、主要百分比与决定质量的数量界限，如各阶层人口与土地比例、划分富农的剥削界限，据此定政策，避免无根据的主观决定。","p":["党委会的工作方法"]}]},{"t":"行动质量取决于事先的告知与准备","d":"集体议事或行动的质量，取决于事先的预告与准备；先让参与者知晓议题、备妥材料与方案，再付诸行动，是避免仓促凑合、保证效能的前提。","sub":[{"t":"开会先发预告并备妥材料再召开","d":"开会先出\"安民告示\"，预告要讨论和解决什么问题，使与会者早作准备；事先备好报告与决议草案，没有准备就不急于开会，避免临时凑合。","p":["党委会的工作方法"]}]},{"t":"组织的协作基础取决于包容意见差异","d":"组织的力量不止于团结意见相同者，更在于容纳意见不同者与犯过错误者；对意见差异的包容越充分，共同协作的基础越宽。","sub":[{"t":"容纳意见不同者与犯过错误者共事","d":"不仅善于团结意见相同的同志，更须团结意见不同者与犯过错误者一道工作，对党外人士亦如此，以扩大共同协作的基础。","p":["党委会的工作方法"]}]},{"t":"领导集体须以谦逊防范自满与腐化","d":"成绩、地位与捧场会给组织带来自满与腐化的危险；领导者须把力戒骄傲作为原则，并以制度约束和艰苦奋斗作风加以防范，才能保持内部团结。","sub":[{"t":"把力戒骄傲作为领导原则并加以制度约束","d":"把力戒骄傲作为领导者的原则问题与保持团结的条件，不因成绩自满，禁止祝寿、以名字命名等歌功颂德现象，保持艰苦奋斗作风。","p":["党委会的工作方法"]}]},{"t":"判断须先分清对象性质与轻重再下结论","d":"对人与事的可靠判断，以先界定其性质界限、再区分主次为前提；性质一旦被混淆，后续估计必错，须把性质界定置于评价判断之前。","sub":[{"t":"划清两类界限并区分主次作基本估计","d":"看问题先划清两种界限——革命与反革命的根本界限，以及革命队伍内正确错误、成绩缺点的界限——再弄清主次，作根本估计（如成绩三分七分之比），经细致研究后再下判断，防止混淆性质。","p":["党委会的工作方法"]}]},{"t":"以必然形势的确定性压缩抉择的余地","d":"当根本对立的力量对比已使结局确定时，认识上不给中间立场与拖延幻想留余地：可供选择的道路与决断的时间都受客观形势限定；以此为基础比较各出路的利弊，争取较优结果并备妥次优路径，促使对方及时取舍。","sub":[{"t":"以排除中间道路和指明不可逆形势促使对方限时抉择","d":"面对口头接受条件、实际拖延游移的和谈对手，先确立抉择结构：只有互相排斥的两条路，第三条路客观不存在，徘徊是幻想；再指明不可逆趋势——无论签不签协定，解放军总是要前进的；进而比较各出路的利弊，争取较优结果（签订协定）同时备妥次优路径（局部谈判解决），把选择权交还对方但限定时间，排除一切幻想、空话与游移余地。 # 待理论层归并的 L1","p":["南京政府向何处去？"]},{"t":"书面与口头表达简明扼要","d":"讲话、演说、写文章、写决议案都简明扼要，会议也不宜过长，以控制篇幅与时长提高表达与议事效率。 # Method Dedup Index（61-66 批次） **批次：** 61-66（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 61、向全国进军的命令 · 62、中国人民解放军布告 · 63、中国人民解放军总部发言人为英国军舰暴行发表的声明 · 64、在新政治协商会议筹备会上的讲话 · 65、论人民民主专政 · 66、丢掉幻想，准备斗争","p":["党委会的工作方法"]}]},{"t":"整体判断不替代局部单位的可独立选择","d":"对一个整体的定性判断，不能自动套到其内部每一可独立决定的单位上。把整体拆成可分别表态的单位，对各单位给出同一公开条件并保持其独立选择余地，处置才能按各单位实际取向而非整体标签来确定。","sub":[{"t":"把整体拒绝的对象分解为可独立选择的单位区别对待","d":"整体已拒绝时，不把整体表态当作内部每个单位都不可转变；先按实际作战与管辖边界把整体分解为地方政权、地方军事集团和可独立决定的机关，再对每一单位维持同一套统一条件，并给出现实选择：愿停止对抗者照已拟方案签订下级协定，被围困后仍愿接受者再给一次机会。处置按对象实际意愿而非整体身份决定。","p":["向全国进军的命令"]},{"t":"按对象实际行为而非整体身份区别处置","d":"面对被整体定性的群体，不把整体身份标签自动套到每个个体，而按其行为性质（是否持枪抵抗、是否阴谋破坏、是否怙恶不悛）决定处置：对战争罪犯与反革命分子严办，对不抵抗、不破坏的旧政权人员不加俘虏逮捕并量才录用。处置随实际取向而非身份决定。","p":["中国人民解放军布告"]}]},{"t":"以独立主权为底线规定关系建立的前提","d":"与外部力量建立关系时，不放弃自主决定权，先划清不可让步的主权与独立底线，据此预先规定关系成立所必需的前提条件——对方须撤出、不得助敌、须平等互惠；己方主动规定条件、拒绝带威胁性的安排，再谈关系建立。底线由己方划定而非对方给予。","sub":[{"t":"以主权底线为据规定对外交往的前提条件","d":"与外部力量建立关系时，先划清不可侵犯的主权底线、限定反对对象（只反对敌对制度及其阴谋，不排斥一切对象），据此规定对方须满足的前提（撤走武装、不得助敌、断绝与敌对方面关系并取真正友好态度）；再以平等、互利、互相尊重主权为基础决定是否建交，愿意合作但拒绝一切威胁性安排，由己方主动规定关系建立的前提。","p":["中国人民解放军总部发言人为英国军舰暴行发表的声明","在新政治协商会议筹备会上的讲话"]}]},{"t":"从正反经验中提炼统一行动公式","d":"面对分散而丰富的正反历史经验，先全面回溯成功与失败的实践，再归纳其中反复成立的共同结论，浓缩为简明统一的行动公式，使其成为多方共同遵循的依据，避免各凭片面经验行事。经验是提炼纲领的材料，纲领是统一行动的形式。","sub":[{"t":"从正反历史经验中总结集中到一点的行动纲领","d":"面对重大方针的确立，不凭抽象原则定夺，而回溯一段长历史中成功与失败两方面的经验，找出反复出现的共同结论；再把这些分散经验\"集中到一点\"，凝练为简明公式与纲领，作为统一行动的依据。","p":["论人民民主专政"]},{"t":"从长期正反斗争经验中凝练敌我斗争定律","d":"面对分散而长久的斗争经验，回溯长历史中敌我双方反复出现的固定行为——帝国主义\"捣乱失败再捣乱再失败直至灭亡\"、人民\"斗争失败再斗争再失败再斗争直至胜利\"——从百余年正反经验中把它们凝练为双方各自不可违背的逻辑即定律，据此预见敌我结局，决定对敌人不抱幻想、对人民坚持斗争。","p":["丢掉幻想，准备斗争"]}]},{"t":"按对象性质区别选择处理方法","d":"面对性质不同的对象，不把同一方法套用于一切对象，而按对象性质选择与之相称的处理方式，并在各类之间保持原则界限；方法的选用以对象类别为准，防止越界混用导致处理失效或失当。","sub":[{"t":"按对象类别区别使用说服与强制并保持界限","d":"处理两类性质不同的对象时，先按性质分清类别，对一类用民主的说服方法教育改造、对另一类用强迫劳动与教育相结合的方法改造，并在两类方法之间保持原则区别，不混用也不互相取代。","p":["论人民民主专政"]},{"t":"按对象性质区别对待：对敌人斗争、对人民内部教育","d":"处理性质不同的对象时先分清敌我界限：自我批评与说服教育的方法只能用于人民内部；对帝国主义和反动派不指望其发善心，唯一办法是组织力量斗争，揭露、制裁直至打倒；只有经过斗争取得平等地位，才有希望在平等互利条件下同帝国主义打交道，并把缴械投降的敌对分子教育改造成好人。","p":["丢掉幻想，准备斗争"]}]},{"t":"以可核对的取舍检验不可核对的宣称","d":"当一个对象的自我说明无法独立核对真假时，不停留在宣称本身，而基于它已经承认的前提构造一个具体且尽量对它有利的方案，迫使其在公开可核对的取舍中表态。取舍是可验证的事实，由此得到的判断与责任归属不随对方表态而失效。","sub":[{"t":"以对方承认的前提拟出方案检验其真伪并判定责任","d":"面对宣称接受某些原则却拒绝由此导出的具体安排的对象，先取出它已承认的前提，据此拟出具体、可操作且尽量宽大的方案。若它既承认前提又拒绝该方案，其宣称的诚意即不成立；同时因我方已把条件放到极宽大，继续冲突的责任随之交还对方。判断与责任归属都不依赖对方表态，只依赖可核对的取舍。","p":["向全国进军的命令"]}]},{"t":"在管辖转换中保持运转连续与资产完整","d":"在权力或管辖主体转换时，不立即切断原有机构运转，而是责成原职人员照常供职、保护资财档案并听候接管，以保全存量资产与秩序；同时以奖功罚过和量才录用引导合作。这样过渡成本最低，也避免资产在权力真空期流失。","sub":[{"t":"责成原班照常供职并听候接管以保全资产","d":"接管新区域机构时，不中断其运转，责成原有人员在接管前照旧供职、负责保护资财机器图表账册档案，听候清点接管；保护有功者奖、怠工破坏者罚；愿继续服务者接管后量才录用不使流离。以连续性维持运转与资产完整，再作人事安排。","p":["中国人民解放军布告"]}]},{"t":"结构性变革按准备程度与对象性质分阶段区别推进","d":"对方向确定但牵动广泛的社会制度变革，不一次到位，而先确定方向、再按准备程度分步实施（如先减租减息后分配土地），并按对象与地域性质区别处理（如城乡土地不能同样对待）。准备不足时只做初步改革，避免秩序崩坏。","sub":[{"t":"重大社会变革有准备有步骤并城乡区别","d":"对确定要废除的旧制度，不急于一次解决，而先行减租减息、待解放军到达工作相当时期后再分配土地；农民组织起来协助初步改革并努力耕种不降低生产。城市土地房屋不与农村同样处理。方向确定但按准备程度与地域性质分阶段区别推进。","p":["中国人民解放军布告"]}]},{"t":"以公开统一规则划定行为边界以争取配合","d":"进入新区域时，主动发布统一、公开且可核对的政策边界（保护什么、没收什么、惩办什么），使各界人民据以判断并配合，同时要求人民不信谣言、安居乐业。公开规则把政策变成各方可共同遵守的准则，降低摩擦。","sub":[{"t":"以公开约法划清政策边界争取人民协助","d":"进入新区域时，发布统一公开的约法，明确保护全体人民生命财产、民族工商、文教公益，没收官僚资本，惩办破坏分子与战争罪犯，保护外侨安全等边界，要求各界采取合作态度、切勿轻信谣言自相惊扰。公开可核对规则使人民据以配合，降低接管摩擦。","p":["中国人民解放军布告"]}]},{"t":"从行为事实还原责任归属以拆解借口","d":"面对对方转嫁罪名或以借口为自身行为辩护时，不停留在与对方争辩说辞，而回到可确证的客观行为事实，据此界定行为性质、把责任还原到真正的行为者，从而拆解借口并确立己方正当要求。事实是可核验的，说辞不是。","sub":[{"t":"以行为事实反诘戳穿侵略者借口","d":"面对侵略者以\"报复\"\"有权\"等借口为暴行辩护时，不纠缠其说法，而回到行为事实——谁闯入防区、谁开炮、谁造成伤亡，以反问把罪名反转回真正的行为者，指出犯罪在对方，据此要求其认错、道歉、赔偿。以事实界定性质并反转责任归属。","p":["中国人民解放军总部发言人为英国军舰暴行发表的声明"]}]},{"t":"对对立面的反扑保持充分估计与戒备","d":"在胜利或有利形势下，对立面的反抗不会自动消失；须断定其必然图谋报复、枚举可能手段并充分估计，不因胜利放松警惕，因为放松戒备将使自身解除行动能力而陷于被动。戒备建立在对反扑的估计上而非胜利的既成事实上。","sub":[{"t":"在胜利形势下估计对立面的报复可能并保持警惕","d":"面对胜利或有利形势，先断定失败一方必不甘心、必然勾结图谋报复；再枚举其可能手段（钻入内部捣乱、封锁海港、侵扰边境等）并要求充分估计；进而规定不因胜利放松警惕，把放松戒备明示为政治上解除武装、陷于被动的危险，最后号召团结粉碎一切阴谋计划。","p":["在新政治协商会议筹备会上的讲话"]}]},{"t":"以对根本任务的态度划定团结与斗争的对象","d":"动员大规模力量前，先明确必须排除的敌对势力范围，排除后其余力量均视为可团结对象；团结与斗争的范围由对根本任务的态度决定，不因其他身份差别缩小，从而形成广大而巩固的统一战线。","sub":[{"t":"以排除敌对范围确定团结对象","d":"面对大规模动员，先确定必须排除的对象范围（帝国主义者、封建主义者、官僚资产阶级、国民党反动派及其帮凶），排除后其余一切人均划入朋友范围；再确认统一战线涵盖的阶级构成及其巩固性，据以扩大并稳固团结面。","p":["在新政治协商会议筹备会上的讲话"]}]},{"t":"以最终目标为参照规定当前任务","d":"最终目标确定后，当下任务并不与目标直接相同，而按现时条件被规定为实现目标的过渡环节；以目标为参照判断条件差距，再规定当前该做什么、暂不做什么，使当下行动既服从长远方向又不脱离现实条件。","sub":[{"t":"以最终目标为参照规定当前阶段任务","d":"当最高目标与当下行动看似矛盾时，先确认终极目标，再判断现时条件尚不具备，从而把强化国家机器等当下任务规定为实现目标所必需的过渡条件，说明\"为最终实现而暂时采取相反性质步骤\"的统一，并据此确定现阶段政策。","p":["论人民民主专政"]}]},{"t":"先界定概念与对象再澄清判断","d":"面对性质疑或概念之争，先界定概念所指的对象及其类别界限，再分别说明对各类对象的适用与不适用，把抽象的指责转化为范围明确的判断，使争论建立在对象划分而非含混字面上。","sub":[{"t":"对性质疑先界定概念与对象再作答复","d":"面对\"你们独裁\"一类性质疑，不回避字面也不急于辩解，先界定关键概念所指，再划分两类对象并分别说明对各自的适用，从而把抽象指责转化为对主张的明确澄清与范围限定。","p":["论人民民主专政"]}]},{"t":"向已掌握所需本领的对象学习必备能力","d":"当自身缺乏某项必备本领而任务又必须完成时，不凭空自造方法，先承认不具备，再确认谁已掌握该本领，向其恭谨而持久地学习直到掌握。本领的取得以\"谁已具备\"为准，学习对象不限于友好者，也可从对立面的既有实践中取得。","sub":[{"t":"以恭谨老实态度向一切内行的人学习不熟悉的事务","d":"面对不熟悉的新任务，先承认不懂、不装懂、不摆官僚架子；再确定学习对象——向一切内行的人们学习，拜他们做老师；以恭恭敬敬、老老实实的态度长期学，钻进去直到学会。","p":["论人民民主专政"]},{"t":"从对立面既有实践中学习维持政权的统治方法","d":"当所需本领自身尚无先例而对方已经掌握时，明确这一方法可从对立面的既有实践学来——革命的专政是从反革命的专政学来的；不学会它就不能维持政权，掌握后用于维持自身、取代对方。","p":["论人民民主专政"]}]},{"t":"以阶级斗争观点认识社会形势与历史进程","d":"面对复杂的社会形势与敌对力量，不从表面宣称、甜言蜜语或情感幻想出发，而以阶级矛盾与阶级斗争是历史实际内容的观点考察各对象的阶级性质与历史走向，据此判断其本性是否可变及其最终结局，为确立认识和行动提供根据。","sub":[{"t":"以历史唯物主义观点观察敌对力量与中间势力","d":"面对对帝国主义、国民党、苏联、中国共产党等各方力量的观察，不从幻想和表面说法出发，而以\"阶级斗争是历史、一些阶级胜利一些阶级消灭\"的历史唯物主义观点考察对象的阶级性质；赞成并运用这一观点才能看清帝国主义本性不可改变、必然捣乱直至灭亡，否则对各方的观察都不正确，陷入被动。","p":["丢掉幻想，准备斗争"]}]},{"t":"以对立面自我暴露的材料教育动摇者","d":"争取思想上动摇、尚存幻想但非敌对的群体时，不靠空泛劝告，而利用对立面公开暴露其意图与本性的材料作为事实教材，使动摇者自行认清其真面目，从而丢掉幻想、转变立场；教育的效力以自我暴露的事实为据，而非以说教为据。","sub":[{"t":"利用敌人自我暴露的公开文件作反面教材教育摇摆者","d":"争取对革命尚存幻想、思想动摇的中间分子时，不凭空说教，而利用敌人公开发表的文件作反面教材，借其自我暴露的捣乱意图与所依靠的对象证明帝国主义本性不可改变，帮助他们丢掉幻想、站到人民大众方面来，从而争取中间派、孤立帝国主义。 # Method Dedup Index（67-70 批次） **批次：** 67-70（本批次 4 篇，独立 method index 文件） **当前覆盖：** 67、别了，司徒雷登；68、“友谊”，还是侵略？；69、为什么要讨论白皮书？；70、唯心历史…","p":["丢掉幻想，准备斗争"]}]},{"t":"从服务于对方自身目的的陈述中反向取证","d":"对方为自身利益所作的陈述，不因其立场而失去价值。凡与其目的相反却仍被承认的内容，反而是可靠的；凡陈述停止的地方，往往正是需要补出的地方。对这类材料应按内容与陈述者利益的关系分辨取用，而不按发布者身份一次性决定信或不信。","sub":[{"t":"从对手为脱卸责任而作的自述中反向取证","d":"对手为推卸责任而公布的材料，不整体采信也不整体弃置。按它自己列举的方案逐项追问取舍理由，取其中对自身不利却仍被承认的部分作为，并把其用语还原为实际内容；再检查它的坦白到哪里为止，补出它不肯说的部分及其原因；最后把这份出自对方之手的材料交给本方仍存幻想的人去读。","p":["别了，司徒雷登"]},{"t":"借论敌自我暴露组织全面讨论并印证判断","d":"当本方判断长期不被普遍信服时，抓住敌人为内部斗争而公开暴露自身材料的时机，把它作为讨论革命内外各方面相互关系的教育材料；以敌人自己的说法与既有判断相对照，凡如出一辙之处即以其为佐证，使将信将疑者打开眼界；通过全面讨论使矛盾侧面充分暴露，把材料来源的对抗性转化为认识教育的契机。","p":["为什么要讨论白皮书？"]},{"t":"按利害立场判定论敌言论的取舍","d":"面对论敌自诩客观坦白的论述，先确定其立场与党派利益；以其利益为标尺划定坦白界限——主观上有利于其党派的内容才坦白，不利的则隐瞒；据此识别\"装作坦白\"是为作战目的，不把自我标榜的坦白程度当作可信程度。","p":["为什么要讨论白皮书？"]}]},{"t":"以可核对的事实判定性质，不以宣称与形式为准","d":"一个对象是什么，由它已经做过的事和它被实际安排的方式决定，而不由它对自己的说明或是否履行了某种形式决定。判断应从可核对的痕迹入手，并把性质与程度、与是否被公开承认分开：后两者只影响它在整体中的分量，不改变它是什么。","sub":[{"t":"按可核对的事实与安排判定对方行为的性质与用意","d":"先把对方的自我说明与形式声明放在一边，改从可核对处入手：看人选被挑中所依据的条件，读出他被赋予的作用；看发布时点与相关人员行程、责任关系的配合，读出发布的实际目的；看已发生的事实清单，按事实定性。并把形式与程度从性质中分开——未公开宣布、规模不大都不改变性质，只说明它占多大分量。","p":["别了，司徒雷登"]},{"t":"从长期投入的构成与人员去向识别非武力的侵略形式","d":"判断一项以宗教、慈善、文化、教育面目出现的事业属于什么，不看名目，也不看它是否办了实事，而查三样可统计的东西：投入总额及其在各领域间的构成比例，看重心落在哪一项；经营的持续时间与起点，看是否与侵略史同长、是否起于最初的不平等条约；从业者后来被安排到什么位置。三项指向同一方向时，即可判定它是侵略的一种形式。","p":["“友谊”，还是侵略？"]}]},{"t":"用事项的来历与后果还原其被赋予的名义","d":"一个被命名的事项，其实际内容不在事项本身，而在它从何而来、随之发生了什么。因此检验一个名义，不在名义层面争论，而是把每一被举出的事例放回它的来历与后果中，并把全部事例按发生顺序连成一个过程；名义与这个过程之间的距离，就是它所掩盖的内容。","sub":[{"t":"以行为的全部历史与来历核定关系的性质","d":"对方用\"友谊\"\"善意\"命名双方关系并举出若干事例时，不逐项争论事例好不好，先找出这一关系的起点，从起点到当下连成完整过程；再把每一项好处放回过程中，问它从哪一次失败、哪一个条约、哪一场战争里来，给出它的同时随之发生了什么。逐项还原后把名义重新加回事实之后，名义与过程的距离即关系的实际性质。","p":["“友谊”，还是侵略？"]},{"t":"以侵略的历史过程还原\"外来影响\"的名义","d":"面对把外来侵略表述为\"外来影响\"\"新思想输入\"的名目，不就此名目抽象争论，而把它放回历史过程：查明其实际内容是帝国主义侵略，指出其现实后果是造就洋奴与反抗者两类人，反抗从侵略中发生。名义与过程之间的距离，即被掩盖的实质。","p":["唯心历史观的破产"]}]},{"t":"由制约条件而非行为者意愿解释其行为方式","d":"行为者采取哪种方式，常常不表达它想要什么，而表达它被什么挡住了。解释一种行为方式，应分别考察意愿与约束，把方式归到约束的构成上，并分清哪一项起主要作用。这样得到的判断不随对方姿态的缓和而改变，也指出了方式将在什么条件下改变。","sub":[{"t":"用对手所受的制约而非其意愿解释其行为方式","d":"对手采取比其能力所允许的更温和的方式时，不由此推断其意愿已改变。先把意愿与做法分开，承认它想做而未做；再逐项列出阻挡它的力量，包括其本国人民的态度、他国人民的态度、以及行动对象自身的觉悟与组织程度；在其中判定主要的一项。结论落在力量对比上：制约一旦松动，方式就会改变。","p":["别了，司徒雷登"]}]},{"t":"外来给予的性质由随之建立的关系决定","d":"一项外来的好处是什么，不取决于它的内容有多大用处，而取决于接受之后双方处在什么关系里。因此要把物与关系分开，查明掌握者、去向和条件；条件决定关系，关系决定这项给予对接受者意味着什么。物的有用性不能单独构成接受的理由。","sub":[{"t":"以附加条件与分配去向判定外来给予的性质","d":"面对外部提供的物资、技术或名目上的好处，不从东西本身判断，先查三件事：它掌握在谁手里、实际用于什么；它给了谁、不给谁；接受它要附带什么条件。三项查清后，判断对象从物转到关系上——接受一项带条件的给予，等于接受给予者所要求的从属地位。据此取舍，不因物本身有用就接受。","p":["别了，司徒雷登"]}]},{"t":"以自身已承受过的处境标定新困难的量级","d":"困难的大小不能孤立地估计，只有放进自身经历过的处境序列里才有确定的位置。把已经度过的最坏处境作为标尺，新困难的量级就随之确定；把对方可能施加的最严厉手段预先接受为条件，估计也就不再取决于它是否到来。","sub":[{"t":"用已经历过的更严重处境标定当前困难的量级","d":"面对新出现的困难，不孤立估计其大小。先把对方可能施加的最严厉手段明确接受下来，作为已计入的条件；再把当前困难逐项列出，与本方已经经历并度过的更严重处境对照，由对照定出相对量级。量级确定后结论是可以承受，因而不把消除这项困难当作行动成立的前提。","p":["别了，司徒雷登"]}]},{"t":"按对象在关键关头的实际选择分类并差别处置","d":"一个群体内部的分化，用原有标签看不出来，只有在必须作出选择的关头才显露。因此分类依据应是已经作出的选择，而不是所属的名目。分类之后处置也应有差别：对已作出选择者立为标准，对未作出者留出转变余地并做工作，把可争取的部分与对立面分开。","sub":[{"t":"按关键关头的实际选择划分群体并差别处置","d":"对思想上分化但不属于敌方的群体，不按原有派别一律划线，而按其在现实压迫面前作出的实际选择区分。对已作出选择的公开表彰并立为本群体的标准，必要时指出历史上被表彰错了的对象，使标准明确；对尚未转变、仍存幻想的划为可争取对象，进行说服、争取、教育和团结，使其站到本方一面。","p":["别了，司徒雷登"]}]},{"t":"原则的实际内容由其生效范围显示","d":"一套被宣布的原则说的是什么，不看条文，而看它在哪里生效、在哪里落空。若生效的范围恰好与宣布者的利益范围重合，原则表达的就是这一利益，而不是条文本身；同样，原则表上被省略的条目，也属于它的实际内容。","sub":[{"t":"用宣称原则的实际生效范围检验其真实内容","d":"对方以\"基本原则\"为自己辩护时，不在字面上争论对错，而把每一条原则逐一放回现实：在它影响所及各处今天造成了什么状态，哪里还维持着，哪里出现相反结果。再把维持之处与对方仍能控制之处对照——若原则只在其控制处成立、在失控处全部相反，则原则的实际内容就是它的控制本身。最后清点原则表的缺项，缺项与列出项同样属于其内容。","p":["“友谊”，还是侵略？"]}]},{"t":"普遍判断按适用对象分别检验","d":"一个普遍性概念或判断用于不同对象时，含义可能相反。认识普遍判断须先划分对象类别，分别在每类对象上检验其含义，再决定判断能否成立；把概念在一类对象上成立的用法强加于另一类对象，是概念混乱与错误判断最常见的来源。","sub":[{"t":"按敌我对象区分逐条驳倒概念命题","d":"面对论敌成套的论证概念，不纠缠字面，逐一提炼命题；把命题涉及的对象区分为人民与反动派两类，指出论敌混淆了两类对象的关系；再分别判明概念在每类对象上的真实含义——对反动派专政不等于对人民独裁，人民的舆论不等于反动派的舆论——从而逐一驳倒命题并建立正确判断。","p":["为什么要讨论白皮书？"]}]},{"t":"以真实社会根源判定历史事变的归因","d":"重大历史事变的原因，不从人口数量、外来思想等表面现象取解释，而查产生它的客观社会条件（压迫与剥削、生产与需要）；表面现象即使属实也只是材料，不构成原因。只有社会根源才能说明事变的发生。","sub":[{"t":"以历史实例检验表面归因并确证社会根源","d":"面对把重大历史事变归因于表面现象（人口多少、外来思想输入）的解释，先不争论表面现象本身，而把该归因作为普遍命题，逐项举出与之相悖的历史实例检验其能否成立；检验中把真实原因确立为社会根源（压迫与剥削、生产与需要）；最后用正面事实确证替代解释。结论以实例检验与社会根源分析共同支撑，不因表面现象部分属实而接受其归因。","p":["唯心历史观的破产"]}]},{"t":"思想的作用由同实际的联系、客观需要与实效决定","d":"一种思想能否起作用，不由它自我宣称的优越决定，而由它同客观实际事物的联系、客观存在的需要以及实践中的实效决定；判断思想的作用应把宣称与实际联系、需要、实效分开，以实际为准。","sub":[{"t":"以联系、需要与实效判定思想能否发生作用","d":"判断一种思想（主义）能否在实际中发生作用，先检查三项条件：是否同客观实际的事物相联系、是否有客观存在的需要、是否为人民群众所掌握；再把各思想放进实际斗争，以实践中的胜败检验其效力。缺条件的即使自认最好也不起作用，经实践证实者才被接受为有效的思想武器。","p":["唯心历史观的破产"]}]}],"5":[{"t":"通过组织化整合分散力量改变力量对比","d":"面对局部或整体上处于弱势、主体分散的局面，通过唤起主体自觉、把分散个体组织成有共同目标的整体，从而聚合出足以扭转对比的整体力量。只保留\"自觉—组织—整体优势\"的一般机制，不预设具体敌我与战场。","sub":[{"t":"以统一战线组织分散力量战胜强敌","d":"面对整体弱势、力量分散而敌人强大，先使人民觉悟起来，再把分散个体组织成全国规模、指向共同敌人的统一战线，集中支援武装斗争，由防御转入反攻进攻直至基本打倒敌人。核心是把分散力量聚合为整体优势的\"觉悟—组织—统一战线—集中支援\"链条。","p":["中国人民站起来了"]},{"t":"组织群众克服散漫以凝聚建设力量","d":"面对旧中国散漫无组织的状态，主张把绝大多数人组织进政治、军事、经济、文化及其他各类组织里，用群众的集体力量拥护人民政府和人民解放军，把分散个体凝聚为支撑建设事业的整体力量。核心是把散漫的人民聚合为集体力量的\"组织—集体力量\"链条。","p":["中国人民大团结万岁"]}]},{"t":"以分项任务把抽象定位展开为行动方向","d":"面对宏大而抽象的行动目标，行动主体先确立总体定位，再按领域逐项展开为具体任务清单，使抽象原则转化为边界清晰、可以执行的具体行动方向，避免号召流于空泛。保留\"定位 → 分项任务\"的认识动作。","sub":[{"t":"以分项任务清单明确新政权的行动方向","d":"面对新政权的行动方向需要被人民清楚预期，先确立\"遵照共同纲领、实施人民民主专政\"的总定位，再按军事、经济文化、治安、国防、外交等逐一列明政府将办之事，把政权性质展开为具体任务清单，使方向明确、执行有据。","p":["中国人民大团结万岁"]},{"t":"以分项任务承接总体目标并为每项划定执行边界","d":"面对\"创造三个条件、争取根本好转\"的总体目标如何落地，先以\"全党和全国人民团结起来做好各项工作\"承接目标，再按土改、财经统一、复员整编、文教改革、失业救济、统一战线、肃反、党建八项逐一展开；每项同时规定推进节奏与正反边界，如有步骤有秩序、谨慎、不可偏废，既反对拖延又反对过急，防止执行走偏。核心是\"目标 → 分项任务 → 逐项配边界\"的链条。","p":["为争取国家财政经济状况的基本好转而斗争"]}]},{"t":"以历史进程与已获成果论证现实选择的正当性","d":"面对现实道路需要争取信任与信念时，通过追溯长期奋斗的历史进程、归因于正确领导与人民努力，并以已经取得的胜利成果作为实证，把当下的选择呈现为历史必然，从而为现实正当性提供论证并稳定人心。保留\"历史成果 → 现实正当性\"的认识动作。","sub":[{"t":"以历史奋斗与胜利论证现实道路的正当性","d":"面对人民对现实道路与团结基础的信念需要巩固，追溯一百多年来先进分子领导人民百折不挠的斗争历史，归因于中国共产党的领导与人民长期英勇奋斗，并以已经战胜反动政府、建立新中国的实际胜利为据，说明当下的团结与建国是历史发展的必然结果。","p":["中国人民大团结万岁"]}]},{"t":"区别对待变革对象并把握先后次序以稳定全局","d":"面对涉及多方对象的重大社会变革，变革对象并非铁板一块，应根据变革引起的现实反应区别对待不同对象，主动暂缓触动次要对象，把力量集中于主要对象，并稳住中间与同盟力量，以减少阻力、避免被动、争取全局主动。核心认识动作是\"区分对象 → 安排行动次序 → 孤立主要、稳定全局\"。","sub":[{"t":"暂缓触动次要对象以孤立主要对象并稳定全局","d":"面对规模宏大、容易发生偏向的社会变革，先区分变革对象的主次并评估由战争转入和平后变革引起的社会震动；再主动暂缓触动次要对象，集中力量孤立和解决主要对象，同时保护中间力量、防止过激、稳定同盟者，从而减少阻力、取得政治主动。核心是\"区分对象 → 评估震动 → 暂缓次要 → 孤立主要、稳定全局\"的链条。","p":["征询对待富农策略问题的意见","为争取国家财政经济状况的基本好转而斗争"]},{"t":"镇压与宽大相结合分类处理斗争对象","d":"面对肃清土匪、特务、恶霸及其他反革命分子的斗争政策，不采取单一手段，把对象区分为首恶、胁从、立功三类，分别处以必办、不问、受奖，实行镇压与宽大相结合并强调不可偏废，同时要求提高警惕。核心是\"区分对象性质 → 分类处理 → 手段结合不可偏废\"的链条。","p":["为争取国家财政经济状况的基本好转而斗争"]}]},{"t":"以制度化形式凝结共同意志并使其持久生效","d":"面对多方主体需要统一行动却意志分散的局面，通过广覆盖的代表性机制汇聚共识，再转化为成文的规范、纲领、象征与机构等制度形式，使共同意志获得稳定载体与持续执行的基础。保留\"共识 → 制度化载体\"的认识动作。","sub":[{"t":"以广泛代表性的制度安排固化建国共识","d":"面对建国之际多方主体意志需要统一，先召集覆盖各党派、团体、各地区民族、华侨等代表的会议，以会议名义代表全国意志、宣示空前团结；再按既定原则成文制定组织法、共同纲领、国家象征与机构，使共识转化为有据可依的制度秩序。","p":["中国人民大团结万岁"]}]},{"t":"从客观实际与实践结果出发认识对象性质","d":"面对对某类对象性质的分歧或幻想，以已经发生的客观事实和实践结果为依据，提炼出关于对象根本性质的确定判断，而不是从主观愿望或抽象原则出发。保留\"实践结果 → 性质判断\"的认识动作。","sub":[{"t":"从合作破裂的教训中确立对敌无妥协立场","d":"面对是否可与敌人妥协合作的幻想，回顾一次真实合作经历，观察其被对方破坏、决议被撕毁的实际结果，由此归纳出对方性质，进而确立\"推翻敌人或被敌人压迫，二者必居其一\"的根本斗争判断，作为后续组织与斗争的前提。","p":["中国人民站起来了"]}]},{"t":"依据对立面必然动向预置制度性防范","d":"面对斗争取得阶段性胜利后的局面，基于\"对立力量不会自行消失、必然寻求反扑\"的判断，提前建立制度性保障与持续警惕，而不是把阶段胜利当作终局。保留\"预判对立面动向 → 提前部署防范\"的机制。","sub":[{"t":"以专政制度和持续警惕防范胜利后复辟","d":"面对革命取得阶段性胜利后的新局面，先判断敌人决不甘心失败、必将最后挣扎，并预判其平定后仍会以各种方式破坏、企图复辟；据此不松懈警惕，把人民民主专政的国家制度作为反对复辟的有力武器牢牢掌握，同时团结国际友人以避免孤立，使成果不被逆转。","p":["中国人民站起来了"]}]},{"t":"以时间纵深界定对象意义与历史地位","d":"面对需要界定对象（人物、事件、事业）意义与历史地位的问题，由近及远逐层扩展时间尺度，把当下对象置于更长的历史进程中加以定位，使对象的意义随历史纵深扩展而得到更完整的界定，避免只从眼前尺度衡量其分量。保留\"时间纵深 → 意义界定\"的认识动作。","sub":[{"t":"以递进时间层级界定牺牲者的历史意义","d":"面对如何界定并纪念在革命中牺牲的英雄，不局限于最近一次战争，而是从三年以来的解放战争出发，逐层扩展到三十年以来的人民革命，再上溯到一八四〇年以来反对内外敌人、争取民族独立和人民自由幸福的历次斗争，用三层递进的时间尺度框定牺牲者的范围与意义，使\"永垂不朽\"的判断获得完整的历史纵深。核心是\"由近及远逐层上溯 → 意义范围扩展界定\"的链条。","p":["人民英雄们永垂不朽"]}]},{"t":"从经受考验的局部经验确立普遍长期要求","d":"面对把特定群体在长期实践中经受检验的作风、做法推广到更大范围的问题，从局部长期实践的历史贡献中提炼出一般原则，并把它确立为全局共同且须长期保持的要求。核心认识动作是\"局部长期实践 → 普遍长期规范\"。","sub":[{"t":"以历史贡献确立全国永远保持的作风要求","d":"面对全国胜利后如何传承优良作风的问题，先肯定延安和陕甘宁边区作为解放斗争总后方十余年斗争的历史贡献，再从这段长期实践中提炼出\"艰苦奋斗的作风\"，把它确立为全国一切革命工作人员必须永远保持的共同要求，同时祝愿边区人民继续团结、恢复创伤、发展建设。核心是\"历史贡献 → 提炼作风 → 确立普遍长期要求\"的链条。","p":["永远保持艰苦奋斗的作风"]}]},{"t":"以广泛征询和正反兼收为基础的集中决策","d":"面对涉及全局的重大决策，应向下级与执行层面广泛征询意见，把赞成与反对两面的实际看法一并收集，汇集到决策中枢综合判断后再作决定，使决策建立在充分掌握各方意见的基础上，避免主观片面与被动。核心认识动作是\"分散意见 → 集中决断\"。","sub":[{"t":"重大决策前逐级征询并兼采正反意见","d":"面对涉及全局的重大政策决策，决策中枢先提出倾向性方案，请各中央局在所辖省负责同志会议中征询意见，并逐级转发到省市党委讨论；要求把赞成与反对意见一并收集、迅速上报，供中枢综合判断后定案；同时把握决策与实施季节的衔接，及时修订颁布配套文件，避免错过时机陷于被动。核心是\"提出方案 → 逐级征询 → 兼收正反 → 综合决断\"的链条。","p":["征询对待富农策略问题的意见"]}]},{"t":"以阶段辨析与条件还原评估目标的实现进程","d":"面对复杂目标的实现评估，不以已取得的初步成果误判为根本解决，先判定成果所处阶段，再把目标还原为必要实现条件并估计所需时间，使进展判断与后续部署建立在清醒的阶段评估之上。核心认识动作是\"成果 → 阶段判定 → 条件还原 → 时间预估\"。","sub":[{"t":"以阶段辨析与条件还原确立根本好转的实现路径","d":"面对如何评估财政经济战线胜利的问题，先承认已取得收支接近平衡、通货停止膨胀、物价稳定等成果，判定这只是\"开始好转\"而非\"根本好转\"；再把根本好转还原为土地改革完成、工商业合理调整、国家机构经费大量节减三个必要条件，估计约三年左右的时间，并动员全党全国为实现三条件而奋斗。核心是\"成果评估 → 阶段判定 → 条件还原 → 时间预估 → 动员\"的链条。 # Method Dedup Index（07-12 批次） **批次：** 07-12（每 6 篇文章一个独立 method i…","p":["为争取国家财政经济状况的基本好转而斗争"]}]},{"t":"重大变革须组织各方、统一思想后共同推进","d":"涉及多方利益的重大变革不可能由单方完成，须先组织起承受变革的各方力量，通过协商讨论统一认识，形成思想与行动的一致，再共同推进变革；变革能否顺利通过，取决于各方是否被组织进来并统一起来。","sub":[{"t":"以统一战线与思想统一推进重大变革","d":"面对需要全社会各方共同通过的重大变革（如土地改革），不靠单方推行，而是组织起承担变革的各方力量，通过多研究、多商量、打通思想、整齐步伐，组成广泛的统一战线，使各方在统一的思想基础上形成一致行动，共同通过变革之\"关\"，并据此领导人民、帮助人民顺利前进。","p":["做一个完全的革命派"]},{"t":"以团结协同完成国家重大建设任务","d":"对需要动员全社会力量的重大建设任务，先明确其为国家大事，再说明其完成有赖于军队指战员与工人、农民及其他人民团结一致、协同努力，把重大任务的达成与全体相关者的联合行动联系起来。","p":["你们是全民族的模范人物"]},{"t":"以统一的总任务凝聚干部思想并限时推进准备","d":"面对长期建设任务，先确立统一的总任务思想（如\"三年准备、十年计划经济建设\"），并使之成为省市级以上干部的普遍共识；同时明确剩余准备时间，要求各条战线从各方面加紧进行，把统一思想认识转化为限时、多方面的实际准备。","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"以条件是否具备划定行动的边界","d":"一项改变现存关系的行动是否应当推行，不只取决于目标本身是否正当，还取决于承担改变的一方是否已具备相应条件。条件不齐时应先创造条件而不是提前发动；条件按齐备与否判断，部分具备不足以启动。","sub":[{"t":"按条件是否具备决定群众性改革的推行","d":"发动涉及群众的重大改革前，先逐项检查所需条件是否齐备——是否有群众基础、可依靠的武装、本地自己的干部。只要一项不具备就不进行带群众性的改革，即使其他条件已成熟也不例外；先转为训练本地干部、团结群众等创造条件的准备工作。改革的具体推行必须由当地人自己解决，外来力量只起帮助作用。","p":["不要四面出击"]},{"t":"依条件成熟度稳妥推进群众性改革并适时转入下阶段","d":"推进土改等群众性改革时，以条件成熟度为行动依据：农忙时暂停下来总结经验；对条件不成熟者不勉强去做，而积极创造条件；依靠农民代表会及训练班培养执行力量；改革完成后立即转入生产、教育等下一阶段工作，避免冒进与停顿。","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"以共同标准下的内部批评实现自我教育与团结","d":"团结一致不是掩盖分歧，而是在共同承认的标准下开展批评和自我批评，通过成员自觉的自我教育和自我改造来坚持真理、修正错误，从而维持与加深整体的统一；批评的效力来自有共同标准可依。","sub":[{"t":"以共同标准下的批评自我批评巩固团结","d":"要巩固已建立的统一战线或既有团结，不回避内部矛盾，而是以各方共同认可的标准为依据，开展批评和自我批评，推动成员坚持真理、修正错误，使全体成员通过自我教育和自我改造实现一致，并把这种方法推广为全体革命人民的自我教育的基本方法。","p":["做一个完全的革命派"]},{"t":"以定期集中的工作检查教育干部","d":"教育干部、端正作风，依靠定期集中（一年一次、时间要短）的工作检查：检查工作、总结工作经验、发扬成绩、纠正缺点错误，借以教育干部，使定期集中的自我检查成为干部教育的基本方式。","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"按主次分配力量而不同时应对全部对立面","d":"面对同时存在的多个对立面，力量有限使平均用力必然失败。应按对立的性质和紧迫程度分出主次，容许在次要方向上暂时不求解决，把可用力量集中于主要方向。判断依据是全局能否承受，而不是各对立面本身的是非轻重。","sub":[{"t":"控制同时对抗的方向数量以集中力量","d":"先清点当前所有不利力量，按性质分为必须打击的敌人与只是不满的可争取者，再判断这些方向能否同时应对。对抗方向过多时，主动在次要方向让步、缓和，把力量集中到主要方向进攻。判断标准是同时开战会不会使全局紧张、主要任务无法完成；让步是为进攻服务的手段，不取消对主要敌人的斗争。","p":["不要四面出击"]}]},{"t":"从对方的现实处境入手改变其立场","d":"立场并非固定不变，很大程度上由处境决定。要改变一部分人的对立态度，应先辨明其不满的实际来源，并在现实处境上作出可兑现的改善，而不是仅凭说理或压力；同时把对该对象的长远判断与当前的对待方式区分开。","sub":[{"t":"以可兑现的处境改善争取不满者","d":"把不满对象按处境分类，找出各类不满的具体来源（失业、生计、税负、地位），针对每类给出能够兑现的具体措施，而不是只作政治说服；同时保留必要的斗争面，不因团结放弃原则，也不因斗争把对方推开。对将来要处理的对象，把长期判断与当前策略分开，先解决其眼前处境。","p":["不要四面出击"]}]},{"t":"汇集相关各方意见与经验形成共同决策","d":"重大决策应由承担其结果的相关各方共同参与，在集中其意见、检查其已有经验的基础上形成；决定的正当性来自参与面的广泛与所依据经验的真实，而不是来自少数权威的单独判断。","sub":[{"t":"以集中各方意见共同决定方针","d":"在需要总结经验、决定方针的场合，把有关各方代表集合在一起，允许各方面人士列席参与讨论，在集中广泛意见的基础上检查过去的工作、决定今后的方针，而不是由少数人独自作出决定。这样作出的决定具有广泛基础，应当被采纳并见之实行，并可在地方各级推广。","p":["做一个完全的革命派"]}]},{"t":"以行动与一贯性而非宣示判断真实立场","d":"真实立场不由宣称决定，而由一贯的实际行动决定；只有行为持续一致者才可作为可靠对象，仅停留在口头的表态不能作为判断与托付的依据。","sub":[{"t":"以一贯行动鉴别真实立场","d":"判断一个人或一个团体站在哪一边，不以口头宣示为准，而要看其实际行动；既在口头上又在行动上站在革命人民方面、且一贯坚持不半途而废者才是完全可靠的力量，言行背离者仅是口头拥护。以言行为准可以把表面拥护与真实拥护区分开。","p":["做一个完全的革命派"]}]},{"t":"按对象性质选择强制或说服的方法","d":"对待方式必须与对象性质相称：对敌对者只能依靠强制约束与改造，对同一阵营者则依靠参与、教育与说服；把方法用错对象，对人民用强制或对敌人用说服，都会破坏应有的秩序与团结。","sub":[{"t":"按对象性质选择对待方法","d":"处理一个群体的关系时，先区分对象性质：对敌对者用专政的方法，在必要时期内限制其政治活动、迫使其服从法律并在劳动中改造成为新人；对人民则用民主的方法，让他们参与政治活动，以教育和说服而非强迫来对待。方法与对象性质相匹配，不可混淆。","p":["做一个完全的革命派"]}]},{"t":"以先进典型示范带动整体进步","d":"先进人物的价值在于其经受实践考验的表现可以成为全体学习的榜样。识别并树立这样的典型，明确其联结组织与群众的桥梁地位，再号召全体向榜样学习，可以把个体的示范作用转化为推动共同事业的整体力量。","sub":[{"t":"以模范人物为桥梁凝聚政府与群众","d":"对在实际斗争中经受考验、表现突出的先进分子予以表彰，明确其骨干、可靠支柱与联系群众桥梁的作用，号召全党党员和全国人民向他们学习，使先进个人的示范成为联结政府与群众、推动人民事业的机制。","p":["你们是全民族的模范人物"]}]},{"t":"以持续实际作为维持既有地位","d":"既有的先进地位或光荣称号不是一次获得便永久不变，而是以持续的实际作为为条件才能维持：不断学习、不断作出贡献，地位才得以保持；一旦骄傲自满、停止努力，就失去保持既有地位的资格。","sub":[{"t":"以谦虚持续学习保持先进与继续贡献","d":"对已获光荣称号的先进人物，指出保持称号的条件：决不骄傲自满，继续在战斗中学习、向广大人民群众学习；只有如此才能继续作出优异贡献并保持光荣称号，把持续学习作为继续贡献与保持地位的必要条件。","p":["你们是全民族的模范人物"]}]},{"t":"以正确处理与当地人民政权的关系作为任务完成的政治前提","d":"一方进入另一方地域执行任务时，任务完成不只看任务本身与执行者的能力意志，而以正确处理与当地人民、政权及其领导者的关系并严守纪律为前提；政治关系处理得当构成任务得以完成的前提性政治基础。","sub":[{"t":"以尊重当地人民政权并严守纪律作为境外军事行动的政治基础","d":"部队进入异国境内执行军事任务时，先确立对当地人民、军队、政府、政党及其领袖的友爱尊重态度，同时严格规定军事纪律与政治纪律，把\"态度正确＋纪律严明\"作为完成军事任务的前提性政治基础，而不是任务完成后的附带要求。","p":["给中国人民志愿军的命令"]}]},{"t":"必胜信心以正视困难与落实条件为前提","d":"对胜利的信心不与困难估计相对立，而以充分估计可能遇到与必然遇到的困难为前提，并落实到具体可执行的取胜条件上；困难被正视使信心坚实，条件被落实使信心可靠，从而同时避免轻敌与空谈信心。","sub":[{"t":"以充分估计困难与落实取胜条件支撑必胜信心","d":"面对不可避免的困难，先作深刻而充分的估计，同时纳入\"可能遇到\"与\"必然遇到\"两类困难，再准备克服所需的精神条件——高度热情、勇气、细心和刻苦耐劳；同时判定总体形势的有利方面，把必胜信心落实到坚决勇敢、善于团结当地人民、善于和侵略者作战等具体取胜条件上，使信心建立在现实条件而非口号之上。","p":["给中国人民志愿军的命令"]}]},{"t":"以利益同一化建立共同事业胜利的政治基础","d":"面对与另一方人民共同承担的事业，仅在态度上保持友好并不够，而要在认识上把对方的事情完全看作自己的事情、如同对待自身利益一般，并把它落实为日常细小而具体的爱护行动；这种利益上的同一化及其纪律体现，构成事业赢得人民支持、最终取得胜利的前提性政治基础。","sub":[{"t":"把当地人民利益看作自己的事情并落实为爱护纪律","d":"部队进入异国或面对当地人民时，先完成认识上的同一化——把当地人民的事情看作自己的事情、如同在国内对待自己人民一样；再把这种同一化落实为每个指战员可执行的细致纪律，爱惜当地的一山一水一草一木、不取人民的一针一线；并把这种团结爱护明确为胜利的政治基础，使对当地人民的态度从外部约束升华为自觉行动，从而赢得人民拥护、保证共同事业成功。","p":["中国人民志愿军要爱护朝鲜的一山一水一草一木"]}]},{"t":"按推进程度区分对策以达全面覆盖","d":"在推行普遍性教育或动员任务时，不一律平均用力，先辨别各局部已经推进到的程度，对已推行者着重深入、对未推行者着重普及，以推进程度的差异决定动作的强弱，务求覆盖到每一处、每一个人。","sub":[{"t":"按推行程度分类推进宣传教育运动","d":"推行一项普遍性教育运动时，先辨别各地区已推行的不同程度，对已推行者继续深入、对未推行者普及推广，分别采取强弱不同的推进动作，并以\"每处每人都受教育\"为覆盖目标，实现从局部到全体的普遍化。","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"以群众参与与严密控制并重把握行动边界","d":"处理涉及人的强力肃清或斗争行动时，既依靠群众参与、使相关各方知情与闻，让行动具有广泛基础；又由组织严密控制行动的方向与范围，防止乱与错；对隐蔽于内部的对象分层、谨慎清理，把扩大参与与收紧控制统一于同一行动。","sub":[{"t":"镇反靠群众参与与严密控制并举","d":"开展对敌肃清工作时，判处死刑一般须经过群众并使民主人士与闻，以广泛参与保证慎重；同时由组织严密控制，做到不乱不错；对隐藏于军政机关内部和党内的对象分层、谨慎清理并加强保密；并向干部做教育、给干部撑腰，使斗争既有群众基础又不扩大化。","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"以中心任务统摄各方组织协同行动","d":"当多个组织共同执行同一项工作而容易各自为政时，先确立一个明确的中心任务，使各方组织围绕它统一领导、统一步调，把分散的力量凝聚到中心任务上，并以承担者实际处境的改善作为工作的落点。","sub":[{"t":"城市工作以生产计划为中心统一各方组织领导","d":"加强党委对城市工作的领导时，先确定中心任务——在工厂内以实现生产计划为中心，实行党、政、工、团的统一领导；明确依靠工人阶级的思想；在增加生产的基础上逐步改善工人生活；城市建设贯彻为生产、为工人服务的观点；上级工会着重解决下面的具体问题，使各方组织围绕中心任务协同运转。","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"新办法以局部试验经验为前提再全面推行","d":"对尚无把握、需要验证的新办法，不因目标正当就立即全面铺开，先选择局部进行试验或创造典型经验，待取得实际经验后，再依据经验向全面推行，使全局展开以局部验证为前提。","sub":[{"t":"以典型试验先行推动全局展开","d":"在推行尚缺乏把握的新办法时，先选择局部创造典型经验——城市工作中着重创造典型经验并迅速推及各处，整党中先进行典型试验，待经验成熟后再据以全面推行，使全局展开建立在局部验证的基础上，避免盲目铺开。","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"整顿队伍先立标准、分类分步、尊重自愿","d":"对队伍进行整顿与改造时，不靠一次清洗解决，先普遍进行标准教育，使成员明确合格条件；再按步骤推进、按类别区别对待，对需要清退者坚持自愿、不伤感情；吸收新成员以教育合格为前提，使整顿既严格又有分寸。","sub":[{"t":"整党分三年推进并对不同类别党员区别处置","d":"整顿党组织时，先肯定党的正确方面以统一认识，同时指出存在的问题；整党分三年推进，先普遍进行\"怎样做一个共产党员\"的教育、训练组织人员并作典型试验，然后根据经验整党；处置上先清洗混入党内的第四类人，再区别对待第二、三类人，对经教育仍不合格者劝其自愿退党、不伤感情；新区建党采取慎重方针，对积极分子先教育、合格者才吸收入党。","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"以共同政治基础团结各方并培育其自主力量","d":"扩大团结不以抹平差异为代价，而以各方共同承认的政治基础为前提，在基础上把不同成分团结起来并加以教育；同时对尚不具自主条件的方面，以培养其自己的干部为中心工作，使团结转化为各方自立承担事务的能力。","sub":[{"t":"以反帝反封建为基础团结各界并培养本民族干部","d":"开展统一战线工作时，先向干部讲清加强统一战线工作的理由；把知识分子、工商业界、宗教界、民主党派、民主人士在反帝反封建的共同基础上团结起来并加以教育；在少数民族工作中，以推行区域自治和训练少数民族自己的干部为中心工作，使团结走向各方自主。 # Method Dedup Index（13-18 批次） **批次：** 13-18（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 13、镇压反革命必须实行党的群众路线；14、镇压反革命必须打得稳，打得准…","p":["中共中央政治局扩大会议决议要点"]}]},{"t":"按严重程度分级并设定不可逾越的界限","d":"凡涉及对人或组织采取不可逆处置的任务，应先把对象按情节轻重分级、逐级规定对应处置，使最重者得到应有处理、较轻者得到缓冲空间；同时为界限边缘的情况设定不可逾越的硬性标准，防止因分级不清而扩大化。","sub":[{"t":"以明确界限控制打击面","d":"对运动中需处理的各类对象先按罪行严重程度分级，再逐级规定处置：最严重者坚决从重处置并迅即执行，罪该处死但情节较轻者采取缓刑、劳动改造等缓冲处置；对可捕可不捕者一定不捕、可杀可不杀者一定不杀，越过界限即属犯错误，把总数量控制在比例以内。本篇另含“保留主动权、以观后效”与执行死刑须报请上级批准要素；第17篇另含多维度从宽从严梯度原则（过去从宽、多数从宽、坦白从宽等）与五类划分、比例分布要素。","p":["镇压反革命必须实行党的群众路线","镇压反革命必须打得稳，打得准，打得狠","关于“三反”、“五反”的斗争"]}]},{"t":"群众路线与集中审查相结合保证任务正确","d":"影响面大的任务不能只靠少数人关门办理，也不能只凭热情草率推进。正确与否取决于是否按既定路线组织执行：既充分动员群众、吸收各方参加，又统一领导、严格审查关键环节；路线被忠实的程度决定结果正确的程度。","sub":[{"t":"以党的群众路线组织重大政治运动","d":"把群众路线确立为唯一正确的工作路线并逐项落实：党委领导、全党动员、群众动员、吸收各界人士参加、统一计划统一行动、严格审查关键名单、广泛宣传教育，反对关门主义、神秘主义和草率从事；以“是否完全遵照路线”判定工作正确与否，把严格审查名单与宣传教育作为避免犯错误的关键环节。第17篇另含大张旗鼓、首长负责亲自动手、号召坦白检举与分级惩处要素。","p":["镇压反革命必须实行党的群众路线","关于“三反”、“五反”的斗争"]}]},{"t":"以关键权力上收防范执行偏差","d":"在情绪容易走高、局面容易失控的任务推进期，基层执行者最易出错的决定权应集中到更高层级统一把关。防偏主要靠把关键权力从失控风险点移走，而非靠说服提醒；权限上收要统一彻底、不留例外，才能形成程序防线。","sub":[{"t":"以权力上收防范运动偏向","d":"预见运动高潮中局部易偏激失控，把最易出错的关键处置权（捕人、杀人批准权）从基层一律上收到更高层级统一行使，执行机关不得自行变更；用制度性的权限集中拦截基层擅自行为，为“左”的偏向设刚性防线，覆盖一切地方、不留缺口。第17篇另含检查权上收、禁止肉刑逼供与范围分批控制要素。","p":["镇压反革命必须实行党的群众路线","关于“三反”、“五反”的斗争"]}]},{"t":"以自愿交代与多数策略处理内部问题","d":"处理内部人员的历史或立场问题，不宜强迫清查，而应通过学习教育引导自觉交代、坚持自愿原则，由负责人主持控制节奏；按多数与少数区分对待，先争取多数、孤立极少数，从要害处先行试点取得经验，再逐步推广，使内部清理既查清问题又不造成对立。","sub":[{"t":"以自愿整风方式清查内部问题","d":"对队伍内部需要清查的问题采用整风式处理：先组织学习文件，再号召有问题的人（不是一切人）自觉交清历史、坦白隐藏问题；由负责人主持、坚持自愿原则、不强迫，单位时间要短；策略上争取多数、孤立少数，先清查要害部门取得经验再推广，并吸收党外人士参加。","p":["镇压反革命必须实行党的群众路线"]}]},{"t":"以群众性常设组织承接长期任务","d":"一次性运动成果要转化为长期有效的工作，应依托按单位普遍建立、由群众参与产生、吸收各方可靠力量参加的常设组织来承接，并由相应领导机关统一指导；组织建立要选在条件具备之后、有领导地推进，既发挥群众自主参与，又防止失去管理被利用。","sub":[{"t":"以群众自治组织承接治安任务","d":"把运动中的治安成果固化为长期制度，按单位（农村以乡、城市以机关学校工厂街道）普遍组织由人民选举产生的治安保卫委员会，吸收可靠党外爱国分子参加，形成统一战线性质的组织；明确受基层政府和公安机关领导，承担防奸防谍、保卫公众治安的职责，并在基础工作完成后有领导地组织。","p":["镇压反革命必须实行党的群众路线"]}]},{"t":"以无错底线约束处置力度","d":"对必须坚决推进的处置行动，力度与准确必须同时成立：在确立总体尺度时把“不出错”设为不可逾越的底线来约束手段的使用，使坚决性不以错误为代价；底线优先于效果，防止因求狠而失准、因怕错而退缩。","sub":[{"t":"以稳准狠三重尺度界定处置标准","d":"对必须坚决推进且极易出错的处置任务，先确立总方针并对每一要素给出可操作定义：稳即注意策略、准即不杀错、狠即坚决处置一切应处置者（不应处置者当然不处置）；再把“不杀错”设为不可动摇的底线，守住底线即不因外部叫唤而动摇决心，避免因姑息而失效、因求狠而失准。","p":["镇压反革命必须打得稳，打得准，打得狠"]}]},{"t":"对双向执行偏差按后果轻重区别设防","d":"执行推进中的偏差常以“不足”与“过头”成对出现，不能平均用力；应比较各自后果的严重与不可逆程度，把控制重点和底线设在后果更重的一侧，优先防止不可挽回的错误，对可补救的不足则用教育逐步补足。","sub":[{"t":"在两类执行偏差中优先防后果更重的一侧","d":"排查执行中成对出现的偏差（如劲头不足与草率从事），比较各自后果：不足可经教育补救、迟延影响不大，而草率导致错捕错杀、影响很坏且不可挽回；据此把控制重点与强制要求集中在后果更重的一侧，坚持严格控制、谨慎从事，明确“不可捕错杀错”的底线，再以教育补足力度。","p":["镇压反革命必须打得稳，打得准，打得狠"]}]},{"t":"以历史进步标准评判具体对象的价值","d":"评价历史人物、事件或作品，不以其自我标榜或一时的颂扬为准，而把它放回所处时代的主要历史任务之中，考察它对旧经济基础及其上层建筑的态度、对反动统治者的态度、是否代表新的阶级力量和新的思想；以它推动还是阻碍历史进步来判定应当肯定还是否定。","sub":[{"t":"以历史发展标准评判历史人物与作品的歌颂价值","d":"面对被歌颂的历史人物或作品，先确认其所属时代的主要历史任务，再考察其行为是触动还是维护旧的经济基础及其上层建筑、对反动统治者是坚持斗争还是奴颜婢膝地投降，并判断它是否代表新的社会经济形态、新的阶级力量和新的思想，据此决定应当歌颂还是反对，从而识别出打着“为人民服务”等革命旗号的反动宣传。","p":["武训传","应当重视电影〈武训传〉的讨论"]}]},{"t":"以可集结力量的广度与巩固度判断胜负前景","d":"判断一项事业或斗争的胜负与前景，不取决于对方表面强大或我方一时困难，而取决于能否识别并巩固国内国际一切可团结的力量；力量集结越广泛、团结越巩固，胜利越有把握，低估这一基础必然错判形势。","sub":[{"t":"以团结国内国际一切力量为胜利基础","d":"盘点国内国际一切可以团结的力量（国内各民族、各民主阶级、各民主党派、各人民团体及一切爱国民主人士在工人阶级和共产党领导下的巩固团结，国际上以苏联为首的和平民主阵营与世界爱好和平人民的同情），把这种团结确立为各项胜利的基础，并据此判断低估这一力量的敌人必败、世界局面必变。","p":["三大运动的伟大胜利"]}]},{"t":"以具体行动任务支撑必要目标的持续坚持","d":"对必须长期坚持的必要目标，不能止于原则表态，而应把支持它的需要具体化为全体可执行的生产、节约等行动任务，并以中心任务的形式统摄动员；用物质与行动上的准备保证目标的持续实现。","sub":[{"t":"把坚持斗争的需要落实为中心任务与生产节约行动","d":"对必须继续坚持的正义斗争，先确认其必要与正义，再把支持斗争的需要确立为全国中心任务，具体化为增加生产、厉行节约等可执行行动以提供物质支撑，使全体人民围绕该任务一致行动。","p":["三大运动的伟大胜利"]}]},{"t":"以对等前提条件是否成立判定合作成败","d":"谈判或合作的成败不由单方愿望或表面表态决定，而取决于对方能否在公平合理的基础上满足前提条件、不再破坏合作；条件成立则可能成功、条件缺失则必然失败，判断应依据可核验的条件而非意愿。","sub":[{"t":"以对方能否满足公平合理条件判定和平谈判成败","d":"先确立和平解决的总方向，再明确对方必须满足的前提条件（在公平合理基础上解决问题、不再用破坏和阻挠手段干扰谈判），据条件是否具备判定谈判可能成功或不可能成功，不以单方愿望为准。","p":["三大运动的伟大胜利"]}]},{"t":"以分化瓦解形成统一战线孤立少数","d":"面对成分复杂、内部存在矛盾的对象群体，不一律打击，而先分清依靠对象与团结对象，利用对象内部矛盾分化瓦解，实行团结多数、孤立少数的策略，形成统一战线，使少数顽固分子陷于孤立后集中处置，以较小代价缩小打击面。","sub":[{"t":"以统一战线分化策略孤立少数","d":"开展对复杂对象群体的斗争时，先明确依靠力量（工人阶级）与团结对象（守法的资产阶级及其他市民），对阶级和群众力量作精密部署，利用矛盾、实行分化、团结多数、孤立少数，迅速形成统一战线，使罪大恶极者陷于孤立后再依法给予逮捕、没收、罚款等必要惩处。","p":["关于“三反”、“五反”的斗争"]}]},{"t":"以建设性目的规定整治行动","d":"大规模整治行动不以惩处本身为终点，而把查明真实情况、划清界限、改组组织、建立监督制度、追回损失等治理性目标纳入斗争目的，使运动成果转化为可长期运作的治理与组织成果。","sub":[{"t":"使斗争服务于查明情况与组织制度改造","d":"开展大规模整治时，先明确规定斗争要达到的建设性目的：彻底查明对象情况以利计划管理，明确划分阶级界限、改组组织团体，建立工人店员监督生产和经营的制度，从补、退、罚、没中追回经济损失，并在大的和中等的私营企业工人店员中建立党的支部，使斗争成果沉淀为长期制度。","p":["关于“三反”、“五反”的斗争"]}]},{"t":"以确立工作重心并组织实行保证决策落地","d":"一项需要全面推行的决策不能停留在文件层面：应先把必要事项确立为统一的工作重心，再经逐级印发、内外解释与组织实行，转化为基层的实际行动。决定发出不等于落地，实行是否到位取决于组织推进的深度。","sub":[{"t":"以大事定位推进决议草案的组织实行","d":"对需要普遍推行的决议，先确立其为全党的大事并明确适用范围（一切已完成土地改革的地区都要解释和实行）；再把草案印发到县、区委，在党内外进行解释，并组织实行，使文件逐级下达到基层并转化为统一行动。","p":["把农业互助合作当作一件大事去做"]}]},{"t":"以内容成熟度划定传播范围","d":"内容的公开与传播范围应与它的成熟定型程度相称：尚未定型时只在限定层级内流传，防止把未定稿当作正式结论对外扩散；公开层级随内容是否具备对外发布的成熟度而调整。","sub":[{"t":"按草案定型程度划定传播范围","d":"对尚未定型的文件，先判定其“草案”性质，再据此划定传播边界：可在党内刊物上发表，不在党外报刊上发表；以内容的定型程度决定公开层级，防止把未定稿当作正式结论扩散。 # Method Dedup Index（19-24 批次） **批次：** 19-24（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 19、元旦祝词；20、中共中央关于西藏工作方针的指示；21、工人阶级与资产阶级的矛盾是国内的主要矛盾；22、团结起来，划清敌我界限；23、祝贺中国人民…","p":["把农业互助合作当作一件大事去做"]}]},{"t":"新任务纳入既有总框架以承接正当性并统一动员","d":"面对必须在整体范围迅速推开的新任务，不孤立提出，而是先纳入既有的总体工作框架，赋予其与其他任务并列的定位，承接整体框架的正当性与组织力，再以全体一致、雷厉风行的要求统一推进。","sub":[{"t":"把新任务定位为新战线并发动大规模群众斗争","d":"把新任务命名为整体工作框架中的\"新开辟的战线\"，与既有战线并列获得同等地位；点明其要清除的积弊对象（贪污、浪费、官僚主义等旧社会遗留污毒）；号召全体人民和一切工作人员大张旗鼓、雷厉风行地一致开展群众性斗争。","p":["元旦祝词"]}]},{"t":"以统一框架归类工作并按阶段检阅推进","d":"面对多项并存的工作，先以统一框架把分散任务归类为可逐项检阅的并行单元，再按过去—现在—未来的时间阶段确认成绩、提出期望，使整体动员获得连续的组织结构。","sub":[{"t":"以战线化检阅组织承前启后的动员","d":"在阶段交接时刻，把分散于各领域的工作按领域组织为统一\"战线\"并逐条确认；以肯定成绩、总结上一阶段胜利、提出下一阶段更大目标期望的方式，形成承前启后的整体动员。","p":["元旦祝词"]}]},{"t":"以物质基础的建立作为政治举措的前提","d":"政治举措（改革、争取群众、统一战线）的效力受制于是否具备物质基础。进入缺乏物质基础的新环境时，先以生产自给和保障民生立脚，政治措施才能生根；否则争取多数、孤立少数的政策会因无物质依托而软弱无力。","sub":[{"t":"以生产自给与贸易建立立脚的物质基础","d":"进入缺乏物质基础的新区域时，不急于推行政治改革，先以精打细算、生产自给解决自身生存问题，并以之影响群众；同时打通对内对外贸易，不使当地人民生活水平下降。生产和贸易问题解决，才有存在的物质基础，团结多数、孤立少数的政策才不至软弱无力。","p":["中共中央关于西藏工作方针的指示"]}]},{"t":"根据条件成熟度把握行动时机","d":"推行政策前须先衡量其所需基础是否齐备，基础不成熟而勉强实行则害多利少。此时应暂缓实行、维持现状，用时间做工作、积累理由，待条件成熟再行推进，使己方理由随拖延而增多、对方理由随拖延而减少。","sub":[{"t":"在条件不成熟时暂缓实行以时间积累条件","d":"判断一项政策能否实行，须看物质、群众、上层等多重基础是否齐备；任一基础不备而勉强实行则害多利少。此时暂不实行、维持现状，只做生产、贸易、修路、医药、统战等好事，以争取群众，用时间积累理由，待条件成熟再谈实行。时间拖得愈久，己方理由愈多，对方理由愈少。","p":["中共中央关于西藏工作方针的指示"]}]},{"t":"以两案准备应对不确定前景","d":"面对方向不明的前景，不孤注一掷，而是先推演可能出现的各类结局，并为每种结局预备一条可接受的处理路径，使无论和平转化还是冲突爆发都能立于不败并继续推进目标。","sub":[{"t":"对未来两种前景同时准备使两种结局均对我有利","d":"对未来不确定期，先推演可能发生的两类情形——和平转化与暴力反抗——并分别预备对应手段：统战收效则群众渐靠拢、坏分子不敢暴乱；暴乱则我军在自卫中反击。不论出现哪种，都预先确立\"对我有利\"的处置路径，使对方反抗本身成为继续推进理由的积累。","p":["中共中央关于西藏工作方针的指示"]}]},{"t":"透过对方姿态识别其真实意图并保留主动","d":"对方以请愿、示威等姿态提出的要求往往带有策略伪装，须透过表面要价识别其真实底线与意图（是要价还是决裂）。在力量对比不利或时机未到时，可形式上守住原则立场、实际上相机退让，以争取时间与主动。","sub":[{"t":"在事实上接受请愿而在形式上保持攻势","d":"面对对方的请愿或示威，先解读其真实意图：内容有策略、不表示决裂、只要求让步，表面要价（如要求不驻军）并非真意而是交换筹码。据此在事实上接受请愿、延缓协定实行，以缓和局势；而形式上责备其无理以守住原则；实际准备让步、等候条件成熟，为将来进攻预留空间。","p":["中共中央关于西藏工作方针的指示"]}]},{"t":"以主要矛盾判断校准对象定位","d":"判断某一对象是主要矛盾一方还是中间势力、是斗争对象还是争取对象，不来自既定称谓而来自对现实主要矛盾的判断；主要矛盾随阶级关系变化而转移时，须同步校正对象定位与策略表述，使政策对象判断跟随现实关系而非旧框架。","sub":[{"t":"依据主要矛盾转换重新定位社会力量","d":"判定地主阶级与官僚资产阶级被推翻后，国内主要矛盾已转为工人阶级与民族资产阶级的矛盾；据此重新认定民族资产阶级的政治位置——由可争取的中间势力变为主要矛盾一方；并同步统一表述，删除与新判断相抵触的\"中间阶级\"称谓。核心链：确认矛盾地位转移 → 重新定位相关社会力量 → 校正统一表述。","p":["工人阶级与资产阶级的矛盾是国内的主要矛盾"]}]},{"t":"按性质区分界限以区别对待","d":"面对需要团结多数、孤立少数的对象，先按问题性质区分不同界限（如敌我界限与内部是非界限），对不同性质的问题采取不同处理方式——对根本对立者划清界限，对内部是非者教育改造，从而在团结最大多数的同时保持问题性质不被混淆。","sub":[{"t":"划清敌我界限并区别处理敌我问题与内部是非问题","d":"把敌我界限作为第一界限，把内部是非界限作为第二界限；对属于敌我性质者明确划清、不与妥协，对属于内部是非者（如贪污分子）不作敌我处理而采取教育改造；再按是否真正划清敌我界限、是否为人民服务的标准联合一切可联合者，坚持统一战线而不取消。","p":["团结起来，划清敌我界限"]}]},{"t":"依据对方力量对比与矛盾判断战略大势","d":"面对战争、谈判等战略抉择，不凭愿望或恫吓作判断，而系统分析对方的实力消耗、财政负担、内外矛盾与战略重心，据此判断大势所趋；在此基础上决定打、谈、和并举的组合手段，并认清己方在全局中可主导的范围。","sub":[{"t":"依据对方力量与矛盾判断和战双轨方针","d":"分析对方四项客观条件——人员损耗、财政负担、内外矛盾、战略重点所在；据以判断\"大势所趋，不和不利\"，得出谈还是要谈、打还是要打、和还是要和的双轨方针；同时认清朝鲜战争我方只能作一半主，不把不可控因素计入承诺。","p":["团结起来，划清敌我界限"]}]},{"t":"把复杂任务分解为可检验的具体问题逐一解决","d":"面对复杂艰巨的任务，先将其分解为若干可检验的具体问题，逐一确认各问题的解决状态；对条件不足的环节，用因地制宜的土办法就地弥补，使整体任务在逐项攻克的进程中推进。","sub":[{"t":"把战争难题分解为具体问题逐一解决","d":"面对复杂战争任务，先分解出可检验的具体问题（能不能打、能不能守、有没有东西吃），逐一确认解决状态；对条件不足的环节，用因地制宜的土办法（钻洞子、储粮于洞）就地弥补，使方针明确、阵地巩固、供给有保证。","p":["团结起来，划清敌我界限"]}]},{"t":"以歼灭有生力量为目标并以保存己方为取舍争取主动","d":"在整体防御或相持的对抗中，不以守住或夺取地盘为直接目标，而以不断歼灭对方有生力量为目标；为此在选定要点的局部集中优势力量主动寻歼，并以保存己方力量为界限决定攻守取舍——能守则守、不能守则弃——从而持续消耗对方、保留主动与再战能力。","sub":[{"t":"在选定战术要点集中优势力量歼敌并依条件取舍阵地","d":"在若干被选定的战术要点上集中优势兵力火力，采取突然动作，对成排、成连、成营的敌军予以全部或大部歼灭；待敌反击时在反复作战中大量杀伤；对攻克据点能守则守、不能守则弃，保持主动、准备以后反击。以阵地为依托连续实行，使敌损远大于我，终可迫敌妥协。","p":["祝贺中国人民志愿军的重大胜利"]}]},{"t":"以实际战果与自身代价的双向对比评估方法价值","d":"判断一种方法是否有效、是否应坚持，不依据口号、愿望或个例，而依据其对对方的实际打击效果与己方付出的实际代价这一双向结果的变化；只有对方代价升高与己方代价降低同时成立，方法才算被确认为有效，进而获得继续实行的依据。","sub":[{"t":"以敌我双向损失对比检验战法有效性","d":"不凭主观估计判断战法是否有效，而对比其推行前后双方损失变化：阵地作战以来给予敌军的损失远超前此各次运动战，同时我军月均人员损失由二万五千人降至八千人。以敌损大增、我损大减的双向结果确认方法有效，并据此决定继续坚持。","p":["祝贺中国人民志愿军的重大胜利"]}]},{"t":"以胜利为契机总结经验并全面升级组织协作","d":"在取得阶段性胜利后，不把胜利当作终点，也不简单重复既有做法，而以总结经验为杠杆，从组织程度、方法技术、资源效率、对外协作等各面同时提出升级要求，使一次胜利成为整体能力持续提升的起点。","sub":[{"t":"以周年总结提升组织性并团结友军争取更大胜利","d":"在出国作战两周年之际，以总结经验为起点，同时提出提高组织性、提高战术、节省弹药三方面的自身改进，并更亲密地团结朝鲜同志和朝鲜人民，把单次胜利转化为争取今后更大胜利的持续升级。","p":["祝贺中国人民志愿军的重大胜利"]}]},{"t":"从群众直接反映中发现组织内部问题","d":"领导机关与基层之间存在信息距离，对下情可能麻木不仁；须以群众直接反映的问题（来信、控告等实际信号）为可靠线索穿透这一距离，发现并检查组织中真实的干部问题，避免对坏人坏事熟视无睹。","sub":[{"t":"从处理人民来信入手检查基层干部问题","d":"领导机关把处理人民来信作为了解下情的切入口，通过清理积压来信、受理群众控告，检查县、区、乡三级干部中命令主义和违法乱纪分子的情况，并结合整党建党等工作向这些坏人坏事展开坚决斗争，以群众直接反映的问题为线索，纠正领导机关对基层问题不了解或熟视无睹的官僚主义。","p":["反对官僚主义、命令主义和违法乱纪"]}]},{"t":"以惩恶扬善并举和正反典型对照引导风气","d":"在整顿组织作风时，不仅对反面典型予以揭发、制裁与清除，还须在适当时机同步调查、表扬正面典型，以正反两面对照形成明确导向，使正气得到弘扬、邪气受到压制，并教育干部与群众。","sub":[{"t":"对典型事例惩处坏人、表扬好人并举以发扬正气","d":"对典型的官僚主义、命令主义和违法乱纪事例在报纸上广为揭发；违法情形严重者给以法律制裁，党员必须执行党纪；各级党委有决心把为群众痛恨的违法乱纪分子惩处并清除出党政组织，最严重者处极刑；在斗争达到适当阶段时，调查分析并表扬典型好人好事，使全党向好的典型看齐，发扬正气、压倒邪气。惩恶与扬善并用，先惩处清除、后表扬推广。 # Method Dedup Index（25-30 批次） **批次：** 25-30（每 6 篇文章一个独立 method index 文件） **当前覆盖：*…","p":["反对官僚主义、命令主义和违法乱纪"]}]},{"t":"以根本路线为统一基准判别并纠正方向性两极偏差","d":"方向性错误不能凭个别口号或主观感受判定，须对照统一的根本路线基准；同一基准之下会同时产生相反的两极偏差（冒进与停滞），纠偏须两极并举，并以分步渐进的方式保持方向与节奏的统一。","sub":[{"t":"以过渡时期总路线为轴判别并纠正\"左\"右偏差","d":"面对政策路线分歧，先确立总路线（工业化＋三大改造）作为衡量一切工作的统一标准；据此界定两类相反偏差——急躁求快为\"左\"、民主革命后停留不转为右；再以\"逐步过渡\"为正确推进方式，把过程时间化分步（十五年、分月），走得太快是\"左\"、不走是右，反\"左\"反右直至全部过渡完。推进农业改造时同样以总任务为基准，识别不去发展（右倾）与搞猛了（\"左\"倾）两极偏差，坚持自愿原则、有准备有步骤分步推进。","p":["批判离开总路线的右倾观点","青年团的工作要照顾青年的特点"]}]},{"t":"从直接接触实际中把握被表面掩盖的真实状况","d":"面对表面平静却潜伏严重矛盾的局面，形式化、表面化的了解会失真；只有派具备对象认知与同情的干部真正深入实地、直接接触实际，才能破除表象、发现被掩盖的真实问题。","sub":[{"t":"派懂政策且有同情的干部实地深入调查而非走马观花","d":"面对表面平静但暗含严重问题的民族关系，应派出懂民族政策、对少数民族同胞怀同情的同志率访问团实地认真调查研究、帮助发现问题解决问题，反对走马看花式访问。核心是让能理解对象实际的人直接接触实际。","p":["批判大汉族主义"]}]},{"t":"先准确判定问题性质再施以针对性系统教育","d":"纠正错误思想的前提是不低估问题：先把对象准确判定为严重而非残余/轻微，再施以系统的、分步的思想教育与改造。诊断性质决定处置力度，轻判会错失时机、危险积累。","sub":[{"t":"准确判定民族关系问题为严重大汉族主义而非残余并开展系统教育","d":"对民族关系问题先纠正\"只是残余\"的轻判，明确其为严重的（资产阶级思想统治、未受马克思主义教育与民族政策）大汉族主义，再开展认真教育、一步一步解决。关键在准确判定性质与严重程度，再匹配针对性思想改造。","p":["批判大汉族主义"]}]},{"t":"以基于事实的公开批判配合内部教育引导群众","d":"纠正具有社会影响的错误思想，仅靠内部教育不够；应以基于事实的公开舆论批判作配合，使纠正既深入组织内部，也面向社会、引导群众认知。公开批判须以事实为据。","sub":[{"t":"借助基于事实的公开报刊批判配合党内教育","d":"除内部教育外，运用报纸等公开舆论根据事实多写文章公开批判，教育党员和人民。把基于事实的公开批判与内部教育结合，使错误思想既在内部被纠正、也在社会层面被揭批。","p":["批判大汉族主义"]}]},{"t":"从产生问题的上层组织入手统一治理","d":"当问题的表现集中在基层、而其制度性根源在上层组织时，不应就基层现象就地处置，而应追溯到产生问题的组织层级，在该层级展开针对性斗争并统一规定、废止过时制度，从源头根治。","sub":[{"t":"追溯基层负担根源至领导机关并统一规定治理","d":"面对基层任务、会议、表册、组织、兼职过多等负担问题，先断定其根源不在基层自身而在上级领导机关的分散主义与官僚主义，再在该层级展开反分散反官僚斗争，并统一规定任务、会议、表册、组织形式与积极分子使用，废止各自为政的旧办法。","p":["解决\"五多\"问题"]}]},{"t":"逐级分责并实地核查基层实情","d":"一项治理任务涉及多个组织层级时，应自上而下逐级明确责任归属，使每级都有负责主体并逐级报告；同时通过实地检查基层真实情况校正决策参考，让部署既分层落实、又不脱离基层实际。","sub":[{"t":"按行政层级分责清理并实地检查基层情况","d":"对须多级组织共同落实的治理任务，按中央、大区省市、专区县逐级明确清理责任，各级由主管同志负责规定解决办法并逐级报告；同时上级派出检查组实地检查一两个区、乡的真实情况作为参考材料，使部署既有层级责任、又扎根基层实际。","p":["解决\"五多\"问题"]}]},{"t":"以压倒一切的中心任务为界并依对象实际限定干预","d":"当对象同时承受多项任务时，应先确立压倒一切的中心任务作为衡量标尺，凡妨碍中心任务者一律排除；并依据对象实际的生产方式与经济条件限定干预程度与方式，用间接引导代替直接指令。","sub":[{"t":"以压倒一切的农业生产为界限定任务并依小农经济实际减少干涉","d":"面对农村多项工作竞相布置的局面，确立农业生产为农村压倒一切的中心工作，其他工作均围绕其服务，凡妨碍农民生产的任务和工作方法必须避免；因我国农业是分散小农经济，不能对农民施以过多干涉，只能用价格政策及必要可行的经济、政治工作加以指导。","p":["解决\"五多\"问题"]}]},{"t":"以授权审阅程序作为权威名义行为的效力前提","d":"以组织或权威名义作出的行为，其效力与正当性不取决于名义本身，而取决于是否完成既定的授权审阅程序；绕过该程序擅自以名义行事，行为无效并构成破坏纪律。核查权威名义行为时应先检验其是否经过既定授权程序，再判定效力与责任。","sub":[{"t":"确立权威名义文件发出须经审阅方为有效并核查违规","d":"面对以中央名义发出的文件、电报未经最高决策者审阅便擅自发出、破坏纪律的问题，先确立程序规则：凡以中央名义发出的文件、电报必须经最高决策者审阅方能发出，否则一律无效；随后部署对既往一段时期内未经审阅即以组织名义发出的文件、电报进行专项核查，弄清数量与情况，并把擅自发出定性为错误、破坏纪律的行为。","p":["对刘少奇、杨尚昆破坏纪律擅自以中央名义发出文件的批评"]}]},{"t":"以变动现实检验凝固化提法","d":"概念与提法的有效性须以现实是否处于变动为尺度：凡把本在变动的过程凝固为可\"确立\"、可\"确保\"、可永远\"走向\"的静止状态，都是用静止框架裁剪动态现实；应以动态现实检验凝固化提法，凡不能适应变动者即失当。","sub":[{"t":"以动态现实逐句检验凝固化口号提法","d":"面对貌似合理的政治口号，先把错误主张概括为若干具体提法（确立秩序、走向、确保私有），再以过渡时期天天变动、年年在变的动态现实逐一对照，凡提法隐含静止、含糊未达或迁就现状而不能适应变动者，即判定其有害、妨碍事业。","p":["批判离开总路线的右倾观点"]}]},{"t":"按对象实际特点确定统一任务的执行方式","d":"统一任务要求不能以同一模板强加于所有对象；执行者应在保持统一目标的前提下，以对象（人群或领域）的实际特点——年龄、负担能力、需求差异——为依据确定执行方式与独立活动安排。统一要求与对象特点是结合而非替代关系，脱离对象特点的执行会脱离群众。","sub":[{"t":"围绕党的中心任务照顾青年特点开展独立工作","d":"面对组织既要服从统一领导又要保持对象针对性的关系，先明确配合党的中心工作是前提，同时必须有照顾对象特点的独立工作；再识别对象（青年）长身体、需学习、负担不能过重、需娱乐休息等实际特点，据此安排独立活动与系统工作；以脱离对象特点即脱离群众为检验标准。","p":["青年团的工作要照顾青年的特点"]}]},{"t":"全面兼顾相互制约的两个方面、防止偏执一头","d":"当两个方面的要求相互制约、缺一不可（如推进工作与恢复体力、学习与休息）时，认识上须把两方面同时纳入安排、充分兼顾，不能只抓紧一头而搁置另一头；积极性或某一要求的过度膨胀，会以另一方面的失衡为代价，统筹兼顾才可持续。","sub":[{"t":"学习工作与休息娱乐两方面充分兼顾、两头抓紧","d":"面对积极性过高导致过劳的问题，先承认\"太积极太热心以致过于疲劳\"的现实，再规定承载底线（睡眠九小时、减少上课与会议），把学习工作与休息娱乐两方面同时安排、充分兼顾，做到两头都抓紧，并设监督执行机制，防止只抓紧一头、搁置另一头。","p":["青年团的工作要照顾青年的特点"]}]},{"t":"以多数人的实际可行为基准设置组织要求与规则边界","d":"组织制度与规则要求的可行性须以多数成员的实际能力为基准：过严、只有少数能办到的规定应放宽，使多数跟得上；原则要求与实际之间的差距应被承认并通过灵活执行弥合，不以理想要求取代现实可能，规则边界只为分清根本界限而设。","sub":[{"t":"按多数人可行能力放宽组织要求、原则性灵活执行","d":"制定组织制度（团章）时，先把重点放在多数而非少数先进分子；把义务过多、过严的条文放宽到多数人跟得上的程度，凡办不到或只有少数能办到的不要规定；承认\"应当是那样、实际是这样\"的差距，原则性要灵活执行，规则边界只为分清敌我等根本界限而设。","p":["青年团的工作要照顾青年的特点"]}]},{"t":"以实际能力而非资历年龄判断人并信任新生力量","d":"判断一个人的价值与能否胜任，应以实际能力与工作表现而非年龄、资历、经验多少为标准；对新生力量应充分信任绝大多数能够胜任，允许个别偏差通过改选等机制校正，不因个别风险动摇对整体方向的信任。","sub":[{"t":"按实际能力而非年龄资历选拔干部并充分信任青年","d":"选拔年轻干部时，用历史事例证明青年可当大任，明确\"不能统统按年龄，还要按能力\"；提高年轻干部名额占比，充分相信绝大多数能胜任，允许个别人不称职通过改选校正，不因个别风险否定整体方向，并说服不赞成者。","p":["青年团的工作要照顾青年的特点"]}]},{"t":"信任与威信以实践了解为基础、循序渐成","d":"信任与威信不是靠名义或命令形成的，而是以他人对当事者在实践中的真实了解为前提：\"真正了解，才能相信\"。因此对新生领导者的信任应留出实践检验与渐进建立的余地，靠坚持主要原则与充分民主生活逐步积累，不急于求成、不因一时批评动摇。","sub":[{"t":"靠实践了解与充分民主生活逐步建立威信","d":"对待新领导威信不高的问题，先承认威信是逐渐建立的、不强求；做法上抓大放小，只抓主要原则（三大纪律八项注意）、不禁不查琐碎骂语，靠革命实践让群众真正了解而信服，以充分民主生活、当面揭疮疤化解私下议论，不急于求成，承认问题会长期存在。","p":["青年团的工作要照顾青年的特点"]}]},{"t":"以实际关系与分配结构判定性质而非名义归类","d":"判定一个事物（尤其经济成分）的性质，不能以其名称、形式归类为据；性质由该事物与政权、主导经济的实际关系，以及产出的实际分配归属结构决定。透过名义归类，以实际占有、服务目的与分配比例衡量真实性质。","sub":[{"t":"以政权关系、服务目的与利润分配判定经济成分性质","d":"判断一种经济成分（如现存资本主义经济）的性质，不从其名称出发，而先看它与人民政权和国营经济的实际关系（政府管理、与国营经济联系、受工人监督）；再看存在目的（主要供应人民和国家需要而非为资本家利润）；再以利润分配比例（约四分之一归资本家，其余归工人福利、国家税收与扩大生产设备）量化利益归属；据此判定其带很大社会主义性质、对工人和国家有利。 # Method Dedup Index（31-36 批次） **批次：** 31-36（每 6 篇文章一个独立 method index…","p":["关于国家资本主义"]}]},{"t":"以阶段总目标作为判断局部行动方向的统一尺度","d":"面对由多个局部构成的长期任务，需要先确立覆盖整个阶段的总目标，并以它作为衡量各局部行动方向的共同标准。局部的对错不能只由局部自身的效果判断，偏离总目标的两个相反方向都应被认作方向性错误。","sub":[{"t":"以阶段总任务作为各项工作的统一判准","d":"先界定当前阶段的起止与性质，再规定这一阶段的总任务及其大致完成期限，并把它确立为衡量各项具体工作的共同依据，而不是让每项工作各自确定方向。检查时以是否离开总任务为准，双向识别偏差：走得过缓与走得过急都判为方向性错误，使局部工作的对错有统一尺度可依。","p":["党在过渡时期的总路线","改造资本主义工商业的必经之路"]},{"t":"以总路线为纲统摄各项具体工作","d":"先确立统摄全局的主题之纲——社会主义和资本主义的矛盾并逐步解决（总路线），使克服\"五多\"以及各项政治工作、经济工作都有统属；把农贷、救济、水利、深耕密植等具体好事与总路线、社会主义联系起来，才能从对农民\"行小惠\"上升为社会主义工作，避免在小农经济基础上零敲碎打。","p":["关于农业互助合作的两次谈话"]}]},{"t":"已定原则应对后续行动保持约束力","d":"当一类问题的基本原则已经由正式程序确定下来，后续处理应先确认它是否已被解决，再以该原则为准检查现行做法，而不是让同一问题被反复另立标准。原则的效力体现在跨时间的执行连续性上。","sub":[{"t":"以既定决议原则约束后续工作中的另立一套","d":"先确认这类问题的基本原则是否已由正式决议提出并作过原则性解决；若已解决，后续工作的任务是照规定执行，而不是重新提出主张。据此检查实际做法，识别不愿遵照规定、在个别问题上另搞一套、公然违反原则等不同偏离形态，并把它们指认为同一性质的问题：绕开已定原则重新立论。","p":["党在过渡时期的总路线","反对党内的资产阶级思想"]}]},{"t":"以方向实质而非表面标签定性认识错误","d":"判断一种思想认识的性质，应依据其实际作用方向——它有利于谁、服务于何种基本路线，而不是依据个人品格、派别标签或表面说辞；方向实质决定错误的性质与处理方式。","sub":[{"t":"以阶级方向判定党内错误性质","d":"面对党内思想认识分歧，先区分一般性错误与原则性错误；对原则性错误不按个人品格或派别标签定性，而看其实际利于谁、背离什么路线——有利于资本主义、离开总路线即资产阶级思想反映；据此确定批判重点与处理界限，并教育干部展开批评讨论。","p":["反对党内的资产阶级思想"]},{"t":"以实际作用方向识别口号与政策的阶级实质","d":"面对\"确保私有财产\"\"四大自由\"一类貌似正当的口号主张，不因其表面合法性（法律保护私有财产）而认同，而看其实际作用方向——有利于谁、走资本主义还是社会主义的路；据此识别其为有利于富农和富裕中农的\"小惠\"，防止以正当名义推行错误方向。","p":["关于农业互助合作的两次谈话"]}]},{"t":"以是否符合客观实际为尺度判定双向偏差","d":"判断工作方法的对错，应以是否符合客观实际为统一尺度，由此双向识别相反方向的同类错误——过与不及同源于主观脱离客观；克服偏差在于使主观与客观相适合，而非只纠一偏。","sub":[{"t":"以是否符合实际双向识别并克服主观主义","d":"面对工作偏差不只看某一侧——急躁冒进与保守迟缓都是不按实际情况办事，同属主观主义；中央领导机关要走出去了解下情，避免没有原料只出次品；用同一标准（是否符合客观实际）双向识别并一起反对，同时据需要与可能（政治、经济、干部条件）划清正当工作与\"干涉过多\"的界限，不把需要做、可能做且非命令主义的正当工作反掉；以惩前毖后、治病救人的办法处理犯错误者，努力使主观与客观相适合。","p":["反对党内的资产阶级思想","关于农业互助合作的两次谈话"]}]},{"t":"以集体决策机制保障组织行动统一","d":"组织的统一行动不能依赖个人威信或自发一致，而须依靠集体领导与统一的决策程序，使重大事项先经集体讨论再执行，防止分散主义破坏统一；对态度分歧者宜先教育、再区分处理。","sub":[{"t":"以集体领导约束分散主义倾向","d":"面对组织内部各行其是的倾向，先认定其危害（削弱统一行动、妨碍正确领导），再确立\"一切主要和重要的问题先由党委讨论决定、再由政府执行\"的决策程序；区分不同态度者分类处理——对一般缺乏党性者说服教育，对极少数坚决反对集体领导者另作处置；以集体政治经验与智慧保障决策正确和团结。","p":["反对党内的资产阶级思想"]}]},{"t":"以既定方针的明确化统一行动前提","d":"方针即使已由纲领确定，若未在决策者头脑中被明确肯认，仍不能成为行动的前提；须先以实践经验确认其健全性，再经\"明确起来、逐步具体化\"的认识环节，使正确方向成为上下统一的行动前提。","sub":[{"t":"以实践经验确认并明确化改造方针","d":"面对方向性的改造方针，先用已有实践经验检验并肯认其健全性，再把纲领条文在中央及地方领导人物头脑中明确起来、逐步具体化，首先肯定其为改造的必经之路，使统一认识成为开展改造工作的前提。","p":["改造资本主义工商业的必经之路"]}]},{"t":"按对象形态分类渐进推进变革","d":"面对需要整体推进的变革任务，先按对象的具体形态分解为不同类别并分别确定可操作的形式，再划定渐进的时间节奏，对经验不足的领域保留研究余地，避免以单一方式一刀切和骤变引起震动。","sub":[{"t":"按行业形态分类渐进推进私营工商业改造","d":"对改造任务不搞一刀切：先划定\"稳步前进、不能太急\"的渐进节奏和三至五年的时间底线以避免震动，再按行业形态分别确定改造形式——工业采取公私合营、加工订货等三种形式，商业确认可行但保留研究余地，使经验不足的领域不被仓促定型。","p":["改造资本主义工商业的必经之路"]}]},{"t":"以价值确认与双向校正统一对象认识","d":"面对需要争取或改造的对象群体，先确认其实际价值与作用，不因身份预判全盘否定；当对象内部存在方向相反的认识偏差时，分别进行校正而非只压一端，并以具体的利益安排把折中的目标定位确立为双方共同接受的基础。","sub":[{"t":"以利益定位与双向教育统一公私认识","d":"先确认改造对象在国计民生中的价值与作用；再用制度化的利润分配比例（所得税、福利费、公积金、资方红利）把\"基本上为国计民生服务的、部分地是为资本家谋利的\"落到利益实处；对保持距离、唯利是图的资本家和前进太快、不允许资本家有利的工人两端分别教育说服，统一到折中定位上。","p":["改造资本主义工商业的必经之路"]}]},{"t":"借助先进分子带动多数","d":"面对需要整体说服或改造的同质对象，先培育其中觉悟较高、愿意合作的先进部分，再借助其影响去带动说服其余多数，使对象内部的力量成为转变的桥梁，而不是对全体平均施力。","sub":[{"t":"以先进分子为桥梁说服中间多数","d":"面对同质性改造对象，不直接对全体平均施力，先有计划地培养其中眼光远大、愿意靠近的先进资本家，再经由他们的影响去说服带动大部分资本家，使教育借助对象内部的力量完成。","p":["改造资本主义工商业的必经之路"]}]},{"t":"以自愿作为合作性改造的边界","d":"凡属合作性质的改造或事业，必须以对象自愿为前提方可推行；合作的性质决定其不能强迫，自愿与否构成合作区别于强制性处置的根本边界。","sub":[{"t":"以自愿原则作为合作改造的边界","d":"实行国家资本主义一类的合作性改造，不但要根据需要和可能，而且要出于对象自愿；因属合作事业而不能强迫，据此把自愿与否作为该改造能否推行的边界条件，与对地主的强制性处置划清界限。","p":["改造资本主义工商业的必经之路"]}]},{"t":"以群众力量为根本、领导为辅助","d":"战胜强大对手，力量的根本不在武器装备，也不在个别领导人的英明，而在发动起来的人民群众——群众能想出干部一时想不出的具体办法；领导的正确只是辅助因素。判断胜负前景时，先看人民是否发动起来、群众是否在想办法。","sub":[{"t":"以人民战争为基础、依靠群众与正确领导战胜优势装备敌人","d":"面对武器远超己方的敌人，不把希望寄托于装备或个别领导人，而以人民战争为基础：充分发动群众想办法解决战争中的具体困难（防空护车、修路、坑道），由群众智慧与正确领导相结合形成整体作战能力，从而用劣势装备战胜优势装备；判断胜负前景时，先看人民是否发动起来、群众是否在想办法。","p":["抗美援朝的伟大胜利和今后的任务"]}]},{"t":"综合多因素并抓住决定性主要因素","d":"对形势或对手行动的判断，应从多个侧面收集因素而不是只看一面；在各因素并列后必须比较权重、识别起决定作用的主要因素，结论才可靠。认识的关键动作是从\"因素并列\"推进到\"主次区分\"，而不是停留在罗列。","sub":[{"t":"综合敌我多因素判断形势并抓住决定性原因","d":"判断敌人行动的可能方向时，不凭姿态言词或单一方面，而从军事、政治、经济等多侧面枚举敌我态势，逐一比较各因素的权重，识别起决定作用的主要因素（如军事挨打），据此作出\"敌人不得不和\"一类可靠判断，并预判其不愿讲和时的行为逻辑。","p":["抗美援朝的伟大胜利和今后的任务"]}]},{"t":"以实际接触破除对强敌的想象畏惧","d":"对陌生而强大的对象，其\"可怕\"往往来自未接触时的想象与传闻；只有通过直接交手、亲身接触取得真实经验，才能把对象还原为可评价、可应对的实体。认识的转换方向是从\"间接传闻\"走向\"直接经验\"，畏惧随真实了解的加深而消退。","sub":[{"t":"以实际接触作战积累经验、摸清强敌底细","d":"面对传说中强大的敌人，不凭想象和传闻定位其强弱，而通过实际接触和长期交手积累真实经验，逐项摸清对方的能力、弱点与作战底细，把\"摸不透的底\"变为可把握的判断，从而破除盲目畏惧、作出准确评价并形成对策。","p":["抗美援朝的伟大胜利和今后的任务"]}]},{"t":"以长远利益为重的利益权衡","d":"当眼前利益与长远目标发生冲突时，认识上应把两种要求区分开来并明确\"兼顾但重长远\"的顺序：为长远目标必须接受暂时困难，眼前呼声不能成为放弃根本目标的理由。这一原则用于任何涉及\"当前让利与长远建设\"取舍的决策。","sub":[{"t":"以当前与长远利益兼顾、重点在长远的原则处理资源与牺牲","d":"遇到眼前困难（加税、生活改善缓慢）与长远目标（战争胜利、重工业建设）的取舍时，先把要求划分为当前利益与长远利益两类，坚持两者兼顾但把重点放在长远利益上，据此刻意限制眼前改善的幅度，说服群众接受必要牺牲，并批评把眼前利益绝对化、妨碍根本目标的片面主张。","p":["抗美援朝的伟大胜利和今后的任务"]}]},{"t":"以量化指标与执行检查推动任务落实","d":"领导意图要落实为行动，不能只靠号召或原则表态，而要把任务化为可分派、可检查的量化指标，合理摊派而不强迫，并定期检查执行情形；数字使工作心中有底、防止自流，检查使执行有据可查，从而把要求转化为可核查的实际完成。","sub":[{"t":"以控制数字与检查督促推动任务落实","d":"落实互助合作一类发展任务，先规定控制数字，使工作心中有数、防止自流；再合理摊派到各地，摊派而不强迫、不是命令主义，允许地方超额完成；随后定期检查完成情形，以检查校准执行并决定后续任务，使领导要求成为可核查的实际行动。","p":["关于农业互助合作的两次谈话"]}]},{"t":"按成熟程度分阶段推进变革并允许具备条件者先行","d":"面对需要整体推进的变革，先按对象的发展成熟程度划分循序渐进的阶段次序（由低级形式进到高级形式），以稳的步骤推进、防止骤变；同时允许已具备充分条件的部分直接先行试办，不机械拘守必经程序；规模与形式依实际条件弹性把握，避免一刀切与冒进。","sub":[{"t":"按发展程度分阶段渐进并允许具备条件者先行","d":"面对农业合作化一类发展任务，先按发展程度确定一般渐进次序——由社会主义萌芽的互助组，进到半社会主义的合作社（土地入股），再进到完全社会主义的合作社（土地归公），步骤要稳；但允许具备条件的直接办社试办、走直路；规模按条件弹性把握，能大则大、不能则小，不要用一个规格到处套；以典型试办积累经验，不冒进。","p":["关于农业互助合作的两次谈话"]}]},{"t":"重大决策须经群众广泛检验并与群众意见相结合","d":"面对重要决策，不能只由少数人闭门议定：应组织有代表性的广泛讨论加以检验，采集意见并按\"正确、适当、可采用\"分类处理，采纳合理部分补全方案，使领导机关意见与群众意见相结合，决策既得人心又可实行。","sub":[{"t":"以广泛讨论检验并完善重大立法方案","d":"面对由少数人拟出的立法草案，不闭门定案：先组织有代表性的广泛讨论，确认基本条文与原则为大家赞成并保留正确内容；再搜集意见按\"不正确、不适当、可采用\"分类处理，采纳合理意见补全草案；把领导机关意见与群众意见相结合，并规定一切重要立法都采用此法。","p":["关于中华人民共和国宪法草案"]}]},{"t":"以总结正反历史经验作为立论依据","d":"确立重大方案时，先系统总结同类问题的历史经验——以本国经验为主、兼参国际经验；对历史上的正反经验都取其可取、弃其当弃，既不抹杀旧事物的历史地位也不照搬旧类型，以历史经验的取舍作为判断新方案正确性的依据。","sub":[{"t":"以总结本国历史经验为主并参酌国际经验立宪","d":"起草根本文献时，先系统总结本国革命和建设经验，以及以往同类问题（宪法史）的正反经验；以本国经验为主、参考国际经验中好的东西；对旧事物（如资产阶级民主）不一笔抹杀也不照搬，据此确立新类型，使方案既有历史根据又优于旧类型。","p":["关于中华人民共和国宪法草案"]}]},{"t":"原则性与灵活性相结合以实现长期目标","d":"确定不可动摇的根本原则后，实现路径上允许逐步推进、采用多种形式，现在能实行的写、暂不能实行的不写，共性用共同规定、特殊性用特殊规定；以灵活性保证原则能够实行而不变质，避免因形式激进导致行不通。","sub":[{"t":"以原则性与灵活性相结合制定可实行的方案","d":"确定基本原则（人民民主、社会主义）后，对一时办不到的事允许逐步去办、采用多种形式（如国家资本主义的各种形式）；现在能实行的就写、不能实行的就不写，共性用共同条文、特殊性用特殊条文；使原则不因形式激进而失败，达到逐步实行的效果。","p":["关于中华人民共和国宪法草案"]}]},{"t":"以成文规范固定根本原则以统一行动轨道","d":"把经过确认的根本原则上升为成文的总规范（总章程、根本大法），使全体行动者有清楚明确的轨道和道路可循，以规范化固定稳定长期方向、提高行动自觉，并作为必须执行、不得违反的准绳。","sub":[{"t":"以根本大法固定基本原则以统一行动轨道","d":"面对国家长期发展，以宪法（根本大法）形式把人民民主和社会主义原则固定下来，使全国人民有清楚明确的轨道和道路可循；规定全国人民特别是国家机关工作人员必须带头实行、不实行即违反宪法，以规范化固定提高行动自觉与积极性。","p":["关于中华人民共和国宪法草案"]}]},{"t":"以科学正确性为取舍标准破除迷信","d":"对任何对象——不论古今中外、身份地位、权威与否——的判断与取舍只以是否科学、是否正确为标准；正确者信，不正确者不仅不信还要批评；对条文和主张不因个人品格、传统或权威而盲从，破除迷信、只服从科学。","sub":[{"t":"以科学态度对待条文删改与既有结论","d":"面对删改条文一类的解释，不归因于个人品格（谦虚）等表面因素，而看是否适当、合理、科学；对任何对象——不论古今中外、身份地位——正确的就信、不正确的就不信并批评，破除迷信，只服从科学判断。 # 待理论层归并的 L1","p":["关于中华人民共和国宪法草案"]},{"t":"以谦虚学习与坚忍精神准备长期奋斗","d":"面对胜利后的长期任务，先识别骄傲自满的危害（看不起人的态度不科学、妄自尊大不对），再规定持久姿态：永远向一切对象（包括小国小党）保持学习态度，苦学苦干；对艰巨任务坚忍到底、不干则已、一干到底；以不作寿、不送礼、少敬酒、少拍掌、不以人名作地名、不把中国同志与马恩列斯平列等具体规定落实谦虚。","p":["反对党内的资产阶级思想"]},{"t":"以目标阶段化与现状清醒保持长期建设的谦虚","d":"面对长期建设目标，先把总目标具体化为分阶段时限（三个五年计划打基础、约五十年成型），再以现实起点校准预期（目前尚不能制造汽车等）；无论成就达到何种程度都保持谦虚、永远不翘尾巴，防止脱离现实的吹牛与骄傲。 # Method Dedup Index（37-44 批次） **批次：** 37-44（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 37、为建设一个伟大的社会主义国家而奋斗；38、关于《红楼梦》研究问题的信；39、原子弹吓不倒中国人民；41…","p":["关于中华人民共和国宪法草案"]}]},{"t":"按对象性质与范畴分别确定对待方法与判断边界","d":"面对性质不同的对象，不笼统采用同一标准，而先按对象性质划清范畴，对不同范畴分别确定适用的判断标准与对待方法；何谓正当、何谓错误、是否应当一律，都随对象范畴而定，范畴划分是方法与判断的前提。","sub":[{"t":"按人民内部与外部范畴分别采用民主说服与专政方法","d":"面对必须分别对待的两类对象（人民与反革命），先按其阶级性质划清人民内部与外部两个范畴：对人民内部允许舆论不一律、以民主说服和竞赛由先进克服落后，压制批评是犯罪；对反革命外部实行专政，只许规规矩矩不许乱说乱动。以对象范畴为界确定“民主”还是“专政”的方法选择，并据此确立制度根据。","p":["驳“舆论一律”"]},{"t":"把普遍化指责还原到具体对象范畴再判定其正当性","d":"面对“舆论一律”“强迫人”“压制自由”等普遍化指责，不随之笼统论争，先把指责还原到它实际所指的对象范畴，再按范畴分别判定：对反革命实行专政正是制度所需，对人民实行强迫命令才是真错误。通过还原所指、按范畴重判，拆解以普遍概念抹杀范畴界线、借抽象词令制造理亏感的论调。","p":["驳“舆论一律”"]},{"t":"按经济地位与觉悟程度分批组织群众","d":"不按一律标准吸收成员，而先按经济地位划分人群，再按觉悟程度分批组织：先吸收基本群众中的积极分子，耐心等待尚不积极者觉悟、不违反自愿原则，暂缓吸收动摇者，坚决不接收暂不该接收的对象，从而避免命令主义。","p":["关于农业合作化问题"]},{"t":"在群众工作中确立党团员—积极分子—群众的三级依靠次序","d":"面对大规模群众运动，领导机关不把所有群众混同对待，而先按组织身份与积极程度分出依靠次序：首先依靠党团员并区别于非党群众，第二依靠约占农村人口百分之五的非党积极分子并着力训练成队伍，第三才依靠一般贫农和两部分下中农的广大群众；每一层次不与相邻层次混同，使依靠什么人和如何依靠法清晰化。","p":["农业合作化必须依靠党团员和贫农下中农"]}]},{"t":"以阶段化部署把长期目标拆解为连续可推进的步骤","d":"面对宏大且不可一蹴而就的任务，不把远景当成可立即兑现的目标，而以固定时间单位做分阶段部署，把总体方向转化为连续、可推进、可检验的具体步骤。","sub":[{"t":"用分阶段长期规划把远大建设目标落到可执行步骤","d":"面对把经济文化落后国家建成工业化现代强国这一无法一蹴而就的跨越任务，不以远景口号替代执行，而以五年计划为单位做连续部署，把总体方向拆为可在若干周期内逐步推进、可检查的建设步骤。","p":["为建设一个伟大的社会主义国家而奋斗"]},{"t":"以逐步前进的分阶段步骤推进大规模改造","d":"面对把一亿一千万农户由个体经营改变为集体经营的巨大变革，不一步到位，而分三步走：先组织带社会主义萌芽的互助组，再组织土地入股、统一经营的半社会主义合作社，最后联合为大型完全社会主义合作社；使农民从自己的经验中逐步提高觉悟、减少突然改变的不适，保证增产、避免减产，同时训练大批干部。","p":["关于农业合作化问题"]}]},{"t":"在自主建设中主动借鉴外部先进经验并保持务实作风","d":"面对自身起点落后，主动把先行者的先进经验作为学习对象以缩短摸索成本，同时以老实、勤恳、互勉的态度推进，并警惕虚夸骄傲等破坏实效的作风。","sub":[{"t":"以学习他国先进经验为主并保持务实谦虚的建设作风","d":"面对自身起点落后，主动把苏联和兄弟国家已有先进经验作为学习对象以缩短摸索成本，同时以老老实实、勤勤恳恳、互勉互助的态度推进，并时刻警惕虚夸与骄傲这类破坏实效的作风。","p":["为建设一个伟大的社会主义国家而奋斗"]},{"t":"借鉴外部经验但防止其掩护保守","d":"对待外部历史上的失败教训，一方面认真吸取、反对没有准备地盲动冒进，另一方面不允许利用该经验为保守爬行思想作掩护，而用经验的全貌与本国实际证明目标可能，坚持独立判断。","p":["关于农业合作化问题"]}]},{"t":"以客观实际检查判定认识正误","d":"判定一种认识或思想路线是否正确，不以其是否省力、动听为据，而看它是否依据客观实际并愿意接受客观实际的检查；不受实际检查的认识路线必然流于主观臆断，因此“省力”恰恰是唯心论形而上学的特征。","sub":[{"t":"以依据并接受客观实际检查判定思想路线","d":"面对“机械论最省力”之类贬低唯物论的论调，不争论“省力”与否的表面，而考察一种认识路线是否依据客观实际、是否接受客观实际的检查：省力源于不受检查的瞎说，唯物论和辩证法则必须用气力依据客观实际并接受其检查，否则滑向唯心论形而上学。以“依据并接受客观实际检查”作为判定认识正误与思想路线的标准。","p":["驳“舆论一律”"]},{"t":"以历史事实论证方针可行性并确立信念","d":"面对“能否发展、能否巩固”的怀疑，不空谈可能与否，而系统回顾同类事业的历史发展过程与既有成效，用已经巩固的事实证明方针正确，并归结为对基本群众力量与领导能力的根本信任，为继续推进确立信念基础。","p":["关于农业合作化问题"]},{"t":"按实际情况规划并及时检查调整","d":"不按固定不变的预定数字机械推行，而每年按实际情况规定控制数字，并根据情况变化与成绩好坏多次检查、因地制宜调整具体步骤；发展一批后必须停止整顿再发展，一有问题及时解决、批评要及时，同时建立全面规划并随实际发展不断修正。","p":["关于农业合作化问题"]}]},{"t":"从基本群众的实际地位与根本关系出发检验和判定方针","d":"判断政策是否过快、方向是否正确，依据不在少数人的愿望或表面现象，而在占多数的基本群众的实际经济地位、利益与根本关系；从这种地位出发看本质主流，以多数人能否受益和基本联盟能否巩固来定取舍。","sub":[{"t":"从群众实际地位检验发展速度并看本质主流","d":"面对“发展超过了实际可能、超过了群众觉悟、超过了干部经验”等批评，不从抽象标准而从占多数的基本群众的实际经济地位出发检验其意愿与需要；同时分清本质、主流与非本质、非主流，不因支流问题迷惑方向，并认识到经验只能在斗争实践中取得。","p":["关于农业合作化问题"]},{"t":"从基本阶级关系判断战略方向","d":"面对“推进会破坏基本联盟、应当下马”的警告，不从表面看，而从农村阶级关系的实际变化判断：不推进则两极分化加剧、旧联盟基础已过时；联盟只能在新基础上——改造所有制、使全体人民共同富裕——才能巩固，因此必须推进而不是退却。","p":["关于农业合作化问题"]},{"t":"按经济地位与合作化态度具体化依靠口号","d":"当既有的依靠口号因阶级结构变化而失去精确性时，不放弃口号本身，而按对象的实际经济地位和对合作化运动的态度重新划分：贫农和两部分下中农相当于老贫农、作为依靠对象，两部分上中农相当于老中农、作为巩固地团结的对象；并按觉悟程度分批评吸收，不强迫上中农入社、不侵犯其利益，防止资本主义思想浓厚者窃取领导，树立贫农下中农的领导地位。","p":["农业合作化必须依靠党团员和贫农下中农"]}]},{"t":"通过内外力量整合凝聚共同目标的合力","d":"面对艰巨的共同任务，不把力量局限于自身，而是同时动员内部全体成员形成统一意志并争取外部可争取的支援，把分散力量聚合成服务共同目标的合力。","sub":[{"t":"以团结国内人民并争取国际支援凝聚建设合力","d":"面对建设伟大国家的艰巨任务，不把力量局限于自身，而是同时动员国内全体人民形成统一意志，并争取一切国际朋友的支援，把分散的国内外力量聚合为服务于共同目标的合力。","p":["为建设一个伟大的社会主义国家而奋斗"]}]},{"t":"排除身份与权威障碍坚持认识批判","d":"认识判断只应取决于思想观点本身的是非，不应取决于批评者的身份、地位与发表场所；面对长期无人批评的权威错误观点，应支持处于弱势的新生批评力量，排除其身份障碍，让批判公开展开。","sub":[{"t":"支持新生批评力量对权威错误观点展开批判","d":"面对权威的错误观点长期无人认真批评，不因批评者出身“小”、地位低或发表场所不“正规”而拦阻，而应支持新生批评力量对权威观点展开批判，排除以“小人物的文章”、“党报不是自由辩论的场所”等理由的阻挠，推动公开争论开展起来。","p":["红楼梦","关于〈红楼梦〉研究问题的信"]}]},{"t":"以历史教训对照当前处置","d":"对重复出现的同类问题，把此前同类事件的处理结果（是否批判、是否引出教训）作为对照基准来校准当前判断，从而识别旧问题以新形式复发而不自觉的风险。","sub":[{"t":"以同类历史教训核查当前批判是否彻底","d":"当同类错误问题再次出现时，不孤立看待当前事件，而回溯此前同类事件的处理结果——是否真正展开批判、是否引出教训——以历史结果对照当前，识别“批判不彻底、未引出教训导致问题复发”的风险。","p":["红楼梦","关于〈红楼梦〉研究问题的信"]}]},{"t":"区分对人的态度与对思想的批判","d":"在需要维持团结关系的同时面对错误思想时，不把“团结某人”等同于“放弃批判其思想”：个人态度与思想批判是两个可分离的维度，批判不因关系而取消，形成团结而不妥协的认识边界。","sub":[{"t":"对错误思想批判与对个人团结相区别","d":"对待必须团结的对象（如资产阶级知识分子），把“对人的态度”与“对思想观点的批判”分开处理：个人仍取团结态度，但其错误思想必须批判，不因团结关系而放弃思想批判，明确不投降的底线。","p":["红楼梦","关于〈红楼梦〉研究问题的信"]}]},{"t":"不因外来威慑动摇既定立场与原则","d":"面对强者以武力或威胁施压，立场不应随威胁强度而改变：和平意愿与抵抗意志作为统一原则同时坚持，威胁只能压缩外部空间，而不能改变既定立场的是非取舍。","sub":[{"t":"面对军事威慑确立不战不屈、受侵必回击的两条方针","d":"面对好战者以战争与核武器相威胁，不因威慑放弃和平意愿，也不因恐惧放弃抵抗决心：明确自己不要战争、以和平共处为原则，同时明确若遭侵略必坚决回击，把“不主动求战”与“不惧应战”统一为两条方针向人民讲清，使威慑既不能动摇立场，也不能压制抵抗。","p":["原子弹吓不倒中国人民"]}]},{"t":"以人民支持与历史规律而非技术条件判断胜负","d":"对对峙结局的判断，不以表面技术或装备对比为依据，而从人民支持这一根本力量和由历史先例显现的规律出发推演长期走向：决定性因素不在武器先进程度，而在民心向背与历史必然性。","sub":[{"t":"以人民力量与历史规律消解武器威慑并预判战争结局","d":"面对对方武器的绝对优势，不陷入武器优劣对比，而从更基本的力量出发：先以己方人口、土地规模消解单一武器的杀伤效力，再引入全世界人民的支持，并以历史战争结局为规律参照，论证胜负取决于人民支持与战争性质而非先进武器，得出“侵略者发动战争越早、被消灭越早”的判断。","p":["原子弹吓不倒中国人民"]}]},{"t":"在亲身实践中取得经验与自我改造","d":"能力与经验不能仅靠外部传授获得，只能在亲身实践中取得；领导者应放手让实践主体去做，使其在做的中间得到教训、增长才干并改造自身，而不是代劳包办。","sub":[{"t":"大胆放手领导群众运动并在做中学习","d":"面对新的群众运动高潮，不因怕出偏差而评头品足、忧虑退缩，先认清运动主流健康、偏差可纠正；然后积极热情有计划地领导，大胆放手让干部和群众去做，使他们在做的中间得到教训、增长才干并改造自身；派下去的干部也要在运动中才能学会怎样做工作，使领导不落在群众运动的后头。","p":["关于农业合作化问题"]}]},{"t":"以质量与实际成效为尺度，以充分准备与巩固保障规模扩张","d":"规模扩张不以数量本身为目标，而以质量与实际成效为尺度；发展前充分准备、发展后及时整顿巩固，以成员自愿与成效支撑可持续性，反对单纯追求数目字。","sub":[{"t":"以注重质量、充分准备与经常整社巩固合作社","d":"不片面追求数目字，一开始就注重质量；建社前做好批判错误思想、系统宣传政策、拟定全面规划、训练干部、发展互助组等充分准备，不打无准备之仗；建社后随即经常整顿（一年两至三次），由巩固的社带动待巩固的社，只在全体成员坚决不愿干时才解散，否则保留多数退出少数。","p":["关于农业合作化问题"]},{"t":"以保证增产和自愿互利巩固合作社","d":"明确组织必须在实际产出上超过原有形式，否则就没有存在的必要；为此坚持自愿、互利原则，改善经营管理，提高技术，增加生产资料，并逐项解决各利益相关方的互利问题，以互利实现自愿。","p":["关于农业合作化问题"]}]},{"t":"从整体联系中看待相互依存的部分，不孤立分割","d":"面对互为条件、相互依存的诸方面，不分割孤立地看，不片面强调一方、减弱另一方，而从彼此的制约与促进关系中把握整体，使各部分在相互适应中共同推进。","sub":[{"t":"从相互依存联系看待工业化与农业合作化","d":"面对“发展不必与相依存的其他部门相适应、可以采取特别迟缓速度”的主张，不孤立地看工业与农业，而从相互依存关系把握：原料与商品供需矛盾需靠合作化解决、重工业机器只在合作化大规模经营基础上才能使用、资金有相当部分来自农业；结论是两者不可分割、必须相适应。 # Method Dedup Index（45-51 批次） **批次：** 45-51（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 45、农业合作化的一场辩论和当前的阶级斗争；47、征询对农业…","p":["关于农业合作化问题"]}]},{"t":"化反面经验为认识资源","d":"面对错误、失败与敌对示范，不回避也不单纯否定，而是主动当作反面教材来学习，以付出代价换取的认识教育自己与组织，把负面对抗转化为判断力提升的资源。","sub":[{"t":"把错误与敌对力量转化为反面教材","d":"承认犯错误有教育作用、可以教育人民和党；把自身路线错误（陈独秀、王明、张国焘等）与敌对势力（日本、美国、蒋介石等）都列为反面教员，主动向他们学习，付出代价换取经验，把负面教训变成前进的认识资源。","p":["美帝国主义是纸老虎","增强党的团结，继承党的传统","我们党的—些历史经验"]}]},{"t":"由个别典型认识普遍规律以指导全局","d":"从个别典型中抽象普遍规律以指导整体，避免事必躬亲的普查；以典型突破带动全局，配合经验交流与情况掌握使问题早处置。","sub":[{"t":"由少数典型推普遍结论指导全局","d":"面对大量同类对象，不逐一普查，而是把少数典型（如几个合作社）彻底搞清楚，从中看出普遍性、作出结论指导全局；配合简报交流、各级掌握进度，早发现早处置。","p":["农业合作化的一场辩论和当前的阶级斗争","加快手工业的社会主义改造","我们党的—些历史经验"]}]},{"t":"在原则性斗争与团结教育之间保持张力","d":"既坚持原则、开展严肃斗争，又给同志留改正余地以团结大多数，在斗争与教育间保持张力而非一味打击，适用于处理内部错误与思想分歧。","sub":[{"t":"思想交锋与严肃批评宽大结合纠正错误","d":"思想斗争须中肯、让意见直接交锋才明确彻底；对犯错误同志坚持两条——本人愿革命、别人也准许其继续革命，以严肃批评加宽大态度帮助改正，不当下不准革命的角色。绝大多数错误可挽救。","p":["农业合作化的一场辩论和当前的阶级斗争"]},{"t":"以共同事业为尺度扩大团结范围并积极帮助犯错误者","d":"以是否对共同事业有用为团结标准，不限意见相同者，特别把意见分歧、反对过自己、使自己吃过亏的人纳入团结对象；对犯错误者不消极旁观，而\"一为看、二为帮\"，用积极帮助改正代替排斥，扩大团结面。","p":["增强党的团结，继承党的传统"]}]},{"t":"以客观量化比较作为方向判断的根据","d":"面对方向性取舍，以可量化的客观事实横向比较作为判断根据，让差距与趋势显明，据此确立升级路径，避免凭印象、惯例或口号决定方向。","sub":[{"t":"以量化对比确立技术升级方向","d":"把各类生产组织的可量化产出（如人均年产值）摆出横向比较，从个体手工业到国营现代工业形成明显差距，据此确立必须提高劳动生产率、向半机械化机械化升级的方向。","p":["加快手工业的社会主义改造"]},{"t":"以量化横向比较确立发展目标与赶超方向","d":"论证建设目标时不只靠口号，把钢产量等指标分期量化，并与强国的人口、资源、历史作横向比较，据以判断赶超既可能又必要，把目标转化为责任与动员。","p":["增强党的团结，继承党的传统"]}]},{"t":"在多重关系的主次区分中配置力量、孤立主要对手","d":"面对含多个对象的复杂关系，先判定谁是主要敌人和可借用的次要力量，再以主次联盟的相互制约把主要对手孤立，避免在次要方向消耗主攻力量。适用于需分化、孤立对手的各种斗争与谈判局面。","sub":[{"t":"以两个联盟的相互作用孤立主要敌人","d":"面对需孤立主要对手的斗争，区分与基本群众联盟（主要、第一位）和与次要对象联盟（暂时、第二位）；利用次要联盟取得资源满足群众、克服其摇摆，并依靠群众掌握关键资源反制次要对象使其政治孤立。两联盟在经济落后时都必要。","p":["农业合作化的一场辩论和当前的阶级斗争"]},{"t":"利用敌人内部矛盾集中打击当前最主要的敌人","d":"面对分属不同集团、内部有矛盾的多个敌人，不平均用力，先利用其矛盾分化，集中打击当前最主要的敌人、一个一个解决；打击面要小，只打少数最反动的（连大地主也只打其最反动少数），避免四面树敌。","p":["我们党的—些历史经验"]},{"t":"以民族旗帜团结一切可能力量孤立主要敌人","d":"无产阶级政党把民族旗帜拿在自己手里，提出民族团结纲领，团结除帝国主义走狗以外的一切可能力量，使人民看到党的爱国与团结主张，从而孤立帝国主义及其走狗、孤立大地主大资产阶级。","p":["我们党的—些历史经验"]}]},{"t":"在理论与实际结合中认识问题","d":"普遍理论必须同具体实际结合才有力量；认识是否成立，以\"思想反映客观实际并在客观实践中得到检验\"为准则。纠正错误认识不靠口号与抽象争论，而靠理论与实践对上号并经受实践检验。","sub":[{"t":"以理论结合实际与实践检验纠正主观主义","d":"发现不从客观实际而从主观愿望出发的主观主义后，把它作为批评与打击对象；坚持马克思主义普遍真理同中国具体实践相结合，以\"思想必须反映客观实际并在客观实践中得到检验\"为准则，把理论与实践统一作为判断是非的基本依据。","p":["增强党的团结，继承党的传统"]},{"t":"把普遍真理与本国具体情况相结合、不硬搬外国经验","d":"面对别国（包括中国革命）经验，只作参考不作教条；把马克思列宁主义普遍真理与本国具体情况结合起来。经验是否适用以本国实际为准，先清算党内教条主义路线，才能走出自己的路。","p":["我们党的—些历史经验"]}]},{"t":"依据客观条件成熟度把握行动时机","d":"行动该办不该办取决于客观条件是否成熟而非主观愿望；条件未到而勉强办为\"左\"，条件已熟而不准办为右。须以成熟度为准绳决定进止，并配合分期分批控制节奏，自然达成目标。","sub":[{"t":"依条件成熟度判定推进时机以区分\"左\"右倾","d":"推进群众运动前核查群众觉悟、组织基础与领导力量是否成熟；已具备仍不办属右倾，未具备却大办属\"左\"倾。按\"瓜熟蒂落\"自然达成，以分期分批控制节奏，不勉强不延误。","p":["农业合作化的一场辩论和当前的阶级斗争"]}]},{"t":"通过分层规划与有节奏的进退掌握运动进程","d":"对复杂大规模运动须有分层规划与及时信息掌握，并保留临机纠偏（煞车）权力，以有节奏的进退和间歇掌握进程，按质量与节奏而非盲目速度推进。","sub":[{"t":"分层级全面规划并临机煞车防\"左\"","d":"建立合作社、乡、县到省的多层级全面规划，辅以开会、简报、巡视、办刊物编书等方法掌握情况；省地县三级实时跟踪，一有问题即解决，切忌成堆再放马后炮；情况不对立即煞车，重点比质量而非速度。","p":["农业合作化的一场辩论和当前的阶级斗争"]},{"t":"发展与整顿波浪式交替推进","d":"推进群众运动须在两个发展浪潮间安排休整：发展一批后必须整顿巩固再发展下一批，如同打仗两仗间要休整；不允许只发展不间歇。休整为更好发展，不是停滞。","p":["农业合作化的一场辩论和当前的阶级斗争"]}]},{"t":"以持续的新任务保持组织前进动力","d":"在组织取得阶段性胜利、易松懈骄傲时，以连续的新任务牵引注意力，防止自满、维持前进动能，适用于任何需持续奋进的集体。","sub":[{"t":"以持续新任务防止骄傲保持动力","d":"当组织刚取胜、欲骄傲时及时提出新任务（如从比数量转比质量），使其来不及骄傲、把精力转向新准备，保持前进动力。该办法过去在军队打胜仗后试用有效。","p":["农业合作化的一场辩论和当前的阶级斗争"]}]},{"t":"在决策确定前完成执行层可行性征询与意见闭环","d":"重大决策在集中确定前，先交执行层逐条检验可行性、判断依据是否充分并允许增补，限定反馈期限后汇总再定案，把执行层意见的完备性纳入决策依据，避免未经验证的方案直接定案执行。","sub":[{"t":"重大部署先交执行层逐条审查可行性并限期反馈","d":"面对重大部署草案，不直接定案，先明确向执行层提出三项征询问题——每条是否都能实现、根据是否充分；除草案外是否应增补；是否准备纳入来年计划开始实行。召集下级党委负责人逐条研究，规定统一反馈期限，汇总后再由中央会议集中确定，把执行层对可行性的检验纳入决策程序。","p":["征询对农业十七条的意见"]}]},{"t":"将长期目标分解为分期限、可量化的执行指标","d":"宏大发展目标须分解为分期限、可量化、按地区差别化并纳入年度计划执行检查的具体指标，使目标成为可检验、可考核的任务体系，而不是停留在方向性口号上。","sub":[{"t":"将建设目标量化为分期限分区域的指标并纳入年度计划","d":"把一整套建设目标逐项落为具体任务，给每项配明确期限（三年、七年、十二年）、量化标准（入社比例、亩产斤数、识字量等）与区域差别，并要求纳入来年计划逐年实行、按期检查，使宏大目标变成可执行、可检验、可考核的任务体系。","p":["征询对农业十七条的意见"]}]},{"t":"以服务对象实际需要为据取舍组织形式","d":"组织形式的集中与分散等取舍，应以服务对象的实际需要与满意程度为根据，根据实际效果动态调整，不因规模冲动或管理便利而牺牲服务可及性。","sub":[{"t":"以群众满意度校准服务网点的集中与分散","d":"当服务性行业集中生产、撤点过多引起群众不满时，不以集中为当然取向，而是按群众满意度恢复该恢复的分散服务网点，在集中与分散之间随实际需要动态调整，保留贴近群众的分散经营形式。","p":["加快手工业的社会主义改造"]}]},{"t":"在变革中保护并提升既有优质存量","d":"在改造或革新过程中，先识别既有优质成果与传统技艺并予以保护，不因创新与升级而舍弃已有价值；被破坏者应恢复并提升，使存量优势成为变革的财富而非被否定的对象。","sub":[{"t":"在改造中保护并恢复传统优质产品与技艺","d":"识别有价值的手工业产品与民间技艺（名牌刀剪、景泰蓝等），明确不要搞掉；已被搞掉的民族好东西必须恢复并搞得更好；以设机构、办学院、召集会议等方式保护民间老艺人、提高工艺美术水平。","p":["加快手工业的社会主义改造"]}]},{"t":"以先予后取推动对象成长与渐进过渡","d":"对力量薄弱、需要扶持的对象，先给予资源帮助其发展壮大，待其具备条件后再要求回报，以先后两阶段的取予安排实现渐进式的成长与归属转变，而非一开始就按最终归属要求对象。","sub":[{"t":"以低价扶持与逐步回收安排国家与合作社的关系","d":"国家调拨物资给合作社要合理作价，合作社起步时以低价拨给旧机器、多余机器厂房予以扶持；待其基础壮大后再多收税、原料加价进行回收，使合作社在形式上集体所有、实际上向全民所有过渡。","p":["加快手工业的社会主义改造"]}]},{"t":"从整体本质与局部实际两个层次把握对象","d":"面对貌似强大的对象，应分别从整体本质与局部实际两个层次把握：整体上看清其虚弱的本质而敢于轻视、坚定必胜信念，局部上正视其现实力量而谨慎对待、逐个击破，以逐步积累实现强弱转化。适用于一切强弱悬殊的对敌与竞争局面。","sub":[{"t":"战略上藐视、战术上重视的逐步斗争","d":"面对外表强大而本质虚弱的敌人，先从战略上、整体上、长远上轻视它——它脱离人民、必败无疑；再从战术上、局部上、具体斗争中重视它——它仍有现实力量，须用力斗；然后一个一个地解决、一仗一仗地打，逐步削弱直至彻底消灭，并接受这需要时间。","p":["美帝国主义是纸老虎"]}]},{"t":"以人民联系为尺度判断真实力量与胜负","d":"判断真实力量与斗争前途，不以表面规模为准，而以是否联系、代表大多数人民为尺度：脱离人民者虽强必衰，联系人民者虽弱必胜。用历史反复验证这一尺度，可避免被表面的强大吓倒。","sub":[{"t":"以人民联系判断真实强弱与胜负","d":"判断谁强谁弱、谁会胜利，不看表面规模，而看是否联系人民：力量小的、同人民联系的强，力量大的、反人民的弱；强大的失败因脱离人民，弱小的胜利因为人民工作。以清朝、蒋介石、日本军国主义等一连串历史反复验证此规律，再用以判断美帝国主义本质。","p":["美帝国主义是纸老虎"]}]},{"t":"以实际处境而非身份标签划分敌友与联合基础","d":"面对成分复杂的群体，划分敌友与确定联合对象应以实际处境（受压迫与否）为依据，而非民族、血统、语言等先赋身份；处境相同者易于联合，与对立处境者须分清界限。","sub":[{"t":"以受压迫地位划分联合对象","d":"反帝斗争中识别盟友不以民族、血统、语言为准：把欧洲移民白人区分为统治者与被统治者两部分，被压迫白人因地位与本地人相同而容易接近联合；同一受压迫地位者性质相同、做同样的工作，是同志，可共同反对帝国主义压迫。","p":["美帝国主义是纸老虎"]}]},{"t":"从客观实际出发认识问题","d":"认识、经验总结与判断的可靠性，取决于是否以客观实际为出发点和根据，而不是从主观愿望或材料罗列出发；从实际出发抓住重点，才能作出符合事实的判断，避免主观与客观相脱离。","sub":[{"t":"总结实践经验要抓重点、从实际出发","d":"面对丰富的历史经验，不罗列很多事情，而是抓住重点，从客观实际出发，依据马克思主义观点加以总结；以这样的总结给全党以推动力，使后续工作做得更好，防止总结陷入材料罗列而脱离实际。","p":["增强党的团结，继承党的传统"]}]},{"t":"从社会根源与阶级基础理解思想分歧","d":"理解个人的错误、动摇与思想分歧，不能只看个人品格或孤立行为，而要追溯其代表的社会阶级根源；认识到错误有其社会基础，才能既不把思想错误当成个人品德问题而排斥，也不把个人错误无限放大，并据此确定对待态度。","sub":[{"t":"从社会根源认识党内错误与分歧","d":"看待犯过路线错误者，不看作孤立的个人，而追溯其代表的社会力量（小资产阶级动摇性），认识到错误有社会根源；据此把思想路线错误同反革命分裂区别对待，不因人废事，也不照搬排斥路线。","p":["增强党的团结，继承党的传统"]}]},{"t":"从全局与长远效果衡量决策得失","d":"衡量一项人事或组织决策是否恰当，不以一时一地、局部表面的公道为据，而从全局利益与长远效果出发：看它对整体大多数的影响、教育作用与长远后果，把个别安排纳入整体得失中权衡。","sub":[{"t":"从全局与长远效果决定人事组织安排","d":"面对\"选举犯大错误者是否公道\"的疑问，不按局部表面公道判断，而从全局利益与长远效果权衡：选举表明党等待犯错误者改正、有利于教育广大小资产阶级动摇分子，且与历史实践对照无损失，据此决定人事安排。","p":["增强党的团结，继承党的传统"]}]},{"t":"从结构分层中立体认识社会对象","d":"面对看似统一同质的对象，不停留在平面的表面印象，而按对象内在的结构（成分、利益、地位）分层，识别各部分差异、相互关系与各自要求，形成立体认识，据以判断对待各方的策略。","sub":[{"t":"用阶级观点分层立体认识社会","d":"认识像农村这样看似同质的对象时不停留于平面印象，用阶级观点分层——区分雇农、贫农、中农、富农、地主等成分与利益差异，分析各阶级革命要求，形成立体认识以辨别依靠谁、联合谁；此法须掌握马克思主义并经实践磨炼确立。","p":["我们党的—些历史经验"]}]},{"t":"在团结与斗争的并用中对待两面性同盟者","d":"对同时存在对立与合作两面性的对象，不取一面而两手并用：团结其有利于己的一面，对其不利一面作适当而有分寸的斗争，并始终以团结为归宿；只团结不斗争或只斗争不团结均属偏差。","sub":[{"t":"对两面性同盟者实行又团结又斗争","d":"对待同时存在对立与合作两面性的对象（民族资产阶级），两手并用：团结其反对帝国主义一面，对其剥削压迫人民、反共一面作适当斗争；斗争有理有利有节并调查双方情况，斗争目的是团结。只团结不斗争是右，只斗争不团结是\"左\"。 # Method Dedup Index（52-58 批次） **批次：** 52-58（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 52、纪念孙中山先生 · 53、在中国共产党第八届中央委员会第二次全体会议上的讲话 · 54、在中…","p":["我们党的—些历史经验"]}]},{"t":"在对立面的斗争与比较鉴别中发展真理","d":"真理性认识不能靠禁止错误意见来维持；应允许对立意见并存与交锋，通过比较、鉴别与充分说理的批判而非行政压制处理分歧；真理在同谬误的斗争中发展，错误东西的存在是鉴别与斗争的必由前提。","sub":[{"t":"放手让不同意见交锋、在对立斗争中发展真理","d":"在思想文化领域采取\"放\"而非\"收\"的方针：放手让大家讲意见，敢于批评争论，容许批评与反批评；不怕错误议论与有毒素的东西，不禁止人接触错误思想；对错误思想、毒草作充分说理、有分析、有说服力的批判，而非粗暴压制；让各种意见辩论，在比较鉴别和同错误斗争中使真理发展。","p":["在中国共产党全国宣传工作会议上的讲话"]},{"t":"让对立意见充分暴露后分辨并系统反击","d":"面对有组织的意见进攻，不压制而先让正反两面意见充分暴露（座谈会、登报、学生表态），使对立面\"大吐毒素\"、充当反面教员；到适当时机组织党团员分辨批评性质——建设性的接受并改正自身缺点、破坏性的予以反驳；同时组织正面讲演、党报掌握发表时机，最后由有威信负责人作有分析有说服力的总结演说扭转空气，再转入和风细雨整风。","p":["组织力量反击右派分子的猖狂进攻","文汇报的资产阶级方向应当批判"]}]},{"t":"以预先告示的教育方式促人自觉改正","d":"处理内部错误不以突然打击和单纯惩处为先，而预先公布要求与期限，给予自动申报、分期改正的机会；以批评与自我批评促其自觉转变，目标是治病救人、达到团结而非整人。","sub":[{"t":"以整风方法教育整改、给改正台阶","d":"整顿党内思想作风，先发通知把要整顿的项目（主观主义、宗派主义、官僚主义）预先公开并留出时间，允许犯错误者申报、分期改正（\"搭楼梯慢慢下楼\"）；核心是学习文件基础上检查思想和工作，开展认真的批评与自我批评，既严肃认真又和风细雨、惩前毖后、治病救人，反对\"一棍子把人打死\"，达到新的团结。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话","在中国共产党全国宣传工作会议上的讲话"]}]},{"t":"按对象性质选择矛盾处理方式","d":"处理矛盾与问题应先判断对象性质，再选择相应方式：对敌性、对抗性的对象用强有力的群众斗争，对人民内部矛盾用教育批评的方法；方法随对象性质而变，不把单一方式套用于一切对象。","sub":[{"t":"按对象性质选择民主方法","d":"对民主这种手段，先判断对象与用途：无产阶级领导下的大民主（发动群众）用于对付帝国主义、封建主义、资本主义及官僚主义者；人民内部的事情则用整风、批评与自我批评的小民主，不搞对敌斗争那一套。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]},{"t":"按对象性质区分处理宽严","d":"面对错误言论与犯错者，先区分对象性质——右翼骨干（有言论有行动）、有言论无行动者、累戒不戒者——再分别确定处理宽严：对骨干宽大为怀、不予办罪，但错误言论批判干净、允许保留意见；对累戒不戒、触犯刑律者办罪；坚持惩前毖后、治病救人，化消极因素为积极因素。","p":["文汇报的资产阶级方向应当批判"]}]},{"t":"从对象所处的历史条件出发认识与评价其功过","d":"评价对象时不以其所处时代之后的标准苛求，而先还原其所处历史条件，把功过视为该条件的产物，由此获得历史地、而非抽象地理解人物的认识原则。","sub":[{"t":"以历史条件评价历史人物功过","d":"面对历史人物评价，先承认伟大人物亦多有其缺点；再把缺点放回其所处历史条件中说明，使人理解其成因；结论是不以后来标准苛求前人。核心是历史地而非抽象地评判功过。","p":["纪念孙中山先生"]}]},{"t":"在继承既有成果基础上沿其方向继续发展","d":"推进事业以继承为前提、以发展为目标：先系统接续前人各阶段成果并定位自身为继承者，再识别其未完成部分，沿其内在方向把事业推向更高阶段，而非另起炉灶。","sub":[{"t":"在继承前辈未竟事业中发展革命","d":"承接前人事业时，先肯定其在各阶段贡献并定位自身为继承者；再识别未完成部分；进而接续完成未竟事业，并沿其方向推进到更高阶段（如由民主革命发展为社会主义革命）。","p":["纪念孙中山先生"]}]},{"t":"以谦虚自省约束自身对外行为、防止强权心态","d":"自身力量壮大、对外交往增多时，以持续的谦虚自省约束对外行为，主动、彻底地消除可能滋生的强势傲慢与大国主义心态，而非放任，防止由强而生骄。","sub":[{"t":"以谦虚自省戒除国际交往中的大国主义","d":"国力增强、对外交往增多时，先确立\"永远谦虚\"的自我约束；再落实为对外行为硬边界——在国际交往中坚决、彻底、干净、全部地消灭大国主义，防止强权傲慢滋生。","p":["纪念孙中山先生"]}]},{"t":"通过研究客观实际情况保持认识的虚心与开放","d":"认识的虚心不来自姿态表态，而来自对客观实际（历史、现状、外部）的系统研究；以对实际材料的掌握支撑开放态度，避免脱离实际的自满。","sub":[{"t":"通过研究历史现实与外国情况保持虚心","d":"要保持认识的虚心与开放，靠系统研究而非表态：研究本国历史与当前社会情况，也研究包括外国（如苏联）在内的外部情况；以实际材料支撑虚心气魄，避免自满。","p":["纪念孙中山先生"]}]},{"t":"在矛盾运动中把握前进方向","d":"认识事物发展不能把静止平衡绝对化；平衡是暂时的有条件的，矛盾与运动是绝对的。判断方向与取舍时应承认非直线的波浪式运动，在动态变化中把握总体前进趋势，而非追求一步到位。","sub":[{"t":"用辩证分析确定进退取舍","d":"面对进与退、上马与下马这类取舍，先对问题作全面分析，承认平衡是暂时的有条件的、不平衡与矛盾发展是绝对的；由此确定\"有进有退、主要是进\"的波浪式前进方向，各级组织保持根本促进态度。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]}]},{"t":"在保护的前提下批评、不因缺点否定整体","d":"对待有缺点错误的对象，批评必须置于保护其基本价值与能动性的前提之下；先肯定与保护，再批评，不因部分缺点全盘否定对象，也不回避其错误，使批评服务于改进而非否定。","sub":[{"t":"以保护积极性为前提批评缺点","d":"对干部和群众，在保护其积极性的根本条件下批评缺点，包括批评我们自己的缺点；对群众要求办而暂时办不到的事情解释清楚，不泼冷水，使批评转化为干劲而非挫伤。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]},{"t":"保护与批评并举对待对象","d":"对待有重大功绩也有错误的对象（如斯大林），采取\"第一条保护、第二条批评\"：不丑化、不毁灭，肯定其基本价值，同时按实际情况批评其错误；对内部犯错误者也同样保护又批评。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]}]},{"t":"以多轮公开审议保障多方判断","d":"对专业性强、易被少数人垄断判断的事务，通过多轮公开审议与信息透明，使缺乏专业知识的主体也能在反复接触中形成鉴别能力，以多方共同判断校正单一专业判断。","sub":[{"t":"以多轮公开审议让非专家参与判断","d":"对需要专业判断的事务（如国家预算），不满足于少数经手人了解，而组织相关同志分三轮公开讨论定案；使不掌握专业细节者通过反复接触材料获得鉴别能力，依靠\"观众\"式的多主体判断校正\"演员\"式的专业结论。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]}]},{"t":"抓关键环节纠偏并防止矫枉过正","d":"工作部署中某项被过度突出、其他被忽视时，由决策者亲自抓住关键环节纠偏；同时警惕纠正本身制造新的极端，在动态调整中避免从一偏转向另一偏，保持各方面安排的协调。","sub":[{"t":"抓关键环节纠正单一偏向","d":"党委负责人亲自抓财政、计划等关键环节，纠正部署中只抓一项忽略其他的单一偏向；纠偏时防止矫枉过正（如由偏粮转向偏副业造成谷贱伤农），并借助报纸等渠道统一宣传导向。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]}]},{"t":"从错误与坏事中取得教育","d":"失败、倒霉与错误不只具有消极一面；在一定条件下它们会暴露问题、教育人们。认识主体应看到坏事的两重性，主动把教训转化为学习材料，而不是停留在单纯否定或恐慌。","sub":[{"t":"从坏事两重性中提炼教育","d":"对坏事、失败、错误（如东欧乱子、中东事件），不作单纯否定，而承认其两重性——在一定条件下产生好的结果；主动从中提取教育意义，转化为全党全国改进认识的教材。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]}]},{"t":"以两点论分析经验并辨明取舍","d":"对待任何来源（外来或本土）的经验，坚持两点分析而不作全盘肯定或否定；在辨别优劣的基础上进一步判断其是否适合自身条件，适合者取、不适合者改，避免盲目照搬而脱离实际。","sub":[{"t":"以两点论分析外来经验辨明取舍","d":"对待苏联等他国经验，不作一点论（凡是好的、硬搬照搬），而坚持两点论：中国的外国的都可以分析，有好的有不好的；辨别适合本国土地的部分，适合则学，不适合的坚决改过来。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]}]},{"t":"从最坏处着想、预先做好准备","d":"处理不确定且风险高的事项时，从最坏情形出发进行估计与布防，预先准备应对条件；不以侥幸心理代替准备，坏结果出现时不慌乱、不改变根本方针，保持主动。","sub":[{"t":"从最坏处着想预先做好准备","d":"对可能失控的事项（如达赖出走），先估计最坏可能并做好准备——备足粮水、修好堡垒、不动声色；不先发制人，让对方先动再从容反击；对坏结果本身不惊不惧，继续既定方针。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]}]},{"t":"以艰苦奋斗保持同群众的联系","d":"领导者与群众保持联系不靠物质上差别化，而靠共同生活条件与同甘共苦；艰苦奋斗作为政治本色，通过自觉纪律而非强制体现，使队伍在困难时仍与人民站在一起。","sub":[{"t":"以勤俭节约同甘共苦保持与群众联系","d":"提倡勤俭建国、反对铺张浪费，领导机关和军队在困难时住棚子、艰苦奋斗；与人民有福共享、有祸同当，以自觉性（如战士不吃人民的苹果）建立纪律，以此保持不脱离群众。","p":["在中国共产党第八届中央委员会第二次全体会议上的讲话"]}]},{"t":"思想转变只能靠说服、不能靠压服","d":"人的思想与立场的改变是长期过程，不能靠强制、压制和短期突击实现；只能通过说理、说服与耐心细致的长期工作促其自觉转变，压制的结果是\"压而不服\"、反而扩大矛盾。","sub":[{"t":"对思想问题只说服不压服、改造须长期耐心","d":"面对知识分子对马克思主义\"赞成但不熟悉、中间状态长期存在\"的状况，不要求过高、不降低任务；宣传马克思主义要逐步进行、使人愿意接受，不能强迫人接受，只能说服人接受。思想改造是长期、耐心、细致的工作，不能靠几次会议改变几十年形成的意识；要人家服只能说服不能压服，压而不服；要学习通过辩论、说理的方法克服各种错误思想。","p":["在中国共产党全国宣传工作会议上的讲话"]}]},{"t":"以辩证分析克服认识的绝对化与片面性","d":"认识与评判事物时，不作全盘肯定或全盘否定的绝对化判断，而以辩证的矛盾分析分别考察正反两面；逐步以全面分析取代形而上学，避免因绝对化而丧失判断力与说服力。","sub":[{"t":"用矛盾分析克服片面性、学会全面看问题","d":"对工作与事物不作\"肯定一切\"或\"否定一切\"的绝对化判断，而加以分析；把辩证法逐步推广，学会分析事物的矛盾；要求逐步使较多的人采用比较全面地看问题的方法。写文章要对事物有分析、有说服力，不靠装腔作势吓人；对片面看问题的人以惩前毖后、治病救人的态度去批评帮助。","p":["在中国共产党全国宣传工作会议上的讲话"]}]},{"t":"先受教育并借实践结合补全认识","d":"承担教育、领导职能者须先保持学习者身份，向自己的教育对象与实践学习；从书本与前人获得的间接知识是不完全的，必须同直接实践、同群众经验结合，才能补全并不断更新自身认识。","sub":[{"t":"知识分子先受教育、同工农实践结合补全知识","d":"知识分子是教育者，当先生的要先受教育；情况不断变化，要使思想适应新情况就得学习，接受新事物、研究新问题；一面当先生一面当学生，向工人农民学习、向自己教育的对象学习。同时到群众中去，以\"走马观花\"\"下马看花\"\"安家落户\"等不同程度接近工农；书本知识不同实践结合时不完全，须研究当前情况、实际经验和材料，把书本学来的马克思主义变成自己的东西。","p":["在中国共产党全国宣传工作会议上的讲话"]}]},{"t":"主要负责人亲自抓易被忽视的重要问题","d":"对关系全局而常被日常事务挤掉的问题，不能因\"忙\"而搁置；须将其正式列入议事日程、由主要负责人亲自研究，并组织有不同意见者参加的讨论，以重视与多方参与保证正确解决。","sub":[{"t":"党委把思想问题列入议程、第一书记亲自抓","d":"各地党委要把思想问题当作重要问题抓起来，不能因忙而不抓或抓得很少；所谓\"抓\"就是把问题提到议事日程上、要研究；第一书记应亲自出马来抓，只有重视了和研究了这个问题，才能正确地解决这个问题；要召开像这次宣传会议一样、有党内外和不同意见者参加的会议讨论思想工作。","p":["在中国共产党全国宣传工作会议上的讲话"]}]},{"t":"不被表面声势左右、以真实力量与群众基础定策","d":"面对来势汹汹的对抗，不依据表面声势与一时恐慌判断局势，而先估计双方真实力量对比（对方活跃分子实为少数）；据此判定风险可控，并通过预作布置与动员组织群众，把恐慌转化为有组织的应对。","sub":[{"t":"以真实力量估计和群众动员对抗表面声势","d":"面对猖狂进攻，先估计对方真实数量——右派不过百分之几、最积极疯狂分子不过百分之一，判定不足为惧，不为一时\"天昏地暗\"的声势吓倒；同时预作布置、实行挡驾，防止其向本机关外扩张；召集工厂干部和老工人开会说明真相，动员群众撕毁反动标语、不上当、不闹事；以大字报为战斗武器，在双方斗争中取得经验、锻炼人才。","p":["组织力量反击右派分子的猖狂进攻"]}]},{"t":"透过形式判断实质、依真实力量掌握判断主动权","d":"判断局势的主动权不能只看表面形式——表面主动可能是假主动，形式被动可能蕴含实际主动；判定依据是真实力量的掌握程度。由此对局势作出实质性判断并保持定力，不被表象误导。","sub":[{"t":"透过表面形式判断真实主动权","d":"判断局势的主动权，不依据表面形式——过去形式上主动、实际上至少有一半是假主动；现在形式上被动、实际开始有主动，因为认真整风。判定依据是真实力量的掌握：能否巩固地掌握工农党政军及大多数学生。据此看清敌我真实消长，保持信心与策略定力。","p":["组织力量反击右派分子的猖狂进攻"]}]},{"t":"透过表面言辞判断是否触及问题根本","d":"判断认错、检讨与表态是否真实有效，不停留于言辞表面——表面承认错误可能实为辩护；关键在于判断其是否触及问题根本性质，并以确有改过行动者为参照加以鉴别，从而识别真伪、把握主动。","sub":[{"t":"判断自我检讨是否触及方向根本","d":"面对方向性错误后的自我检讨，不因对方承认\"犯了一些错误\"即予接受，而判断其检讨是否触及根本性质——是真正触及方向错误，还是停留枝节、实为辩护（并识别其辩护逻辑，如以个别性前提推出普遍性结论）；以确有改过行动者为参照标准，要求照其办理，使被动转化为主动。","p":["文汇报的资产阶级方向应当批判"]}]},{"t":"主动引导不可避免的问题提前局部暴露并分割化解","d":"对不可避免要爆发的破坏性事件，不被动等待其集中爆发，而主动创造受控条件使其提前在局部暴露；把可能整体爆发的大问题分割为分散的小问题逐一处理，使破坏局部化，并把处理过程转化为锻炼队伍、教育群众的机会。","sub":[{"t":"主动引出并分割处理潜在乱子","d":"对不可避免要爆发的乱子，不被动等待其整体爆发，而通过主动整风把可能的\"匈牙利事件\"引出来；将其分割到各机关各学校去演习、处理，化为许多\"小匈牙利\"；使党政基本不溃乱、只溃乱一小部分，挤出脓包；把处理过程转化为锻炼人才、教育群众的有利机会。","p":["组织力量反击右派分子的猖狂进攻"]}]},{"t":"共同事业的推进以统一领导核心为前提","d":"完成需要全体成员共同推进的事业，以形成并维护统一领导核心为必要条件：核心统一则分散力量得以凝聚、事业能够胜利，核心缺失则力量涣散、事业不能成功；判断言行以是否服务该共同事业为尺度。","sub":[{"t":"以统一领导核心为前提推动共同事业并划定边界","d":"面对需要全体成员共同推进的事业，先明确统率整体的领导核心，确认其存立是事业胜利的必要前提；再推动成员团结在核心周围，把团结转化为为共同目标坚决奋斗的行动；同时以该目标为尺度划定允许与禁止的言行边界，使偏离目标的言行被明确排除。 # Method Dedup Index（59-62 批次） **批次：** 59-62（每 6 篇文章一个独立 method index 文件） **当前覆盖：** 59、一九五七年夏季的形势；60、坚定地相信群众的大多数；61、党内团结的辩证方法…","p":["中国共产党是全中国人民的领导核心"]}]},{"t":"按矛盾或对象性质确定相称的解决方法","d":"面对不同性质的对象或矛盾，先判定其属于对抗性敌我矛盾还是人民内部矛盾，再分别采用专政孤立或民主说服的方法。方法必须与对象性质相称，不能用压服处理内部问题，也不能用温和对待敌对进攻。","sub":[{"t":"按矛盾性质分别采用专政与民主方法","d":"先判定矛盾属对抗性敌我还是非对抗人民内部，再分别施策：敌我实行专政孤立分化，人民内部用民主说服。总题目是正确处理两类矛盾，方法实事求是、群众路线。","p":["一九五七年夏季的形势"]},{"t":"有反必肃少杀不废死刑依法惩办","d":"肃反方针有反必肃、杀人要少但决不废除死刑、决不大赦，刑满再犯再提再判；严重罪犯必须惩办，轻罪重判与重罪轻判皆不对，当前危险在后者。依法区别对待，稳控打击面。","p":["一九五七年夏季的形势"]},{"t":"对可改造的对立面留余地以分化争取","d":"区分死硬派与可改造者；对作为敌对力量但可转化的对象，不采取最严厉处置（不提人、不取消选举权），留转弯余地以利分化，多数可摘帽归队，少数顽固者搁置观察。","p":["坚定地相信群众的大多数"]},{"t":"对不可救药的对立面战略排斥而策略妥协","d":"对敌对分子和不可救药者，判定其与己方绝对互相排斥、只有一重性，无法帮助、只能打倒；但这是战略目的上的态度，在策略阶段上允许妥协（如三八线与美妥协、越南与法妥协）。区分战略目的与策略阶段，既坚决排斥又保持策略灵活性。","p":["党内团结的辩证方法"]}]},{"t":"分批分阶段依条件推进并保持中心任务","d":"复杂运动不一下子全面铺开，而是按单位条件成熟程度分期分批逐步推行，并分解为若干必经阶段循序推进；同时任何时候不耽误生产这一中心任务，使政治运动与工作建设互不冲击。","sub":[{"t":"整风四阶段循序推进","d":"中央、省市、地、县四级整风须经历四阶段：大鸣大放（边整边改）、反击右派（边整边改）、着重整改（继续鸣放）、每人研究文件批评反省提高自己；整风大体一年一次定期举行。阶段依次推进，不可草率收兵。","p":["一九五七年夏季的形势","坚定地相信群众的大多数"]},{"t":"分期分批逐步推行整风且不影响生产","d":"整风不应当在一切单位同时并举，应分期分批逐步推行，且任何时候不耽误生产和工作；城乡基层按条件成熟程度分批展开，使政治运动与生产建设互不冲击。","p":["一九五七年夏季的形势"]},{"t":"各个击破逐次解决局部","d":"面对庞大的整体任务，不指望一次完成，而是分解为若干局部逐一解决：打仗一仗一仗打，敌人一部分一部分消灭，工厂一个一个盖，逐次推进直至完成整体；整体任务必须靠局部逐个完成，无一口吞下整体的捷径。","p":["一切反动派都是纸老虎"]}]},{"t":"以民主说理讨论协商解决人民内部矛盾","d":"对于人民内部的思想认识与意见分歧，坚持用说理、批评、公开讨论和同群众协商的方式去解决，而不是用压服、命令或强制。通过摆事实讲道理、鸣放辩论，让矛盾在公开表达中暴露并被克服，从而团结多数、孤立少数。","sub":[{"t":"以鸣放辩论大字报座谈会揭露克服矛盾","d":"用大鸣大放、大字报、座谈会和辩论会作为揭露克服矛盾、推动进步的形式；农村先鸣放提意见再择善而从、不善者批判，全民性大辩论解决道路与领导等重大问题；大辩论主要目的是争取半服半不服的中间派，使多数人在自我教育中改造。矛盾在公开表达中暴露并被克服。","p":["一九五七年夏季的形势","坚定地相信群众的大多数"]},{"t":"以批评自我批评摆事实讲道理开展整风","d":"整风采用批评和自我批评、摆事实讲道理的方法，把斗争方向引导到端正政治方向、提高思想水平、改正缺点、团结群众、孤立分化右派；整风口号通用是为争取多数人接受、使党主动。核心是说服而非压服。","p":["一九五七年夏季的形势"]},{"t":"正确处理人民内部矛盾即走群众路线","d":"正确处理人民内部矛盾即走群众路线：同群众商量办事、不离开群众，党群如鱼水；军队能实行三大民主用说服解决问题，工厂农村更当发扬民主。怕老百姓的人不是真正共产主义者。","p":["一九五七年夏季的形势"]}]},{"t":"从群众实际和亲身调查取得正确认识","d":"认识与工作必须从基本群众的实际状况和亲身调查出发：坚定信任工农基本群众多数以估计自身力量，领导人更要亲自蹲点调查具体基层单位，取得直接认识和发言权，避免脱离实际的空泛指导。","sub":[{"t":"以信任群众多数为基本出发点","d":"基本出发点是坚定信任工农基本群众多数以估计自身力量；经摸底测算，全国约百分之九十赞成社会主义、约百分之十不赞成、死硬派约百分之二且分散于各单位，据此判断\"乱不了\"、敢于放开。低估自身力量、高估敌人是错误，应说服干部正确估计双方。","p":["一九五七年夏季的形势","坚定地相信群众的大多数"]},{"t":"领导人亲身蹲点基层单位取得发言权","d":"省市委第一书记及各级书记半年到一年内亲身研究一个合作社、工厂、商店或学校，取得直接知识和发言权以利指导全盘；中央省市取得经验后教会地县、区乡。发言权来自亲身调查而非空泛指示。","p":["一九五七年夏季的形势"]},{"t":"以充分鸣放作摸底手段使矛盾现底","d":"把充分鸣放当作摸底手段，让各单位意见、言论全部暴露出来（\"一把明矾放下去，就看见了底\"），据以看清拥护与反对的实际比例，摸清底数、心中有数，再决定下一步行动。","p":["坚定地相信群众的大多数"]}]},{"t":"面对攻势冷静蓄力待机反攻","d":"当敌对势力猖狂进攻时，不急于反驳，而是硬着头皮顶住、只听不驳，聚精会神分析研究、团结左派争取中间派、积蓄力量，待洪峰过去再准备反攻。这是一套在压力下冷静蓄力、择机反击的斗争策略。","sub":[{"t":"面对进攻硬着头皮顶住积蓄力量准备反攻","d":"右派猖狂进攻时领导者硬着头皮顶住、只听不驳（五月到六月八日一概不驳），聚精会神分析研究，团结左派、争取中间派、孤立右派，聚集力量准备反攻；约两三周洪峰过去即转入反击新阶段。","p":["一九五七年夏季的形势","坚定地相信群众的大多数"]}]},{"t":"通过联系基本群众完成立场改造","d":"认识与实践主体的世界观与立场不是孤立转变的，须通过与基本群众的实际联系辨明方向，并经系统的思想改造才能真正确立新立场；立场改造依靠联系群众来完成，而非脱离群众的孤立修身。","sub":[{"t":"引导知识分子联系工农并系统改造思想","d":"让知识分子走出知识小圈子，到工人、农民（老工人、贫农下中农）中找朋友、辨明方向，同时以\"红与专\"要求和思想改造运动彻底改造资产阶级世界观，造就无产阶级自己的知识分子队伍。","p":["坚定地相信群众的大多数"]}]},{"t":"以对立统一观点辩证对待对象","d":"面对人、事与分歧，承认其内部与彼此之间充满对立统一，不采取\"全好全坏、否定一切\"的形而上学；从两面性出发，既不因缺点否定整体，也不因坚持原则而放弃帮助与团结，以斗争与团结、原则与灵活的两手把握分寸。一分为二普遍存在，辩证方法可普及为日常认识工具。","sub":[{"t":"对犯错误的同志采取一斗二帮的辩证方法","d":"先辨别对象，只要不是敌对分子、破坏分子就采取团结态度；再用辩证方法分析，承认人总犯错误、不因一个错误否定他的一切；对错误思想第一要斗争、彻底肃清，第二还要帮助，从善意出发帮他改正、使他有一条出路。拒绝形而上学\"全盘否定\"的老路。","p":["党内团结的辩证方法"]},{"t":"以原则性与灵活性统一的辩证方法处理同志分歧","d":"同志之间有隔阂分歧，不视作铁板一块无须谈判，而从团结出发用帮助的精神开谈判；谈判时在不损伤马克思列宁主义原则下，接受一些可接受的意见、放弃一些可放弃的意见；用两只手——一只手作斗争坚持原则，一只手讲团结给以出路。","p":["党内团结的辩证方法"]},{"t":"把一分为二的辩证方法宣传普及到群众中去","d":"辩证法不应停留在哲学家圈子，要广泛宣传对立统一的观念，在各国党政治局会议和中央全会、各级地方委员会上谈；群众实际都懂一分为二——支部书记在支部大会作报告时在小本子上记优点、缺点两点，把辩证法化为群众日常可用的认识工具。","p":["党内团结的辩证方法"]}]},{"t":"整体判断与具体处理相统一","d":"面对貌似强大的对象或艰难任务，先在整体上把握其本质与趋势、坚持必胜判断，再在具体环节上逐一认真对待；整体上藐视防悲观恐惧，具体上重视防轻率冒进，两端并守构成完整的认识姿态。","sub":[{"t":"战略上藐视敌人、战术上重视敌人","d":"对同一对象分层对待：整体上认清其虚弱本质、坚持必胜信心（战略上藐视），具体环节上逐一认真处理（战术上重视）；整体上藐视防机会主义的悲观，具体上重视防冒险主义的轻率，两端并守缺一不可。","p":["一切反动派都是纸老虎"]}]}]};